(function(){
'use strict';
const rows=[["EG","Pyramids of Giza","يتميّز الموقع بأنه جزء من جبانة منف القديمة، ويجمع بين عمارة المقابر الملكية والتخطيط الجنائزي الذي يوضح مكانة الملوك في الدولة القديمة.","يمكن ملاحظة اختلاف أحجام الأهرامات الثلاثة واتجاهاتها، ثم تأمل العلاقة المكانية بينها وبين أبو الهول ومقابر النبلاء.","https://whc.unesco.org/en/list/86","شُيدت الأهرامات الملكية الكبرى خلال الأسرة الرابعة في عصر الدولة القديمة، وتكاملت مع معابد جنائزية وطرق صاعدة ومقابر أخرى ضمن جبانة واسعة.","الهرم الأكبر هو المقبرة الملكية الوحيدة الباقية من عجائب الدنيا السبع القديمة؛ أما تاريخ بناء الأهرامات فيرتبط بملوك مختلفين، لا بملك واحد."],["FR","Eiffel Tower","يمثل البرج تحولًا في توظيف الهياكل المعدنية الضخمة أواخر القرن التاسع عشر، وأصبح علامة على التقدم الصناعي والهندسي في باريس.","أبرز ما يُلاحظ شبكة الدعامات الحديدية المفتوحة وتغيّر منظر المدينة والنهر تدريجيًا من مستويات البرج المختلفة.","https://www.toureiffel.paris/en/the-monument/history","أُقيم البرج لمعرض باريس العالمي سنة 1889، وكان مشروعه الهندسي موضع جدل قبل أن يتحول إلى أحد أشهر رموز العاصمة.","لم يُصمَّم البرج في البداية ليكون رمزًا سياحيًا دائمًا؛ وقد أسهم استخدامه للاتصالات والتجارب العلمية في استمرار أهميته."],["IT","Colosseum","يُظهر المدرج حجم الحياة العامة في روما الإمبراطورية وطريقة تنظيم الحشود والعروض داخل فضاء معماري بيضاوي متعدد المستويات.","تُظهر المدرجات والأقواس والممرات تحت الساحة كيف كان الدخول والتنقل وتجهيز العروض يتم داخل المدرج.","https://colosseo.it/en/area/the-colosseum/","بدأ بناء المدرج في عهد فسبازيان واكتمل الجزء الرئيسي في عهد تيطس خلال القرن الأول الميلادي، وكان مرتبطًا بالعروض العامة في روما.","الاسم التاريخي «المدرج الفلافي» ينسبه إلى الأسرة الحاكمة التي بنته؛ أما «الكولوسيوم» فهو اسم اشتهر لاحقًا."],["SA","Hegra","يمثل الحجر شاهدًا بارزًا على مملكة الأنباط خارج البتراء؛ وتكشف واجهات المقابر المنحوتة عن تفاعل التجارة والعمارة في شمال غربي الجزيرة العربية.","تلفت الواجهات الصخرية المزخرفة والانفراد النسبي لبعض المقابر الانتباه إلى اختلاف تصميمها وحجمها من موضع لآخر.","https://whc.unesco.org/en/list/1293","ازدهرت الحِجر ضمن شبكة طرق القوافل في شمال غرب شبه الجزيرة العربية، وأصبح الموقع إحدى مدن المملكة النبطية ومراكزها الجنائزية.","الحِجر أول موقع في المملكة العربية السعودية أُدرج على قائمة التراث العالمي لليونسكو، عام 2008."],["TR","Hagia Sophia","تبرز أهمية آيا صوفيا في تأثير قبتها وفضائها الداخلي على تاريخ العمارة، وفي تعاقب وظائفها الدينية عبر العصور البيزنطية والعثمانية.","تستحق القبة المركزية وأنصاف القباب والأعمدة والفسيفساء والمشغولات الخطية التأمل بوصفها طبقات من تاريخ المكان.","https://whc.unesco.org/en/list/356","اكتمل المبنى البيزنطي القائم سنة 537م في عهد الإمبراطور جستنيان الأول، ثم تحول إلى مسجد بعد الفتح العثماني للقسطنطينية عام 1453.","القبة الكبيرة ليست مجرد عنصر زخرفي؛ بل يعتمد اتساع الفضاء الذي تغطيه على نظام هندسي من العقود وأنصاف القباب والدعامات."],["ES","Alhambra","يُظهر قصر الحمراء تطور المدينة القصرية في الأندلس، حيث ارتبطت المساكن والحدائق والماء والتحصينات ضمن مجمع واحد.","تُبرز أفنية القصور الناصرية والزخارف الجصية وقنوات الماء توازن العمارة مع حدائق جنة العريف والمشهد الجبلي.","https://whc.unesco.org/en/list/314","شهدت الحمراء توسعها الأشهر في عهد بني نصر خلال القرنين الثالث عشر والرابع عشر، حين أصبحت مقرًا للحكم والحياة البلاطية في غرناطة.","اسم «الحمراء» يرتبط تقليديًا بلون تحصيناتها؛ لكن هوية الموقع تقوم أيضًا على هندسة المياه والبساتين والقصور وليس اللون وحده."],["GB","Stonehenge","تتجاوز أهمية ستونهنج شكل الدائرة الحجرية؛ فالموقع جزء من مشهد احتفالي وجنائزي أوسع يعود إلى العصرين الحجري الحديث والبرونزي.","يمكن ملاحظة انتظام الأحجار والعتبات الحجرية وارتباط محور الموقع بشروق شمس الانقلاب الصيفي وغروب شمس الانقلاب الشتوي.","https://whc.unesco.org/en/list/373","بُني الموقع وتغيّر على مراحل خلال عصور ما قبل التاريخ؛ وتوجد حوله تلال دفن وآثار تشكّل جزءًا من المشهد الأثري نفسه.","ارتباط بعض محاور الأحجار بالانقلابات الشمسية معروف، لكن الوظيفة الأصلية الكاملة للموقع لا تزال موضع بحث ولا يجوز الجزم بتفسير وحيد."],["US","Grand Canyon","الأخدود سجل جيولوجي مكشوف يوضح تراكم طبقات الصخور ثم نحت نهر كولورادو والهضبة عبر مدد زمنية طويلة.","تكشف نقاط الإطلالة عن تدرّج الطبقات الصخرية وألوانها واتساع الأخدود، بينما يظهر مجرى النهر بعيدًا أسفل الحواف.","https://www.nps.gov/grca/learn/nature/geologicformations.htm","تكوّنت طبقات الصخور التي تظهر في جدران الأخدود عبر أزمنة جيولوجية متباعدة، ثم ساعد ارتفاع هضبة كولورادو والنحت النهري في تشكيل المشهد الحالي.","الطبقات الصخرية أقدم بكثير من الأخدود بوصفه تضاريس محفورة؛ لذلك يجب التمييز بين عمر الصخور وعمر تشكّل الوادي."],["CN","Great Wall at Badaling","يمثل قطاع بادالينغ جزءًا من شبكة دفاعية تاريخية ممتدة، ولا ينبغي اعتباره سورًا منفصلًا عن منظومة التحصينات الصينية الواسعة.","يمكن تتبع مسار الجدار فوق خط القمم والانتباه إلى الأبراج ونقاط المراقبة واختلاف انحدار الممرات.","https://whc.unesco.org/en/list/438","يمثل بادالينغ جزءًا من التحصينات التي طُورت بشكل خاص خلال عهد أسرة مينغ لحماية الممرات الجبلية المؤدية إلى منطقة بكين.","ليس سور الصين خطًا واحدًا بُني في عصر واحد؛ بل شبكة قطاعات وحصون شُيدت وأُعيد بناؤها في فترات تاريخية مختلفة."],["IN","Taj Mahal","تنبع قيمة تاج محل من الجمع بين ضريح مغولي وتنسيق حدائق متناظر وفنون الرخام المطعّم والخط والزخرفة؛ وهو نصب تذكاري بناه شاه جهان تخليدًا لزوجته ممتاز محل.","يبرز المحور المتناظر من البوابة والحديقة المائية نحو الضريح، مع تفاصيل الرخام الأبيض والزخارف الدقيقة والقبة المركزية.","https://whc.unesco.org/en/list/252","أمر الإمبراطور المغولي شاه جهان بإقامة المجمع في أغرا خلال القرن السابع عشر تخليدًا لزوجته ممتاز محل، وضم المشروع حديقة ومباني مرافقة.","يتغير الإحساس بلون الرخام الأبيض باختلاف الإضاءة، لكن المبنى في أصله ضريح جنائزي وليس قصرًا للسكن."],["JP","Fushimi Inari Shrine","يرتبط المزار بعبادة الإله إيناري في التقليد الشنتوي، وتشكّل بوابات التوري المتتابعة مسارات ذات رمزية دينية على سفح الجبل.","تُعد ممرات بوابات التوري الحمراء والطرق الصاعدة بين الأشجار والعتبات الصغيرة أبرز عناصر التجربة البصرية للموقع.","https://inari.jp/en/","تعود جذور المزار في كيوتو إلى تقاليد دينية قديمة مرتبطة بإيناري، وترتبط بواباته المميزة بتبرعات التعبد والشكر.","بوابات التوري الكثيرة لا تشكل ممرًا مستقيمًا واحدًا؛ بل تتوزع على مسارات متعددة تصعد نحو جبل إيناري."],["AE","Burj Khalifa","يقدم البرج مثالًا للهندسة الرأسية الحديثة في المدن الخليجية، حيث يسهم تصميمه المتدرج في تكوين صورة عمرانية مميزة لدبي.","تُظهر الواجهة المتدرجة والشكل المكوّن من أجنحة حول مركز البرج انتقال الكتلة المعمارية إلى قمة رفيعة، مع مشهد المدينة من الأعلى.","https://www.burjkhalifa.ae/","افتُتح البرج في دبي عام 2010، ضمن مشروع عمراني حديث أعاد تشكيل منطقة وسط المدينة وربط الاستخدامات السكنية والفندقية والمشاهدة.","يبلغ ارتفاع برج خليفة نحو 828 مترًا، لكن هذا الرقم يصف ارتفاع المبنى ولا يعني أن جميع طوابقه مخصصة للمشاهدة."],["EG","Cairo Citadel","تجسد القلعة انتقال القاهرة إلى عصر التحصينات الأيوبية ثم تطورها مركزًا للحكم؛ لذلك تتجاور داخلها مبانٍ من فترات إسلامية مختلفة.","يبرز مسجد محمد علي بقبابه ومآذنه، إلى جانب أسوار القلعة وإطلالاتها الواسعة على نسيج القاهرة التاريخية.","https://egymonuments.gov.eg/en/world-heritage/historic-cairo","أنشئت قلعة صلاح الدين في أواخر القرن الثاني عشر لتدعيم دفاعات القاهرة.","الموقع المرتفع يتيح قراءة مشهد القاهرة التاريخية من أعلى."],["EG","Khan el-Khalili","تكمن أهمية السوق في استمرار تقاليد التجارة والحرف داخل القاهرة التاريخية، لا في كونه سوقًا لشراء الهدايا فحسب.","تكشف الأزقة والدكاكين التقليدية والواجهات القديمة عن العلاقة بين التجارة والعمارة في الحي المحيط بالأزهر.","https://whc.unesco.org/en/list/89","تطورت الأسواق والممرات التجارية في هذه المنطقة خلال العصر المملوكي وما بعده.","زيارة السوق تكشف تاريخ التجارة والحرف أكثر من كونها زيارة لمبنى منفرد."],["EG","Citadel of Qaitbay","توضح القلعة كيف أعادت الإسكندرية استخدام موقعها الساحلي الاستراتيجي للدفاع عن الميناء بعد اختفاء منارة فاروس القديمة.","يبرز شكل الحصن الحجري وأبراجه وفتحات المراقبة، مع منظر البحر المتوسط حول طرف الميناء الشرقي.","https://egymonuments.gov.eg/monuments/qaitbay-fort/","شُيّدت في عهد السلطان المملوكي الأشرف قايتباي في القرن الخامس عشر.","يجمع الموقع بين تاريخ الدفاع الساحلي وإطلالة البحر المتوسط."],["EG","Valley of the Kings","يُعد الوادي مصدرًا أساسيًا لفهم طقوس الدفن الملكي في الدولة الحديثة؛ إذ تتزين بعض المقابر بنصوص دينية ومشاهد من عالم ما بعد الموت.","تُظهر ممرات المقابر والغرف المنحوتة والنقوش الملونة اختلاف تخطيط المدافن وطرائق تصوير الرحلة الأخروية.","https://whc.unesco.org/en/list/87","استخدم ملوك الدولة الحديثة وادي الملوك في البر الغربي لطيبة لدفن عدد من حكام الأسر الثامنة عشرة والتاسعة عشرة والعشرين، بعيدًا عن المعابد الكبرى في الضفة الشرقية. ومن أشهر اكتشافاته مقبرة توت عنخ آمون التي أبرزت قيمة الأثاث الجنائزي والنصوص والرسوم المتعلقة بالبعث والحياة الأخرى.","تختلف المقابر في طول الممرات وتوزيع الحجرات والزخارف؛ لذلك لا تمثل مقبرة واحدة تخطيط جميع المقابر. كما أن شهرة مقبرة توت عنخ آمون ترجع بدرجة كبيرة إلى ما وُجد داخلها، لا إلى كونها أضخم مقابر الوادي."],["FR","Notre-Dame de Paris","تمثل الكاتدرائية تطور العمارة القوطية الفرنسية ومكانتها في الذاكرة الدينية والمدنية لباريس عبر قرون.","تُبرز الواجهات الحجرية والنافذتان الورديتان والدعامات الطائرة كيفية الجمع بين البناء المرتفع والضوء والزخرفة.","https://www.notredamedeparis.fr/en/","بدأ تشييد الكاتدرائية في القرن الثاني عشر ومرت مراحل البناء عبر أجيال.","تقع الكاتدرائية على جزيرة المدينة، وهي من أقدم مراكز باريس العمرانية."],["FR","Arc de Triomphe","يحمل القوس ذاكرة عسكرية ووطنية فرنسية؛ وأصبح قبر الجندي المجهول أسفله جزءًا من طقوس إحياء ذكرى ضحايا الحروب.","يمكن تأمل النقوش البارزة وأسماء المعارك والقادة على الجدران، ثم ملاحظة المحاور العمرانية المتفرعة من ساحة شارل ديغول.","https://www.paris-arc-de-triomphe.fr/en/","أمر نابليون الأول بإنشائه سنة 1806، واكتمل في ثلاثينيات القرن التاسع عشر.","تلتقي عند ساحته طرق شعاعية تمنح المشهد العمراني طابعًا مميزًا."],["FR","Château de Chambord","يبرز شامبور طموح العمارة الملكية في عصر النهضة الفرنسية، حيث اجتمع الاستعراض الفني مع مبنى أُنشئ ضمن نطاق غابي واسع.","من أبرز تفاصيله السلم الحلزوني المزدوج والشرفات الكثيرة وخط الأسقف المعقد بأبراجه ومداخنه.","https://www.chambord.org/en/","بدأ بناء القصر في عهد فرانسوا الأول في القرن السادس عشر.","يجمع القصر بين طابع حصون العصور الوسطى وزخارف عصر النهضة."],["FR","Verdon Gorge","تنبع أهمية الخانق من جيولوجيته الجيرية وتشكيله منظرًا نهريًا عميقًا بفعل التعرية على مدى زمني طويل.","تظهر الجدران الكلسية العالية وتعرجات النهر والمياه الفيروزية من نقاط المشاهدة المطلة على الأخدود.","https://www.parcduverdon.fr/","تكوّنت طبقات الحجر الجيري التي تشكل جدران أخدود فيردون في بحار قديمة خلال العصرين الجوراسي والطباشيري، ثم ارتفعت وتصدعت مع حركات بناء جبال الألب. وبعد ذلك عمّق نهر فيردون مجراه عبر التعرية المائية، فنشأ الأخدود ذو الجروف الشاهقة الذي يربط اليوم بين التاريخ البحري للصخور وتطور التضاريس الجبلية.","يوضح المكان أثر التعرية المائية طويلة الأمد في تشكيل التضاريس."],["IT","Roman Forum","كان المنتدى قلبًا للحياة السياسية والدينية والتجارية في روما القديمة، وتكشف أطلاله عن تغير استعمال الساحة عبر عصور متتابعة.","يمكن تتبع الطريق المقدس بين بقايا المعابد والأعمدة وأقواس النصر، ومقارنة مواقع المباني المدنية حول الساحة.","https://colosseo.it/en/area/roman-forum/","مرّ عبر المنتدى الطريق المقدس المعروف باسم «فيا ساكرا»، الذي ارتبط بالمواكب والاحتفالات العامة في روما القديمة.","المكان ليس معلمًا منفردًا بل شبكة مبانٍ حول ساحة عامة تاريخية."],["IT","Pantheon, Rome","يُعد البانثيون شاهدًا مهمًا على ابتكار الرومان في البناء الخرساني، وخصوصًا إنشاء قبة واسعة فوق فضاء دائري.","تسمح الفتحة العليا المعروفة بالأوكولوس بتغير بقعة الضوء داخل القاعة، ويظهر توازن القبة مع الصفوف المحيطة من التجاويف.","https://direzionemuseiroma.cultura.gov.it/pantheon/","أعيد بناء البانثيون في شكله المعروف خلال عهد الإمبراطور هادريان.","تعمل الفتحة الدائرية في القبة مصدرًا للضوء الطبيعي داخل المبنى."],["IT","Piazza San Marco","تعكس الساحة الطابع البحري والسياسي لجمهورية البندقية التاريخية، إذ تتجمع حولها مبانٍ دينية ومدنية كبرى.","تتجاور واجهة البازيليكا مع برج الأجراس والأروقة الطويلة، وتتضح صلة الساحة بمنطقة قصر دوجي والواجهة المائية.","https://whc.unesco.org/en/list/394","شكلت الساحة قلب المناسبات الرسمية والحياة العامة في البندقية.","تعكس الساحة علاقة المدينة التاريخية بالتجارة البحرية والسلطة."],["IT","Florence Cathedral","تجسد الكاتدرائية طموح فلورنسا الفني والهندسي في أواخر العصور الوسطى وعصر النهضة، وخصوصًا قبة برونليسكي.","يمكن مقارنة الرخام متعدد الألوان في الواجهات مع ضخامة القبة المثمنة وبرج الأجراس القائم بجانبها.","https://duomo.firenze.it/en/home","بدأ تشييد الكاتدرائية أواخر القرن الثالث عشر، وتوجت بقبة برونليسكي في القرن الخامس عشر.","تتميز الواجهة بالرخام الملون بينما يشكل القبة رمز أفق فلورنسا."],["SA","Masmak Fortress","ترتبط قلعة المصمك بتاريخ الرياض الحديث وباستعادة الملك عبدالعزيز المدينة عام 1902، وهي شاهد على العمارة الدفاعية النجدية.","يُظهر المبنى جدران الطين السميكة والأبراج الركنية والبوابة الخشبية، مع فناء داخلي يشرح طبيعة الحصون المحلية.","https://www.visitsaudi.com/ar/see-do/destinations/riyadh/al-masmak-palace-in-riyadh","يرتبط حصن المصمك باستعادة الرياض سنة 1902 في سياق نشأة الدولة السعودية الحديثة.","توضح جدرانه الطينية السميكة ملاءمة العمارة النجدية لبيئتها."],["SA","Elephant Rock (AlUla)","الصخرة مثال بارز على النحت الطبيعي الناتج عن التجوية والتعرية في البيئة الصحراوية للعلا؛ وشكلها الشبيه بالفيل هو مصدر اسمها.","يظهر القوس أسفل الكتلة الصخرية وهيئة الخرطوم بوضوح من الزوايا الجانبية، خاصة مع تغير الظلال وقت الغروب.","https://www.experiencealula.com/en/places-to-go/elephant-rock","تكوّن جبل الفيل من الحجر الرملي عبر فترات جيولوجية طويلة، حيث تسللت عوامل التجوية والتعرية إلى الشقوق والطبقات الأضعف فأزالت أجزاء من الصخر تدريجيًا. نتج عن ذلك تكوين طبيعي مستقل بفتحة أسفل الكتلة وهيئة تشبه خرطوم الفيل، وليس أثرًا منحوتًا صنعه الإنسان.","يبلغ ارتفاع جبل الفيل نحو 52 مترًا وفق موقع العلا الرسمي. ويُظهر تكوينه كيف تصنع فروق مقاومة طبقات الحجر الرملي للتعرية أشكالًا صخرية لافتة؛ أما التسلق على الصخرة فغير مسموح حفاظًا عليها."],["SA","Al-Balad, Jeddah","تجسد جدة التاريخية دور الميناء القديم بوابةً للتجارة وللحجاج القادمين عبر البحر الأحمر، وما نتج عنه من طراز عمراني مميز.","تظهر الرواشين الخشبية والشوارع الضيقة والبيوت متعددة الطوابق المصنوعة من الحجر المرجاني في النسيج التاريخي.","https://whc.unesco.org/en/list/1361","ازدهرت جدة التاريخية ميناءً على البحر الأحمر منذ القرن السابع الميلادي، وصارت بوابةً للحجاج القادمين بحرًا إلى مكة ومركزًا لتجارة المحيط الهندي. وفي القرنين التاسع عشر والعشرين شيّد التجار بيوتًا مرتفعة بالحجر المرجاني ورواشين خشبية متأثرة بتبادل الحرف عبر طرق الملاحة.","لا تقتصر جدة التاريخية على بيوت الرواشين؛ فهي نسيج من أسواق ومساجد وأربطة وساحات مرتبطة بالتجارة والحج. وأسهمت الرواشين الخشبية البارزة في التهوية والخصوصية والتعامل مع حرارة الساحل ورطوبته؛ وأُدرج الموقع في قائمة اليونسكو عام 2014."],["SA","Asir National Park","تبرز قيمة منطقة عسير الطبيعية في اختلاف مناخ المرتفعات وغطائها النباتي عن الأقاليم الصحراوية المحيطة بها.","تتغير المشاهد بين القمم الجبلية والمنحدرات والغطاء النباتي والضباب الموسمي في بعض المواضع المرتفعة.","https://www.visitsaudi.com/content/dam/saudi-tourism/media/guides/saudi-visit-adventure-english.pdf","تتدرج تضاريس عسير من المرتفعات الجبلية إلى المنحدرات الغربية.","يمنح الضباب أحيانًا المرتفعات مشهدًا مختلفًا عن معظم شبه الجزيرة."],["TR","Galata Tower","يمثل برج غلطة طبقة من تاريخ إسطنبول التجاري والدفاعي، ويرتبط بالمشهد العمراني لمنطقة غلطة على الضفة الشمالية للقرن الذهبي.","يظهر البرج الحجري الأسطواني بسقفه المخروطي وسط الشوارع المتدرجة، وتُرى منه معالم القرن الذهبي والبوسفور.","https://muze.gov.tr/muze-detay?sectionId=GLT04&distId=MRK","شُيّد برج غلطة بشكله التاريخي المعروف نحو عام 1348 ضمن تحصينات المستعمرة التجارية الجنوية في منطقة غلطة، شمال القرن الذهبي. وفي العهد العثماني تغيّرت وظائفه، فاستخدم في بعض الفترات للحبس ثم لمراقبة الحرائق، قبل ترميمه في القرن العشرين وتحويله لاحقًا إلى متحف وإطلالة على المدينة.","البرج الحالي ليس برجًا عثمانيًا أُنشئ من الصفر، بل مبنى جنوي أُعيد استخدامه وترميمه مرات عديدة. تتيح شرفته العلوية رؤية القرن الذهبي وأجزاء من البوسفور وإسطنبول التاريخية من نقطة واحدة."],["TR","Basilica Cistern","تكشف الصهريج عن جانب غير مرئي من هندسة المياه في القسطنطينية البيزنطية، حين استخدمت مخازن كبيرة لدعم إمداد المدينة بالماء.","تتكرر صفوف الأعمدة تحت الأقبية الحجرية، وتلفت قواعد ميدوسا المعاد استخدامها الانتباه لتنوع عناصر البناء.","https://www.yerebatan.com/en","شُيد الصهريج في العصر البيزنطي لتخزين المياه وتوفيرها للمنطقة الإمبراطورية.","تثير قواعد ميدوسا اهتمامًا خاصًا لأنها وضعت في اتجاهات غير مألوفة."],["TR","Pamukkale","يجمع الموقع بين ظاهرة جيولوجية نشطة نسبيًا تتمثل في ترسيب كربونات الكالسيوم وبين آثار مدينة هيرابوليس القديمة.","تبدو المصاطب البيضاء والبرك المتدرجة بجوار الآثار الرومانية، مع اختلاف تدفق المياه حسب إجراءات حماية الموقع.","https://whc.unesco.org/en/list/485","تترسب كربونات الكالسيوم من المياه الحرارية مشكلة مصاطب ترافرتين بيضاء.","يتغير مظهر البرك وتدفق المياه بحسب إجراءات حماية الموقع."],["TR","Ephesus","كانت أفسس مركزًا حضريًا وتجاريًا مهمًا في آسيا الصغرى، وتتيح آثارها دراسة التخطيط الروماني العام وشبكات الحياة المدنية.","تُبرز واجهة مكتبة سيلسوس والمسرح الكبير والشارع المرصوف بالأعمدة صورة ملموسة للمدينة القديمة.","https://whc.unesco.org/en/list/1018","كانت أفسس مدينة مهمة في العالمين اليوناني والروماني قرب ساحل الأناضول الغربي.","تغير الخط الساحلي التاريخي نتيجة تراكم الرواسب عبر الزمن."],["JP","Meiji Shrine","يجمع الضريح بين إحياء ذكرى الإمبراطور ميجي والإمبراطورة شوكن وبين تقاليد العمارة الشنتوية داخل مساحة مشجرة واسعة في طوكيو.","تمنح بوابات التوري الضخمة والمسارات الحصوية والغابة المحيطة إحساسًا بالانتقال من المدينة إلى فضاء شعائري هادئ.","https://www.meijijingu.or.jp/en/","أُسس الضريح في القرن العشرين تكريمًا للإمبراطور ميجي والإمبراطورة شوكن.","تمنح بوابات التوري والمسارات المشجرة انتقالًا بصريًا من المدينة إلى الهدوء."],["JP","Tōdai-ji","يرتبط المعبد بدور نارا عاصمةً لليابان في القرن الثامن، وبالدور الذي لعبته البوذية في تشكيل الفن والعمارة آنذاك.","تُبرز قاعة بوذا العظيم الضخمة الهيكل الخشبي وتمثال بوذا البرونزي، كما تكشف البوابة الجنوبية عن منحوتات حارسة.","https://www.todaiji.or.jp/en/","أنشئ المعبد في القرن الثامن عندما كانت نارا مركزًا للحكم الياباني.","أعيد بناء أجزاء من المبنى عبر التاريخ بعد حرائق وأضرار."],["JP","Hiroshima Peace Memorial Park","تمثل الحديقة مساحة للتذكر والتثقيف حول ضحايا القصف الذري عام 1945، وتربط المدينة المعاصرة برسالة منع تكرار المأساة.","يمكن تأمل النصب التذكاري ومتحف السلام بمحاذاة المشهد النهري، مع قبة القنبلة الذرية القريبة.","https://hpmmuseum.jp/?lang=eng","أقيمت الحديقة لإحياء ذكرى ضحايا القصف الذري على هيروشيما عام 1945.","يجمع المكان بين التوثيق التاريخي ورسالة السلام ومنع تكرار الكارثة."],["JP","Lake Ashi","البحيرة جزء من المشهد البركاني لمنطقة هاكونه، وتجمع بين الجغرافيا الجبلية ورموز التراث المحلي.","تظهر المياه المحاطة بالمرتفعات والغابات، ومع صفاء الجو يمكن رؤية جبل فوجي من بعض الإطلالات وبوابة التوري على الضفة.","https://www.mlit.go.jp/tagengo-db/en/R1-01101.html","تكوّنت بحيرة آشي في منطقة هاكونه البركانية قبل نحو ثلاثة آلاف سنة، عندما سدّت المواد المنهارة من جانب جبل كامياما مجرى النهر وتجمعت المياه خلف السد الطبيعي. تتغذى البحيرة من الأمطار والمياه الجوفية، وأصبحت عبر الزمن جزءًا من المشهد الثقافي المحيط بمزار هاكونه ومسارات التنقل القديمة.","تظهر على ضفافها بوابات توري وأحراج جبلية تعكس الجمع بين الطبيعة والتراث."],["ES","Park Güell","يمثل المنتزه تجربة لغاودي في دمج العمارة بالمناظر الطبيعية؛ وقد تحول المشروع العمراني الأصلي إلى فضاء عام يحمل بصمته الفنية.","تظهر مقاعد الفسيفساء المتموجة والسلم الشهير وتكوينات الأعمدة العضوية مع إطلالات على برشلونة.","https://whc.unesco.org/en/list/320","صمم غاودي الحديقة ضمن مشروع عمراني بدأ مطلع القرن العشرين قبل أن تصبح منتزهًا عامًا.","تشتهر الساحة المرتفعة بمقعد متموج مغطى بفسيفساء الترينكاديس."],["ES","Royal Alcázar of Seville","يجسد القصر طبقات متراكبة من تاريخ إشبيلية، وخاصة التأثير المدجّن الذي جمع الحرف الإسلامية بالأذواق الملكية المسيحية.","تُبرز قاعة السفراء والباحات المزخرفة والبلاط الهندسي والحدائق المائية تنوع أساليب البناء داخله.","https://www.alcazarsevilla.org/","ترجع جذور المجمع إلى التحصينات الإسلامية في إشبيلية منذ القرن العاشر، ثم توسّع وتحوّل مع انتقال الحكم وتبدّل الطرز المعمارية. وفي القرن الرابع عشر أمر بيدرو الأول ببناء قصر مدجّن يزاوج الزخارف والحرف الأندلسية بوظائف البلاط المسيحي، وأضيفت لاحقًا عناصر من عصور أخرى.","مصطلح «المدجّن» يصف أسلوبًا فنيًا استُخدمت فيه تقاليد حرفية إسلامية داخل عمارة الممالك المسيحية؛ لذا فإن زخارف القصر الإسلامية الشكل لا تعني أن كل أجنحته شُيدت في عهد الحكم الإسلامي."],["ES","Aqueduct of Segovia","تُظهر القناة المائية براعة الهندسة الرومانية في نقل المياه إلى المدينة عبر تضاريس متفاوتة الارتفاع.","تتوالى الأقواس الحجرية العالية وسط المدينة القديمة، حيث يظهر انتظام الكتل الحجرية دون استخدام ملاط في القسم الأشهر.","https://turismodesegovia.com/en/arquitectura-civil/obras-de-ingenieria/aqueduct","أُنشئت قناة سيغوفيا لنقل الماء بالجاذبية من مصادر خارج المدينة إلى خزاناتها ونوافيرها خلال العصر الروماني، ويرجّح الموقع السياحي الرسمي للمدينة تأريخ بنائها إلى أوائل القرن الثاني الميلادي. وقد ظل مجراها ونظام الأقواس الحجرية جزءًا من عمران سيغوفيا عبر قرون طويلة.","لا يقتصر الإنجاز على الأقواس الظاهرة في الساحة؛ فقد امتد نظام نقل المياه لمسافة تزيد على 16 كيلومترًا من المصدر، بينما يبلغ طول الجزء المقوّس نحو 959 مترًا. ووضعت كتل الجرانيت في الأقواس من دون ملاط رابط؛ إذ يساهم توازن البناء وضغط الأحجار في تثبيتها."],["ES","Teide National Park","يكشف المنتزه عن تاريخ بركاني معقد في تينيريفي، وتساعد تضاريسه وارتفاعه على فهم تشكل الجزر البركانية.","تظهر الفوهات والتكوينات الصخرية المتعددة الألوان وسفوح جبل تيد وسط مشاهد بركانية شبه قاحلة.","https://whc.unesco.org/en/list/1258","يحتضن متنزه تيديه في جزيرة تينيريفي بركان تيديه–بيكو فييخو الطبقي، الذي ارتفع عبر مراحل متعاقبة من الثورانات وتراكم الحمم والمواد البركانية. تظهر حوله كالديرا لاس كانياداس وتكوينات من فترات مختلفة، ويبلغ ارتفاع قمته نحو 3718 مترًا، وهو أعلى موضع في إسبانيا. أُدرج المتنزه في قائمة التراث العالمي سنة 2007.","تمثل التضاريس المرتفعة بيئة مختلفة جذريًا عن شواطئ الجزيرة."],["GB","Buckingham Palace","يرتبط القصر بالمؤسسة الملكية البريطانية وبالاحتفالات والمناسبات الرسمية أكثر من ارتباطه بكونه مجرد مقر سكني.","تُعرف واجهته الرئيسية والشرفة المطلة على الساحة، وتبرز أمامه مساحة نصب الملكة فيكتوريا ومشهد تبديل الحرس.","https://www.rct.uk/visit/buckingham-palace","بدأ القصر منزلًا أرستقراطيًا عُرف باسم باكنغهام هاوس في أوائل القرن الثامن عشر، ثم شهد توسعات وتحويلات ملكية خلال القرنين الثامن عشر والتاسع عشر. وفي عام 1837 أصبحت الملكة فيكتوريا أول حاكم بريطاني يستخدم قصر باكنغهام مقرًا رسميًا للبلاط الملكي.","الشرفة الأمامية ارتبطت بالظهور الملكي في المناسبات العامة، لكن القصر ليس مجرد واجهة احتفالية؛ فهو مكان لاستقبال الضيوف الرسميين وإقامة فعاليات الدولة، مع اختلاف إتاحة بعض قاعاته للزيارة وفق البرامج الموسمية."],["GB","Edinburgh Castle","يعكس الحصن الدور الاستراتيجي للصخرة البركانية المرتفعة في تاريخ اسكتلندا السياسي والعسكري.","تُرى الأسوار والبطاريات الدفاعية وأبنية القصر التاريخي مع إطلالات مرتفعة على مدينة إدنبرة.","https://www.edinburghcastle.scot/","بدأ استخدام صخرة القلعة البركانية موضعًا محصنًا منذ العصور القديمة، ثم أصبحت القلعة مقرًا ملكيًا اسكتلنديًا بارزًا، خصوصًا في القرنين الخامس عشر والسادس عشر. وبعد حصار 1571–1573 ازدادت أهميتها العسكرية وتوسعت تحصيناتها؛ ولا تزال بعض أجزائها مرتبطة بالاستخدام العسكري.","تضم القلعة كنيسة القديسة مارغريت المبنية نحو عام 1130، وهي أقدم مبنى باقٍ في إدنبرة. كما وُلد فيها جيمس السادس سنة 1566، وتعرض جواهر التاج الاسكتلندي، ما يجعلها موقعًا ملكيًا وتاريخيًا يتجاوز وظيفة الدفاع."],["GB","Roman Baths (Bath)","تكشف الحمامات عن حضور الرومان في بريطانيا واستخدامهم الينابيع الساخنة في الطقوس والاستحمام والحياة الاجتماعية.","يمكن مشاهدة الحوض الكبير المحاط بالأروقة وبقايا المنشآت الرومانية المعروضة تحت مستوى الشوارع الحديثة.","https://www.romanbaths.co.uk/","استغل الرومان الينابيع الحارة الطبيعية لإقامة مجمع استحمام وعبادة.","المياه المعروضة جزء من موقع أثري وليست حمام سباحة عامًا."],["GB","Giant's Causeway","تتكون الأعمدة البازلتية من تبريد حمم بركانية قديمة وانكماشها، وهو تفسير جيولوجي يميز الموقع عن الأساطير المرتبطة به.","تظهر أعمدة حجرية متعددة الأضلاع متجاورة على الساحل، وبعضها يشكل درجات طبيعية قرب مياه الأطلسي.","https://whc.unesco.org/en/list/369","نشأت أعمدة البازلت في ممر العمالقة نتيجة نشاط بركاني قبل نحو 50 إلى 60 مليون سنة، حين بردت الحمم وانكمشت وتشققت إلى أعمدة متعددة الأضلاع. وأثارت تشكيلاته الساحلية حكايات شعبية عن عمالقة يعبرون البحر نحو إسكتلندا، قبل أن تفسرها الدراسات الجيولوجية الحديثة.","يتألف الموقع من نحو أربعين ألف عمود بازلتي، كثير منها سداسي الأضلاع وإن لم تكن كلها سداسية. نشأت أشكال الأعمدة حين بردت الحمم وانكمشت، وتُعد الطبقات البركانية المكشوفة مرجعًا علميًا لفهم تاريخ النشاط البركاني في شمال الأطلسي."],["US","Golden Gate Bridge","أصبح الجسر رمزًا للهندسة المعلقة في القرن العشرين ولصلة سان فرانسيسكو بسواحل شمال كاليفورنيا.","تظهر الأبراج والكوابل المعلقة واللون البرتقالي المميز فوق المضيق، مع تغير المنظر عند مرور الضباب الساحلي.","https://www.goldengate.org/bridge/","افتُتح الجسر سنة 1937 ليربط سان فرانسيسكو بمقاطعة مارين عبر مضيق البوابة الذهبية، وأصبح من أبرز مشاريع الجسور المعلقة في القرن العشرين.","اسم اللون المستخدم في طلاء الجسر هو «البرتقالي الدولي»؛ واختياره يجعل الهيكل مميزًا في مشهد الساحل الذي يكثر فيه الضباب."],["US","Yellowstone National Park","يحفظ المتنزه منظومة حرارية أرضية واسعة فوق منطقة بركانية نشطة جيولوجيًا، إلى جانب نظم بيئية للحياة البرية.","تتنوع المشاهد بين نافورات الماء الحار والبرك الملونة والوديان والشلالات والسهول التي تعيش فيها الحيوانات.","https://www.nps.gov/yell/index.htm","أُعلن يلوستون منتزهًا وطنيًا عام 1872، وأصبح محطة مهمة في تاريخ حماية المشاهد الطبيعية والظواهر الحرارية الأرضية في الولايات المتحدة.","تنتج الألوان المتدرجة حول بعض الينابيع الحارة، ومنها غراند بريزماتيك، عن مجتمعات ميكروبية محبة للحرارة، إلى جانب خصائص الماء والضوء."],["US","Empire State Building","يجسد المبنى طموح ناطحات السحاب في نيويورك خلال عصر آرت ديكو، وأصبح جزءًا من هوية أفق مانهاتن.","تظهر تفاصيل المدخل الزخرفية والكتلة المتدرجة للمبنى ومنصات مشاهدة تكشف شبكة شوارع المدينة.","https://www.esbnyc.com/","اكتمل تشييد المبنى عام 1931 بعد فترة بناء استغرقت عامًا و45 يومًا، وافتُتح في الأول من مايو من العام نفسه.","استُخدم البرج، إلى جانب وظائفه التجارية، في بث إشارات الإذاعة والتلفزيون، فأصبح جزءًا من البنية التقنية للمدينة."],["US","Hawaiʻi Volcanoes National Park","يحمي المتنزه مشاهد من نشاط بركاني تشكلت معه أجزاء من جزيرة هاواي، ويجمع بين أهمية جيولوجية وثقافية للسكان الأصليين.","يمكن رؤية حقول الحمم المتجمدة والفوهات والصدوع والتباين بين الصخور البركانية والغطاء النباتي.","https://www.nps.gov/havo/learn/news/hawaii-volcanoes-national-park-fact-sheet.htm","أُنشئت المنطقة المحمية ضمن متنزه هاواي الوطني سنة 1916، ثم أصبح متنزه براكين هاواي مستقلًا بعد فصل منطقة هاليكالا في ستينيات القرن العشرين. يضم المتنزه بركاني كيلاويا وماونا لوا، وتتجدد تضاريسه مع تدفقات الحمم والثورانات، بينما تحافظ إدارته على نظم بيئية وتقاليد ثقافية محلية مرتبطة بالمشهد البركاني.","يختلف شكل كيلاويا عن الصورة الشائعة للبركان المخروطي الحاد؛ فهو بركان درعي واسع المنحدرات، وترتبط فوهة هاليماوماو في التقاليد الهاوائية ببيليه إلهة البراكين. وتجدد الحمم أحيانًا أجزاء من سطحه؛ ولذلك ينبغي التمييز بين خصائصه الجيولوجية المستقرة وحالة الثوران المتغيرة."],["CN","Summer Palace (Beijing)","يعكس القصر الصيفي تقاليد تصميم الحدائق الإمبراطورية الصينية، حيث تتكامل المياه والتلال والمباني في منظر مقصود.","تبرز بحيرة كونمينغ والتلة الاصطناعية والممر الطويل والجسور والأجنحة المزخرفة الممتدة على ضفاف الماء.","https://whc.unesco.org/en/list/880/","أُنشئت الحديقة الإمبراطورية في بكين عام 1750 في عهد الإمبراطور تشيان لونغ، وكان اسمها الأصلي «حديقة التموجات الصافية». تعرض معظم مجمعها للتدمير خلال حرب عام 1860، ثم أُعيد ترميمه على أساساته القديمة منذ ثمانينيات القرن التاسع عشر، وارتبط لاحقًا بالإمبراطورة الأرملة تسيشي.","يعكس تصميمه تنسيق الحدائق الصينية بين الماء والتلال والعمارة."],["CN","Zhangjiajie National Forest Park","تشتهر المنطقة بأعمدتها الصخرية المرتفعة التي تشكلت عبر عمليات تعرية وتجوية طويلة في نطاق وولينغيوان.","تبدو الأعمدة الصخرية نحيلة ومتقاربة وسط الغابات والضباب، وتُظهر نقاط المشاهدة فروق الارتفاع الحادة.","https://whc.unesco.org/en/list/640","تطورت أعمدة الحجر الرملي الكوارتزي في منطقة وولينغيوان عبر رفع الصخور وتصدعها ثم نحت المياه والتجوية للفواصل عبر أزمنة جيولوجية طويلة. تحولت الكتل الصخرية إلى آلاف الأعمدة والقمم الرفيعة، ويفسر اختلاف مقاومة الصخور وتباعد الشقوق تنوع أشكالها. يُعد نطاق وولينغيوان، الذي يضم مشاهد تشانغجياجيه، موقعًا للتراث العالمي منذ عام 1992.","يضم نطاق وولينغيوان المدرج لدى اليونسكو أكثر من ثلاثة آلاف عمود وقمة من الحجر الرملي الكوارتزي، ويزيد ارتفاع كثير منها على مئتي متر. كما توجد أودية وجسور صخرية طبيعية وكهوف؛ وتشانغجياجيه جزء من هذا النطاق الأوسع وليست الاسم الرسمي لكامل موقع التراث العالمي."],["CN","Yu Garden","تعكس الحديقة أسلوب الحدائق الصينية التقليدية الذي يصمم مشاهد مصغرة من الصخور والمياه والأجنحة داخل فضاء محدود.","تظهر الصخور الزخرفية والبرك والجسور المتعرجة والأسقف المنحنية التي تنفتح منها مناظر متتابعة.","https://www.meet-in-shanghai.net/en/tourist-attraction/yuyuan-garden-998246/","بدأ المسؤول بان يون دوان إنشاء حديقة يو في شنغهاي سنة 1559 خلال أسرة مينغ، لتكون مكانًا هادئًا لوالديه. تطورت الحديقة عبر مراحل من البناء والتجديد، وشهدت أضرارًا وتغيّرات خلال اضطرابات القرنين التاسع عشر والعشرين، قبل أعمال ترميم حافظت على طابع حدائق جيانغنان التقليدية.","يعني اسم «يو» السكينة وإسعاد الوالدين، لا أنه اسم إمبراطور. وتجمع الحديقة بين الأجنحة والبرك والصخور المصممة بعناية؛ أما الأسواق ومجمعات التسوق المحيطة بمنطقة يو يوان فهي جزء من الحي الأوسع وليست كلها داخل الحديقة التاريخية."],["CN","Leshan Giant Buddha","يعكس التمثال تقاليد النحت البوذي الصخري في الصين وعلاقة الموقع بالتقاء الأنهار والطرق المائية القديمة.","يمكن ملاحظة ضخامة التمثال الجالس المنحوت في الجرف، وتفاصيل الرأس واليدين والقدمين مقارنة بحجم الزوار.","https://whc.unesco.org/en/list/779","نُحت تمثال بوذا العملاق في جرف صخري خلال عهد أسرة تانغ عند ملتقى ثلاثة أنهار، وهو موقع ارتبط تاريخيًا بالملاحة والمعتقدات البوذية.","لا تُفهم ضخامة التمثال بوصفها استعراضًا للنحت فحسب؛ فموقعه على ملتقى الأنهار يربط المعلم بمشهد مائي وجغرافي واسع."],["IN","Amber Fort","يُظهر الحصن تطور العمارة الملكية في راجستان، حيث تندمج التحصينات مع القاعات الزخرفية والباحات المرتفعة.","تتتابع الأفنية والبوابات وقاعة المرايا والتفاصيل الجصية فوق التلال المحيطة بأمير.","https://whc.unesco.org/en/list/247","نشأ حصن آمبر وتوسّع مقرًا لحكام المنطقة الراجبوتية قرب جايبور، حيث جمعت المنشآت بين الدفاع والحكم والإقامة الملكية.","يطل الحصن على بحيرة ماوتا من موقع مرتفع، بينما تكشف الأفنية المتتابعة وقاعة المرايا انتقال الزائر من التحصينات إلى الفضاءات القصرية."],["IN","Golden Temple","يُعد المجمع من أبرز المواقع المقدسة لدى السيخ، ويعبر عن مبادئ الضيافة والخدمة الجماعية المرتبطة بالتقاليد السيخية.","يظهر الحرم المذهب وسط حوض الماء المقدس وتنعكس واجهاته على سطحه، وتحيط به الممرات البيضاء.","https://sgpc.net/sri-harmandir-sahib-2/","تطوّر المجمع المقدس في أمريتسار حول حوض «أمريت ساروفار» خلال أواخر القرن السادس عشر، ثم أشرف المعلم السيخي الخامس غورو أرجان على تشييد المعبد المركزي. وفي سنة 1604 وُضع فيه «آدي غرانث»، النص المقدس الذي أصبح لاحقًا أساس غورو غرانث صاحب، وترسخت مكانة المعبد مركزًا روحيًا للسيخ.","تشكل خدمة الطعام المجاني الجماعي جانبًا مهمًا من تقاليد المكان."],["IN","Gateway of India","أصبح القوس المطل على بحر العرب أحد رموز مومباي الحديثة، ويرتبط بتاريخ المدينة خلال الحكم البريطاني.","تُلاحظ الأقواس والزخارف الحجرية المطلة على الواجهة البحرية، مع حركة القوارب ومشهد الميناء القريب.","https://mumbaicity.gov.in/en/tourist-place/gateway-of-india/","أُقيمت بوابة الهند على واجهة مومباي البحرية تخليدًا للزيارة الملكية التي قام بها جورج الخامس والملكة ماري عام 1911، ووضع حجر الأساس في العام نفسه. صمم المعماري جورج ويتت القوس بأسلوب هندي-ساراسيني يمزج عناصر معمارية متعددة، واكتمل بناؤه عام 1924 خلال الحكم البريطاني.","يبلغ ارتفاع القوس نحو 26 مترًا ويطل على منطقة أبولو بندر في جنوب مومباي. ويختلف اسم «بوابة الهند» هنا عن «بوابة الهند» التذكارية في نيودلهي؛ فهما معلمان منفصلان بتاريخ ووظيفة وموقع مختلفين."],["IN","Group of Monuments at Hampi","تكشف آثار هامبي عن عاصمة إمبراطورية فيجاياناغارا وما بلغته من تقدم في المعابد والتخطيط الحضري والتجارة.","تظهر المعابد ذات الأبراج والنقوش والعربات الحجرية والمدرجات الصخرية الممتدة وسط التلال.","https://whc.unesco.org/en/list/241","كانت هامبي عاصمة إمبراطورية فيجاياناغارا التي ازدهرت بين القرنين الرابع عشر والسادس عشر في جنوب الهند. شُيدت فيها مجمعات معابد وقصور وأسواق ومنشآت مائية ضخمة، ثم تعرضت المدينة للنهب بعد هزيمتها أمام تحالف من سلطنات الدكن سنة 1565، وبقيت آثارها شاهدًا على ازدهارها السابق.","العربة الحجرية الشهيرة أمام معبد فيتّالا جزء من عمارة دينية أوسع، وليست عربة معدّة للانتقال. ويكشف الموقع أيضًا عن شوارع احتفالية مصطفة بالأعمدة، وخزانات مياه متدرجة وقنوات مائية، ما يوضح تطور التنظيم العمراني والهندسة في عاصمة فيجاياناغارا."],["AE","Burj Al Arab","يمثل الفندق تجربة معمارية حديثة استخدمت هيئة الشراع لتكوين معلم بصري على ساحل دبي.","تبرز الواجهة المنحنية على جزيرة اصطناعية صغيرة وموقعها مقابل الشاطئ، خاصة في المشاهد البعيدة.","https://mediahub.jumeirah.com/from-sand-to-skyline/?lang=eng","صُمّم برج العرب في تسعينيات القرن العشرين ليكون رمزًا معماريًا لدبي، واستلهم المعماري توم رايت هيئته من شراع السفن التقليدية المرتبطة بتاريخ الخليج البحري. شُيّد على جزيرة اصطناعية متصلة بالبر بجسر خاص، وافتُتح عام 1999 مع صعود دبي وجهةً سياحية عالمية.","يرتفع المبنى نحو 321 مترًا، ويُعرف بتصميم الشراع وأجنحته الفندقية. ووصفه الشائع بأنه «سبع نجوم» تعبير إعلامي عن الفخامة وليس تصنيفًا فندقيًا رسميًا معتمدًا."],["AE","Louvre Abu Dhabi","يقدم المتحف نموذجًا للتبادل الثقافي بين الحضارات عبر مجموعاته ومعارضه، ضمن عمارة تجمع بين الضوء والماء والقباب.","تُكوّن القبة المعدنية المثقبة ظلالًا هندسية متغيرة على المباني والممرات البيضاء المحاطة بالماء.","https://www.louvreabudhabi.ae/","افتُتح لوفر أبوظبي سنة 2017 في جزيرة السعديات، ليعرض أعمالًا فنية من حضارات مختلفة في مبنى صممه جان نوفيل.","تتسلل أشعة الشمس عبر طبقات القبة ذات الفتحات الهندسية لتُحدث ما يُعرف معماريًا بتأثير «مطر الضوء» داخل الممرات."],["AE","Al Fahidi Historical Neighbourhood","يحفظ الحي نمطًا من عمران دبي السابق للطفرة الحديثة، وخاصة البيوت التقليدية المرتبطة بالتجارة والبيئة الساحلية.","تظهر الأبراج الهوائية والأفنية والممرات الضيقة والجدران الجصية التي ساعدت على التكيف مع المناخ.","https://www.visitdubai.com/en/places-to-visit/al-fahidi-historical-neighbourhood","يحافظ الحي على شواهد من دبي السابقة للتوسع العمراني الحديث.","تعكس أزقته الضيقة نمط حياة مرتبطًا بالتجارة والسكن في الخليج."],["AE","Sharjah Museum of Islamic Civilization","يتيح المتحف قراءة جوانب من العلوم والفنون والحياة اليومية في الحضارات الإسلامية عبر مقتنيات متنوعة.","يمكن مشاهدة المصاحف والمخطوطات والأدوات العلمية والخزف والمعادن، إضافة إلى تفاصيل القبة الداخلية.","https://www.sharjahmuseums.ae/en-US/museums/sharjah-museum-of-islamic-civilization","افتتح متحف إسلامي في منطقة التراث بالشارقة سنة 1996، ثم نُقلت مجموعاته إلى مبنى سوق المجرة السابق الذي أعيد تهيئته للعرض المتحفي. وافتتح الموقع بصورته الحالية تحت اسم متحف الشارقة للحضارة الإسلامية في 6 يونيو 2008، ليعرض نماذج من تاريخ العلوم والفنون والحياة الدينية.","المبنى كان سوقًا تقليديًا قبل تحويله إلى متحف، ويحتوي اليوم على آلاف المقتنيات موزعة في قاعات موضوعية. وتتيح معروضات الأدوات الفلكية والمخطوطات والخزف فهم تنوع الحضارة الإسلامية عبر مناطق وعصور مختلفة."],["TH","Wat Phra That Doi Suthep","يُعد المعبد من أبرز الرموز الدينية في شيانغ ماي، ويرتبط بتقاليد بوذية محلية وموقع مرتفع على الجبل.","تظهر الستوبا الذهبية والسلالم المزخرفة بدرابزين على هيئة أفاعٍ أسطورية، مع إطلالات على المدينة.","https://www.tourismthailand.org/Attraction/wat-phra-that-doi-suthep","نشأ معبد فرا ذات دوي سوثيب في أواخر القرن الرابع عشر على جبل يطل على شيانغ ماي، ليصبح من أبرز مواقع الحج البوذي في شمال تايلاند. وتربط الرواية التقليدية اختيار المكان بفيل أبيض حمل ذخيرة دينية ثم توقف عند موضع المعبد؛ وهي قصة تراثية دينية لا تُقدَّم بوصفها حدثًا تاريخيًا مثبتًا.","تؤدي إلى المعبد سلالم مزينة بدرابزين على هيئة أفاعٍ أسطورية «ناغا»، وتبرز في قلبه ستوبا ذهبية تحفظ رمزية الذخيرة المقدسة. والزيارة جزء من تجربة دينية حية وليست مجرد مشاهدة لعمارة تاريخية."],["TH","Sukhothai Historical Park","تكشف آثار سوخوثاي عن مرحلة مبكرة مهمة في تاريخ الممالك التايلاندية وتطور فنونها الدينية.","تنتشر تماثيل بوذا والستوبات والمعابد الحجرية وسط برك وأشجار ومساحات مفتوحة.","https://whc.unesco.org/en/list/574","كانت سوكوتاي مركزًا سياسيًا لمملكة ازدهرت في القرنين الثالث عشر والرابع عشر، وأسهمت في نشوء طراز معماري وفني تايلاندي مميز تأثر بتقاليد محلية وإقليمية. وتضم المنطقة التاريخية معابد وآثارًا ارتبطت أيضًا بمدينتي سي ساتشانالاي وكامفينغ فيت ضمن التراث العالمي.","تدرج اليونسكو سوخوثاي ضمن موقع تراث عالمي متسلسل يضم ثلاث مدن تاريخية مترابطة: سوخوثاي، وسي ساتشانالاي، وكامفينغ فيت. وكانت الأولى مركز الحكم، والثانية مركزًا دينيًا وصناعة الفخار، والثالثة موقعًا استراتيجيًا على طرق الاتصال والدفاع."],["TH","Railay Beach","تكمن خصوصية رايلاي في الجروف الجيرية التي تفصل شبه الجزيرة عن الطرق البرية المباشرة، فتكون القوارب وسيلة الوصول المعتادة.","تظهر المنحدرات الكارستية العالية فوق الشواطئ والمياه، مع كهوف ومسارات قصيرة بين الخلجان.","https://thai.tourismthailand.org/Attraction/%E0%B8%AD%E0%B9%88%E0%B8%B2%E0%B8%A7%E0%B9%84%E0%B8%A3%E0%B9%88%E0%B9%80%E0%B8%A5%E0%B8%A2%E0%B9%8C","تقع شبه جزيرة رايلي بين جروف كلسية تجعل الوصول البري إليها محدودًا.","تُظهر المنطقة تضاريس كارستية ساحلية تميز بحر أندامان."],["TH","Jim Thompson House","يعرض المنزل طريقة جمع بيوت تايلاندية خشبية تقليدية وتحويلها إلى مجمع سكني ومتحفي مرتبط بتاريخ الحرير التايلاندي.","تظهر البيوت الخشبية المرتفعة والأسقف المائلة والأثاث والتحف داخل حديقة استوائية في بانكوك.","https://www.jimthompsonhouse.org/","يجمع المتحف منازل خشبية تايلاندية تقليدية أعيد تجميعها في بانكوك.","توضح العمارة المحلية أسلوب التهوية والارتفاع عن مستوى الأرض."],["ID","Tegallalang Rice Terrace","تعكس المدرجات أساليب استغلال المنحدرات لزراعة الأرز في بالي، ضمن تقاليد ري مشتركة محلية.","تتدرج حقول الأرز الخضراء على جوانب الوادي في خطوط متعرجة، وتظهر قنوات الماء على المنحدرات.","https://whc.unesco.org/en/list/1194","توضح مدرجات تيغالالانغ قرب أوبود كيف يكيّف مزارعو بالي المنحدرات لزراعة الأرز عبر تقسيم الأرض إلى مصاطب وقنوات ري صغيرة. وينتمي هذا المشهد إلى تراث زراعي أوسع يقوم على تعاون المزارعين في إدارة المياه، ويُعرف محليًا بتقاليد «سوباك» التي تربط الري بالحياة الاجتماعية والطقوس الدينية.","أدرجت اليونسكو سنة 2012 خمسة مكوّنات مختارة من المشهد الثقافي لنظام سوباك في بالي، وليس معنى ذلك أن مدرجات تيغالالانغ نفسها موقع تراث عالمي منفصلًا. وتغيّر مواسم زراعة الأرز لون المدرجات وشكلها، لذلك لا يظهر المشهد أخضر بالدرجة نفسها طوال العام."],["ID","Komodo National Park","يحمي المتنزه موائل تنين كومودو إلى جانب نظم بحرية وجزرية متعددة، وهو من أهم مواقع التنوع الحيوي في المنطقة.","تتنوع مناظره بين التلال الجافة والشواطئ والمياه الصافية، وقد تُشاهد سحالي كومودو في نطاقات محمية.","https://whc.unesco.org/en/list/609","بدأت حماية أجزاء من جزر كومودو ورينكا وبادار قبل إنشاء المتنزه الوطني رسميًا عام 1980 لحماية تنين كومودو وموائله. ثم توسعت الحماية لتشمل مساحات بحرية وشعابًا مرجانية ومجتمعات طبيعية في منطقة انتقال بين النظم الحيوية الآسيوية والأسترالية. وأُدرج المتنزه في قائمة التراث العالمي سنة 1991.","يعيش تنين كومودو في مناطق طبيعية محددة من الأرخبيل الإندونيسي."],["ID","Mount Bromo","يبرز برومو ضمن مشهد بركاني من الفوهات والرمال البركانية في منطقة تنغر بشرق جاوة.","تظهر فوهة البركان والدخان المتصاعد أحيانًا فوق بحر الرمال، مع قمم مجاورة تُرى عند الشروق.","https://www.indonesia.travel/id/en/travel-ideas/adventure/bromo-tengger-semeru-national-park---yadnya-kasada-ceremony","يقع بركان برومو النشط داخل كالديرا تنغر الواسعة في جاوة الشرقية، حيث تغطي الرواسب البركانية أرضية تُعرف باسم «بحر الرمال». ولم يقتصر أثر الجبل على الجغرافيا؛ فقد نشأت حوله تقاليد دينية لدى شعب التنغر، ومنها طقس «يادنيا كاسادا» الذي تُقدَّم خلاله قرابين رمزية عند حافة الفوهة تعبيرًا عن الامتنان وطلب البركة، وفق روايات محلية متوارثة.","ترتبط المنطقة بتقاليد شعب التنغر، ولذلك يحمل الجبل قيمة ثقافية محلية بجانب قيمته الجيولوجية ومشاهده البركانية."],["ID","Lake Toba","نشأت البحيرة داخل منخفض بركاني هائل، وهي معلم مهم لفهم تاريخ النشاط البركاني في سومطرة.","تظهر البحيرة الواسعة تحيط بها المرتفعات، وتتوسطها جزيرة ساموسير التي تضم قرى من ثقافة الباتاك.","https://www.unesco.org/en/iggp/toba-caldera-unesco-global-geopark","تكونت كالديرا توبا العملاقة في شمال سومطرة عبر سلسلة ثورانات بركانية، وكان أكبرها في المرحلة الأخيرة قبل نحو 74 ألف سنة. انهارت أجزاء من سقف حجرة الصهارة، ثم امتلأ المنخفض بالمياه مشكلًا بحيرة توبا، بينما أسهم ارتفاع لاحق في قاع الكالديرا في ظهور جزيرة ساموسير الكبيرة وسطها. ويحمل المشهد المحيط أيضًا تراث مجتمعات الباتاك.","يوضح حجم البحيرة الأثر الهائل للعمليات البركانية القديمة."],["KR","Changdeokgung","يُظهر القصر كيف تكيّفت العمارة الملكية في عصر جوسون مع التضاريس والأشجار بدل فرض محور هندسي صارم دائمًا.","تتدرج القاعات والأسقف التقليدية إلى الحديقة الخلفية المعروفة بهوون، حيث البرك والأجنحة بين الأشجار.","https://whc.unesco.org/en/list/816","شُيّد قصر تشانغدوكغونغ في أوائل القرن الخامس عشر خلال عهد جوسون، وتكشف مساحاته عن أسلوب إقامة المباني الملكية بين التلال والأشجار.","حملت الحديقة الخلفية «هوون» وظيفة ملكية خاصة؛ ويُلاحظ فيها اندماج البرك والأجنحة ومسارات الغابة مع تضاريس القصر."],["KR","Haedong Yonggungsa","يتميز المعبد البوذي بموقعه الساحلي الصخري، على خلاف الصورة الشائعة للمعابد الجبلية في كوريا.","تظهر السلالم والبوابات وتماثيل بوذا والأجنحة فوق الصخور المطلة مباشرة على البحر.","https://english.visitkorea.or.kr/","ترجع رواية تأسيس المعبد الساحلي في بوسان إلى سنة 1376 خلال عهد غوريو، وتنسب بدايته إلى الراهب ناونغ. تعرض الموقع للدمار أثناء الغزوات اليابانية لكوريا في أواخر القرن السادس عشر، ثم أُعيد بناؤه في القرن العشرين. وتعود التسمية الحالية «هايدونغ يونغغونغسا» إلى مرحلة ترميمه في سبعينيات القرن الماضي.","يضم مدخل المعبد الساحلي تماثيل حيوانات الأبراج الاثني عشر في التقليد الكوري، ويقود إلى ساحاته درج مشهور من 108 درجات. وتذكر هيئة السياحة الكورية أن الجسر والمنحوتات جزء من المشهد التعبدي، بينما تعكس إطلالته البحرية موقعًا مختلفًا عن معظم المعابد الجبلية."],["KR","Hallasan","الجبل البركاني هو أعلى قمة في كوريا الجنوبية ويشكل محورًا طبيعيًا لجزيرة جيجو وتنوع نظمها البيئية.","تتبدل المناظر من الغابات الجبلية إلى الصخور البركانية والمروج المرتفعة وفوهة القمة.","https://whc.unesco.org/en/list/1264","هالاسان بركان درعي يشغل وسط جزيرة جيجو، وتشكلت تضاريسه في سياق مراحل من النشاط البركاني الذي بنى الجزيرة.","تتغير النظم البيئية مع الارتفاع على منحدرات الجبل، من الغابات إلى النباتات التي تتحمل الظروف الأبرد قرب القمة."],["KR","Hwaseong_Fortress","تعكس أسوار هواسونغ في سوون محاولة تطوير التحصينات الكورية في أواخر القرن الثامن عشر باستخدام أفكار دفاعية جديدة.","تلتف الأسوار حول أجزاء من المدينة، وتتخللها بوابات وأبراج مراقبة ومنشآت دفاعية حجرية وخشبية.","https://whc.unesco.org/en/list/817","أمر الملك جيونغجو بتشييد قلعة هواسونغ في سوون بين عامي 1794 و1796، ضمن مشروع عمراني ارتبط بنقل قبر والده إلى المنطقة.","أُدرجت قلعة هواسونغ ضمن قائمة التراث العالمي لليونسكو، باعتبارها مثالًا مهمًا على عمارة التحصينات في أواخر عصر جوسون."],["VN","Marble Mountains (Vietnam)","تجمع التلال الخمس قرب دا نانغ بين بيئة صخرية من الحجر الجيري والرخام ومواقع تعبّد تاريخية داخل الكهوف.","تظهر الكهوف المفتوحة للضوء والدرجات الحجرية والمعابد الصغيرة بين التلال والأشجار.","https://vietnam.travel/things-to-do/around-marble-mountains/","تُعرف جبال الرخام باسم نغو هانه سون، وهي خمس تلال من الحجر الجيري والرخام قرب دا نانغ، تحمل أسماء عناصر الطبيعة الخمسة في التقليد الفيتنامي.","الجبال ليست قمة واحدة؛ بل مجموعة من خمس تلال متجاورة، وقد استُخدمت كهوفها لأغراض روحية عبر قرون."],["VN","Tràng An Scenic Landscape Complex","يجمع ترانغ آن بين أبراج الحجر الجيري والكهوف والأنهار وآثار استيطان بشري قديم، لذلك يحمل قيمة طبيعية وثقافية معًا.","تمر المسارات المائية بين جروف شاهقة وفتحات كهوف ومزارع وأودية خضراء.","https://whc.unesco.org/en/list/1438","تجمع ترانغ آن في نينه بينه بين جبال كارستية وأنهار وممرات كهفية ومواقع تاريخية قديمة، وأُدرجت ضمن التراث العالمي بوصفها موقعًا ثقافيًا وطبيعيًا مختلطًا.","تسمح المجاري المائية لبعض القوارب الصغيرة بالعبور عبر كهوف تحت جبال الحجر الجيري، في مشهد يربط الجيولوجيا بتاريخ الاستيطان."],["VN","Sơn Đoòng Cave","يشتهر الكهف بضخامة بعض فراغاته الداخلية ووجود ظواهر مثل فتحات السقف التي تسمح بنمو نباتات داخلية.","تظهر كتل الصخور والهوابط والنهر الجوفي وفتحات الضوء التي تكشف حجم القاعات الهائلة.","https://oxalisadventure.com/the-exploration-of-hang-son-doong","تشكّل كهف سون دونغ داخل صخور الحجر الجيري في نطاق فونغ نها–كي بانغ نتيجة عمل المياه الجوفية عبر فترات جيولوجية طويلة. عثر هو خانْه على مدخله عام 1990، ثم ساعد فريقًا من مستكشفي الكهوف البريطانيين على الوصول إليه واستكشافه عام 2009. كشفت البعثات عن ممرات هائلة ونهر جوفي وفتحات انهيار تسمح للضوء والنباتات بالدخول، وأظهرت أهمية الكهف لدراسة تطور الأنظمة الكارستية.","تسمح فتحات السقف في بعض المواضع بدخول الضوء ونمو النباتات."],["VN","Independence Palace","يرتبط القصر بتاريخ سايغون السياسي وبأحداث أبريل 1975، ويعد شاهدًا على العمارة الرسمية في جنوب فيتنام خلال القرن العشرين.","تظهر الواجهة ذات الحواجز الأفقية والقاعات الرسمية والمساحات الخضراء المحيطة بالمبنى.","https://dinhdoclap.gov.vn/en/","بُني قصر الاستقلال الحالي في سايغون بعد تضرر القصر السابق سنة 1962، وافتُتح سنة 1966 ليكون مقرًا للحكم في جمهورية فيتنام آنذاك.","يعرض القصر قاعات رسمية وغرف عمليات ومرافق اتصالات تعكس وظائفه السياسية والعسكرية في القرن العشرين."],["EG","Egyptian Museum","يتميز المتحف المصري بالتحرير بأنه أحد أقدم المتاحف المخصصة للآثار المصرية القديمة في مبنى أُنشئ لهذا الغرض، وتساعد مجموعاته على فهم الحياة اليومية والطقوس والفنون عبر عصور متعددة.","يستحق تأمل البهو المركزي والتماثيل الضخمة والتوابيت والقطع الصغيرة مثل الحلي والبرديات؛ فهي تُظهر تنوع المقتنيات بعيدًا عن المعالم الحجرية.","https://egymonuments.gov.eg/museums/egyptian-museum/","افتُتح مبنى المتحف في ميدان التحرير سنة 1902 ليعرض آثار مصر القديمة في مقر صُمم لهذا الغرض.","يساعد تنوع القطع على فهم الحياة المصرية القديمة خارج آثار الأهرامات وحدها."],["EG","Al-Azhar Mosque","يجمع الأزهر بين مكانته الدينية ودوره التعليمي الممتد منذ العصر الفاطمي، كما تشهد إضافاته المعمارية على تعاقب عصور حكم القاهرة.","يمكن ملاحظة اختلاف طرز المآذن والبوابات التاريخية، والفناء الرخامي والأروقة المحيطة به.","https://whc.unesco.org/en/list/89","تأسس الجامع الأزهر في القرن العاشر مع قيام القاهرة الفاطمية.","يعكس اختلاف المآذن والأروقة تعاقب العصور المعمارية على المبنى."],["EG","Hanging Church","تُبرز الكنيسة المعلقة استمرارية التراث القبطي في مصر القديمة وارتباطه بموقع حصن بابليون الروماني.","تظهر الأيقونات والحواجز الخشبية المنقوشة والسقف الخشبي وتفاصيل البناء المرتفع فوق أجزاء من الحصن القديم.","https://egymonuments.gov.eg/monuments/the-hanging-church/","يرجع تاريخ الكنيسة المعلقة إلى أواخر القرن الرابع أو أوائل الخامس الميلادي، وشهدت مبانيها وتجهيزاتها تغيرات وترميمات عبر القرون.","داخل الكنيسة منبر رخامي تاريخي، وهو أحد العناصر الفنية المميزة إلى جانب الأيقونات والحواجز الخشبية المنقوشة."],["EG","Luxor Temple","يرتبط معبد الأقصر بطقوس ملكية ودينية في طيبة القديمة، وكان جزءًا من المشهد المقدس الذي يصل إلى الكرنك.","تُظهر واجهته الصرح الضخم وتماثيل رمسيس الثاني والأعمدة والفناء، ويمكن تتبع امتداد طريق الكباش باتجاه الكرنك.","https://whc.unesco.org/en/list/87","تكون المعبد عبر مراحل متعاقبة؛ فترجع نواته الكبرى إلى عهد أمنحتب الثالث، ثم أضاف رمسيس الثاني الصرح والفناء الأمامي والتماثيل الضخمة. وارتبط المعبد بعيد الأوبت الذي انتقلت خلاله مواكب تماثيل ثالوث طيبة المقدس من الكرنك إلى الأقصر في احتفال ديني مهم.","على خلاف معابد كثيرة اتخذ المعبد اتجاهًا مرتبطًا بمجمع الكرنك ومسار المواكب. وأمام صرح رمسيس الثاني كانت مسلتان؛ لا تزال إحداهما في الأقصر بينما توجد الأخرى اليوم في ميدان الكونكورد بباريس."],["EG","Philae Temple","يمثل مجمع فيلة موقعًا مهمًا لعبادة إيزيس، كما أن نقل معابده يعكس أحد أبرز مشروعات إنقاذ الآثار من آثار إنشاء السد العالي.","تستحق المشاهدة الأعمدة والنقوش وموقع المعابد وسط الماء على جزيرة أجيليكا، مع تباين الأحجار والمناظر النيلية.","https://whc.unesco.org/en/list/88","ازدهرت عبادة الإلهة إيزيس في مجمع فيلة خلال العصور البطلمية والرومانية، ثم تعرض الموقع الأصلي في النيل لخطر الغمر عقب مشروعات السدود بأسوان. وفي إطار حملة دولية لإنقاذ آثار النوبة، بدأت أعمال إنقاذ المعابد ونقلها إلى جزيرة أجيليكا المجاورة في سبعينيات القرن العشرين، بعد تفكيك المباني وإعادة تركيبها.","المجمع الذي يشاهده الزائر اليوم ليس في موضعه النهري الأصلي؛ فقد أُعيد بناء معابده على أجيليكا حفاظًا على النقوش والمنشآت. لذلك يُعدّ فيلة شاهدًا مزدوجًا على التاريخ الديني المصري القديم وعلى تقنيات صون التراث في العصر الحديث."],["EG","Wadi El Rayan","يجمع وادي الريان بين البحيرات الصحراوية والتشكيلات الرملية والموائل الطبيعية، ويبرز التباين بين الماء والصحراء في الفيوم.","يمكن مشاهدة الشلالات بين البحيرتين والمنحدرات والكثبان الرملية ومظاهر الحياة الطبيعية حول المياه.","https://www.eeaa.gov.eg/Uploads/Topics/Files/20221213131818469.pdf","تضم محمية وادي الريان بحيرتين وشلالات بينهما ومناطق صحراوية واسعة.","تُظهر المنطقة التقاء البيئات المائية والكثبان والتكوينات الصحراوية."],["EG","Saint Catherine's Monastery","يمثل الدير شاهدًا مهمًا على استمرار الرهبنة المسيحية في سيناء وتراث المخطوطات والأيقونات القديمة في موقع ذي أهمية دينية استثنائية.","تظهر الأسوار الحجرية وكنيسة التجلي ومباني الدير وسط الجبال الجرانيتية الشاهقة.","https://whc.unesco.org/en/list/954","تأسس دير سانت كاترين في القرن السادس الميلادي في العصر البيزنطي عند سفح جبل سيناء، وتُربط نشأة أسواره الكبرى بعهد الإمبراطور جستنيان. حافظ الدير على دوره الديني قرونًا طويلة، وأصبحت مكتبته ومجموعاته من المخطوطات والأيقونات مصادر مهمة لدراسة الفن المسيحي المبكر والتاريخ البيزنطي.","لا تقتصر قيمة الموقع على مبنى الدير؛ إذ يضم نطاق التراث العالمي مشهدًا جبليًا ومواقع دينية وأثرية ترتبط بتقاليد دينية لدى المسلمين والمسيحيين واليهود. ويُعد استمرار نشاط الدير منذ القرن السادس من أبرز سماته التاريخية."],["FR","Musée d'Orsay","يُظهر المتحف كيف أمكن تحويل محطة قطارات تاريخية إلى فضاء فني يحفظ جانبًا بارزًا من فن القرن التاسع عشر، خصوصًا الانطباعية وما حولها.","تُلفت الساعة الكبيرة والسقف المقوّس والممرات الواسعة النظر، إلى جانب لوحات لفنانين مثل مونيه ورينوار.","https://www.musee-orsay.fr/en","أُعيد توظيف محطة قطارات بُنيت لمعرض باريس العالمي سنة 1900 لتصبح متحفًا.","وجود ساعة المحطة القديمة يذكّر بالوظيفة الأصلية للمبنى."],["FR","Sacré-Cœur, Paris","ترتبط البازيليكا بتاريخ فرنسا في أواخر القرن التاسع عشر، ويمنحها موقعها المرتفع على مونمارتر حضورًا بصريًا فوق باريس.","تظهر القباب البيضاء وواجهتها ذات الطراز الروماني البيزنطي والمشهد الواسع للمدينة من الساحة الأمامية.","https://www.sacre-coeur-montmartre.com/decouvrir/notre-histoire/les-grandes-etapes-de-la-construction/","وُضع حجر أساس بازيليكا القلب المقدس على تلة مونمارتر عام 1875 بعد مشروع نذر ديني وطني ظهر في سياق حرب فرنسا وبروسيا. فاز بول أبادِي بمسابقة التصميم سنة 1874، ثم واصل معماريون آخرون العمل بعد وفاته. وتأخر تكريس الكنيسة بسبب الحرب العالمية الأولى حتى 16 أكتوبر 1919.","اختير للكنيسة طراز روماني-بيزنطي وتخطيط بصليبي يوناني، وبدأت فيها شعائر دينية قبل اكتمال جميع عناصر البناء. لذلك ينبغي التفريق بين وضع حجر الأساس سنة 1875، وبدء الاستخدام الديني، وتاريخ التكريس النهائي سنة 1919."],["FR","Promenade des Anglais","يعكس ممشى الإنجليز تحول نيس إلى وجهة ساحلية دولية منذ القرن التاسع عشر، وأصبح جزءًا من هوية عمران الريفييرا الفرنسية.","يتتابع الشاطئ الحصوي وخليج الملائكة والمباني ذات الواجهات التاريخية ومقاعد الجلوس على امتداد الواجهة البحرية.","https://whc.unesco.org/en/list/1635","بدأ ممشى الإنجليز في نيس مسارًا متواضعًا على الساحل ساهم زوار بريطانيون يقضون الشتاء في إنشائه سنة 1824، ثم توسّع تدريجيًا مع نمو المدينة كمنتجع شتوي أوروبي. وفي القرن التاسع عشر ساهمت مخططات التحسين العمراني وارتباط نيس بشبكة السكك الحديدية في تحويل الطريق الساحلي إلى واجهة حضرية مميزة.","ترتبط التسمية بالزوار البريطانيين الذين اعتادوا قضاء الشتاء في نيس قبل انتشار السياحة الشاطئية الصيفية. وأُدرجت نيس سنة 2021 لدى اليونسكو بوصفها «مدينة منتجع شتوي في الريفييرا»؛ فالممشى عنصر من مشهد المدينة التراثي وليس موقع يونسكو مستقلًا."],["FR","Cité de Carcassonne","تكشف المدينة المحصنة عن عمارة الدفاع في العصور الوسطى وعن أثر الترميم التاريخي الواسع خلال القرن التاسع عشر.","تبرز الحلقتان من الأسوار والأبراج والبوابات الحجرية وممرات البلدة الضيقة خلف التحصينات.","https://whc.unesco.org/en/list/345","تطورت تحصينات كاركاسون فوق أسوار تعود إلى العصور الرومانية المتأخرة، ثم توسعت في القرون الوسطى وأُضيفت إليها القلعة والأسوار المزدوجة. وفي القرن التاسع عشر قاد المعماري فيوليه لو دوك ترميمًا طويلًا غيّر فهم الحفاظ على المباني التاريخية وأعاد إبراز طابع المدينة المحصنة.","يجب التمييز بين العناصر التاريخية القديمة والأجزاء التي أُعيد ترميمها."],["FR","Place de la Bourse","تُعد الساحة مثالًا للعمارة الحضرية المتناظرة في بوردو خلال القرن الثامن عشر، وترتبط بهوية الميناء التاريخي على نهر الغارون.","يظهر انتظام الواجهات الحجرية والنافورة في وسط الساحة، وتنعكس المباني على سطح مرآة الماء المجاورة.","https://whc.unesco.org/en/list/1256","تُجسد ساحة البورصة التخطيط العمراني الكلاسيكي لبوردو في القرن الثامن عشر.","المرآة المائية عنصر معاصر يبرز المباني التاريخية، وليست جزءًا أصليًا منها."],["FR","Strasbourg Cathedral","تُعد كاتدرائية نوتردام في ستراسبورغ أحد أبرز نماذج العمارة القوطية في منطقة الراين، وهي شاهد على تاريخ الألزاس بوصفها منطقة تلاقت فيها التأثيرات الثقافية الفرنسية والألمانية. وتمتزج في المبنى بقايا من الطراز الرومانسكي مع مراحل البناء القوطي اللاحقة.","من ساحة الكاتدرائية يمكن تتبع المنحوتات المحيطة بالمداخل الثلاثة والنافذة الوردية الكبيرة أعلى الواجهة. وداخلها تبرز النوافذ الزجاجية الملونة والمنبر القوطي والساعة الفلكية ذات الأشكال المتحركة. كما تتيح منصة المشاهدة رؤية مدينة ستراسبورغ من أعلى.","https://www.visitstrasbourg.fr/en/discover/must-see-attractions/the-cathedral/","بدأ بناء كاتدرائية رومانسكية في الموقع سنة 1015، ثم شُيدت أجزاء كبيرة من المبنى الحالي على مراحل منذ القرن الثاني عشر. وبدأ العمل في الواجهة الغربية في القرن الثالث عشر، واكتمل برجها المدبب سنة 1439، بعد قرون من التطوير المعماري.","يصل ارتفاع البرج المدبب إلى نحو 142 مترًا، وكان من أعلى المباني في العالم لقرون. أما الساعة الفلكية الحالية فتضم آلية تعود إلى سنة 1842، وتجمع بين قياس الزمن والحسابات الفلكية والعرض الميكانيكي."],["FR","Lascaux","تمثل رسومات لاسكو شاهدًا على فنون البشر في العصر الحجري القديم، وتقدم صور الحيوانات والأشكال دليلًا مهمًا لدراسة التعبير البصري المبكر.","تظهر رسوم الثيران والخيول والغزلان على جدران الكهف؛ والزيارة العامة تكون لنسخ تفسيرية حفاظًا على الكهف الأصلي.","https://lascaux.fr/en/history-of-lascaux/","اكتشف أربعة مراهقين كهف لاسكو في منطقة مونتينياك الفرنسية يوم 12 سبتمبر 1940، وكشفت رسومه عن جانب غني من التعبير الفني لدى إنسان العصر الحجري القديم. فُتح الكهف للجمهور عام 1948، لكن تغيرات الرطوبة وثاني أكسيد الكربون والطحالب المرتبطة بكثرة الزيارات أسهمت في إغلاق الأصل عام 1963 لحماية الرسوم.","الكهف الأصلي ليس مفتوحًا للزيارة السياحية. بدلًا منه تعرض «لاسكو 2» منذ 1983 نسخة من أجزاء شهيرة، بينما يقدم مركز «لاسكو 4» منذ 2016 إعادة إنشاء أوسع للكهف مع وسائل شرح علمية؛ أي إن التجربة الحالية لا تعني دخول الموقع الأصلي."],["IT","Castel Sant'Angelo","تغيّرت وظيفة قلعة سانت أنجلو عبر القرون من ضريح إمبراطوري إلى حصن ومقر بابوي، ما جعلها سجلًا معماريًا متعدد الطبقات.","يمكن تتبع الشكل الأسطواني الضخم والتحصينات اللاحقة والممرات الداخلية والإطلالة على جسر سانت أنجلو ونهر التيبر.","https://direzionemuseiroma.cultura.gov.it/en/museo-nazionale-di-castel-santangelo/","بدأ الإمبراطور هادريان إنشاء ضريح له ولأسرته سنة 135 ميلادية، واكتمل بعد وفاته سنة 139 في عهد أنطونينوس بيوس. تحوّل المبنى الأسطواني لاحقًا إلى حصن ضمن دفاعات روما، ثم إلى مقر وحصن بابوي وسجن؛ وأصبح اليوم متحفًا يعرض طبقات هذه التحولات.","يربط ممر «باسيتو دي بورغو» المحصن القلعة بمنطقة الفاتيكان، وكان يُستخدم طريقًا آمنًا في أوقات الخطر. أما اسم «سانت أنجلو» فيرتبط بتقليد ديني عن رؤيا للملاك ميخائيل خلال وباء في القرن السادس، وليس باسم المبنى الروماني الأصلي."],["IT","Spanish Steps","يعكس الدرج الإسباني فن التخطيط الحضري الباروكي الذي يربط بين مستويين من المدينة ويحوّل الحركة اليومية إلى مشهد معماري.","تتدرج المصاطب والمنحنيات من ساحة إسبانيا ونافورة باركاتشا نحو كنيسة ترينيتا دي مونتي أعلى التلة.","https://www.turismoroma.it/en","شُيد الدرج في القرن الثامن عشر ليربط ساحة إسبانيا بكنيسة ترينيتا دي مونتي.","اسم الدرج مرتبط بساحة إسبانيا لا بأنه أثر من إسبانيا نفسها."],["IT","Uffizi Gallery","تشتهر أوفيزي بمجموعاتها التي تشرح تطور الرسم الإيطالي، خاصة في عصر النهضة، داخل مبنى تاريخي مرتبط بإدارة فلورنسا.","يمكن مشاهدة قاعات تضم أعمالًا لبوتيتشيلي وليوناردو وغيرهما، مع إطلالات من الممرات على نهر أرنو.","https://www.uffizi.it/en","نشأ مبنى أوفيزي في عصر أسرة ميديشي ليضم مكاتب إدارية قبل استخدامه معرضًا فنيًا.","تجعل الممرات الطويلة والنوافذ مشهد نهر أرنو جزءًا من التجربة."],["IT","Doge's Palace","يجسد قصر دوجي تداخل الحكم والقضاء والاحتفالات في جمهورية البندقية، وتجمع واجهاته بين عناصر قوطية وتأثيرات شرقية.","يظهر صف الأقواس الحجرية الرشيقة والفناء وقاعات المجالس التاريخية والجسر المرتبط بالسجون المعروفة بجسر التنهدات.","https://palazzoducale.visitmuve.it/en/home/","نشأ مقر دوق البندقية في موقع القصر منذ القرن التاسع تقريبًا، ثم أعيد بناء الأجنحة الكبرى المطلة على البحيرة والساحة بين القرنين الرابع عشر والخامس عشر. وبعد حريق 1483 أعيد تشكيل جناح يضم شقق الدوق ومكاتب الحكم بطرازات عصر النهضة. ظل المكان مركزًا سياسيًا وإداريًا للجمهورية حتى سقوطها عام 1797.","لم يكن الدوق حاكمًا مطلق السلطة؛ فقد كان منصبه مقيدًا بمؤسسات الجمهورية ومجالسها. كما أن جسر التنهدات الذي يصل القصر بالسجون الجديدة يعود إلى مرحلة لاحقة من القرن السابع عشر، وليس إلى البناء الأول للقصر في العصور الوسطى."],["IT","Pompeii","تسمح بومبي بدراسة شوارع ومنازل ومتاجر رومانية حفظتها رواسب ثوران فيزوف سنة 79 ميلادية، بدل الاكتفاء بآثار قصور ومعابد.","تظهر الشوارع المرصوفة والفسيفساء والرسوم الجدارية ومخططات المنازل والأفران وغيرها من تفاصيل الحياة اليومية.","https://pompeiisites.org/en/","دُفنت أجزاء كبيرة من بومبي خلال ثوران فيزوف سنة 79 ميلادية.","تكشف البيوت والمحلات والحمامات عن تفاصيل الحياة اليومية الرومانية."],["IT","Cinque Terre","تمثل القرى الخمس نموذجًا لتكيف التجمعات الساحلية مع التضاريس الوعرة عبر زراعة المدرجات وبناء مساكن متقاربة على المنحدرات.","تُرى البيوت الملونة وموانئ القرى الصغيرة والكروم المدرجة ومسارات المشي المطلة على بحر ليغوريا.","https://whc.unesco.org/en/list/826","تشكّلت قرى تشينكوي تيريه الخمس على امتداد ساحل ليغوريا الوعر خلال قرون من الاستقرار البشري، حيث أُنشئت مدرجات حجرية للكروم والزيتون على المنحدرات الشديدة. وكان الوصول إلى هذه التجمعات يعتمد بدرجة كبيرة على البحر والمسارات المحلية، قبل أن يغيّر خط السكك الحديدية بين جنوة ولا سبيتسيا في سبعينيات القرن التاسع عشر اتصال المنطقة بما حولها.","تعني التسمية الإيطالية «الأراضي الخمس» وتشير إلى مونتيروسو وفيرناتسا وكورنيليا ومانارولا وريومادجوري. قيمة المنطقة التراثية لا تقتصر على ألوان البيوت؛ فالمدرجات الزراعية والجدران الحجرية دليل على تكيّف الناس مع تضاريس شديدة الانحدار."],["IT","Piazza del Campo","تظهر الساحة تطور التنظيم المدني في سيينا خلال العصور الوسطى، وتتميز بمخططها المقعّر المتجه نحو مقر الحكم.","يمكن مشاهدة الرصف الشعاعي الذي يقسم أرضية الساحة وواجهة القصر العام وبرج مانجا المرتفع.","https://www.visitsiena.it/en/piazza-del-campo","نشأت ساحة كامبو في سيينا عند ملتقى طرق وأسواق المدينة، ثم تطورت خلال القرنين الثالث عشر والرابع عشر لتصبح مركزًا للحياة السياسية والمدنية. وضع مجلس المدينة قواعد لتنظيم واجهات مبانيها، وبدأ رصف الساحة بالطوب الأحمر في القرن الرابع عشر مع توجيه انحدارها نحو القصر العام.","تقسم خطوط الحجر الفاتح أرضية الساحة إلى تسعة أقسام ترتبط رمزيًا بحكومة التسعة التي حكمت سيينا في أوج قوتها الوسيطة. وتقام فيها مسابقة الخيل التقليدية «باليو» مرتين في السنة، ما يوضح استمرار وظيفتها الاجتماعية حتى اليوم."],["JP","Tokyo Skytree","يمثل البرج أحد أبرز مشاريع البث والاتصالات الحديثة في طوكيو، ويستخدم ارتفاعه الكبير لتقديم مشاهد بانورامية للعاصمة.","يبرز الهيكل الشبكي الضخم ومنصات الرؤية، ومن الأعلى تتضح كثافة العمران ومسار نهر سوميدا.","https://www.tokyo-skytree.jp/group/pre-learning/skytree/construction/overview.php","بدأ إنشاء طوكيو سكاي تري سنة 2008 وافتتح في مايو 2012 ضمن مشروع لتطوير البث التلفزيوني والاتصالات في العاصمة، بعدما أصبحت المباني الشاهقة تؤثر في انتشار الإشارات من الأبراج الأقل ارتفاعًا. يضم البرج منصات مشاهدة على ارتفاعات كبيرة إلى جانب مرافق البث والخدمات.","ارتفاع البرج 634 مترًا، واختير الرقم أيضًا لارتباط نطقه الياباني «مو-سا-شي» باسم إقليم موساشي التاريخي. وتقع منصتا المشاهدة الرئيسيتان قرب 350 و450 مترًا؛ لذا لا يعني ارتفاع البرج أن الزائر يصعد إلى قمته تمامًا."],["JP","Shibuya Crossing","يعكس التقاطع إيقاع المدينة اليابانية الحديثة وكثافة حركة المشاة حول محطة شيبويا التجارية.","يمكن مشاهدة تدفق المارة من اتجاهات متعددة عند تغير الإشارة، مع الشاشات العملاقة والطرق المحيطة.","https://www.gotokyo.org/en/","تطور محيط محطة شيبويا مع توسع شبكات السكك الحديدية والتجارة في طوكيو خلال القرن العشرين، وأصبح التقاطع المتعدد الاتجاهات المعروف باسم «سكرامبل» علامة للحي؛ وتذكر خريطة سياحية صادرة عن طوكيو أن نظام العبور بهذا الشكل ظهر سنة 1973. ساعدت الشاشات والمحال ووسائل الإعلام في تحويله إلى رمز عالمي للحياة الحضرية اليابانية.","يقع تمثال الكلب هاتشيكو الشهير قرب المحطة، لكنه معلم مجاور وليس جزءًا من التقاطع نفسه. وفكرة عبور المشاة في اتجاهات متعددة في المرحلة الضوئية ذاتها تنظم حركة الزحام؛ لذا فإن الأعداد المتداولة للعابرين تختلف باختلاف الوقت ولا ينبغي تقديمها كرقم ثابت."],["JP","Kiyomizu-dera","يرتبط المعبد بتراث كيوتو البوذي، وتعد منصته الخشبية البارزة فوق المنحدر إنجازًا معروفًا في البناء التقليدي.","تظهر الأعمدة الخشبية الحاملة للمنصة وأسقف المعبد المطلة على الأشجار والمدينة، خاصة مع اختلاف ألوان الفصول.","https://www.kiyomizudera.or.jp/en/","يرتبط المعبد بتراث كيوتو البوذي وتعود أصوله إلى القرن الثامن.","يتغير المشهد المحيط مع ألوان أشجار القيقب والكرز حسب الفصل."],["JP","Arashiyama Bamboo Grove","تمنح غابة الخيزران في أراشيياما نموذجًا لمشهد نباتي يرتبط بالهوية الجمالية لمنطقة كيوتو الغربية.","تكوّن سيقان الخيزران الطويلة المتقاربة ممرًا أخضر يتغير ضوؤه مع حركة الشمس والرياح.","https://www.japan.travel/en/spot/ma_129/","كانت منطقة ساغانو وأراشيياما غرب كيوتو مقصدًا لنزهات نبلاء البلاط منذ القرن الثامن، وارتبطت بحدائق ومساكن صارت بعض مواقعها لاحقًا معابد. أُنشئ معبد تينريو-جي المجاور في القرن الرابع عشر، وتحوّلت ممرات الخيزران إلى واحدة من أشهر صور المشهد الطبيعي الثقافي في كيوتو.","غابة الخيزران ممر طبيعي ثقافي ضمن منطقة ساغانو الأوسع، بينما تسجيل التراث العالمي يخص معبد تينريو-جي القريب ضمن آثار كيوتو التاريخية، ولا يعني أن ممر الخيزران نفسه موقع يونسكو منفصلًا."],["JP","Himeji Castle","تُعد قلعة هيميجي من أوضح أمثلة القلاع اليابانية الباقية، وتُعرف بهيكلها الخشبي المعقد وترتيباتها الدفاعية متعددة الطبقات.","يظهر البرج الأبيض الرئيسي والأسقف المتدرجة والمسارات الملتوية والبوابات المؤدية إلى قلب الحصن.","https://whc.unesco.org/en/list/661","عرف موقع قلعة هيميجي تحصينات منذ القرن الرابع عشر، لكن الهيئة الرئيسية الباقية اليوم تبلورت بعد أن بدأ إيكيدا تيروماسا إعادة بنائها عام 1601. واكتملت أبراجها الرئيسية عام 1609، ثم حافظت القلعة على شبكة دفاعية من البوابات والساحات والممرات المتعرجة خلال التغيرات السياسية اللاحقة.","لا يقتصر البياض الشهير على الزينة؛ إذ يغطي الجص الجيري الأبيض أجزاء من الأسوار ويساعد على مقاومة الحريق في قلعة بُنيت مكوناتها الأساسية من الخشب. وتشمل دفاعاتها خنادق وبوابات ومسارات معقدة لإبطاء أي مهاجم قبل الوصول إلى البرج الرئيسي."],["JP","Nikkō Tōshō-gū","خُصص الضريح لتوكوغاوا إياسو، ويُظهر تداخل السلطة السياسية والرموز الدينية والحرف الزخرفية في مطلع عصر إيدو.","تستحق المشاهدة بوابة يوميمون والألوان الزاهية والنقوش الخشبية الشهيرة، ومنها القرود الثلاثة.","https://whc.unesco.org/en/list/913","أُقيم ضريح توشوغو تكريمًا لتوكوغاوا إياسو، الشخصية التي ارتبطت ببداية حكم شوغونية توكوغاوا في اليابان.","من أشهر تفاصيله زخارف القرود الثلاثة على أحد مباني المجمع؛ وتوضح كيف تحمل الزخرفة الخشبية رسائل رمزية بجانب دورها الجمالي."],["JP","Mount Fuji","يحتل جبل فوجي مكانة روحية وفنية في اليابان، وألهم مشاهد لا حصر لها في الرسم والأدب، إلى جانب كونه بركانًا بارزًا.","تظهر قمته المخروطية المتناظرة من بحيرات ومواقع عدة، مع تغيّر الثلوج والسحب والغطاء النباتي خلال الفصول.","https://whc.unesco.org/en/list/1418","جبل فوجي بركان طبقي وأعلى قمم اليابان، وقد اكتسب مكانة دينية وفنية ظهرت في تقاليد الحج والأعمال التصويرية.","لا يأتي شكل المخروط من ثبات الطبيعة؛ فقد تراكمت طبقات من المواد البركانية خلال مراحل نشاط مختلفة لتكوين هيئة الجبل المعروفة."],["SA","King Abdulaziz Historical Center","يجمع المركز بين الذاكرة الوطنية والمقتنيات الأثرية وسرد تاريخ شبه الجزيرة العربية، وتشكّل المتاحف والحدائق جزءًا من مشروع إحياء منطقة المربع في الرياض.","تبرز قاعات المتحف الوطني وتخطيط الحدائق والممرات المحيطة بقصر المربع والمباني التاريخية المجاورة.","https://saudipedia.com/مركز-الملك-عبدالعزيز-التاريخي","افتتح مركز الملك عبدالعزيز التاريخي في حي المربع بالرياض يوم 22 يناير 1999، ضمن مشروعات الاحتفاء بمرور مئة عام على استرداد الملك عبدالعزيز للرياض. أنشأته الهيئة الملكية لمدينة الرياض ليجمع مباني تاريخية قائمة مع مؤسسات ثقافية حديثة، منها المتحف الوطني ودارة الملك عبدالعزيز ومكتبة الملك عبدالعزيز العامة.","يمتد المركز على مساحة تقارب 440 ألف متر مربع، وتجمع ساحاته بين قصر المربع والمتحف الوطني وحدائق ومرافق ثقافية. افتتاح المركز سنة 1999 لا يعني أن كل المباني داخله شُيّدت في هذا العام؛ فبعضها أقدم ويحفظ تاريخ المربع."],["SA","Shubra Palace","يعكس قصر شبرا طراز المباني الراقية في الطائف أوائل القرن العشرين، حيث تتداخل الزخارف المحلية مع عناصر بنائية وافدة.","تظهر الشرفات الخشبية والنوافذ المقوسة والتفاصيل الجصية وتوزيع الغرف حول المساحات الداخلية.","https://heritage.moc.gov.sa/en","أقيم قصر شبرا بالطائف في أوائل القرن العشرين واستخدم لأغراض رسمية.","تُميز نوافذه وشرفاته وتوزيع الغرف طراز المباني التاريخية بالطائف."],["SA","King Fahd's Fountain","تحولت نافورة الملك فهد إلى أحد أبرز الرموز البصرية لكورنيش جدة، وتعكس علاقة المدينة بواجهتها البحرية الحديثة.","يرتفع عمود الماء فوق سطح البحر في مشهد واضح من مواقع متعددة على الكورنيش، وتبرز إضاءته ليلًا.","https://saudipedia.com/نافورة-الملك-فهد","أُنشئت نافورة الملك فهد على ساحل جدة ضمن مشروع بدأ في مطلع الثمانينيات، وانطلقت مياهها للمرة الأولى عام 1985 بوصفها هدية للمدينة من الملك فهد بن عبدالعزيز. أصبحت النافورة علامة بصرية للكورنيش؛ وتعتمد على ضخ مياه البحر الأحمر إلى ارتفاع شاهق.","يصل ارتفاع الماء وفق سعوديبيديا إلى نحو 312 مترًا، وتتخذ قاعدة النافورة هيئة مستوحاة من المبخرة التقليدية. ويُظهر نظام الإضاءة شكل عمود الماء ليلًا، فيما تؤثر الرياح والصيانة على إمكان تشغيلها، فلا يُفترض عملها في كل وقت."],["SA","Al-Ahsa Oasis","تُعد الواحة مشهدًا ثقافيًا متطورًا يجمع الزراعة التقليدية وإدارة المياه والتجمعات السكنية والتراث العمراني في بيئة صحراوية.","تمتد بساتين النخيل وقنوات الري والعيون والمباني التاريخية بين أجزاء الواحة، بما يوضح ترابط الإنسان والماء والزراعة.","https://whc.unesco.org/en/list/1563","تُعد الأحساء واحة نخيل واسعة ترتبط بنظام تاريخي من العيون والقنوات.","أُدرج المشهد الثقافي للأحساء ضمن قائمة التراث العالمي لليونسكو."],["SA","Al-Ukhdud","يحفظ الأخدود بقايا استيطان قديم في نجران؛ وتساعد نقوشه وأطلاله في دراسة تاريخ جنوب الجزيرة العربية قبل الإسلام.","تظهر أساسات المباني الحجرية وبعض النقوش والكتابات القديمة ضمن المساحة الأثرية المفتوحة.","https://heritage.moc.gov.sa/en","تضم منطقة الأخدود قرب نجران بقايا أثرية تعود إلى فترات متعددة.","لا تمثل كل الأطلال فترة زمنية واحدة؛ فالموقع ذو طبقات تاريخية."],["SA","Wadi Al Disah","يمثل الوادي تباينًا جغرافيًا لافتًا بين الصخور الرملية العملاقة والنباتات والمياه الموسمية في شمال غربي السعودية.","تتوالى الجروف الصخرية الحمراء والأعمدة الطبيعية وبساتين النخيل على امتداد ممر الوادي.","https://pure.kfupm.edu.sa/en/publications/geomorphosite-assessment-of-wadi-al-disha-from-the-perspective-of/","يقع وادي الديسة في شمال غرب السعودية ضمن نطاق جبلي تأثر بحركات تكتونية مرتبطة بتطور منطقة البحر الأحمر. أسهمت الصدوع وتدفّق المياه عبر فترات طويلة في نحت الأخدود بين طبقات الحجر الرملي، فظهرت جروف شديدة الانحدار وأعمدة صخرية منفصلة. وتساعد طبقات المياه القريبة من السطح والينابيع على استمرار النبات والزراعة في أجزاء من الوادي، رغم طبيعة المنطقة الجافة المحيطة.","تُظهر ألوان الصخر اختلاف طبقات الترسيب والتجوية."],["SA","Marjan Island (Dammam)","تعكس الجزيرة أحد مشاريع الترفيه الساحلي في الدمام، وتتيح رؤية العلاقة بين كورنيش المدينة ومياه الخليج العربي.","يمكن تأمل الجسر الواصل إلى الجزيرة والمساحات المفتوحة والبحر المحيط بها وأفق الدمام من بعيد.","https://www.visitsaudi.com/en/eastern-province/attractions/murjan-island-in-dammam","أُنشئت جزيرة المرجان بوصفها منطقة ترفيهية ساحلية متصلة بكورنيش الدمام.","تمثل نموذجًا للمساحات الترفيهية الحديثة لا للمواقع الأثرية."],["TR","Dolmabahçe Palace","يجسد القصر انتقال البلاط العثماني في القرن التاسع عشر إلى أساليب معمارية أكثر تأثرًا بالطراز الأوروبي، مع استمرار رموز الحكم السلطاني.","تظهر الواجهة المطلة على البوسفور والبوابات المزخرفة والثريات الضخمة والقاعات الاحتفالية الداخلية.","https://www.millisaraylar.gov.tr/Lokasyon/3/Dolmabahce-Sarayi?culture=en","شُيد قصر دولمة بهجة في القرن التاسع عشر ليصبح مقرًا عثمانيًا على البوسفور.","يُظهر القصر تحوّل الذوق المعماري في أواخر العصر العثماني."],["TR","Grand Bazaar, Istanbul","يعكس البازار الكبير دور إسطنبول التاريخي مركزًا للتجارة والحرف، وتطور شبكة معقدة من الأسواق المسقوفة.","تمتد الممرات المقببة تحت أسقف مزخرفة، وتنتظم فيها متاجر السجاد والمجوهرات والتحف والحرف التقليدية.","https://goturkiye.com/istanbul/blog/best-places-for-shopping-in-istanbul","تطور البازار الكبير حول أسواق عثمانية مسقوفة منذ القرن الخامس عشر.","لا تقتصر قيمته على التسوق بل تشمل شبكة الخانات والممرات التاريخية."],["TR","Hadrian's Gate","تقدم بوابة هادريان شاهدًا على العمارة التذكارية الرومانية في أنطاليا وعلى استمرارية المدينة عبر عصور مختلفة.","تظهر ثلاثة أقواس رخامية بأعمدتها وزخارفها، محصورة بين أجزاء من الأسوار التاريخية.","https://goturkiye.com/antalya/routes","ترتبط بوابة هادريان بزيارة الإمبراطور الروماني للمنطقة في القرن الثاني.","تدل أقواسها الثلاثة على استمرار آثار العصر الروماني داخل المدينة الحديثة."],["TR","Derinkuyu Underground City","تكشف المدينة المحفورة في صخور كابادوكيا عن وسائل دفاع وسكن وتخزين تحت الأرض، مع شبكة ممرات تصل مستويات متعددة.","تُلاحظ الممرات الضيقة والآبار وفتحات التهوية والأبواب الحجرية الدائرية التي كانت تُغلق بعض الممرات.","https://www.muze.gov.tr/muze-detay?DistId=DKY&SectionId=DKY01","استُخدمت مدينة ديرينكويو المنحوتة في صخور كابادوكيا مأوىً ومكانًا للحماية في فترات تاريخية مختلفة. توسعت منشآتها تحت الأرض، خصوصًا في الفترات المسيحية البيزنطية، لتضم غرفًا للمعيشة والتخزين والعبادة وممرات ضيقة وآبارًا وفتحات تهوية، ما سمح بالاحتماء بعيدًا عن سطح الأرض.","تصف وزارة الثقافة والسياحة التركية ديرينكويو بأنها مدينة من ثمانية طوابق تحت الأرض، تضم فتحات تهوية وآبارًا وغرف تخزين وعبادة ومدرسة دينية. وتبرز فيها الأبواب الحجرية الأسطوانية الكبيرة التي كانت تُغلق الممرات الضيقة لأغراض الحماية، فلا يقتصر الموقع على أنفاق فارغة."],["TR","Sumela Monastery","يمثل دير سوميلا مثالًا على اختيار مواقع منعزلة ومرتفعة للتعبد، ويبرز تفاعله المعماري مع جرف جبلي شديد الانحدار.","تظهر واجهاته المبنية فوق الصخر وسلالم الوصول والرسوم الجدارية داخل الكنيسة الصخرية وبين الغابات المحيطة.","https://goturkiye.com/blog/20-of-turkiyes-most-impressive-historical-sites","نشأ دير سوميلا في تقليد رهباني مسيحي ارتبط بجبال البحر الأسود، وتطورت مبانيه ورسومه الجدارية على مراحل تاريخية.","يفرض الجرف الصخري الشاهق على الزائر قراءة المباني مع الجبل المحيط بها، وليس بوصفها مجمعًا دينيًا منفصلًا عن تضاريسه."],["TR","Göbekli Tepe","يقدم الموقع دليلًا مهمًا على قدرة مجتمعات الصيد وجمع الثمار في العصر الحجري الحديث على بناء منشآت جماعية ضخمة قبل انتشار المدن.","تظهر أعمدة حجرية على شكل حرف T داخل حظائر دائرية أو بيضاوية، وبعضها يحمل نقوش حيوانات برية.","https://whc.unesco.org/en/list/1572","يعود موقع غوبكلي تبه إلى العصر الحجري الحديث قبل ظهور المدن التاريخية.","ساعدت الاكتشافات في إعادة تقييم تعقيد المجتمعات المبكرة."],["TR","Grand Mosque of Bursa","يُظهر الجامع الكبير في بورصة اتساع القاعة المصلّاة ذات القباب المتعددة في العمارة العثمانية المبكرة.","تتكرر الأعمدة والقباب في الداخل، وتبرز الخطوط العربية المزخرفة والنافورة الداخلية المميزة.","https://goturkiye.com/faith/imperial-ottoman-mosques","بُني الجامع الكبير في بورصة أواخر القرن الرابع عشر خلال فترة التوسع العثماني المبكر، ويُعرف بتنظيم قاعة الصلاة تحت قباب متعددة.","النافورة الداخلية من أبرز العناصر غير المعتادة للزائر، وتجاورها زخارف خطية واسعة على الجدران والأعمدة."],["ES","Royal Palace of Madrid","يبرز القصر الملكي بمدريد تاريخ البلاط الإسباني وعمارة القرن الثامن عشر، ويستعمل في مناسبات رسمية رغم عدم كونه مقر الإقامة اليومية للملك.","تظهر الواجهات الحجرية الفخمة والدرج الرئيسي والقاعات الاحتفالية والأثاث والمجموعات الفنية الملكية.","https://www.patrimonionacional.es/en","شُيّد القصر الحالي في القرن الثامن عشر فوق موقع قصر سابق تعرض لحريق.","تُظهر قاعاته قطعًا فنية وأثاثًا يعكس تطور البلاط الإسباني."],["ES","El Retiro Park","انتقل ريتيرو من فضاء مرتبط بالقصر الملكي إلى حديقة عامة مهمة في مدريد؛ وأصبح جزءًا من مشهد ثقافي يحفظ علاقة المدينة بالطبيعة.","تظهر البحيرة الكبيرة والنصب التذكاري لألفونسو الثاني عشر والقصر البلوري والممرات المشجرة.","https://whc.unesco.org/en/list/1618","كان ريتيرو مرتبطًا بالمجمع الملكي قبل أن يصبح حديقة عامة لمدريد.","يُقدم مثالًا على تحوّل حدائق البلاط إلى فضاء حضري مفتوح."],["ES","Casa Batlló","يعكس المنزل ابتكارات غاودي في إعادة تشكيل الواجهات والفراغات باستخدام خطوط عضوية وضوء طبيعي مستوحى من الطبيعة.","تبرز الشرفات ذات الأشكال العظمية والفسيفساء الملونة والسقف المتموج وبئر الإضاءة الداخلي.","https://www.casabatllo.es/en/","أعاد أنطوني غاودي تصميم المبنى في مطلع القرن العشرين ضمن تيار الحداثة الكتالونية.","تعتمد فتحة التهوية الداخلية على توزيع الضوء الطبيعي بين الطوابق."],["ES","Toledo Cathedral","تكشف الكاتدرائية عن ازدهار العمارة القوطية في قشتالة وعن دور طليطلة مركزًا دينيًا وفنيًا تاريخيًا.","تظهر الأقواس الرفيعة والزجاج الملون والجوقة المنحوتة والمذبح الرئيسي والأعمال الفنية داخل الكنيسة.","https://www.catedralprimada.es/","تعود الكاتدرائية القوطية إلى مشروع بناء بدأ في القرن الثالث عشر في طليطلة.","تعكس المدينة المحيطة بها تداخل تراث ديني وثقافي متعاقب."],["ES","Guggenheim Museum Bilbao","أعاد المتحف تشكيل صورة الواجهة النهرية لبلباو، وأصبح مثالًا بارزًا على العمارة المتحفية ذات الكتل النحتية المعاصرة.","تتغير انعكاسات الضوء على ألواح التيتانيوم المنحنية، وتظهر التكوينات المعمارية مع الجسر والنهر.","https://www.guggenheim-bilbao.eus/en","افتتح متحف غوغنهايم بلباو سنة 1997 بتصميم المعماري فرانك غيري.","استخدم فرانك غيري في تصميم المبنى برنامج CATIA المستعمل أصلًا في صناعة الطيران لترجمة الأشكال المنحنية المعقدة إلى عناصر قابلة للتنفيذ."],["ES","Alcazaba of Málaga","يمثل القصبة في مالقة امتزاج الوظيفة الدفاعية بالقصر الأندلسي؛ واستفاد البناء من ارتفاع التلة لإشرافه على المدينة والميناء.","تتتابع الأسوار والبوابات والأفنية والحدائق الصغيرة مع إطلالات على المسرح الروماني والساحل.","https://www.malagaturismo.com/en","تطورت قصبة مالقة بوصفها حصنًا ومجمعًا حاكمًا في الأندلس الإسلامية.","توضح مستوياتها المتعددة أهمية الدفاع والسيطرة على مداخل المدينة."],["ES","Santiago de Compostela Cathedral","تحتل الكاتدرائية مكانة محورية في تاريخ الحج المسيحي بأوروبا، وهي مقصد طرق سانتياغو التي امتدت عبر القارة.","تبرز الواجهة الباروكية والساحة الواسعة، بينما يكشف الداخل عن عمارة رومانسكية وقطع فنية دينية.","https://whc.unesco.org/en/list/347","ارتبطت نشأة مدينة سانتياغو دي كومبوستيلا في شمال غرب إسبانيا بالتقليد المسيحي الخاص باكتشاف ضريح منسوب إلى القديس يعقوب في القرن التاسع. أصبحت الكاتدرائية مقصدًا للحج عبر طرق متعددة في أوروبا، وتطورت عمارتها الرومانسكية ثم أضيفت واجهات وتوسعات من عصور لاحقة.","تُظهر الكاتدرائية اختلاف مراحل البناء بوضوح: فمدخل «بوابة المجد» من أبرز أعمال النحت الرومانسكي، بينما جاءت الواجهة الغربية الشهيرة في ساحة أوبرادويرو بطراز باروكي لاحق. وتلتقي عندها طرق حج سانتياغو، وهي شبكة تاريخية وليست طريقًا واحدًا."],["US","White House","يمثل البيت الأبيض مركزًا رمزيًا وتنفيذيًا للرئاسة الأمريكية منذ مطلع القرن التاسع عشر، وتعكس مبانيه تعديلات متعاقبة.","تظهر الواجهة الشمالية ذات الأعمدة والحدائق والمداخل الرسمية؛ ولا ينبغي افتراض إمكان دخول كل المساحات للزوار.","https://www.whitehouse.gov/about-the-white-house/","بدأ بناء البيت الأبيض في تسعينيات القرن الثامن عشر في العاصمة الفيدرالية الجديدة.","تختلف الجولات والوصول إلى أجزاء المبنى عن كونه معلمًا مشاهَدًا من الخارج."],["US","Washington Monument","تخلّد المسلة ذكرى أول رئيس للولايات المتحدة، وتعبّر بهيئتها المبسطة عن تقاليد النصب التذكارية المستوحاة من مصر القديمة.","يظهر العمود الحجري المدبب وسط ناشونال مول، وتنعكس صورته في البركة المستطيلة على امتداد المحور.","https://www.nps.gov/wamo/index.htm","شُيّد النصب تكريمًا لجورج واشنطن في قلب العاصمة الأمريكية.","يمكن رؤية اختلاف طفيف في لون الحجر بسبب توقف البناء واستئنافه."],["US","Hoover Dam","يُعد السد من المشروعات الكبرى لتنظيم مياه نهر كولورادو وتوليد الطاقة في القرن العشرين، مع آثار واسعة على البيئة وتوزيع المياه.","تظهر كتلة السد الخرسانية المقوسة بين جدران الأخدود، وخلفها بحيرة ميد وأبراج سحب المياه.","https://www.usbr.gov/lc/hooverdam/","بُني سد هوفر خلال ثلاثينيات القرن العشرين على نهر كولورادو.","يرتبط تاريخ المشروع بالتوسع العمراني والزراعي في الجنوب الغربي الأمريكي."],["US","Zion National Park","يكشف وادي زايون عن تاريخ طويل من ترسيب الحجر الرملي ثم نحته بالمياه، مع تنوع بيئي على امتداد فروق الارتفاع.","تظهر الجدران الرملية الحمراء والبيضاء الضخمة وامتداد النهر بين المنحدرات والمسارات الصخرية.","https://www.nps.gov/zion/index.htm","بدأت الحماية الفدرالية للمنطقة عام 1909 بوصفها نصب موكونتوياب الوطني، ثم تغيّر اسمها إلى زيون عام 1918 وأصبحت منتزهًا وطنيًا سنة 1919. شكل نهر فيرجن وأفرعه أجزاء من الوادي عبر نحت طبقات الحجر الرملي على مدد جيولوجية طويلة، بينما يرتبط المشهد أيضًا بتاريخ السكان الأصليين الذين عاشوا في المنطقة.","تُظهر الجدران الشاهقة طبقات صخرية ترسبت في بيئات قديمة مختلفة، بينها كثبان رملية تحجرت لاحقًا. لذلك فإن ألوان الوادي وتكويناته تروي تغير البيئة عبر الزمن، لا مجرد أثر تعرية نهر واحد في فترة قصيرة."],["US","Yosemite National Park","يرتبط المنتزه بتاريخ التجلد ونحت الصخور الجرانيتية، وهو من أشهر مواقع حماية المناظر الطبيعية في الولايات المتحدة.","تبرز جدران إل كابيتان ونصف القبة وشلالات يوسيميتي والوديان والغابات الجبلية.","https://www.nps.gov/yose/index.htm","تشكّلت تضاريس يوسيميتي بفعل النشاط الجليدي والتعرية في سييرا نيفادا.","تختلف كمية المياه في الشلالات على مدار العام بتغيّر الثلوج والأمطار."],["US","Brooklyn Bridge","جسّد الجسر تقدم تقنية الجسور المعلقة في القرن التاسع عشر وربط الأحياء التي أصبحت لاحقًا جزءًا من نيويورك الكبرى.","تظهر البرجان الحجريان بأقواسهما القوطية وشبكة الكابلات المائلة فوق الممرات والنهر.","https://www.nyc.gov/","اكتمل جسر بروكلين سنة 1883 ليربط مدينتي نيويورك وبروكلين آنذاك.","تتيح ممرات المشاة المرتفعة رؤية الأبراج الحجرية وأفق مانهاتن."],["US","Cloud Gate","تستخدم منحوتة كلاود غيت سطحًا فولاذيًا عاكسًا لتشويه صورة أفق شيكاغو والزوار، وتحويل المشهد الحضري إلى تجربة بصرية تفاعلية.","تظهر انعكاسات المباني والسماء على السطح المنحني، وبداخل القوس تتكرر الصور بصورة غير مألوفة.","https://www.chicago.gov/city/en/depts/dca/supp_info/millennium_park.html","أنجز أنيش كابور منحوتة كلاود غيت في ميلينيوم بارك بشيكاغو.","اسمها الشائع ذا بين نابع من شكلها الشبيه بحبة الفاصوليا."],["CN","Tiananmen Square","تحتل الساحة موقعًا بارزًا في التاريخ السياسي الصيني الحديث، بما في ذلك إعلان قيام جمهورية الصين الشعبية عام 1949 واحتجاجات عام 1989.","تُظهر المساحة المفتوحة الضخمة مباني تذكارية ورسمية، مع بوابة تيانانمن على الجهة الشمالية.","https://www.britannica.com/place/Tiananmen-Square","تشكل ساحة تيانانمن مساحة مدنية وسياسية بارزة في قلب بكين.","ترتبط الساحة بمحطات مهمة من تاريخ الصين الحديث، بما فيها احتجاجات 1989."],["CN","Yonghe Temple","يقدم معبد يونغه نموذجًا للعمارة البوذية التبتية في بكين، ويعكس تداخل تقاليد البلاط الصيني والطقوس الدينية.","تتتابع البوابات والقاعات ذات الأسقف المزخرفة، وتبرز التماثيل البوذية الكبيرة والألوان التقليدية.","https://english.visitbeijing.com.cn/","بُني مجمع يونغه سنة 1694 خلال عهد كانغشي مقرًا لأمير من أسرة تشينغ، ثم أصبح قصرًا إمبراطوريًا في عهد يونغتشنغ سنة 1725. وفي عهد الإمبراطور تشيانلونغ تحوّل عام 1744 إلى معبد للبوذية التبتية، فاحتفظ بعناصر من عمارة القصور الصينية مع وظائف دينية ومجموعات فنية جديدة.","من أشهر مقتنيات المعبد تمثال مايتريا البوذي الذي يبلغ ارتفاعه نحو 18 مترًا وصُنع من جذع خشب صندل واحد بحسب دليل السياحة في بكين. وبذلك يجمع المكان بين تاريخ الأسرة الحاكمة وممارسات البوذية التبتية، ولا يُعد مجرد قصر سكني قديم."],["CN","West Lake (Hangzhou)","تُعد البحيرة نموذجًا للمنظر الثقافي الصيني الذي ألهم الشعر والرسم وتصميم الحدائق عبر قرون.","تظهر الجسور والقناطر والحدائق والأجنحة بين الماء والتلال، مع انعكاسات الأبراج والممرات على سطح البحيرة.","https://whc.unesco.org/en/list/1334","أثّرت بحيرة هانغتشو الغربية في الشعر والرسم وتصميم الحدائق الصينية.","تعكس المنطقة مفهوم المنظر الثقافي الذي يجمع التدخل البشري والطبيعة."],["CN","Li River","تعكس مشاهد نهر لي طبيعة التضاريس الكارستية جنوب الصين، حيث تتشكل التلال الجيرية بفعل عمليات ذوبان وتعرية طويلة.","تظهر قمم مخروطية حادة حول مجرى النهر والحقول والقرى، وتتنوع الإطلالات بين قويلين ويانغشو.","https://www.guilin.gov.cn/","يشتهر نهر لي بمروره بين تلال الحجر الجيري الكارستية قرب قويلين.","يتغير منظر الضباب وانعكاس الجبال على المياه بتغير الطقس."],["CN","Potala Palace","يمثل قصر بوتالا جزءًا محوريًا من التراث السياسي والديني التبتي، وتتميز كتلته البيضاء والحمراء بموقعها المرتفع في لاسا.","تتدرج المباني فوق التلة، وتبرز الأسقف الذهبية والقاعات الشعائرية والجدران السميكة.","https://whc.unesco.org/en/list/707","ارتبط قصر بوتالا تاريخيًا بمؤسسة الدالاي لاما في لاسا على هضبة التبت.","يُظهر موضعه فوق التل أهميته الرمزية والعمرانية في المدينة."],["CN","Mogao Caves","تقدم كهوف موغاو سجلًا فنيًا غنيًا عن التبادل الثقافي والديني على طريق الحرير، وتضم رسومًا ومنحوتات بوذية من عصور متعاقبة.","تظهر القاعات المنحوتة في الجرف والجداريات الملونة والتماثيل، مع اختلاف الأساليب الفنية من كهف لآخر.","https://whc.unesco.org/en/list/440","تمتد كهوف موغاو المنحوتة قرب دونهوانغ عبر مراحل طويلة من تاريخ طريق الحرير.","تساعد مقتنيات المخطوطات المكتشفة بالموقع في دراسة التجارة والديانات."],["CN","Jiuzhaigou","يُعرف وادي جيوتشايقو بمنظومة بحيرات وشلالات تتأثر ألوانها بصفاء المياه والرواسب والبيئة الجبلية المحيطة.","تظهر البرك الزرقاء والخضراء والغابات والشلالات المتدرجة بين الجبال، وتختلف ألوان المنظر بحسب الموسم.","https://whc.unesco.org/en/list/637","تكوّنت مناظر جيوتشايقو في جبال مينشان شمال سيتشوان بفعل التغيرات الجيولوجية وتدفق المياه عبر تضاريس جبلية مرتفعة. ساعد ترسّب كربونات الكالسيوم على تكوين حواجز ودرجات من الترافرتين بين بحيرات وشلالات متتابعة، بينما تحفظ المنطقة غابات جبلية وموائل طبيعية ذات قيمة بيئية كبيرة.","ألوان البحيرات الزرقاء والخضراء ليست طلاءً للمياه؛ بل تتأثر بصفاء الماء والمعادن والعمق والضوء والغطاء النباتي المحيط. وتشير اليونسكو كذلك إلى وجود تشكيلات كارستية جبلية وبقايا آثار جليدية قديمة داخل نطاق المحمية."],["IN","Agra Fort","يمثل حصن أغرا نموذجًا للجمع بين التحصينات والقصور في العمارة المغولية، وكان مركزًا للحكم في مراحل مختلفة.","تبرز الأسوار الحمراء والبوابات الضخمة والقصور والأفنية الداخلية التي تتميز بعض أجزائها بالرخام.","https://whc.unesco.org/en/list/251","أعاد الإمبراطور أكبر بناء حصن أغرا بالحجر الرملي الأحمر ابتداءً من عام 1565، وتحول إلى مقر محصن للحكم المغولي على نهر يامونا. أضاف شاه جهان لاحقًا أجنحة وقاعات من الرخام الأبيض، فجمع المجمع بين الوظيفة الدفاعية والقصور الملكية. وشهد الحصن أيضًا سنوات شاه جهان الأخيرة بعد عزله عن الحكم.","من داخل أجزاء من الحصن يمكن رؤية تاج محل على الضفة القريبة من نهر يامونا، ما يربط بصريًا بين صرحين مغوليين مختلفين. وتُظهر قاعات الديوان وأجنحة السكن كيف اجتمعت الإدارة والاحتفالات والحياة الملكية داخل الأسوار نفسها."],["IN","Ellora Caves","تكشف كهوف إلورا عن نحت معماري هائل في الصخر ووجود منشآت بوذية وهندوسية وجاينية متجاورة عبر قرون.","يبرز معبد كايلاسا المنحوت من كتلة صخرية والواجهات المنقوشة والأعمدة والتماثيل داخل المجمع.","https://whc.unesco.org/en/list/243","نُحتت معابد وأديرة إلورا تدريجيًا في جرف من صخور البازلت بولاية ماهاراشترا خلال قرون امتدت تقريبًا من القرن السادس إلى الثاني عشر الميلادي. تعكس مجموعاتها الثلاث تقاليد بوذية وهندوسية وجاينية، وتوضح كيف تطورت تقنيات النحت في الصخر الصلب بالتوازي مع ازدهار مدارس دينية وفنية متعددة.","تضم المجموعة الأشهر 34 كهفًا مرقّمًا؛ وأبرزها المعبد رقم 16 المعروف بكايلاسا، الذي نُحت ليبدو كمعبد مستقل من كتلة الصخر المحيطة به. لا تعني كلمة «كهوف» أن جميع المواقع تجاويف بسيطة؛ فبعضها مبانٍ معمارية ضخمة منحوتة مباشرة في الجبل."],["IN","Ajanta Caves","تُعد أجانتا شاهدًا مهمًا على الرسم والنحت البوذي القديم في الهند، ولا سيما السرد القصصي عبر الجداريات.","تظهر قاعات صخرية ومشاهد مرسومة بألوان دافئة وتماثيل بوذية وأعمدة منقوشة حول الممرات.","https://whc.unesco.org/en/list/242","حُفرت أولى كهوف أجانتا البوذية في القرنين الثاني والأول قبل الميلاد، ثم أُضيفت كهوف أوسع وأكثر زخرفة خلال القرنين الخامس والسادس الميلاديين. وتوثق الرسوم الجدارية والمنحوتات مراحل تطور الفن البوذي وحياة المجتمعات التي رعت أديرته وقاعات عبادته.","تساعد الرسوم في دراسة الأزياء والحياة والفنون في الهند القديمة."],["IN","Konark Sun Temple","صُمم معبد الشمس في كونارك على هيئة عربة حجرية احتفالية مرتبطة بالإله سوريا، بما يعكس براعة النحت في أوديشا.","تبرز العجلات الحجرية الضخمة والخيول المنحوتة والنقوش المتعددة على الجدران.","https://whc.unesco.org/en/list/246","شُيّد معبد الشمس في كونارك خلال القرن الثالث عشر في عهد الملك ناراسيمهاديفا الأول من أسرة غانغا الشرقية. صُمم المعبد ليجسد عربة الإله سوريا، بعجلات حجرية مزخرفة وخيول منحوتة، وأصبح نموذجًا بارزًا لعمارة كالينغا وفنونها الدينية في أوديشا.","جُسّد المعبد على هيئة عربة للشمس ذات أربع وعشرين عجلة حجرية ضخمة، موزعة في اثني عشر زوجًا وترتبط رمزيًا بدورة الزمن. وتشمل المنحوتات مشاهد لموسيقيين وراقصين وحيوانات؛ أما أجزاء من البرج الرئيسي القديم فلم تبقَ قائمة إلى اليوم."],["IN","City Palace, Udaipur","يعكس مجمع قصر أودايبور تاريخ حكم الميوار وتطور القصور الراجبوتية المطلة على بحيرة بيكولا.","تظهر الشرفات والأفنية والفسيفساء والزجاج الملون، مع مشاهد البحيرة والمدينة القديمة.","https://www.eternalmewar.in/","توسع مجمع قصر مدينة أودايبور خلال حكم سلالة ميوار عبر قرون.","يُظهر تنوع الإضافات تداخل العمارة الراجبوتية مع تأثيرات أخرى."],["IN","Fort Kochi","يوضح فورت كوتشي أثر التجارة البحرية عبر المحيط الهندي ووجود تأثيرات معمارية وثقافية هندية وأوروبية متعاقبة.","تظهر شباك الصيد الصينية التقليدية على الواجهة البحرية، إلى جانب البيوت القديمة والشوارع والأماكن التاريخية.","https://www.keralatourism.org/","نشأ الطابع العمراني لفورت كوتشي من دورها ميناءً على طرق التجارة بالمحيط الهندي.","تُعد شباك الصيد الصينية على الساحل من أبرز المشاهد البصرية."],["IN","Darjeeling Himalayan Railway","يمثل الخط إنجازًا هندسيًا لنقل الركاب عبر تضاريس جبلية شديدة الانحدار ضمن منظومة سكك حديد الهند الجبلية.","تبرز القاطرات الصغيرة والمنحنيات الحادة والحلقات الهندسية ومسار السكة وسط بلدات التلال ومزارع الشاي.","https://whc.unesco.org/en/list/944","افتتح خط دارجيلنغ الجبلي في القرن التاسع عشر لربط السهول بالمرتفعات.","يُعرف بقطاراته التراثية الضيقة ضمن مشهد جبال الشاي والهيمالايا."],["GB","Palace of Westminster","يجمع قصر وستمنستر بين تاريخ المؤسسة البرلمانية البريطانية والعمارة القوطية الجديدة التي أعقبت حريقًا كبيرًا في القرن التاسع عشر.","تظهر واجهته الطويلة على التايمز وأبراج القصر، ومنها برج إليزابيث، مع تفاصيل النوافذ والأقواس الحجرية.","https://www.parliament.uk/about/living-heritage/building/palace/","يقع قصر وستمنستر على الضفة الشمالية لنهر التايمز، وتعرض مبانيه الحالية إعادة بناء واسعة في القرن التاسع عشر بعد حريق سابق.","اسم بيغ بن يشير في الأصل إلى الجرس الكبير داخل برج إليزابيث لا إلى القصر بأكمله."],["GB","St Paul's Cathedral","تُمثل كاتدرائية سانت بول جانبًا مهمًا من إعادة إعمار لندن بعد حريق 1666، وهي من أشهر أعمال المعماري كريستوفر رن.","تبرز القبة الكبرى والدرج والأعمدة الكلاسيكية، ويمكن تأمل بنية القبة والزخارف الداخلية من مستويات متعددة.","https://www.stpauls.co.uk/","أعاد كريستوفر رن تصميم الكاتدرائية بعد حريق لندن الكبير سنة 1666، واكتمل بناؤها مطلع القرن الثامن عشر.","صُممت القبة بنظام بنائي متعدد الطبقات لا يظهر كله من الداخل."],["GB","Tower Bridge","يُظهر تاور بريدج جمع الهندسة المتحركة مع الطابع المعماري الفيكتوري، وقد صُمم للسماح بمرور السفن الكبيرة إلى الميناء.","يمكن رؤية البرجين والممرين العلويين والجزأين المتحركين من الطريق فوق التايمز.","https://www.towerbridge.org.uk/","افتُتح جسر البرج سنة 1894 لحل مشكلة عبور النهر قرب ميناء لندن مع السماح للسفن المرتفعة بالمرور.","يختلط على الزائرين بينه وبين London Bridge؛ وهما جسران مختلفان."],["GB","York Minster","تُعد يورك منستر شاهدًا على مراحل العمارة القوطية الإنجليزية وعلى دور يورك الديني عبر قرون.","تظهر النوافذ الزجاجية الملونة الضخمة والأقبية والعقود المدببة وتفاصيل الواجهة الغربية.","https://yorkminster.org/","تطورت كاتدرائية يورك على مدى قرون وأصبحت من أكبر الكاتدرائيات القوطية في شمال أوروبا.","تظهر تحتها آثار لمراحل رومانية ونورمانية أقدم من البناء القوطي الحالي."],["GB","Bodleian Library","ترتبط مكتبة بودليان بتاريخ الدراسة والبحث في جامعة أكسفورد، وهي مؤسسة رئيسية لحفظ التراث المكتوب في بريطانيا.","تُلفت مبانيها التاريخية والساحات الجامعية وقاعة ديوك همفري القديمة الانتباه إلى تصميم فضاءات القراءة والحفظ.","https://visit.bodleian.ox.ac.uk/plan-your-visit/history-bodleian","افتُتحت مكتبة بودليان في أكسفورد أمام الباحثين في 8 نوفمبر 1602 بعد أن أعاد توماس بودلي تجهيز مكتبة جامعية أقدم، تضم مباني تعود إلى القرن الخامس عشر. ثم أبرم عام 1610 اتفاقًا مع نقابة الناشرين في لندن لتوريد نسخ من الكتب المطبوعة، مما مهّد لمكانة المكتبة بوصفها إحدى مكتبات الإيداع القانوني.","الاسم الحالي لا يعني أن جميع مباني المكتبة شُيّدت سنة 1602؛ فقاعة دوق همفري أقدم من إعادة افتتاحها. وتُعد مكتبة بودليان واحدة من مكتبات الإيداع القانوني التي تحفظ نسخًا من المطبوعات البريطانية، وهو دور يختلف عن إتاحة الكتب للإعارة العامة."],["GB","Lake District National Park","يجمع منتزه ليك ديستريكت بين الطبيعة الجبلية والرعي التاريخي والمناظر التي ألهمت أدباء وفنانين بريطانيين.","تظهر البحيرات الطولية والقمم والتلال الخضراء والجدران الحجرية والقرى الصغيرة بين الوديان.","https://whc.unesco.org/en/list/422","شكّلت الأنهار الجليدية خلال العصور الباردة أودية منطقة البحيرات في شمال غرب إنجلترا.","أُدرجت منطقة البحيرات في قائمة التراث العالمي عام 2017 بوصفها منظرًا ثقافيًا، لا لمجرد احتوائها على بحيرات وجبال. فقد أسهم الرعي والزراعة الجبلية والعمارة المحلية، إلى جانب الأدب والفن وحركات حماية الطبيعة، في تشكيل قيمتها التاريخية."],["GB","Old Man of Storr","هذا التكوين الصخري نتاج عمليات انزلاق أرضي وتعرية في شبه جزيرة تروترنيش بجزيرة سكاي، ولذلك يختلف عن الأبراج المبنية بشريًا.","يبرز العمود الصخري الداكن أمام المنحدرات الخضراء وبحيرات وسواحل سكاي في المشهد الأوسع.","https://thestorr.com/about/","تشكل عمود «أولد مان أوف ستور» في شبه جزيرة تروترنيش على جزيرة سكاي ضمن نطاق من الانهيارات والانزلاقات الصخرية القديمة. تعلو المنطقة طبقات من البازلت البركاني أثقل من الصخور الرسوبية الأقدم تحتها، فساعد اختلاف التكوينات على انفصال كتل وأعمدة صخرية عبر فترات طويلة.","الاسم الغيلي المحلي «بوداخ أن ستور» يرتبط بصورة الرجل العجوز، وتختلف الروايات الشعبية بشأن العمود بين هيئة وجه رجل وإصبع عملاق مدفون. هذه تفسيرات أسطورية للمنظر وليست أصلًا جيولوجيًا؛ فالأعمدة ناتجة عن انزلاقات صخرية وتعرية."],["AE","Palm Jumeirah","تمثل نخلة جميرا مشروعًا هندسيًا لتشكيل أرض جديدة في البحر، وقد أثّر تصميمها الشبيه بالنخلة على شكل الواجهة الساحلية في دبي.","تتضح هيئة الجذع والسعف والحاجز الهلالي من المشاهد الجوية، مع الفنادق والمباني الممتدة على الفروع.","https://www.visitdubai.com/en/places-to-visit/palm-jumeirah-2","أقيمت نخلة جميرا بمشروع استصلاح بحري على هيئة نخلة قبالة ساحل دبي.","تبدو هندستها المميزة بوضوح من الجو أكثر من مستوى الشارع."],["AE","Dubai Miracle Garden","تستعرض الحديقة استخدام الزراعة الموسمية في إنشاء مجسمات ومنشآت زهرية كبيرة داخل مناخ صحراوي حار.","تظهر الأقواس والأشكال الهندسية والمجسمات المغطاة بالأزهار، مع اختلاف التشكيلات من موسم لآخر.","https://www.dubaimiraclegarden.com/","تشتهر حديقة دبي المعجزة بعروض الأزهار الموسمية في تشكيلات ضخمة.","يتطلب الحفاظ على الحدائق الكبيرة في المناخ الصحراوي إدارة ري دقيقة."],["AE","Qasr Al Watan","يُبرز قصر الوطن جوانب من الثقافة الإماراتية ومؤسسات الحكم من خلال عمارة احتفالية ضخمة ومحتوى ثقافي معروض للجمهور.","تلفت القبة الكبيرة والأروقة الرخامية والزخارف الهندسية والثريات والقاعات الفسيحة الانتباه.","https://www.qasralwatan.ae/","يعمل قصر الوطن في أبوظبي بوصفه معلمًا ثقافيًا داخل مجمع رئاسي.","تسمح الزيارة بالتعرف على القاعات الرسمية والزخارف دون اختزال المكان في وظيفته السياسية."],["AE","Qasr al-Hosn","يعد قصر الحصن شاهدًا على تطور أبوظبي من مستوطنة ساحلية إلى مدينة حديثة، وقد ارتبط تاريخيًا بالحكم وحماية مصادر المياه.","يمكن مقارنة برج المراقبة الأبيض والأسوار الحجرية بالمباني المحيطة، وملاحظة الأفنية ومساحات العرض التراثية.","https://qasralhosn.ae/en/discover","بدأ قصر الحصن ببرج مراقبة دائم أُقيم تقريبًا في تسعينيات القرن الثامن عشر لحماية المستوطنة الساحلية ومراقبة طرق التجارة، ثم توسع إلى حصن ومقر للأسرة الحاكمة والحكومة في أبوظبي. ومع نمو المدينة احتفظ بدور سياسي وتاريخي، وأعيد تأهيله ليعرض قصة تطور الإمارة وتراثها.","يضم الموقع أقدم بناء دائم في أبوظبي، وهو برج المراقبة الأول، لكن هيئة القصر الحالية نتاج إضافات زمنية متعددة وليست كلها من فترة تأسيس البرج. كما استُخدم القصر مقرًا للحكم ومجلسًا استشاريًا وأرشيفًا وطنيًا عبر تاريخه."],["AE","Al Ain Oasis","توضح واحة العين نظام الأفلاج التقليدي الذي أسهم في استمرار زراعة النخيل في بيئة جافة، وهي جزء من موقع تراث عالمي أوسع.","تظهر الممرات الظليلة بين النخيل وقنوات الماء والمزارع الصغيرة، مع اختلاف درجات الضوء داخل البساتين.","https://whc.unesco.org/en/list/1343","تتميز واحة العين بمزارع النخيل المرتبطة بأنظمة ري تقليدية.","يشكل نظام الفلج عنصرًا مهمًا لفهم استدامة الواحة تاريخيًا."],["AE","Jebel Jais","يكشف جبل جيس عن تضاريس جبال الحجر الوعرة، حيث تتبدل المنحدرات والوديان مع الارتفاع عن مستوى البحر.","تظهر الطرق الجبلية المتعرجة والحواف الصخرية العميقة والطبقات الجيولوجية المكشوفة.","https://visitrasalkhaimah.com/","يقع جبل جيس في جبال الحجر بشمال الإمارات عند حدود عُمان.","تختلف درجات الحرارة في المرتفعات عن المناطق الساحلية المجاورة."],["AE","Al Bidya Mosque","يتميز مسجد البدية بصغر مساحته وهيئة سقفه ذي القباب الأربع، ما يجعله شاهدًا على تقاليد بناء محلية تختلف عن المساجد الضخمة.","تظهر القباب المنخفضة المتجاورة والدعامة الداخلية والجدران الطينية في مشهد جبلي بسيط.","https://fujairah.ae/","يُعد مسجد البدية موقعًا تاريخيًا صغيرًا على الساحل الشرقي للإمارات.","تكمن أهميته في بقاء مثال من عمارة المساجد المحلية التقليدية."],["TH","Wat Traimit","تنبع شهرة وات ترايميت من احتضانه تمثال بوذا الذهبي الكبير، ما يجعله موقعًا لفهم الفن التعبدي البوذي في بانكوك.","يبرز التمثال الجالس بسطحه الذهبي وتفاصيله الدقيقة داخل قاعة معبد ذات زخارف تايلاندية.","https://www.tourismthailand.org/Articles/top-5-must-visit-temples-in-bangkok-once-in-a-lifetime","يضم معبد وات ترايميت تمثال بوذا ذهبيًا ضخمًا في حي ياوارات ببانكوك.","يعكس المعبد جانبًا من التراث الديني والثقافي للصينيين التايلانديين في المنطقة."],["TH","Wat Rong Khun","يمثل المعبد الأبيض مشروعًا فنيًا دينيًا معاصرًا يستخدم اللون الأبيض والمرايا والرموز البصرية بكثافة.","تظهر الواجهات البيضاء اللامعة والجسر والتماثيل الرمزية والزخارف الدقيقة التي تعكس الضوء.","https://www.tourismthailand.org/Articles/chiang-rai-chiang-mai-a-great-low-budgeted-trip","صمّم الفنان تشاليرمتشاي كوسيتبيبات المعبد الأبيض في شيانغ راي.","يعكس البياض والمرايا معاني النقاء والضوء ضمن الرؤية الفنية."],["TH","Wat Rong Suea Ten","يشتهر المعبد الأزرق بألوانه غير المعتادة في العمارة الدينية التقليدية، ويجمع بين الرسم والنحت والطلاء اللامع.","تظهر الزخارف الزرقاء والذهبية على الواجهات والجدران، وتمثال بوذا الأبيض الكبير في الداخل.","https://www.tourismthailand.org/Articles/https-www-tourismthailand-org-articles-4must-seeplacesinchiangrai","يشتهر معبد وات رونغ سويا تن في شيانغ راي بلونه الأزرق المكثف.","تخلق الجدران الزرقاء والزخارف المذهبة تباينًا بصريًا مميزًا."],["TH","Phuket Big Buddha","أُنشئ التمثال المعاصر على مرتفع في فوكيت ليكون معلمًا بوذيًا بارزًا يُرى من مسافات بعيدة.","يبرز تمثال بوذا الجالس بكسوته الفاتحة فوق التلة، مع مشاهد واسعة للسواحل والمرتفعات المحيطة.","https://www.tourismthailand.org/Trip-Planner/Suggestion-Detail/recommended-route-for-one-day-3","يقع تمثال بوذا الكبير فوق تلة ناكيرد جنوب فوكيت، وهو معلم حديث بالمقارنة بالمعابد التايلاندية القديمة.","لا يُعد أثرًا قديمًا؛ أهميته مرتبطة بالمشهد الديني الحديث وموقعه."],["TH","Phi Phi Islands","تُظهر جزر في في أثر عمليات تعرية الصخور الجيرية في تشكيل جزر مرتفعة وجروف شديدة الانحدار تحيط بخلجان صغيرة.","تظهر المياه الفيروزية والجروف الكارستية والشواطئ الرملية، مع اختلاف المشاهد بين الجزر والخلجان.","https://www.tourismthailand.org/Destinations/Provinces/ko-phi-phi/359?funnel_id=WP_1006605&funnel_source=content_article","تشكل جزر في في أرخبيلًا من الحجر الجيري في بحر أندامان قبالة جنوب تايلاند.","تُعد حماية النظم البحرية وتقييد الضغط السياحي موضوعين مهمين في المنطقة."],["TH","Wat Mahathat (Ayutthaya)","يمثل المعبد جزءًا من آثار أيوثايا عاصمةً تاريخية، ويكشف ما تبقى من عمارتها الدينية بعد تراجع المدينة.","يظهر رأس تمثال بوذا محاطًا بجذور شجرة، إلى جانب قواعد الأبراج الطوبية والتماثيل المتضررة.","https://go.ayutthaya.go.th/tourist-attraction/wat-mahathat-mahathat-temple/","كان وات ماها ثات من أهم أديرة أيوثايا في قلب عاصمة سيام القديمة، ويرجّح أن تأسيسه يعود إلى أواخر القرن الرابع عشر. احتضن آثارًا بوذية مقدسة وشغل مكانة دينية رفيعة، ثم أصابت المدينة والمعابد أضرار واسعة مع سقوط أيوثايا سنة 1767، فبقيت الأبراج والأطلال شاهدًا على تاريخ المملكة.","الصورة الشهيرة لرأس بوذا المحاط بجذور شجرة هي تفصيل واحد من موقع أثري أوسع؛ فقد كان المعبد مركزًا دينيًا مرتبطًا بالسلطة الملكية. ولا يُعرف تاريخ محدد لوصول الرأس إلى موضعه الحالي داخل الجذور، لذا لا يصح تقديم قصة جازمة غير موثقة عن ذلك."],["TH","Erawan Falls","تتميز شلالات إيراوان بتدرجها على مستويات متعددة عبر تضاريس حجرية داخل غابة استوائية، ما يخلق أحواضًا مائية متتابعة.","تظهر المساقط المائية والبرك الخضراء المزرقّة والجذور والأشجار المحيطة بالمسار.","https://www.dnp.go.th/","تقع شلالات إيراوان داخل منتزه وطني في محافظة كانشانابوري بغرب تايلاند.","قد تختلف سهولة الوصول إلى المستويات العليا تبعًا للمياه والظروف الجوية."],["ID","Uluwatu Temple","يرتبط معبد أولوواتو بالمعتقدات الهندوسية في بالي وبموقعه الحاد على حافة جرف فوق المحيط الهندي.","تظهر مباني المعبد والبوابات الحجرية قرب حافة المنحدر، مع الأمواج والشمس المنخفضة خلف البحر.","https://www.indonesia.travel/gb/en/travel-ideas/pilgrimage/pura-uluwatu","يقف معبد أولواتو على جرف مرتفع عند الطرف الجنوبي الغربي لجزيرة بالي.","تضفي موجات المحيط الهندي على الموقع عنصرًا بصريًا لا ينفصل عن طبيعته المقدسة."],["ID","Ulun Danu Beratan Temple","يوضح المعبد علاقة الماء بالطقوس والزراعة في مرتفعات بالي، حيث يقع ضمن مشهد بحيري وبركاني بارد نسبيًا.","تظهر الأبراج ذات الأسقف المتدرجة قرب سطح بحيرة براتان، مع الضباب والجبال في الخلفية.","https://www.indonesia.travel/id/en/destination/bali-nusa-tenggara/bali/bali---ulun-danu-beratan","يقع مجمع أولون دانو براتان على ضفاف بحيرة جبلية في مرتفعات بالي.","تجعل تغيرات منسوب الماء بعض مبانيه تبدو طافية على سطح البحيرة."],["ID","Yogyakarta Palace","يحافظ قصر يوجياكارتا على تقاليد سلطانية جاوية حية، ويجمع بين السكن الرسمي والاحتفالات والفنون المحلية.","تظهر الأجنحة المفتوحة والأعمدة المزخرفة والأفنية الواسعة وأزياء وعروض تراثية مرتبطة بالقصر.","https://www.kratonjogja.id/","يظل قصر كراتون يوجياكارتا مقرًا تقليديًا للسلطان ومركزًا للفنون الجاوية.","لا يمثل مجمعًا أثريًا مهجورًا؛ فهو جزء من الحياة الثقافية المعاصرة للمدينة."],["ID","Ijen","يبرز مجمع إيجين بطبيعته البركانية النشطة وبحيرة الفوهة شديدة الحموضة ونشاط استخراج الكبريت في المنطقة.","يمكن مشاهدة البحيرة الفيروزية وجدران الفوهة وطبقات الكبريت الصفراء وأعمدة الغاز؛ والاقتراب من الغازات خطر.","https://www.indonesia.travel/id/en/destination/java/east-java/kawah-ijen","تشمل منطقة إيجين البركانية فوهة ذات بحيرة شديدة الحموضة ومناطق لرواسب الكبريت.","تنطوي المنطقة على مخاطر الغازات والانحدارات، ولا تصلح زيارتها دون احتياطات مناسبة."],["ID","Tana Toraja","تتميز منطقة توراجا بتقاليد معمارية وطقسية محلية، خاصة البيوت ذات الأسقف المقوسة المرتبطة بهوية المجتمعات الجبلية.","تظهر بيوت تونغكونان المزخرفة وصفوف حظائر الأرز والقرى الواقعة بين حقول ومصاطب خضراء.","https://www.indonesia.travel/content/dam/indtravelrevamp/en/campaign/itbberlin2024/pack/mp1rev.pdf","تشتهر مرتفعات تانا توراجا في سولاويسي الجنوبية بمنازل تونغكونان التقليدية.","تتجاوز قيمة الموقع الطبيعة إلى عمارة المجتمع ومعتقداته وتقاليده."],["ID","Raja Ampat Islands","يُعد أرخبيل راجا أمبات من المناطق البارزة في التنوع الحيوي البحري، ويجمع بين الشعاب المرجانية والجزر الجيرية الصغيرة.","تظهر الجزر الخضراء المتناثرة في مياه زرقاء صافية وبحيرات ومضائق ضيقة من المرتفعات المطلة.","https://www.conservation.org/","تقع جزر راجا أمبات قرب الطرف الشمالي الغربي لجزيرة غينيا الجديدة ضمن إندونيسيا.","ترتبط شهرتها بالحياة البحرية بقدر ارتباطها بمشهد الجزر الكارستية."],["ID","Kelimutu","تشتهر بحيرات كيليموتو الثلاث بتغير ألوانها عبر الزمن نتيجة ظروف كيميائية وفيزيائية مرتبطة بالنشاط البركاني والماء.","تظهر ثلاث بحيرات فوهية متجاورة تفصلها حواف صخرية حادة، وقد تتباين ألوانها بوضوح.","https://volcano.si.edu/volcano.cfm?vn=264140","يقع بركان كيليموتو في جزيرة فلوريس الإندونيسية، وتحتضن قمته ثلاث بحيرات فوهية منفصلة تتغير ألوانها مع تغير التفاعلات الكيميائية ونشاط الغازات والمياه الحارة تحت السطح. وتختلف البحيرات في تركيبها وظروفها، وقد سُجلت في المنطقة تغيرات حرارية ونشاطات بخارية عبر التاريخ؛ لذلك لا يمكن افتراض ثبات لون أي بحيرة.","اختلاف ألوان البحيرات لا يعني وجود أصباغ أضيفت إلى الماء."],["KR","Lotte World Tower","يمثل برج لوتّه ورلد أحد معالم العمارة الرأسية الحديثة في سيول، ويستعمل سطحًا زجاجيًا متدرجًا يحدد أفق المدينة.","تظهر قمته النحيلة والواجهة الزجاجية ومنصات المشاهدة التي تكشف نهر الهان والمباني المحيطة.","https://www.lwt.co.kr/","افتتح برج لوت وورلد في سيول سنة 2017 بوصفه معلمًا جديدًا في أفق المدينة.","تختلف شخصيته المعمارية الحديثة عن القصور والأحياء التاريخية المجاورة."],["KR","Deoksugung","يعكس قصر دوكسوغونغ مرحلة انتقالية في تاريخ كوريا الحديث من خلال تجاور مبانٍ ملكية تقليدية وأخرى ذات تأثيرات غربية.","يمكن مشاهدة بوابات القصر والأجنحة الخشبية المزخرفة مع المبنى الحجري الغربي داخل الحدائق.","https://www.kh.or.kr/","يقع قصر دوكسوغونغ في وسط سيول وكان مرتبطًا بالعائلة الملكية الكورية في أواخر عهد جوسون.","يوضح الموقع التحولات السياسية والثقافية الكورية في أواخر القرن التاسع عشر."],["KR","Namdaemun","تُعد بوابة نامدايمون شاهدًا على أسوار سيول التاريخية في عصر جوسون وعلى جهود ترميم التراث العمراني بعد الأضرار الحديثة.","تظهر القاعدة الحجرية والبوابة الخشبية متعددة الطوابق وسقفها التقليدي وسط منطقة تجارية معاصرة.","https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=111038","أقيمت بوابة سونغنيمون، المعروفة شعبيًا بنامدايمون، في أواخر القرن الرابع عشر بوصفها البوابة الجنوبية الرئيسية لأسوار هانيانغ، الاسم التاريخي لسيول، خلال بدايات حكم جوسون. تعرضت أجزاؤها الخشبية لحريق مدمر عام 2008، ثم أُعيد ترميمها وفتحها للجمهور في مايو 2013.","تجمع البوابة بين قاعدة حجرية ومبنى خشبي متعدد الطبقات، ويُكتب اسمها على اللوحة أعلى المدخل بصورة رأسية لافتة. ورغم اختفاء أجزاء من أسوار سيول التاريخية، بقي موضعها شاهدًا على تنظيم بوابات العاصمة ومداخلها."],["KR","Gamcheon Culture Village","يعكس الحي تحول منطقة سكنية على المنحدرات إلى مقصد ثقافي عبر الرسم الجداري والمبادرات الفنية المحلية.","تظهر البيوت الملونة المتدرجة على التلال والممرات الضيقة والأعمال الفنية الصغيرة بين الأزقة.","https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=72894","نشأ حي غامتشيون على منحدرات بوسان بوصفه تجمعًا سكنيًا استقبل لاجئين خلال الحرب الكورية في خمسينيات القرن العشرين. وفي عام 2009 تعاون سكان وفنانون محليون في مشروع تجديد حضري أضاف الرسوم والأعمال الفنية إلى الأزقة مع الحفاظ على الطابع السكني للحي، فصار مقصدًا ثقافيًا يُعرف بألوان منازله المتدرجة.","تصف هيئة السياحة الكورية غامتشيون بأنه «متحف بلا سقف» بسبب توزيع الأعمال الفنية بين البيوت والشوارع. لكنه حي يعيش فيه سكان بالفعل، ولذلك ترتبط قيمته أيضًا بتاريخ اللجوء والتجديد المجتمعي واحترام خصوصية المنازل، لا بالتصوير فقط."],["KR","Seongsan Ilchulbong","تكوّن سيونغسان إلتشولبونغ نتيجة ثوران بركاني تحت البحر، وهو جزء من تراث جيجو الطبيعي المسجل عالميًا.","تظهر الفوهة الدائرية المحاطة بحافة خضراء، مع البحر والحقول الساحلية من المرتفعات.","https://whc.unesco.org/en/list/1264","تشكّل مخروط سيونغسان إلتشولبونغ البركاني قبالة جزيرة جيجو قبل نحو خمسة آلاف سنة نتيجة تفاعل صهارة صاعدة مع مياه البحر، وهو ما أدى إلى انفجارات أنتجت طبقات من الرماد والمواد البركانية المتماسكة. كان التكوين جزيرة صغيرة منفصلة، ثم وصلته الرواسب الرملية والتربة تدريجيًا بساحل جيجو.","توجد عند القمة فوهة واسعة يبلغ قطرها نحو 600 متر، وليست بحيرة بركانية نشطة. واشتهر المكان بمراقبة شروق الشمس، لكن قيمته العلمية الأساسية ترجع إلى وضوح شكل المخروط الطفّي الناتج عن النشاط البركاني البحري."],["KR","Cheonjiyeon Waterfall","يوضح شلال تشيونجييون تفاعل مجرى الماء مع الصخور البركانية في جزيرة جيجو ضمن بيئة نباتية رطبة.","يسقط الماء على حوض عميق تحيط به الجدران الصخرية والنباتات الكثيفة والمسارات.","https://english.visitkorea.or.kr/svc/contents/contentsView.do?vcontsId=104751","يقع شلال تشيونجييون قرب سوغويبو جنوب جزيرة جيجو، في وادٍ تحيط به صخور بركانية ونباتات رطبة. شكّل تدفق المياه عبر التضاريس البركانية حافة السقوط والحوض أسفلها، بينما اكتسب الموقع قيمة بيئية بسبب الغطاء النباتي المحمي والكائنات المرتبطة بالمياه العذبة.","يبلغ ارتفاع الشلال نحو 22 مترًا، وتذكر هيئة السياحة الكورية أن اسم «تشيونجييون» يشير إلى اتصال السماء بالأرض. ويختلف عن شلال «تشيونجييه‌يون» ذي الاسم المشابه في منطقة جونغمون من جيجو؛ فهما موقعان منفصلان."],["KR","Cheomseongdae","يرتبط برج تشومسونغداي بتاريخ الرصد الفلكي في مملكة شلا، وهو مثال نادر على منشآت علمية مبكرة باقية في شرق آسيا.","يبرز البرج الحجري الأسطواني ذي الشكل المتدرج، وفتحة مربعة في منتصفه تقريبًا وسط مساحة عشبية.","https://english.visitkorea.or.kr/svc/contents/contentsView.do?menuSn=351&vcontsId=94442","يقع مرصد تشومسونغداي في مدينة غيونغجو، عاصمة مملكة شلا التاريخية.","تُعد وظيفته التفصيلية وطرق استخدامه موضع دراسة تاريخية."],["VN","Hoàn Kiếm Lake","تجمع بحيرة هوان كيم بين الحدائق الحضرية والأساطير المحلية والهوية التاريخية لوسط هانوي.","تظهر جزيرة برج السلحفاة الصغيرة وجسر هوك الأحمر المؤدي إلى معبد نغوك سون وسط الأشجار.","https://vietnam.travel/things-to-do/11-must-see-attractions-ha-noi/","تقع بحيرة هوان كيم في وسط هانوي، وترتبط في التراث المحلي بأسطورة السيف المُعاد التي اشتُق منها اسمها الشائع.","يصل جسر هوك الأحمر إلى معبد نغوك سون على جزيرة صغيرة، بينما يقع برج السلحفاة على جزيرة أخرى داخل البحيرة."],["VN","Imperial Citadel of Thăng Long","تكشف القلعة الإمبراطورية عن طبقات متعاقبة من الحكم والإدارة في هانوي وتطور مركزها السياسي عبر أكثر من ألف عام.","تظهر بوابات الحصن والساحات والأطلال الأثرية المكتشفة التي توضح تداخل فترات البناء.","https://whc.unesco.org/en/list/1328","بُنيت قلعة ثانغ لونغ الإمبراطورية في القرن الحادي عشر في عهد أسرة لي الفيتنامية، فوق بقايا حصن أقدم يعود إلى القرن السابع. وظلت المنطقة مركزًا للسلطة السياسية فترات طويلة، وتكشف الحفريات طبقات متعاقبة من القصور والأساسات والفنون التي تأثرت بتبادل ثقافي مع مناطق مجاورة.","تكشف حفريات موقع «18 هوانغ ديو» عن أساسات وآثار مبانٍ متعاقبة، ما يساعد على تتبع انتقال السلطة واستمرار مركز الحكم عبر قرون. وتنبّه اليونسكو إلى أن بعض المباني الظاهرة اليوم مرمّم أو أحدث عمرًا من الطبقات المدفونة؛ فلا تمثل الواجهات الحالية وحدها تاريخ القلعة بأكمله."],["VN","Ho Chi Minh Mausoleum","يمثل الضريح موقعًا تذكاريًا وطنيًا مرتبطًا بتاريخ فيتنام الحديث وبشخصية هو تشي منه.","تظهر الكتلة المعمارية الحجرية المنتظمة والساحة الواسعة والنصب والمباني الحكومية المحيطة.","https://thanglong.chinhphu.vn/english/ho-chi-minh-mausoleum-110663.htm","أُقيم ضريح هو تشي منه في ساحة با دينه في هانوي، حيث أُعلن استقلال فيتنام سنة 1945. بدأ بناؤه في 2 سبتمبر 1973 وافتُتح رسميًا في 29 أغسطس 1975، ليصبح موقعًا تذكاريًا وطنيًا مرتبطًا بشخصية هو تشي منه وبالتاريخ السياسي الفيتنامي الحديث.","يبلغ ارتفاع المبنى نحو 21.6 مترًا وعرضه نحو 41.2 مترًا، وفق الموقع الحكومي الفيتنامي، وتضم واجهته الحجرية مساحة رسمية للمراسم. ينبغي التمييز بين الضريح الذي افتتح عام 1975 والساحة التاريخية الأقدم التي شهدت إعلان الاستقلال."],["VN","Tam Cốc-Bích Động","تعكس المنطقة مشهد كارست نينه بينه حيث تمر المياه بين التلال الحجرية وحقول الأرز ضمن بيئة ثقافية وطبيعية متداخلة.","تُرى القوارب في الممرات المائية تحت الكهوف والجروف العالية، مع حقول الأرز على جانبي النهر.","https://whc.unesco.org/en/list/1438","تكوّنت تلال تام كوك–بيتش دونغ الكلسية ضمن مشهد كارستي تشكل عبر زمن جيولوجي طويل بفعل ذوبان الصخور ونحت المياه. وهي جزء من مجمع ترانغ آن الطبيعي والثقافي في نينه بينه، حيث تتداخل الكهوف والمجاري المائية وحقول الأرز مع تاريخ استيطان بشري قديم داخل النطاق الأوسع.","تعني «تام كوك» الكهوف الثلاثة، وتُزار ممراتها المائية بالقوارب عبر مناظر حقول الأرز والجبال. أما تسجيل اليونسكو فهو باسم مجمع ترانغ آن الأوسع، الذي يشمل أيضًا آثارًا ترتبط باستيطان بشري لأكثر من ثلاثين ألف سنة، وليس تسجيلًا منفصلًا لكهوف تام كوك."],["VN","Golden Bridge (Vietnam)","يمثل الجسر الذهبي تصميمًا معاصرًا لممر مشاة مرتفع يعتمد على عنصر بصري غير اعتيادي هو اليدان العملاقتان.","يظهر الممشى الذهبي المقوس فوق المنحدرات محمولًا بصريًا على يدين صخريتين وسط المشهد الجبلي.","https://sunworld.vn/en/banahills/activities/golden-bridge","افتُتح الجسر الذهبي في يونيو 2018 ضمن مجمع با نا هيلز الجبلي قرب دا نانغ، وصُمم ممشىً مرتفعًا يصل بين مرافق المنتجع والحدائق ويمنح إطلالة على المنحدرات. اشتهر عالميًا باليدين العملاقتين اللتين تبدوان كأنهما تحملان الممر، فصار مثالًا لمعالم السياحة المعمارية المعاصرة.","يمتد الجسر نحو 150 مترًا ويقع على ارتفاع يقارب 1414 مترًا فوق سطح البحر وفق موقع منتجع با نا هيلز. اليدان عنصران تصميميان حديثان، وليستا منحوتتين أثريتين قديمتين؛ والمكان جزء من مشروع سياحي معاصر وليس ممرًا تاريخيًا."],["VN","Phú Quốc National Park","يحمي منتزه فو كوك غابات استوائية وموائل طبيعية على الجزيرة، ويسهم في حفظ جانب من تنوعها البيئي.","تظهر الغابات الكثيفة والمجاري المائية والمرتفعات الداخلية بعيدًا عن الشواطئ العمرانية.","https://vietnam.travel/things-to-do/phu-quoc-nature/","يحمي منتزه فو كوك الوطني أجزاء من الغابات المدارية داخل جزيرة فو كوك.","تُظهر المنطقة جانبًا طبيعيًا مختلفًا عن شواطئ الجزيرة السياحية."],["VN","Phong Nha Cave","يبرز كهف فونغ نها ضمن منظومة كارستية واسعة في وسط فيتنام، وتكشف ممراته المائية أثر ذوبان الحجر الجيري عبر الزمن.","تظهر القاعات الصخرية والهوابط والصواعد والنهر الجوفي الذي يمر عبر أجزاء من الكهف.","https://whc.unesco.org/en/list/951","يقع كهف فونغ نها ضمن المشهد الكارستي الواسع لمنطقة فونغ نها–كي بانغ في وسط فيتنام، حيث تطورت التكوينات الجيرية عبر مئات الملايين من السنين. وساهمت المياه الجوفية والأنهار في نحت ممرات وكهوف معقدة، وأصبحت المنطقة مرجعًا لفهم تطور التضاريس الكارستية والأنظمة البيئية تحت الأرض.","يُعد جزءًا من منظومة كهوف منطقة فونغ نها-كي بانغ ذات الأهمية الجيولوجية."],["EG","Great Sphinx of Giza","يمثل أبو الهول أحد أقدم التماثيل الضخمة الباقية في مصر، ويرتبط بالمشهد الجنائزي لهضبة الجيزة وبفكرة الحراسة الملكية في الفن المصري القديم.","تظهر ملامح الرأس البشري وجسم الأسد المنحوت من الحجر الجيري، مع آثار التعرية والترميم حول جسده.","https://egymonuments.gov.eg/monuments/the-great-sphinx/","أبو الهول تمثال حجري هائل منحوت مباشرة من صخر هضبة الجيزة. يرجح علماء الآثار أنه أُنجز في عهد الملك خفرع خلال الأسرة الرابعة، وأن هيئته تجمع بين قوة الأسد ورمزية الملك.","كانت بعض أجزاء أبي الهول مدفونة في الرمال عبر فترات طويلة من تاريخه."],["EG","Karnak Temple","يعكس الكرنك تراكم البناء الديني في طيبة عبر أجيال من الفراعنة، وكان أحد أهم المراكز المرتبطة بعبادة آمون.","تُبرز قاعة الأعمدة الكبرى صفوف الأعمدة الشاهقة والكتابات الملونة والمسلات والبحيرة المقدسة.","https://whc.unesco.org/en/list/87","الكرنك ليس معبدًا واحدًا؛ بل مجمع ديني متسع في طيبة القديمة، شاركت أجيال من الفراعنة في توسيعه. كان مركزًا رئيسيًا لعبادة آمون، وأصبحت بواباته وساحاته ومسلاته سجلًا معماريًا لتاريخ مصر.","تضم قاعة الأعمدة الكبرى في الكرنك 134 عمودًا حجريًا، ويبلغ ارتفاع أعمدة الممر الأوسط نحو 20 مترًا وفق وصف اليونسكو. ويرتبط إنشاء القاعة بصورة خاصة بعهدي سيتي الأول ورمسيس الثاني، لذلك فهي مثال على اتساع المشروعات الملكية المتعاقبة داخل مجمع طيبة الديني."],["EG","Abu Simbel Temples","تُظهر معابد أبو سمبل قوة الرمزية الملكية في عهد رمسيس الثاني؛ كما أصبحت مثالًا عالميًا لإنقاذ التراث عند نقلها قبل غمر المنطقة بمياه السد العالي.","تظهر التماثيل الأربعة الجالسة أمام المعبد الكبير، والممرات المنحوتة في الصخر والمعبد الأصغر المرتبط بنفرتاري.","https://whc.unesco.org/en/list/88","نُحت معبدا أبو سمبل في الصخر خلال عهد رمسيس الثاني في النوبة، ليجسدا القوة الملكية والعبادة الدينية. وعندما هدد إنشاء السد العالي الموقع بالغمر، أُطلقت حملة دولية لإنقاذه.","أُعيد تركيب أكثر من ألف كتلة حجرية خلال عملية إنقاذ أبو سمبل."],["FR","Louvre Museum","يُبرز اللوفر تاريخ تحول قصر ملكي إلى متحف عالمي، وتسمح مجموعاته بمقارنة الفنون والآثار عبر حضارات وفترات متعددة.","تظهر الهرم الزجاجي في ساحة نابليون وقاعات العرض داخل المبنى التاريخي، إلى جانب أعمال شهيرة من الرسم والنحت والآثار.","https://www.louvre.fr/en","بدأ اللوفر قلعةً دفاعية في باريس أواخر القرن الثاني عشر، ثم تحول إلى مقر ملكي، قبل أن يفتح متحفًا للفنون في نهاية القرن الثامن عشر. لذلك يجمع المبنى بين تاريخ العمارة الفرنسية ومجموعات الفن العالمي.","افتُتح الهرم الزجاجي الذي صممه المعماري آي. إم. باي في 29 مارس 1989 ليصبح مدخلًا حديثًا للمتحف التاريخي."],["FR","Palace of Versailles","يمثل فرساي رمزًا لسلطة البلاط الفرنسي وفنون التخطيط المعماري والحدائق الرسمية خلال القرن السابع عشر وما بعده.","تلفت قاعة المرايا والواجهات الطويلة والحدائق الهندسية والنوافير والقنوات المائية الانتباه.","https://whc.unesco.org/en/list/83","تحول فرساي من مقر للصيد إلى قصر ملكي واسع ارتبط بقوة لويس الرابع عشر. أصبح مركزًا للحكم والبلاط الفرنسي، وامتدت حوله حدائق هندسية تجسد مفهوم السيطرة على المنظر الطبيعي.","كانت مرايا فرساي استعراضًا للتقدم الصناعي الفرنسي في صناعة المرايا."],["FR","Mont-Saint-Michel","يُجسد مون سان ميشيل ارتباط العمارة الرهبانية بالبيئة الساحلية التي تتحول بصريًا مع حركة المد والجزر.","تظهر الأبنية الحجرية متدرجة على الجزيرة وصولًا إلى الدير في القمة، وتحيط بها المسطحات المدية الواسعة.","https://whc.unesco.org/en/list/80","مون سان ميشيل جزيرة صخرية على ساحل نورماندي، تعلوها كنيسة دير ومبانٍ تاريخية. جمع الموقع بين مركز ديني محصن وقرية صغيرة نمت أسفل الدير، وسط خليج تتغير تضاريسه المرئية بفعل المد والجزر.","قد تبدو الجزيرة محاطة بالرمال في وقت، وبالمياه في وقت آخر بحسب المد."],["IT","Leaning Tower of Pisa","يوضح ميل برج بيزا أثر اختلاف قدرة تحمل التربة على المنشآت الثقيلة، كما يكشف تاريخ محاولات المحافظة على مبنى فريد دون إلغاء طابعه.","تظهر طبقات الأروقة الدائرية والميل الواضح بالنسبة للمباني المحيطة في ساحة المعجزات.","https://whc.unesco.org/en/list/395","برج بيزا المائل ليس برج مراقبة، بل برج أجراس مستقل تابع لكاتدرائية بيزا في ساحة المعجزات. بدأ بناؤه سنة 1173، وظهر ميله مبكرًا بسبب هبوط غير متساوٍ في التربة تحت الأساسات، ما جعل استكمال البناء يستغرق مراحل طويلة.","لم يُصمم البرج مائلًا؛ بل تحول عيب التربة إلى أشهر سماته."],["IT","Trevi Fountain","تُعد نافورة تريفي من أشهر نماذج المزج بين النحت والعمارة الباروكية في الفضاء العام بروما.","تظهر الكتلة المعمارية خلف التماثيل الصخرية والمياه المتدفقة، مع شخصية أوقيانوس المركزية والخيول البحرية.","https://www.turismoroma.it/en","نافورة تريفي من أشهر معالم روما الباروكية، وتستند إلى الواجهة الخلفية لقصر بولي. بدأ إنشاء تصميمها الحالي سنة 1732 على يد المعماري نيكولا سالفي، وأكمله جوزيبي بانيني سنة 1762، لتصبح احتفاءً معماريًا بالماء.","ليست النافورة قطعة منفصلة عن المدينة؛ فهي تبدو كجزء من الواجهة المعمارية لقصر بولي."],["IT","Milan Cathedral","تعكس كاتدرائية ميلانو تقاليد العمارة القوطية المتأخرة ومراحل بناء طويلة شاركت فيها أجيال من المعماريين والحرفيين.","تظهر الواجهة الرخامية وآلاف العناصر النحتية والأبراج المدببة والمنحوتات المرتفعة فوق السطح.","https://www.duomomilano.it/en/","كاتدرائية ميلانو، أو الدومو، مشروع عمراني وديني استمر تطويره قرونًا. بدأ بناؤها سنة 1386، ثم تحولت من مخطط محلي إلى نموذج بارز من العمارة القوطية الأوروبية، بواجهات رخامية وأبراج دقيقة التفاصيل.","استمر العمل في الكاتدرائية على مدى نحو ستة قرون، ولذلك أصبحت رمزًا للمشروعات التي لا تنتهي سريعًا."],["SA","Masjid al-Haram","المسجد الحرام أقدس مسجد في الإسلام، وهو مركز شعائر الحج والعمرة التي تستقطب المسلمين من أنحاء العالم.","تظهر الكعبة المشرفة في قلب المطاف، والمساحات الواسعة المخصصة للطواف والصلاة والأروقة المحيطة.","https://www.nusuk.sa/","المسجد الحرام هو أعظم المساجد قدسية لدى المسلمين، وتقع الكعبة المشرفة في وسطه بمكة المكرمة. ارتبط عبر التاريخ بالحج والعمرة والصلاة، وشهد توسعات متعاقبة لخدمة المصلين وقاصدي بيت الله الحرام.","تطورت منطقة السعي بين الصفا والمروة من مسار تاريخي إلى منشأة متعددة المستويات تخدم أعدادًا كبيرة من الزوار."],["SA","Prophet's Mosque","يرتبط المسجد النبوي بالهجرة النبوية ونشأة المجتمع الإسلامي في المدينة، وقد توسع عمرانيًا خلال عصور متلاحقة.","تظهر القبة الخضراء والمآذن والساحات الخارجية والمظلات القابلة للفتح، إلى جانب عمارة قاعات الصلاة.","https://www.nusuk.sa/","تأسس المسجد النبوي في المدينة المنورة في السنة الأولى للهجرة، ليصبح مركزًا للصلاة والحياة الاجتماعية في المجتمع الإسلامي الأول. وشهد توسعات متتابعة عبر العصور الإسلامية وصولًا إلى التوسعات السعودية الحديثة.","كان المسجد عند إنشائه أصغر بكثير من نطاقه الواسع اليوم؛ وتكشف توسعاته عن نمو المدينة عبر القرون."],["SA","At-Turaif District","يمثل حي الطريف مركزًا تاريخيًا للدولة السعودية الأولى، ويُظهر تميز عمارة نجد بالطين والتكيف مع البيئة المحلية.","تظهر الجدران الطينية والقصور التاريخية والأبراج والممرات المطلة على وادي حنيفة.","https://whc.unesco.org/en/list/1329","حي الطريف التاريخي يقع في الدرعية شمال غرب الرياض، ويعكس نشأة مركز سياسي وعمراني مهم ارتبط بالدولة السعودية الأولى. بنيت كثير من مبانيه باستخدام الطين وفق تقاليد العمارة النجدية المتكيفة مع البيئة المحلية.","يمثل حي الطريف مثالًا على بناء مجمعات قصور كبيرة باستخدام الطوب الطيني."],["TR","Blue Mosque","يُعرف مسجد السلطان أحمد بتصميمه العثماني ذي القباب المتدرجة والمآذن الست، وبالزخارف الخزفية التي أكسبته اسمه الشائع.","تظهر الأفنية الواسعة والقباب المتداخلة والنوافذ العديدة والبلاطات الزرقاء المزخرفة داخل قاعة الصلاة.","https://goturkiye.com/istanbul/blue-mosque","الجامع الأزرق، المعروف رسميًا بجامع السلطان أحمد، بُني في إسطنبول خلال حكم السلطان أحمد الأول بين عامي 1609 و1616م. أراد مؤسسوه إنشاء صرح ديني كبير في موقع بارز قبالة آيا صوفيا، فأصبح واحدًا من أشهر معالم العمارة العثمانية.","جاءت تسمية «الجامع الأزرق» من الانطباع البصري الذي تتركه زخارف البلاط داخل المسجد."],["TR","Topkapi Palace","كان طوب قابي مقرًا للسلاطين العثمانيين وإدارة الدولة قرونًا؛ وتعكس ساحاته المتتابعة التدرج بين المجال العام والخاص.","تظهر البوابات والفناءات والأجنحة المزخرفة والخزائن والمساحات المطلة على البوسفور.","https://www.millisaraylar.gov.tr/Lokasyon/2/Topkapi-Sarayi?culture=en","قصر توبكابي مجمع ملكي عثماني أُقيم بعد فتح القسطنطينية، وبناه السلطان محمد الفاتح بين عامي 1460 و1478م. ظل مقرًا للحكم والإقامة السلطانية قرونًا، ثم تطور على أيدي سلاطين متعاقبين بإضافة أجنحة وقاعات وحدائق.","ليس القصر مبنى واحدًا؛ بل مدينة قصر صغيرة تضم ساحات وبوابات وأجنحة مختلفة."],["TR","Göreme Open Air Museum","تكشف كنائس غوريم المنحوتة في الصخور البركانية عن تاريخ الرهبنة والرسوم الدينية البيزنطية في كابادوكيا.","يمكن رؤية واجهات الكهوف والغرف الصخرية والرسوم الجدارية الملونة داخل الكنائس القديمة.","https://whc.unesco.org/en/list/357","متحف غوريم المفتوح جزء من المشهد الثقافي والطبيعي الفريد في كابادوكيا بوسط الأناضول. حفرت جماعات مسيحية تاريخية كنائس وأديرة ومساكن داخل الصخور البركانية اللينة، وازدهرت فيها رسوم جدارية من العصر البيزنطي.","تحولت الصخور البركانية اللينة إلى مساحات معيشة وعبادة بدلاً من الاعتماد على البناء فوق الأرض وحده."],["ES","Sagrada Família","تمثل ساغرادا فاميليا مشروعًا معماريًا طويل الأمد مستوحى من رؤية أنطوني غاودي للطبيعة والهندسة والرمزية الدينية.","تظهر الأبراج والواجهات النحتية المعقدة والأعمدة الداخلية الشبيهة بالأشجار والزجاج الملون.","https://sagradafamilia.org/en/","ساغرادا فاميليا بازيليكا فريدة في برشلونة ارتبطت بالمعماري أنطوني غاودي. بدأ مشروعها سنة 1882 بتصميم أولي مختلف، ثم تولى غاودي العمل سنة 1883 وأعاد صياغة المشروع اعتمادًا على الأشكال الطبيعية والهندسة والرمزية الدينية.","لم يرَ غاودي مكتملًا سوى برج واحد من أبراج الواجهة التي صممها قبل وفاته سنة 1926م."],["ES","Prado Museum","يبرز متحف برادو بوصفه مرجعًا رئيسيًا للرسم الأوروبي، وخاصة المجموعات الملكية الإسبانية وأعمال كبار الرسامين.","تظهر لوحات لفيلاسكيز وغويا وغيرهما في قاعات تاريخية ذات ترتيب يساعد على مقارنة المدارس الفنية.","https://www.museodelprado.es/en","متحف برادو في مدريد أحد أبرز المتاحف الأوروبية للفنون الجميلة. نشأ من مجموعات ملكية إسبانية، وافتتح للجمهور سنة 1819م داخل مبنى صممه المعماري خوان دي فيانويفا أصلاً لمؤسسة علمية.","كان المبنى الأصلي مخصصًا في البداية لمجموعة التاريخ الطبيعي، قبل أن يتحول إلى متحف فني."],["ES","Mosque–Cathedral of Córdoba","يعكس المبنى طبقات من تاريخ قرطبة الديني والمعماري، إذ استمر استخدامه وتعديله عبر فترات إسلامية ومسيحية متعاقبة.","تُعد الغابة الداخلية من الأعمدة والأقواس الحمراء والبيضاء أبرز عناصره، مع المحراب والزخارف والقلب الكاتدرائي اللاحق.","https://whc.unesco.org/en/list/313","مسجد قرطبة الكبير، المعروف اليوم بمسجد-كاتدرائية قرطبة، من أهم آثار الأندلس. بدأ بناؤه في عهد الأمير عبد الرحمن الداخل بين عامي 786 و788م، ثم جرت توسعات مهمة في عصور لاحقة؛ وبعد سنة 1236 تحول إلى كنيسة كاثوليكية أُضيفت إليها منشآت معمارية جديدة.","تخلق صفوف الأعمدة والأقواس الحمراء والبيضاء إحساسًا ببهو واسع ومتكرر الإيقاع."],["GB","Tower of London","تجمع قلعة لندن بين تاريخ السلطة الملكية والدفاع والسجون وحفظ الرموز الملكية، وهي جزء أساسي من تاريخ العاصمة الإنجليزية.","يظهر البرج الأبيض والأسوار والأبراج المحيطة والفناءات ومرافق عرض جواهر التاج.","https://www.hrp.org.uk/tower-of-london/","برج لندن قلعة ملكية على الضفة الشمالية لنهر التايمز، بدأ تشييد برجها الأبيض بعد الفتح النورماني لإنجلترا في القرن الحادي عشر. تعاقبت عليه وظائف الدفاع والإقامة الملكية والسجن وحفظ مقتنيات التاج، وصار شاهدًا على تحولات السلطة البريطانية.","أُطلق اسم «البرج الأبيض» على قلب القلعة بعد طلاء واجهاته باللون الأبيض في القرن الثالث عشر."],["GB","Big Ben","يشير اسم بيغ بن في الأصل إلى الجرس الكبير داخل برج إليزابيث، وأصبح الاسم شائعًا للدلالة على البرج وساعته.","تظهر واجهة الساعة الأربع والزخارف القوطية الدقيقة والقمة المدببة للبرج بجوار مباني البرلمان.","https://www.parliament.uk/about/living-heritage/building/palace/big-ben/","برج إليزابيث في لندن هو برج الساعة الشهير المجاور لقصر وستمنستر. أما «بيغ بن» فهو في الأصل اسم الجرس الكبير، لكنه أصبح يستخدم شعبيًا للإشارة إلى البرج كله. أُنجز البرج ضمن إعادة بناء البرلمان بعد حريق 1834.","الاسم الشائع «بيغ بن» يخص الجرس الكبير تاريخيًا، لا الساعة أو المبنى نفسه."],["GB","British Museum","يتيح المتحف البريطاني دراسة مجموعات من آثار وفنون حضارات عديدة، مع أهمية مناقشة تاريخ اقتناء بعض القطع والنزاعات المتعلقة بإعادتها.","تظهر قاعات آثار مصر وآشور واليونان والساحة الكبرى المسقوفة بالزجاج في قلب المبنى.","https://www.britishmuseum.org/","المتحف البريطاني أحد أقدم المتاحف العامة الكبرى في العالم. تأسس سنة 1753 على أساس مجموعات عالم الطبيعة والطبيب هانز سلون، وفتح أبوابه للجمهور سنة 1759، ثم اتسعت مجموعاته لتشمل آثارًا ومواد تاريخية من قارات وحضارات مختلفة.","كان المتحف يجمع في بدايته مقتنيات من التاريخ الطبيعي إلى جانب القطع الأثرية والكتب."],["US","Statue of Liberty","أصبح تمثال الحرية رمزًا للتبادل التاريخي بين فرنسا والولايات المتحدة ولتصورات الحرية والهجرة في الذاكرة الأمريكية.","تظهر الشعلة واللوح والتاج ذي الأشعة السبعة، مع القاعدة الحجرية وموقع التمثال في ميناء نيويورك.","https://www.nps.gov/stli/index.htm","تمثال الحرية نصب تذكاري في ميناء نيويورك قُدم هدية من شعب فرنسا إلى الولايات المتحدة تعبيرًا عن الصداقة وقيم الحرية. صممه النحات فريديريك أوغست بارتولدي، وساعد غوستاف إيفل في تصميم هيكله الداخلي، ودُشن سنة 1886.","كان لون النحاس الأصلي أقرب إلى البني، ثم اكتسب اللون الأخضر المعروف اليوم بفعل تفاعل سطحه مع البيئة."],["US","Central Park","يمثل سنترال بارك نموذجًا مهمًا لتصميم الحدائق العامة في المدن الصناعية، حيث صُممت مناظر طبيعية داخل شبكة مانهاتن العمرانية.","تتوزع المروج والبحيرات والجسور والمسارات المشجرة، وتظهر الأبراج العالية خلف المشهد الأخضر.","https://www.centralparknyc.org/","سنترال بارك متنزه حضري واسع في قلب مانهاتن بنيويورك، أُنشئ في القرن التاسع عشر لتوفير مساحة عامة للراحة والطبيعة داخل مدينة سريعة النمو. ارتبط تصميمه بالمخططين فريدريك لو أولمستد وكالفرت فو.","كثير من المناظر التي تبدو طبيعية تمامًا صممها مهندسو المناظر الطبيعية وزُرعت أو شُكلت عمدًا."],["US","Lincoln Memorial","يُخلّد النصب ذكرى أبراهام لنكولن، ويرتبط أيضًا بتاريخ الحقوق المدنية الأمريكية والخطابات الجماهيرية التي شهدتها ساحته.","تظهر الأعمدة الخارجية وتمثال لنكولن الجالس والنقوش الداخلية، مع انعكاس المبنى في البركة التذكارية.","https://www.nps.gov/linc/index.htm","نصب لنكولن التذكاري معلم وطني في واشنطن العاصمة يخلد الرئيس الأمريكي أبراهام لنكولن ودوره خلال الحرب الأهلية الأمريكية. دُشن سنة 1922، وأصبح لاحقًا مسرحًا لأحداث محورية في حركة الحقوق المدنية.","الأعمدة الخارجية الستة والثلاثون ترمز إلى عدد الولايات الأمريكية عند وفاة لنكولن عام 1865."],["CN","Forbidden City","كانت المدينة المحرمة مركزًا للحكم الإمبراطوري في بكين خلال أسرتَي مينغ وتشينغ، وتُظهر تخطيطًا صارمًا للمحاور والساحات الرسمية.","تظهر البوابات المتتابعة والأسقف الصفراء والقاعات الاحتفالية والأفنية المتناظرة.","https://whc.unesco.org/en/list/439","المدينة المحرمة في بكين مجمع قصور إمبراطورية كان مركز السلطة في عهد أسرتي مينغ وتشينغ. شُيد الجزء الأساسي بين 1406 و1420 في عهد الإمبراطور يونغله، ثم استُخدم مقرًا للأباطرة وطقوس البلاط لقرون طويلة.","كان الدخول إلى الأجزاء الداخلية محكومًا بقواعد صارمة للرتب والمراسم، وهو ما يفسر تسميته."],["CN","Temple of Heaven","يعكس معبد السماء طقوس الدولة الإمبراطورية المتعلقة بالدعاء لمواسم الحصاد، مع استخدام هندسة رمزية في المباني والساحات.","تظهر قاعة الصلاة الدائرية ذات السقف الأزرق والمصاطب الرخامية والممرات المحاطة بالأشجار.","https://whc.unesco.org/en/list/881","معبد السماء مجمع احتفالي إمبراطوري جنوب بكين، أسس في القرن الخامس عشر لإقامة طقوس مرتبطة بالسماء والدعاء لمحاصيل جيدة. يعبر تخطيطه عن علاقة رمزية بين السماء والأرض ودور الإمبراطور في المعتقدات التقليدية.","تُستخدم الدوائر والمربعات في المخطط للدلالة على تصورات تاريخية للسماء والأرض."],["CN","Terracotta Army","تُظهر تماثيل جيش التيراكوتا حجم مشروع الدفن المرتبط بالإمبراطور تشين شي هوانغ، وتقدم شواهد على التنظيم العسكري والحرف في الصين القديمة.","تظهر صفوف الجنود والخيول الطينية مختلفة الملامح داخل حفر تنقيب ضخمة مغطاة.","https://whc.unesco.org/en/list/441","جيش التيراكوتا مجموعة هائلة من تماثيل الجنود والخيول المصنوعة من الطين المحروق، اكتُشفت قرب ضريح الإمبراطور تشين شي هوانغ في شيآن عام 1974. كانت التماثيل جزءًا من منظومة جنائزية إمبراطورية تعكس تنظيم الجيوش في الصين القديمة.","كانت تماثيل الجنود ملوّنة عند صنعها، لكن الألوان تضررت بشدة بعد التنقيب والتعرض للهواء."],["IN","Red Fort","يجسد الحصن الأحمر فترة ازدهار الحكم المغولي في دلهي، ويُظهر التداخل بين التحصينات والمباني الملكية والحدائق.","تظهر الجدران الحمراء والبوابات والقاعات الرخامية والزخارف داخل المجمع.","https://whc.unesco.org/en/list/231","القلعة الحمراء في دلهي حصن وقصر إمبراطوري شُيد خلال حكم شاه جهان في القرن السابع عشر، وأصبح مركزًا للحكم المغولي في العاصمة الجديدة شاهجهان آباد. شهدت جدرانه أحداثًا سياسية كبرى وتحولات في تاريخ الهند.","رغم اللون الأحمر الشهير للأسوار، فإن بعض مباني الداخل استخدمت الرخام الأبيض."],["IN","Hawa Mahal","يمثل قصر الرياح واجهة معمارية مميزة في جايبور، صُممت بنوافذ كثيرة تسمح بالتهوية والرؤية من وراء شاشات حجرية.","تظهر الواجهة الوردية المتدرجة والشرفات الصغيرة المتكررة والزخارف الشبكية.","https://www.tourism.rajasthan.gov.in/","هوا محل أو «قصر الرياح» واجهة معمارية شهيرة في جايبور الهندية، أمر ببنائها المهراجا ساواي براتاب سينغ عام 1799. صممت للمشاهدة والتهوية، وتشتهر بطبقات النوافذ الصغيرة المرتبة في واجهة وردية.","يُقال إن الواجهة مستوحاة من هيئة تاج الإله كريشنا في التقاليد المحلية."],["IN","Qutb Minar","تُبرز منارة قطب منار تطور العمارة الإسلامية المبكرة في دلهي، ضمن مجمع أثري متعدد المباني والنقوش.","تظهر طبقات البرج المخددة والكتابات الحجرية والشرفات البارزة، مع الأطلال المحيطة في المجمع.","https://whc.unesco.org/en/list/233","قطب منار مئذنة حجرية مرتفعة داخل مجمع قطب التاريخي في دلهي. بدأ تشييدها في أواخر القرن الثاني عشر في فترة قيام سلطنة دلهي، واكتملت أو عُدّلت مراحل منها على أيدي حكام لاحقين.","يضم المجمع عمودًا حديديًا تاريخيًا سبق بناء المئذنة بعدة قرون."],["JP","Kinkaku-ji","يُعد الجناح الذهبي في كيوتو مثالًا على مزج العمارة الدينية بالحدائق اليابانية، وتُكوّن انعكاساته على الماء جانبًا من جمال الموقع.","يظهر الجناح المذهب وسط البركة والأشجار والصخور المرتبة بعناية حول المسار.","https://www.shokoku-ji.jp/en/kinkakuji/","كينكاكو-جي، أو الجناح الذهبي، من أشهر معالم كيوتو اليابانية. كان في الأصل جزءًا من مقر تابع للشوغون أشيكاغا يوشيميتسو أُنشئ أواخر القرن الرابع عشر، ثم تحول بعد وفاته إلى معبد زن بوذي، وأعيد بناء الجناح بعد حريق في القرن العشرين.","يمثل كل مستوى من الجناح أسلوبًا معماريًا مختلفًا مرتبطًا بالبلاط والساموراي والزن."],["JP","Tokyo Tower","استوحى برج طوكيو من أبراج الاتصالات الحديدية الكبيرة، وأصبح رمزًا لمرحلة التحديث والنمو الياباني بعد الحرب العالمية الثانية.","تظهر البنية الشبكية الحمراء والبيضاء والمنصات المرتفعة وسط عمران طوكيو.","https://en.tokyotower.co.jp/","برج طوكيو معلم معدني للاتصالات والمشاهدة اكتمل عام 1958 خلال مرحلة إعادة بناء اليابان بعد الحرب العالمية الثانية. استُوحي هيكله من برج إيفل مع اختلافات في التصميم والحجم والوظيفة، وأصبح رمزًا لمدينة طوكيو الحديثة.","يتجاوز ارتفاع برج طوكيو الارتفاع الأصلي لبرج إيفل عند افتتاحه."],["JP","Sensō-ji","يرتبط سينسوجي بالتراث البوذي الشعبي في منطقة أساكوسا، وما زال نقطة التقاء دينية وثقافية داخل طوكيو.","تظهر بوابة كاميناريمون بفانوسها الأحمر الضخم وشارع ناكاميسي التجاري والباغودا وقاعة المعبد.","https://www.senso-ji.jp/english/","سينسو-جي معبد بوذي تاريخي في حي أساكوسا بطوكيو. تربط الرواية التقليدية نشأته بعثور صيادين على تمثال للبوذيساتفا كانون في نهر سوميدا في القرن السابع الميلادي، ثم تطور الموقع إلى مركز ديني وثقافي شهير.","يُعرف المكان أيضًا باسم أساكوسا كانون في بعض المراجع."],["AE","Sheikh Zayed Grand Mosque","يعكس جامع الشيخ زايد رؤية معمارية حديثة تستلهم أساليب إسلامية متعددة، وأصبح من أشهر معالم أبوظبي الدينية والثقافية.","تظهر القباب البيضاء والمآذن والأعمدة المطعمة والزخارف النباتية والساحات الرخامية الواسعة.","https://www.szgmc.gov.ae/","جامع الشيخ زايد الكبير معلم ديني ومعماري بارز في أبوظبي، ارتبط برؤية الشيخ زايد بن سلطان آل نهيان لإنشاء مسجد يعكس قيم التسامح وجمال العمارة الإسلامية. بدأت أعمال البناء عام 1996، وفتح أبوابه للصلاة في عيد الأضحى سنة 2007.","يضم الجامع 82 قبة رئيسية وفق وصف مركز جامع الشيخ زايد الكبير، وتوجد قبب أخرى في مرافق مختلفة."],["AE","Dubai Frame","صُمم برواز دبي على هيئة إطار معماري ضخم يربط بصريًا بين المناطق القديمة والحديثة في المدينة.","تظهر واجهته الذهبية ذات النقوش الهندسية والممر العلوي الذي يمنح إطلالات باتجاهين مختلفين.","https://www.dubaiframe.ae/","فُتح برواز دبي للجمهور في يناير 2018 بحديقة زعبيل، وتصل أبراجه إلى ارتفاع يقارب 150 مترًا، ويربط بينها جسر علوي للمشاهدة.","المعلم ليس صورة إطار للزينة فقط؛ بل هيكل يمكن للزائر الصعود بداخله والمشي في جسره العلوي."],["AE","Museum of the Future","يمثل المتحف تجربة معمارية ومعرضية معاصرة حول سيناريوهات المستقبل والتقنية، ويتميز بهيئته الحلقية المغلّفة بالخط العربي.","تظهر الواجهة المعدنية المنحنية وفتحات الخط العربي والزوايا المتغيرة للمبنى من الشوارع المحيطة.","https://museumofthefuture.ae/","متحف المستقبل في دبي صرح ثقافي يستكشف السيناريوهات المحتملة للتقنية والبيئة والحياة البشرية في العقود القادمة. افتتح في 22 فبراير 2022، ويشتهر بشكله الحلقي المعدني ونقوش الخط العربي الممتدة على الواجهة.","تستخدم فتحات الخط العربي في الواجهة عنصرًا فنيًا ووسيلة لدخول الضوء الطبيعي."],["TH","Grand Palace","يُظهر القصر الكبير استمرار دور المجمع الملكي في تاريخ بانكوك منذ أواخر القرن الثامن عشر، مع تداخل القصور والمباني الاحتفالية والمعابد.","تظهر الأسقف التايلاندية المزخرفة والأبراج الذهبية وقاعات القصر ومجمع معبد بوذا الزمردي.","https://www.royalgrandpalace.th/en/discover/history","كان القصر الكبير مقرًا رسميًا لملوك سيام منذ تأسيس بانكوك عاصمة سنة 1782. يجمع المجمع بين مبانٍ ملكية وقاعات احتفالات ومعبد بوذا الزمردي.","يضم القصر الكبير مباني للإقامة والاحتفالات والإدارة، إلى جانب معبد بوذا الزمردي الذي لا يقيم فيه رهبان، بخلاف كثير من المعابد البوذية. والتمثال المسمى «الزمردي» منحوت من حجر اليشب الأخضر وليس من الزمرد، وفق الموقع الرسمي للقصر."],["TH","Wat Arun","يتميز وات آرون ببرجه المركزي المغطى بزخارف خزفية، وهو أحد أبرز الأمثلة على العمارة الدينية المطلة على نهر تشاو فرايا.","يظهر البرج المرتفع المحاط بأبراج أصغر والتفاصيل الخزفية الملونة وانعكاسات النهر المجاور.","https://www.tourismthailand.org/Attraction/wat-arun-ratchawararam-ratchawaramahawihan","وات آرون معبد على ضفة نهر تشاو فرايا في بانكوك، يرتبط اسمه بإله الفجر أرونا. اكتسبت منارته المركزية صورتها المميزة خلال القرن التاسع عشر.","تضيف قطع الخزف الملون تفاصيل لافتة عند الاقتراب من الزخارف."],["TH","Wat Pho","يجمع وات فو بين التراث البوذي والتقاليد المرتبطة بالتعليم والعلاج التايلاندي التقليدي داخل مجمع معابد واسع.","يظهر تمثال بوذا المتكئ الضخم والفسيفساء اللامعة والستوبات والأروقة المزخرفة.","https://www.watpho.org/en/buddha/detail/204","وات فو من أقدم مجمعات المعابد البوذية في بانكوك، ويشتهر بتمثال بوذا المتكئ وبتراث التعليم التقليدي والتدليك التايلاندي.","يبلغ طول تمثال بوذا المتكئ في وات فو 46 مترًا وارتفاعه 15 مترًا وفق الموقع الرسمي للمعبد. وتزخرف باطني قدميه تطعيمات بعرق اللؤلؤ تُصوّر 108 رموز ميمونة في المعتقد البوذي، ما يمنح التمثال أهمية دينية وفنية تتجاوز حجمه الضخم."],["TH","Ayutthaya Historical Park","تكشف آثار أيوثايا عن عاصمة مزدهرة لمملكة سيام قبل تدمير أجزاء كبيرة منها في القرن الثامن عشر.","تظهر الأبراج الطوبية والستوبات وتماثيل بوذا وأطلال القصور والمعابد وسط المساحات المفتوحة.","https://whc.unesco.org/en/list/576","كانت أيوثايا عاصمة مملكة قوية في تايلاند من سنة 1351 حتى دمارها عام 1767. تحفظ المنطقة التاريخية بقايا المعابد والأديرة والقصور.","توجد رأس بوذا حجرية شهيرة تحيط بها جذور شجرة عند وات ماهاثات."],["ID","Borobudur","يُعد بوروبودور مجمعًا بوذيًا حجريًا ضخمًا من العصر الوسيط المبكر في جاوة، وتُعرض فيه رموز وتعاليم دينية من خلال تصميم مصاطبه ونقوشه.","تتدرج المصاطب الحجرية حتى الستوبات المثقبة العلوية، مع مشاهد منحوتة على الجدران.","https://whc.unesco.org/en/list/592","شُيّد بوروبودور في جاوة الوسطى في القرنين الثامن والتاسع في سياق سلالة سايليندرا، ويعبّر تدرّج مصاطبه عن رحلة رمزية في التصور البوذي.","تزداد المصاطب استدارة في المستويات العليا، وتنتظم حولها ستوبات مثقبة تضم تماثيل بوذا؛ وهو اختلاف مقصود عن المصاطب المربعة السفلية."],["ID","Prambanan","يمثل برامبانان مجمعًا هندوسيًا رئيسيًا في جاوة، ويُظهر براعة العمارة الدينية في القرن التاسع.","تظهر الأبراج الحجرية المدببة والنقوش القصصية والمباني المخصصة لآلهة هندوسية مختلفة.","https://whc.unesco.org/en/list/642","تطورت مجمعات برامبانان الدينية في جاوة بين القرنين الثامن والعاشر الميلاديين، ويضم الموقع المدرج لدى اليونسكو مجموعات معابد هندوسية وبوذية متجاورة، منها لورو جونغرانغ وسيوو وبوبراه ولومبونغ. تعرضت بعض المنشآت للانهيار بفعل الزلازل وتغير مراكز الحكم، ثم بدأت أعمال ترميمها في العصر الحديث.","لا يشير اسم «برامبانان» إلى برج واحد؛ فمجمع لورو جونغرانغ الهندوسي يضم مئات المنشآت، بينما تمثل سيوو مجموعة بوذية كبيرة مجاورة. وتعرض النقوش على معابد شيفا وفيشنو وبراهما مشاهد من ملحمة رامايانا في نسختها الجاوية."],["ID","Tanah Lot","يرتبط تاناه لوت بالتقاليد الهندوسية البالية التي تمنح المعابد الساحلية دورًا دينيًا ورمزيًا خاصًا.","يظهر المعبد على كتلة صخرية منفصلة نسبيًا عند ارتفاع المد، مع الأمواج والمشهد الساحلي عند الغروب.","https://www.indonesia.travel/id/id/destination/bali-nusa-tenggara/bali/tanah-lot","يرتبط تاريخ معبد تاناه لوت الساحلي بتقاليد دينية في بالي تنسب تأسيسه إلى الراهب دانغ هيانغ نيرارثا في القرنين الخامس عشر والسادس عشر. وتحكي الأسطورة المحلية أنه نقل الصخرة إلى البحر بقوة روحية؛ وهي رواية رمزية في التراث الديني، وليست تفسيرًا جيولوجيًا مثبتًا لكيفية تكوّن الموقع.","يعني اسم «تاناه لوت» تقريبًا «الأرض في البحر»، ويبدو المعبد منفصلًا عن اليابسة عند ارتفاع المد. ما زال مكانًا للشعائر الهندوسية المحلية وليس مجرد منصة تصوير، وتتغير إمكانات الاقتراب من صخرته بحسب المد والأمواج وتعليمات المكان."],["ID","National Monument (Monas)","يخلّد نصب موناس استقلال إندونيسيا ويُعد نقطة بارزة في التخطيط الحضري لساحة ميرديكا في جاكرتا.","تظهر المسلة العالية المتوّجة بشكل شعلة ذهبية والميدان الواسع حول قاعدتها.","https://www.jakarta.go.id/","أُقيم النصب الوطني «موناس» في ساحة ميرديكا بجاكرتا تخليدًا لكفاح إندونيسيا من أجل الاستقلال، وأصبح علامة في قلب العاصمة.","الشعلة المتوجة للنصب ترمز إلى استمرارية روح الاستقلال، بينما يربط موقعه داخل الساحة بين الذاكرة الوطنية والمشهد الحضري."],["KR","Gyeongbokgung Palace","كان غيونغبوكغونغ من أهم قصور مملكة جوسون في سيول، وتوضح ساحاته الرسمية تنظيم البلاط الملكي التقليدي.","تظهر بوابة غوانغهوامون وقاعة العرش وأروقة القصر وأجنحته الخشبية أمام الجبال.","https://royal.cha.go.kr/ENG/contents/E101010000.do","أُنشئ قصر غيونغبوكغونغ عام 1395 بعد قيام مملكة جوسون بوصفه قصرها الملكي الرئيسي في العاصمة هانيانغ. تضرر وتهدّم خلال الغزو الياباني سنة 1592، ثم أُعيد بناؤه عام 1867 في عهد الملك غوجونغ. وشهد خلال الاحتلال الياباني هدم أجزاء واسعة، قبل مشروعات ترميم حديثة بدأت منذ تسعينيات القرن العشرين.","لم يبقَ القصر بهيئة واحدة منذ عام 1395؛ فالمباني القائمة تجمع بقايا تاريخية مع إعادات إنشاء موثقة. ويرتبط موضعه بمحور العاصمة التاريخي عند بوابة غوانغهامون، وبمراحل تطوير الكتابة الكورية خلال عهد الملك سيجونغ."],["KR","Bukchon Hanok Village","يحفظ حي بوكتشون أمثلة من بيوت هانوك التقليدية ضمن أحياء سيول المعاصرة، وهو في الوقت نفسه حي سكني يتطلب احترام خصوصية سكانه.","تظهر الأسقف القرميدية المنحنية والأزقة الصاعدة والمنازل الخشبية أمام خلفية المدينة الحديثة.","https://english.visitseoul.net/attractions/Bukchon%20Hanok%20Village_/263","بوكتشون حي تاريخي في سيول بين قصري غيونغبوكغونغ وتشانغدوكغونغ. تُظهر أزقته منازل هانوك تقليدية وما زال حيًا سكنيًا.","بوكتشون منطقة سكنية حية وليست متحفًا مفتوحًا بلا قيود: فرضت سيول منذ نوفمبر 2024 ضوابط على الزيارات السياحية في المنطقة الحمراء، مع تقييد دخول السياح بين الخامسة مساءً والعاشرة صباحًا. ينبغي احترام الهدوء وعدم تصوير داخل البيوت، والتحقق من الإرشادات المحلية قبل الزيارة."],["KR","N Seoul Tower","يُظهر برج إن سيول دور جبل نامسان نقطة مشاهدة مركزية للعاصمة، وتحوله إلى معلم حضري وثقافي.","تظهر البنية الأسطوانية أعلى التلة والطرق المشجرة ومنصات الإطلالة على أحياء سيول ونهر الهان.","https://www.nseoultower.co.kr/eng/global/intro3.asp","بدأ إنشاء برج سيول على جبل نامسان في ديسمبر 1969 لخدمة إرسال الإذاعة والتلفزيون، واكتمل جسم البرج في أوائل السبعينيات، ثم افتُتح للجمهور في أكتوبر 1980. وبعد تجديدات كبرى في 2005 أصبح يُعرف باسم «إن سيول تاور» بوصفه مركزًا للمشاهدة والثقافة إلى جانب وظيفة الاتصالات.","البرج ليس مجرد منصة سياحية؛ فقد شُيّد أصلًا لتحسين البث والاتصالات في العاصمة. وتوضح سجلاته الرسمية أن اسمه الحالي اعتمد بعد تجديد سنة 2005، بينما بدأ استقبال الزوار عام 1980."],["KR","Bulguksa Temple","يُعد معبد بولغوكسا من أبرز مواقع التراث البوذي لمملكة شلا، وارتبط بتطور فنون البناء والنحت الديني في كوريا.","تظهر السلالم الحجرية التاريخية والبوابات الخشبية والباغودات الحجرية داخل ساحات المعبد.","https://whc.unesco.org/en/list/736","بولغوكسا معبد بوذي تاريخي قرب مدينة غيونغجو يرتبط بفنون مملكة شلا الموحدة. يُعد من أهم مجمعات التراث البوذي في كوريا.","تجسد بعض الأبراج الحجرية أنماطًا مختلفة من الفن البوذي الكوري."],["VN","Temple of Literature","يرتبط معبد الأدب في هانوي بتاريخ التعليم الكونفوشي والامتحانات الرسمية وإعداد النخبة الإدارية في فيتنام.","تظهر الأفنية المتتابعة والبوابات والبرك الحجرية وشواهد أسماء العلماء على قواعد السلاحف.","https://vanmieu.gov.vn/en/inner-temple","أسس الإمبراطور لي ثانه تونغ معبد الأدب في هانوي عام 1070 لتكريم كونفوشيوس والعلماء، ثم أُنشئت مؤسسة كوك تو جيام التعليمية المرتبطة به سنة 1076 في عهد لي نهان تونغ. أدى المجمع دورًا مهمًا في تعليم النخبة وإعداد المسؤولين خلال حقب من التاريخ الفيتنامي.","يضم المجمع خمس ساحات متتابعة وشواهد حجرية بأسماء الناجحين في الامتحانات الإمبراطورية تستند إلى تماثيل سلاحف. وتُعد هذه الشواهد سجلًا تاريخيًا للتعليم والامتحانات، لا مجرد عناصر زخرفية في ساحة المعبد."],["VN","Hội An Ancient Town","تُظهر هوي آن ازدهار التبادل التجاري البحري في جنوب شرق آسيا وتأثر عمارتها بتقاليد فيتنامية وصينية ويابانية.","تظهر البيوت ذات الواجهات الصفراء والجسر المغطى والفوانيس والأزقة التجارية القديمة.","https://whc.unesco.org/en/list/948","هوي آن مدينة ساحلية وتجارية ازدهرت بين القرنين الخامس عشر والتاسع عشر، وحافظت على مزيج من العمارة المحلية والتأثيرات الأجنبية.","احتفظت هوي آن بتخطيط شوارعها التجارية القديمة ومنازلها الخشبية التي يصل بعضها بين واجهة الدكان والنهر من الخلف، لتسهيل نقل البضائع بالقوارب. ومن أشهر معالمها الجسر الياباني المغطى، ما يعكس اتصالات الميناء التجارية والثقافية عبر آسيا."],["VN","Hạ Long Bay","يُعد خليج ها لونغ مشهدًا جيولوجيًا بارزًا من الجزر الكارستية الناتجة عن عمليات طويلة من ذوبان الحجر الجيري وتعرية السواحل.","تظهر الجزر الجيرية المكسوة بالنباتات فوق المياه الهادئة، والكهوف والمضائق بين الكتل الصخرية.","https://whc.unesco.org/en/list/672","خليج ها لونغ منظر طبيعي شهير في شمال شرق فيتنام، تتوزع فوق مياهه آلاف الجزر والتكوينات الجيرية التي نحتتها العمليات الجيولوجية.","نتجت أشكال الصخور من عمليات جيولوجية طويلة في بيئة كلسية."],["VN","Imperial City of Huế","تكشف مدينة هيو الإمبراطورية عن مجمع الحكم في عهد أسرة نغوين، وتبرز فيه أسوار وقصور وبوابات مستوحاة من التخطيط الملكي التقليدي.","تظهر الأسوار والخنادق والبوابات والقاعات الملكية والحدائق داخل القلعة الإمبراطورية.","https://whc.unesco.org/en/list/678","كانت هيو عاصمة لأسرة نغوين الإمبراطورية بين 1802 و1945. تضم مدينتها المحصنة مجمعًا من البوابات والقصور والساحات الملكية.","يعكس تخطيط الأسوار والبوابات مزيجًا من الدفاع والطقوس الملكية."],["GR","Acropolis of Athens","يرتبط الأكروبوليس بذروة العمارة اليونانية الكلاسيكية في القرن الخامس قبل الميلاد، وكان البارثينون معبدًا مكرسًا للإلهة أثينا.","تظهر أعمدة البارثينون ومعبد إرخثيون وبوابة البروبيلايا فوق الهضبة الصخرية، مع إطلالات على أثينا.","https://whc.unesco.org/en/list/404","أُعيد بناء أبرز معابد الأكروبوليس بعد الحروب الفارسية، وارتبط برنامج البناء في القرن الخامس قبل الميلاد بازدهار أثينا السياسية والفنية.","الأكروبوليس مجمع من معابد ومبانٍ؛ البارثينون أحدها وليس الاسم البديل للهضبة كلها."],["GR","Archaeological Site of Delphi","اعتُبرت دلفي في اليونان القديمة مركزًا دينيًا شهيرًا ارتبط بوحي أبولو، وشهدت ألعابًا ومسابقات ومظاهر تجمع بين المدن اليونانية.","تظهر بقايا معبد أبولو والمسرح والملعب القديم متدرجة على سفح جبلي فوق وادي الزيتون.","https://whc.unesco.org/en/list/393","كانت دلفي مركزًا دينيًا مهمًا في العالم اليوناني القديم يرتبط بمعبد أبولو واستشارة الوحي.","أُقيمت في دلفي الألعاب البيثية، وهي من أبرز المنافسات الدينية والرياضية اليونانية القديمة."],["GR","Meteora","تجمع ميتيورا بين تكوينات جيولوجية من أعمدة صخرية شاهقة وتاريخ رهباني بيزنطي تطور في مواقع يصعب الوصول إليها.","تبدو الأديرة قائمة على قمم الصخور المنفصلة، مع ممرات ودرجات ومشاهد واسعة لسهل ثيساليا.","https://whc.unesco.org/en/list/455","نشأت أديرة ميتيورا على أعمدة صخرية عالية وصارت مركزًا رهبانيًا خلال العصور الوسطى.","حُملت مواد البناء والمؤن قديمًا إلى بعض الأديرة عبر سلال وحبال في مواقع يصعب الوصول إليها."],["GR","Oia, Santorini","تُظهر أويا كيف تكيف العمران في سانتوريني مع حافة الكالديرا البركانية، وأصبحت مشاهدها من رموز العمارة الساحلية في جزر بحر إيجة.","تتدرج المباني البيضاء والقباب الزرقاء والممرات الضيقة فوق المنحدر المطل على البحر والجزر البركانية.","https://www.visitgreece.gr/islands/cyclades/santorini/","تشكلت كالديرا سانتوريني بعد تاريخ طويل من النشاط البركاني، ثم تكيف عمران أويا مع حافتها شديدة الانحدار.","القباب الزرقاء الشهيرة جزء من مشهد عمراني أوسع؛ ليست جميع مباني القرية ذات قباب زرقاء."],["CH","Old City of Bern","تحافظ مدينة برن القديمة على تخطيط حضري من العصور الوسطى وتشتهر بأروقتها التجارية الحجرية حول شبه جزيرة نهر آري.","تظهر الشوارع المرصوفة والنوافير التاريخية وبرج الساعة زِتغلوغه والأسقف الحمراء على ضفاف النهر.","https://whc.unesco.org/en/list/267","تأسست برن في العصور الوسطى وتطورت حول منعطف نهر آري، وحافظ مركزها على أجزاء كبيرة من تخطيطه القديم.","أروقة المشاة المسقوفة في برن تسهل التنقل بين المتاجر حتى وقت المطر."],["CH","Swiss Alps Jungfrau-Aletsch","تكشف منطقة يونغفراو أليتش عن أنظمة الجليد والقمم العالية والعمليات الجيولوجية التي شكّلت مشاهد جبال الألب.","يمكن تأمل الأنهار الجليدية الممتدة والقمم الثلجية والوديان العميقة والواجهات الصخرية العالية.","https://whc.unesco.org/en/list/1037","كوّنت الأنهار الجليدية الوديان والقمم المرتفعة في منطقة يونغفراو أليتش التي تحظى بحماية تراثية.","نهر أليتش الجليدي الأكبر في جبال الألب من حيث الامتداد، لكن حدوده تتغير مع المناخ."],["CH","Matterhorn","يشتهر ماترهورن بقمة هرمية نتجت عن النحت الجليدي، وأصبح رمزًا لتاريخ تسلق الجبال والسياحة الألبية.","تظهر الأوجه الحادة للقمة فوق زيرمات، وتنعكس صورته أحيانًا على البحيرات الجبلية الصغيرة.","https://www.myswitzerland.com/en/destinations/matterhorn-symbol-for-switzerland/","يُعد ماترهورن رمزًا للألب، وشهد صعوده الأول عام 1865 حدثًا بارزًا في تاريخ تسلق الجبال.","للقمة أربعة أوجه حادة تقريبًا، وقد تشكل مظهرها عبر التجلد والتعرية."],["CH","Lavaux Vineyard Terraces","تجسد مدرجات لافو تاريخ استغلال المنحدرات المطلة على بحيرة جنيف لزراعة الكروم، مع توازن بين الريف والقرى والمنظر الطبيعي.","تتتابع جدران المدرجات الحجرية وصفوف الكروم والقرى الصغيرة فوق البحيرة والجبال المقابلة.","https://whc.unesco.org/en/list/1243","أنشأ السكان جدرانًا حجرية ومدرجات متتابعة لتحويل سفوح شديدة الانحدار إلى حقول قابلة للزراعة، واستمر الحفاظ على هذا النظام عبر أجيال.","الجدران الحجرية في المدرجات تساعد على تثبيت التربة واستغلال المنحدر الشديد."],["MA","Medina of Marrakesh","تمثل مدينة مراكش القديمة مركزًا تاريخيًا للتجارة والحكم والحرف في المغرب، وتجمع عمارة دينية ومدنية من عصور مختلفة.","تظهر ساحة جامع الفنا والأسواق والمآذن والأسوار الحمراء والأفنية والزخارف التقليدية.","https://whc.unesco.org/en/list/331","تطورت مراكش منذ العصر المرابطي في القرن الحادي عشر لتصبح مركزًا للتجارة والحكم والعمران.","تغيرت وظيفة ساحة جامع الفنا عبر الزمن، ولا تختصر المدينة القديمة كلها في الساحة وحدها."],["MA","Medina of Fez","تُعد المدينة العتيقة بفاس أحد أهم مراكز التراث الحضري والحرفي والعلمي في المغرب، مع نسيج كثيف من الأزقة والأسواق والمدارس.","يمكن ملاحظة أبواب المدينة والمدارس التاريخية والزليج المغربي والدباغات والممرات الضيقة.","https://whc.unesco.org/en/list/170","كانت فاس مركزًا علميًا وحرفيًا مهمًا في المغرب، وتطورت أحياؤها ومدارسها ومساجدها على مدى قرون.","تتشكل شوارع المدينة العتيقة كشبكة أزقة دقيقة لا تتبع تخطيط الشوارع العريضة الحديث."],["MA","Aït Benhaddou","يقدم آيت بن حدو مثالًا واضحًا للعمارة الترابية المحصنة جنوب المغرب التي تطورت على طرق التجارة والقوافل.","تظهر الأبراج الطينية المزخرفة والأسوار والمنازل المتدرجة فوق التل على ضفة الوادي.","https://whc.unesco.org/en/list/444","كان آيت بن حدو تجمعًا محصنًا على طرق القوافل التاريخية، وتميز بالبناء الترابي المتدرج على التل.","القصر في التسمية المغربية يشير هنا إلى قرية محصنة، لا إلى قصر ملكي واحد."],["MA","Chefchaouen Medina","تتميز شفشاون بهويتها العمرانية ذات الأزقة والجدران الزرقاء داخل المشهد الجبلي لمنطقة الريف، مع تأثيرات أندلسية ومحلية في تاريخها.","تظهر السلالم والأبواب الزرقاء والساحات الصغيرة والمباني المتقاربة تحت الجبال المحيطة.","https://www.visitmorocco.com/en/travel/chefchaouen","نشأت شفشاون في منطقة الريف في أواخر القرن الخامس عشر، وتداخلت في تراثها مؤثرات محلية وأندلسية.","درجات الأزرق تتفاوت بين الأزقة والجدران، وتُجدَّد الطلاءات بصورة دورية."],["MY","Petronas Twin Towers","أصبح البرجان التوأمان رمزًا للنهضة العمرانية الماليزية في نهاية القرن العشرين، ويبرز تصميمهما أنماطًا هندسية مستوحاة من الفن الإسلامي.","تظهر الكتلتان المعدنيتان المتناظرتان والجسر السماوي الواصل بينهما والحدائق المحيطة.","https://www.petronastwintowers.com.my/","اكتمل برجا بتروناس في التسعينيات ضمن نهضة كوالالمبور العمرانية، واستُخدمت عناصر هندسية مستوحاة من الزخارف الإسلامية.","الجسر السماوي يربط البرجين فوق مستوى الشارع، لكنه ليس عند قمة المبنيين."],["MY","George Town, Penang","تُظهر جورج تاون تاريخ التبادل التجاري والثقافي في مضيق ملقا، وتجاور العمارة الصينية والهندية والملايوية والأوروبية.","تظهر البيوت التجارية التاريخية والواجهات المزخرفة والمعابد والفنون الجدارية والأحياء متعددة الثقافات.","https://whc.unesco.org/en/list/1223","توسعت جورج تاون ميناءً تجاريًا في مضيق ملقا وتكونت أحياؤها من ثقافات ومجتمعات مهاجرة متعددة.","تجاور المعابد والمساجد وبيوت التجارة في شوارع متقاربة شاهد على التنوع التاريخي."],["MY","Kinabalu Park","يحمي منتزه كينابالو تنوعًا نباتيًا واسعًا عبر نطاقات ارتفاع متفاوتة حول الجبل، وهو من أبرز مواقع الطبيعة في بورنيو.","يمكن مشاهدة غابات الجبال والقمم الجرانيتية والنباتات المدارية والمناطق الألبية المرتفعة.","https://whc.unesco.org/en/list/1012","أنشئت منطقة كينابالو المحمية للحفاظ على جبل كينابالو والنباتات والحيوانات المتنوعة باختلاف الارتفاع.","تتغير أنواع النباتات سريعًا مع الارتفاع، وتُعرف المنطقة بتنوع كبير من الأوركيد."],["MY","Batu Caves","تمثل كهوف باتو موقعًا دينيًا هندوسيًا مهمًا في ماليزيا داخل تشكيلات كلسية طبيعية قرب كوالالمبور.","تظهر السلالم الملونة المؤدية إلى مدخل الكهف والتمثال الذهبي الضخم والفضاءات الصخرية الداخلية.","https://www.malaysia.travel/","تكوّنت الكهوف في الحجر الجيري خلال فترات جيولوجية طويلة، ثم أُقيمت فيها مزارات هندوسية وأصبحت مرتبطة باحتفالات دينية حاشدة.","الدرج الملون والمعابد إضافات بشرية حديثة نسبيًا مقارنة بعمر الصخور الجيري."],["DE","Brandenburg Gate","تعكس بوابة براندنبورغ تاريخ برلين الحديث؛ فبعد وقوعها قرب الجدار الذي قسم المدينة أصبحت رمزًا لإعادة توحيد ألمانيا.","تظهر الأعمدة الكلاسيكية الستة والتكوين النحتي للعربة التي تجرها أربعة خيول فوق البوابة، مع امتداد ساحة باريس أمامها.","https://www.visitberlin.de/en/brandenburg-gate","اكتملت بوابة براندنبورغ في أواخر القرن الثامن عشر، وتحولت لاحقًا من بوابة مدينة إلى رمز لتقسيم برلين ثم وحدتها.","العربة ذات الخيول الأربعة أعلى البوابة تحمل اسم الكوادرِيغا، وقد مرّت بتحولات تاريخية."],["DE","Neuschwanstein Castle","أمر الملك لودفيغ الثاني ببناء القلعة في القرن التاسع عشر بوصفها تصورًا رومانسيًا للعصور الوسطى، لا حصنًا دفاعيًا قديمًا.","تبرز الأبراج البيضاء ذات الأسقف المدببة والواجهات المطلة على الغابات والجبال والبحيرات البافارية.","https://www.neuschwanstein.de/englisch/palace/","بدأ الملك لودفيغ الثاني تشييد نويشفانشتاين سنة 1869، واستلهم تصميم الغرف والرسوم من الأساطير والفن الرومانسي، ولم يُكمل المشروع في حياته.","رغم مظهرها الوسيط، فإن القلعة أحدث بكثير من قلاع العصور الوسطى الدفاعية."],["DE","Cologne Cathedral","تُعد كاتدرائية كولونيا أحد أبرز إنجازات العمارة القوطية في أوروبا، وقد استمر مشروع بنائها عبر قرون حتى القرن التاسع عشر.","يمكن ملاحظة برجيها المدببين والنوافذ الزجاجية الملونة والواجهة الغنية بالتفاصيل النحتية.","https://whc.unesco.org/en/list/292","بدأ بناء كاتدرائية كولونيا في القرن الثالث عشر، واستؤنف المشروع بقوة في القرن التاسع عشر حتى اكتمل.","ارتفاع البرجين وتنوع الزجاج الملون من السمات التي تكشف طموح العمارة القوطية."],["DE","Museum Island, Berlin","تجمع جزيرة المتاحف خمسة متاحف رئيسية في فضاء حضري واحد، وتُظهر تطور فكرة المتحف العام في القرنين التاسع عشر والعشرين.","تظهر مباني المتاحف الكلاسيكية والواجهات ذات الأعمدة والساحات بينها، بجوار نهر شبري وكاتدرائية برلين.","https://whc.unesco.org/en/list/896","تطورت جزيرة المتاحف في القرن التاسع عشر وبداية العشرين بوصفها مجمعًا لمؤسسات ثقافية عامة.","تضم الجزيرة عدة متاحف مستقلة وليست متحفًا واحدًا يحمل اسمها."],["MX","Chichén Itzá","تُظهر تشيتشن إيتزا تداخل تقاليد المايا مع التأثيرات الإقليمية في يوكاتان، وكانت مركزًا سياسيًا ودينيًا رئيسيًا في أمريكا الوسطى القديمة.","تظهر درجات هرم كوكولكان والملعب الكبير للكرة ومعبد المحاربين والأعمدة المنحوتة.","https://whc.unesco.org/en/list/483","تطورت المدينة في شمال شبه جزيرة يوكاتان عبر مراحل من عمر حضارة المايا؛ وتكشف ساحاتها وملاعب الكرة ومرصدها عن تنوع وظائف المركز الحضري.","هرم كوكولكان جزء من مدينة أثرية أكبر تشمل ملعب الكرة ومبانٍ احتفالية."],["MX","Teotihuacan","كانت تيوتيهواكان مدينة حضرية ضخمة في وسط المكسيك قبل صعود إمبراطورية الأزتك، ويُظهر تخطيطها تقدمًا في التنظيم المعماري.","يمكن تأمل هرم الشمس وهرم القمر وشارع الموتى والمجمعات السكنية والأثرية الممتدة.","https://whc.unesco.org/en/list/414","نمت تيوتيهواكان في وادي وسط المكسيك حتى غدت من أهم المراكز الحضرية في أمريكا الوسطى بين القرنين الأول والسابع الميلاديين، قبل عصر الأزتك بقرون. ويعكس تخطيط أهرام الشمس والقمر ومعبد كيتزالكواتل وشارع الموتى نظامًا عمرانيًا ذا دلالات دينية وسياسية.","اسم «شارع الموتى» تسمية لاحقة، ولا يعني أن الشارع كان كله مخصصًا للمقابر."],["MX","Palenque","تشتهر بالينكي بعمارة المايا الكلاسيكية والنقوش التي تحفظ معلومات عن حكام المدينة وتاريخها وسط غابات تشياباس.","تظهر معابد الأهرامات وقصر المدينة والواجهات المنحوتة المحاطة بالأشجار الاستوائية.","https://whc.unesco.org/en/list/411","كانت بالينكي مدينة مايا مهمة في العصر الكلاسيكي، وتحفظ نقوشها أسماء حكام وتسلسل أحداث.","تحتضن بعض المعابد نقوشًا هيروغليفية ساعدت الباحثين على إعادة بناء تاريخ المدينة."],["MX","Tulum Archaeological Site","تكشف تولوم عن موقع مدينة مايا ساحلية ارتبطت بالتبادل التجاري البحري في أواخر فترات حضارة المايا.","يبرز مبنى القلعة المعروف باسم إل كاستيو فوق الجرف المطل على البحر الكاريبي والمباني الحجرية داخل الأسوار.","https://www.inah.gob.mx/","كانت تولوم مدينة ساحلية مسوّرة للمايا ومرتبطة بالتجارة البحرية في المراحل المتأخرة من تاريخهم.","الموقع يختلف عن مدن المايا الداخلية بسبب موقعه المباشر على جرف كاريبي."],["BR","Christ the Redeemer","أصبح تمثال المسيح الفادي أحد الرموز الثقافية والبصرية لمدينة ريو دي جانيرو، ويتميز بموقعه على جبل كوركوفادو وسط تضاريس ساحلية حادة.","يظهر التمثال بأذرعه الممدودة فوق المدينة، مع منظر خليج غوانابارا والجبال والشواطئ المحيطة.","https://www.tremdocorcovado.rio/","اكتمل التمثال سنة 1931 بعد مشروع هندسي وفني في ريو، وأُقيم فوق كوركوفادو مستفيدًا من الموقع المرتفع الذي يطل على أجزاء واسعة من المدينة.","التمثال مكسو بطبقة من حجر الصابون، وليس منحوتًا كله من قطعة حجر واحدة."],["BR","Iguaçu Falls","تتكون شلالات إيغواسو من شبكة واسعة من المساقط على نهر إيغواسو، ويحيط بها أحد أبرز موائل الغابة الأطلسية شبه الاستوائية.","تظهر جدران المياه المتعددة والضباب المتصاعد والقوس الطبيعي للمساقط، خاصة عند منطقة حلق الشيطان.","https://whc.unesco.org/en/list/355","تشكّلت شلالات إيغواسو على امتداد نهر حدودي بين البرازيل والأرجنتين فوق تشكيلات صخرية بركانية قديمة.","منظومة الشلالات تتكون من مساقط متعددة، لا شلال واحد مستقيم."],["BR","Sugarloaf Mountain","تكشف قمة شوغرلوف الصخرية عن تضاريس ريو الجرانيتية عند مدخل خليج غوانابارا، وتمنح منظرًا واضحًا لعلاقة المدينة بالبحر والجبال.","تظهر القمة المستديرة والكابلات المعلقة التي تصل إلى مناطق المشاهدة، مع شواطئ المدينة والجزر المجاورة.","https://riotur.rio/","تكون جبل شوغرلوف من صخور جرانيتية متحولة المظهر بفعل النحت والتعرية وأصبح رمزًا لميناء ريو.","تُوصل عربات تلفريك بين محطات مشاهدة، فلا يلزم تسلق القمة للوصول إليها."],["BR","Historic Centre of Salvador de Bahia","يعكس المركز التاريخي لسلفادور دور المدينة عاصمةً للبرازيل الاستعمارية سابقًا وامتزاج تأثيرات أوروبية وأفريقية وأصلية، إلى جانب تاريخ العبودية المؤلم.","تظهر البيوت الملونة والساحات المرصوفة والكنائس الباروكية والشوارع المنحدرة في منطقة بيلورينيو.","https://whc.unesco.org/en/list/309","كانت سلفادور عاصمة البرازيل الاستعمارية في فترة مبكرة، وارتبطت بتاريخ التجارة والثقافات الأفريقية والأوروبية.","يعكس حي بيلورينيو تراثًا معماريًا وثقافيًا غنيًا إلى جانب تاريخ الاستعباد الذي لا ينبغي تجاهله."],["AU","Sydney Opera House","تُعد دار أوبرا سيدني أيقونة للعمارة الحديثة، واشتهرت بسقوفها القشرية التي أعادت تعريف شكل المباني الثقافية في القرن العشرين.","تظهر الأشكال البيضاء المتداخلة على بنيلونغ بوينت بجوار ميناء سيدني وجسر الميناء.","https://whc.unesco.org/en/list/166","افتُتحت دار أوبرا سيدني سنة 1973 بعد مشروع بناء طويل ومعقد صممه المعماري يورن أوتزون.","أسقف المبنى ليست أشرعة قماشية؛ إنها قشور معمارية مكسوة ببلاطات فاتحة اللون."],["AU","Great Barrier Reef","يضم الحاجز المرجاني العظيم تنوعًا استثنائيًا من الشعاب والكائنات البحرية، لكنه يواجه ضغوطًا بيئية شديدة، منها ارتفاع حرارة البحر وتبيّض المرجان.","تظهر الشعاب بألوان وأنماط هندسية متعددة في المياه الضحلة، مع الجزر والبحيرات المرجانية عند النظر من الأعلى.","https://whc.unesco.org/en/list/154","تراكمت الشعاب المرجانية للحاجز المرجاني العظيم عبر فترات جيولوجية طويلة، وتدعم تنوعًا بحريًا استثنائيًا.","الشعاب كائنات حية حساسة لارتفاع حرارة المياه، ويمكن أن تتعرض للتبيّض."],["AU","Uluru","تحمل أولورو أهمية روحية وثقافية كبيرة لشعب أنانغو من السكان الأصليين، وهي ليست مجرد تكوين جيولوجي منفرد في الصحراء.","تتغير درجات لون الصخرة الرملية مع الشمس، وتظهر على جوانبها الشقوق والتجاويف والمواقع ذات الأهمية الثقافية.","https://whc.unesco.org/en/list/447","ترتبط أولورو بقصص ومعارف متوارثة لدى أنانغو، الذين يواصلون رعاية الموقع بالتعاون مع سلطات الحماية، مع قواعد خاصة لاحترام الأماكن المقدسة.","يتغير لون الصخرة الظاهر مع زاوية الشمس، ولا يتغير تركيبها المعدني خلال اليوم."],["AU","Twelve Apostles (Victoria)","توضح الأعمدة البحرية المعروفة بالرسل الاثني عشر كيف يؤدي نحت الأمواج للمنحدرات الجيرية إلى انفصال كتل صخرية عن الساحل.","تظهر الأعمدة المنعزلة أمام الجروف العالية على ساحل طريق المحيط العظيم، ويتغير المشهد باستمرار بفعل التعرية.","https://www.parks.vic.gov.au/places-to-see/parks/port-campbell-national-park","تشكّلت أعمدة الرسل الاثني عشر من تراجع الجرف الجيري وتآكل الأقواس البحرية على ساحل فيكتوريا.","الاسم لا يعني وجود اثني عشر عمودًا قائمًا اليوم؛ فالتعرية تسقط بعضها مع الزمن."],["AT","Schönbrunn Palace","يعكس قصر شونبرون مكانة فيينا مركزًا للإمبراطورية الهابسبورغية، وكانت حدائقه وغرفه الاحتفالية جزءًا من تمثيل السلطة الملكية.","تبرز الواجهة الصفراء الطويلة والقاعات المزخرفة والحدائق المنتظمة ومرتفَع غلوريت المطل على القصر.","https://whc.unesco.org/en/list/786","كان شونبرون مقرًا صيفيًا لأسرة هابسبورغ، وتطور قصره وحدائقه على مدى قرون ليعكس نفوذ البلاط الإمبراطوري.","تتيح الغلوريت فوق التلة مشهدًا بانوراميًا للحدائق والقصر، وليست جزءًا من الجناح السكني الرئيسي."],["AT","Historic Centre of Salzburg","يمثل المركز التاريخي لسالزبورغ مثالًا على تناغم العمارة الباروكية مع التضاريس والنهر، ويرتبط بتاريخ الموسيقى الأوروبية وولادة موزارت.","تظهر قباب الكنائس والأزقة الضيقة وساحة الكاتدرائية وقلعة هوهنسالزبورغ المطلة على المدينة.","https://whc.unesco.org/en/list/784","تطورت سالزبورغ تحت حكم أمراء أساقفة، واشتهرت بعمارتها الباروكية وتراثها الموسيقي.","وُلِد موزارت في سالزبورغ، لكن المدينة التاريخية تضم طبقات عمرانية أقدم من عصره."],["AT","Hallstatt-Dachstein Cultural Landscape","يُظهر منظر هالشتات وداخشتاين كيف تشكلت المجتمعات الألبية حول استخراج الملح، وهو نشاط يعود إلى عصور موغلة في القدم.","يمكن تأمل بيوت القرية المتراصة قرب البحيرة والجبال العالية ومواقع التعدين التاريخية في المنطقة.","https://whc.unesco.org/en/list/806","ارتبطت هالشتات باستخراج الملح منذ عصور سحيقة، وتركت أنشطة التعدين أثرًا في الثقافة الألبية.","أعطت هالشتات اسمها لمرحلة أثرية أوروبية بسبب اكتشافات مهمة في المنطقة."],["AT","Golden Roof Innsbruck","يرتبط السقف الذهبي بالإمبراطور ماكسيميليان الأول، ويُعد شاهدًا على العمارة الاحتفالية في إنسبروك خلال أواخر القرن الخامس عشر.","تظهر آلاف الصفائح النحاسية المذهبة فوق الشرفة والرسوم والنقوش المحيطة بها وسط الواجهات التاريخية.","https://www.innsbruck.info/en/","أمر ماكسيميليان الأول بتشييد شرفة احتفالية تطل على ساحة المدينة؛ وزُخرف سقفها بصفائح نحاسية مذهبة لتأكيد رمزية البلاط.","اللون الذهبي ناتج عن صفائح نحاسية مذهبة، لا عن سقف مصنوع كاملًا من الذهب."],["PT","Belém Tower","يُجسد برج بيليم الطابع الدفاعي والرمزي لميناء لشبونة خلال عصر التوسع البحري البرتغالي، ويتميز بزخارف الطراز المانويليني.","تظهر الشرفات والأبراج الصغيرة والواجهات الحجرية المطلة على نهر تاجه مع تفاصيل الحبال والعناصر البحرية المنحوتة.","https://whc.unesco.org/en/list/263","بُني برج بيليم في أوائل القرن السادس عشر لحماية مدخل ميناء لشبونة، وأصبح رمزًا للملاحة البرتغالية.","كان موقع البرج مرتبطًا بخط الساحل والنهر، وتأثر موضعه النسبي بتغيرات الضفة."],["PT","Jerónimos Monastery","يرتبط دير جيرونيموس بثراء البرتغال خلال عصر الملاحة وبالرعاية الملكية للفنون الدينية في القرن السادس عشر.","تُبرز الكنيسة والأروقة الحجرية الطويلة والزخارف المانويلينية المعقدة والأعمدة الرفيعة.","https://whc.unesco.org/en/list/263","شُيّد دير جيرونيموس في عصر الثراء البحري البرتغالي بطراز مانويليني غني بالرموز البحرية.","تُظهر زخارف الحجر تفاصيل تشبه الحبال والعُقد والعناصر النباتية، بجانب الرموز الدينية."],["PT","Pena Palace","يمثل قصر بينا أحد أبرز نماذج العمارة الرومانسية الأوروبية، حيث يجمع عمدًا عناصر تاريخية من طرز مختلفة وسط غابة مرتفعة.","تظهر القباب والأبراج الصفراء والحمراء والشرفات المزخرفة والإطلالات على تلال سينترا.","https://whc.unesco.org/en/list/723","أُنشئ قصر بينا في القرن التاسع عشر ضمن نزعة رومانسية جمعت عمدًا طرزًا معمارية مختلفة.","ألوان القصر القوية ليست بقايا طلاء عشوائي؛ بل جزء من صورته المعمارية المميزة."],["PT","Historic Centre of Porto","يكشف المركز التاريخي لبورتو عن تطور مدينة تجارية على نهر دورو، حيث تتدرج الشوارع والمساكن نحو الميناء القديم.","تظهر واجهات ريبيرا الملونة والجسور والأزقة والمنحدرات الحجرية المطلة على النهر.","https://whc.unesco.org/en/list/755","نشأت بورتو على ضفاف دورو وتطورت كمركز تجاري، وحافظ حيها التاريخي على أزقة وواجهات متعددة الفترات.","تتدرج مباني ريبيرا عموديًا فوق النهر، ما يخلق مشهدًا من طبقات عمرانية متقاربة."],["ZA","Table Mountain","يمثل جبل الطاولة جزءًا من المشهد الطبيعي الفريد لرأس الرجاء، ويدعم نباتات الفينبوس التي تتميز بها المنطقة.","يمكن رؤية القمة المسطحة والمنحدرات الحادة وإطلالات كيب تاون والمحيط وجزيرة روبن من نقاط مرتفعة.","https://www.sanparks.org/parks/table-mountain","يمثل جبل الطاولة تشكيلًا جيولوجيًا بارزًا حول كيب تاون، وتوجد على سفوحه نباتات فينبوس محلية.","«مفرش الطاولة» اسم شائع لسحابة قد تغطي القمة المسطحة خلال بعض الظروف الجوية."],["ZA","Robben Island","أصبحت جزيرة روبن رمزًا لتاريخ مقاومة الفصل العنصري بعد استخدامها سجنًا سياسيًا، ومن أشهر سجنائها نيلسون مانديلا.","تظهر مباني السجن والزنازين والساحات مع منظر مدينة كيب تاون وجبل الطاولة عبر البحر.","https://whc.unesco.org/en/list/916","استخدمت جزيرة روبن للسجن والعزل على مدى فترات، وأصبحت رمزًا عالميًا لمقاومة نظام الفصل العنصري.","قضى نيلسون مانديلا سنوات من سجنه السياسي في الجزيرة، لكنها شهدت سجناء آخرين كثيرين."],["ZA","Blyde River Canyon","يُظهر وادي نهر بلايد أثر التعرية في تشكيل أخدود عميق داخل تضاريس دراكنزبرغ، مع غطاء نباتي كثيف نسبيًا.","تبرز المنعطفات الجبلية والتكوينات الصخرية مثل القمم الثلاثة والأخاديد الخضراء من نقاط المشاهدة.","https://www.sanparks.org/","نحتت الأنهار وادي بلايد عبر المرتفعات، وبقيت المنطقة أكثر خضرة من أخاديد صحراوية كثيرة.","تُعرف تشكيلات «الروندافيلات الثلاثة» بصخور تشبه أسقف الأكواخ التقليدية عند النظر من بعيد."],["ZA","Cradle of Humankind","تحتفظ كهوف مهد البشرية بحفريات مهمة لأشباه البشر القدماء، وأسهمت اكتشافاتها في دراسة التطور البشري في أفريقيا.","تظهر مواقع الكهوف الجيرية ومناطق التنقيب والمعارض التي تشرح تاريخ الحفريات وتطور الإنسان.","https://whc.unesco.org/en/list/915","ساعدت أعمال التنقيب في كهوف ستيركفونتين وغيرها على اكتشاف حفريات لأشباه البشر من عصور مختلفة، وأتاحت مقارنتها بإعادة بناء فصول من التطور البشري.","اسم المنطقة وصف لمكان اكتشاف أحافير بارزة، وليس ادعاءً بأن البشر نشؤوا جميعًا داخل كهف واحد."],["AR","Perito Moreno Glacier","يُظهر نهر بيريتو مورينو الجليدي حركة الجليد من الحقول الجليدية في باتاغونيا إلى بحيرة أرخنتينو، وهو معلم لفهم ديناميكية الأنهار الجليدية.","تظهر الجبهة الجليدية الزرقاء المتشققة والقمم المحيطة، وقد تنفصل منها كتل جليدية إلى البحيرة.","https://whc.unesco.org/en/list/145","تُغذي حقول الجليد الباتاغونية الجبهة المتقدمة نحو البحيرة. وتُسجّل الدراسات تغيرات موضع الجبهة مع توازن تراكم الثلوج وذوبان الجليد.","تتغير الجبهة باستمرار؛ لذلك لا يمكن توقع لحظة سقوط قطعة جليدية بعينها."],["AR","Teatro Colón","يمثل مسرح كولون ازدهار الحياة الموسيقية والفنية في بوينس آيرس مطلع القرن العشرين، ويشتهر بتصميم قاعته وصوتياتها.","تظهر القاعة على هيئة حدوة حصان والشرفات المتدرجة والسقف المزخرف والثريات الكبرى.","https://teatrocolon.org.ar/","افتُتح مسرح كولون بمبناه الحالي عام 1908 وأصبح مركزًا بارزًا للأوبرا والعروض الموسيقية في الأرجنتين.","ترتبط شهرته بالتوازن بين تصميم القاعة والصوتيات، وليس بزخارفه وحدها."],["AR","Aconcagua Provincial Park","يُعد أكونكاغوا أعلى جبل في الأمريكتين، ويوضح مشهدًا من الجغرافيا الجبلية العالية والجفاف والثلوج في الأنديز.","تظهر القمة الصخرية الشاهقة والوديان المفتوحة والأنهار الجليدية ومسارات الجبال الوعرة.","https://www.mendoza.gov.ar/areasnaturales/","أسهمت بعثات التسلق والخرائط الجبلية في التعرف على طرق أكونكاغوا منذ القرن التاسع عشر، وأُنشئت منطقة محمية لصون منظره الأنديزي.","ارتفاع الجبل لا يعني أنه بركان نشط؛ فهو قمة جبلية ضمن سلسلة الأنديز."],["AR","San Ignacio Miní","تكشف أطلال سان إغناسيو ميني عن تاريخ بعثات اليسوعيين ومجتمعات الغواراني في أمريكا الجنوبية خلال الفترة الاستعمارية.","تظهر الواجهة الحجرية الحمراء للكنيسة وأطلال الساحات والمساكن المحاطة بالغابات شبه الاستوائية.","https://whc.unesco.org/en/list/275","تكوّنت بعثة سان إغناسيو ميني اليسوعية في سياق تفاعل تاريخي مع مجتمعات الغواراني خلال الحقبة الاستعمارية.","الواجهات الحجرية الحمراء المتبقية جزء من مستوطنة شملت مساحات للعيش والعمل والعبادة."],["NL","Amsterdam Canal Ring","تُظهر قنوات أمستردام تخطيطًا حضريًا مبتكرًا من القرن السابع عشر سمح بالتوسع عبر إنشاء أراضٍ وشوارع وممرات مائية منظمة.","تظهر القنوات نصف الدائرية والجسور الحجرية والبيوت الضيقة ذات الواجهات المزخرفة المنعكسة على المياه.","https://whc.unesco.org/en/list/1349","بدأ شق القنوات الرئيسية في عصر التوسع التجاري الهولندي بالقرن السابع عشر، فصارت المياه جزءًا من تنظيم المدينة وأحيائها.","منازل القنوات ضيقة الواجهات عادةً لأن قطع الأراضي الحضرية كانت محدودة العرض."],["NL","Rijksmuseum","يعرض المتحف تطور الفن والتاريخ الهولنديين عبر قرون، وتضم مجموعته أعمالًا بارزة من العصر الذهبي الهولندي.","تظهر قاعة الشرف ولوحات مثل الحراسة الليلية لرامبرانت، مع تفاصيل المبنى القوطي النهضوي وحدائقه.","https://www.rijksmuseum.nl/en","افتُتح متحف ريكسميوزيوم بمبناه الحالي في القرن التاسع عشر ليضم مجموعات الفن والتاريخ الهولندية.","لوحة «الحراسة الليلية» تُظهر مجموعة مدنية في حركة وتفاعل، لا مجرد صف ثابت من الأشخاص."],["NL","Keukenhof","تُعد كيوكينهوف عرضًا موسميًا لفن زراعة الزهور الهولندية، وليس حديقة طبيعية برية مفتوحة طوال العام.","تظهر أحواض التوليب بألوان متدرجة والممرات وسط الأشجار والبرك وتنسيقات الزهور التي تتغير من موسم لآخر.","https://keukenhof.nl/en/","نشأت حديقة كيوكينهوف الحديثة لعرض منتجات مزارعي الأبصال، وأصبحت مناسبة موسمية مرتبطة بالربيع.","مدة ظهور التوليب محدودة وتتغير بحسب الطقس؛ الموقع ليس حقلاً متفتحًا طوال العام."],["NL","Kinderdijk Windmills","توضح طواحين كيندرديك استخدام طاقة الرياح في إدارة منسوب المياه بالمناطق الهولندية المنخفضة وحماية الأراضي من الغمر.","تنتظم الطواحين التاريخية على جانبي القنوات مع الجسور والمضخات والمناظر الريفية المفتوحة.","https://whc.unesco.org/en/list/818","أُقيم نظام طواحين كيندرديك ضمن جهود تاريخية لتصريف المياه من الأراضي المنخفضة إلى قنوات أعلى.","الطواحين هنا جزء من منظومة هندسية للمياه، وليست مجرد مبانٍ ريفية للزينة."],["NL","Anne Frank House","يرتبط المنزل بقصة آن فرانك وأسرتها خلال اضطهاد اليهود في الحرب العالمية الثانية، ويمثل موقعًا للتعلم عن الهولوكوست وآثار التمييز.","تظهر غرف الملحق السري والممرات الضيقة والمواد التاريخية التي تشرح ظروف الاختباء؛ احترام طبيعة الموقع التذكارية ضروري.","https://www.annefrank.org/en/museum/","دوّنت آن فرانك يومياتها أثناء اختباء أسرتها في ملحق خلف مبنى الشركة بأمستردام خلال الحرب العالمية الثانية.","الموقع مكان للتذكر والتعلّم عن ضحايا الاضطهاد النازي، وليس تجربة ترفيهية."],["NL","Van Gogh Museum","يساعد المتحف على تتبع تطور أسلوب فان غوخ من الأعمال المبكرة إلى اللوحات ذات الألوان والضربات التعبيرية المميزة.","تظهر مجموعات من لوحاته ورسائله ورسوماته التي تربط الفن بحياته الشخصية ومراحل إبداعه.","https://www.vangoghmuseum.nl/en","يروي المتحف مسيرة فان غوخ عبر لوحاته ورسائله، من أعماله المبكرة إلى تجاربه اللونية اللاحقة.","الرسائل المعروضة تساعد على فهم أفكاره وخياراته الفنية، بجانب النظر إلى اللوحات."],["NL","Zaanse Schans","تقدم زانس سخانس عرضًا حيًا لعناصر الصناعة والحياة التقليدية في منطقة زان، حيث ارتبطت الطواحين بإنتاج الأخشاب والزيوت ومواد أخرى.","تظهر الطواحين الخشبية الخضراء والمنازل التراثية والورش التقليدية والحقول المحيطة.","https://www.dezaanseschans.nl/en/","تجمع زانس سخانس مباني وطواحين تراثية نُقلت أو حُفظت لتوضيح حياة المنطقة الصناعية التاريخية.","بعض الطواحين مرتبطة بصناعات مثل نشر الخشب وطحن المواد، وليست كلها لطحن الحبوب."],["NL","Hoge Veluwe National Park","يجمع منتزه هوخه فيلوفه بين الغابات والأراضي الرملية والخلنجية، ويقدم نموذجًا لحماية بيئات طبيعية متنوعة داخل هولندا.","تظهر المساحات الرملية المفتوحة والدراجات البيضاء والمسارات بين الغابات والمراعي.","https://www.hogeveluwe.nl/en","حافظت المنطقة على فسيفساء من الغابات والخلنج والرمال المتحركة، وتجمع حماية الطبيعة مع المؤسسات الثقافية.","يمكن أن تنتقل خلال زيارة واحدة من الغابة الكثيفة إلى مناطق رملية مفتوحة."],["CZ","Prague Castle","يُظهر مجمع قلعة براغ تعاقب عصور الحكم في الأراضي التشيكية، إذ يضم منشآت دينية وسياسية ومعمارية من قرون متعددة.","تظهر كاتدرائية القديس فيتوس والقصور والبوابات والساحات المرتفعة فوق نهر فلتافا.","https://www.hrad.cz/en/prague-castle-for-visitors","نشأ مجمع قلعة براغ عبر عصور متلاحقة وصار مركزًا للحكم، ولذلك لا ينتمي كل جزء منه إلى فترة معمارية واحدة.","تظهر داخل المجمع مبانٍ دينية وملكية وساحات من أنماط تاريخية مختلفة."],["CZ","Charles Bridge","ارتبط جسر تشارلز بتوسع براغ في العصور الوسطى، وبقي معبرًا تاريخيًا بارزًا على نهر فلتافا.","تظهر الأقواس الحجرية وتماثيل القديسين وأبراج الجسر مع الإطلالة على القلعة والمدينة القديمة.","https://www.prague.eu/en/","بدأ بناء الجسر الحجري في القرن الرابع عشر ليحل محل معبر أقدم على نهر فلتافا.","التماثيل المنتشرة على الجسر أضيف كثير منها بعد فترة بنائه الأولى."],["CZ","Prague Astronomical Clock","تعكس ساعة براغ الفلكية اهتمام أوروبا الوسطى التاريخي بقياس الزمن وحركة الأجرام السماوية في جهاز ميكانيكي عام.","تظهر اللوحة الفلكية الدائرية والتقويم والزخارف وحركة التماثيل المرتبطة بعرض الساعة.","https://www.prague.eu/en/","تعمل الساعة الفلكية التاريخية منذ العصور الوسطى، وتجمع عرض الوقت بمعلومات فلكية وتقويمية رمزية.","لوحة الساعة لا تتعامل مع الزمن كساعة حديثة فقط، بل تتضمن رموزًا لحركة السماء."],["CZ","Historic Centre of Český Krumlov","تُعد تشيسكي كروملوف نموذجًا محفوظًا لمدينة وسط أوروبية نشأت حول القلعة والنهر، مع تأثيرات قوطية ونهضوية وباروكية.","تظهر انحناءات فلتافا حول البلدة والأسقف القرميدية والقلعة والبرج الملوّن فوق الشوارع.","https://whc.unesco.org/en/list/617","تطور المركز التاريخي حول قلعة ومجرى متعرج لنهر فلتافا، وحافظ على نسيجه العمراني القديم.","تُرى البلدة من أعلى القلعة وكأن النهر يرسم إطارًا حول أسقفها الحمراء."],["CZ","Sedlec Ossuary","يكشف مصلى سيدليتس عن تقاليد أوروبية قديمة في حفظ عظام الموتى واستخدامها لتكوين عناصر تذكارية وزخرفية غير مألوفة.","تظهر الثريات والتكوينات العظمية داخل مصلى صغير؛ طبيعة المعروضات تتطلب تعاملًا محترمًا مع رفات بشرية.","https://www.sedlec.info/en/","ارتبط المصلى بالمقبرة التاريخية في سيدليتس، وأعيد ترتيب عظام بشرية ضمن عناصره الداخلية.","الزخارف مصنوعة من رفات أشخاص حقيقيين، وهو سبب يستدعي احترامًا خاصًا عند الزيارة."],["CZ","Karlštejn Castle","بُنيت كارلشتين في القرن الرابع عشر بطلب من الإمبراطور شارل الرابع لحماية مقتنيات وذخائر ملكية ثمينة.","تظهر الأبراج المدرجة فوق التلة والأسوار والقاعات التاريخية وسط الغابات القريبة من براغ.","https://www.hrad-karlstejn.cz/en","شُيدت القلعة بأمر من شارل الرابع لتأمين المقتنيات الثمينة داخل حصن يبعد عن براغ.","تساعد الأبراج المتدرجة على فهم ارتباط تصميم القلاع بالدفاع عن المواقع المرتفعة."],["CZ","Lednice–Valtice Cultural Landscape","يُظهر منظر ليدنيتسه وفالتيسه كيف حوّلت أسرة ليختنشتاين مساحة شاسعة إلى حدائق وقصور ومبانٍ زخرفية مترابطة.","تظهر القصور والبحيرات والممرات المشجرة والحدائق المصممة والمنشآت الصغيرة داخل المشهد الطبيعي.","https://whc.unesco.org/en/list/763","صممت عائلة ليختنشتاين القصور والحدائق والمنشآت المنتشرة بالمنطقة كوحدة منظر ثقافي واسع.","المشهد لا يقتصر على قصر واحد؛ فهو شبكة من الحدائق والبحيرات والمباني."],["CZ","Bohemian Switzerland National Park","تتميز سويسرا البوهيمية بتكوينات من الحجر الرملي نتجت عن التعرية، وتضم غابات ووديانًا صخرية حساسة بيئيًا.","يمكن تأمل القوس الصخري برافشيتسكا برانا والمنحدرات والممرات بين الصخور والغابات.","https://www.npcs.cz/en","نشأت أشكال الحجر الرملي في المنطقة من الترسيب والتعرية عبر أزمنة طويلة، ثم أُعلنت الحماية الطبيعية لأجزائها.","القوس الرملي الطبيعي المعروف باسم برافشيتسكا برانا واسع الامتداد، وقد شكّلته التعرية في الحجر الرملي من غير أي بناء بشري."],["CA","Niagara Falls","تُظهر شلالات نياجرا قوة التعرية المائية على جرف نياجرا، وتشكل حدودًا طبيعية بارزة بين كندا والولايات المتحدة.","تظهر شلالات حدوة الحصان من الجانب الكندي مع الضباب الكثيف والأمواج الهابطة إلى المضيق.","https://www.niagaraparks.com/","تكوّنت شلالات نياجرا بفعل جريان المياه ونحت الصخور بعد العصر الجليدي الأخير.","الشلالات تتحرك جيولوجيًا ببطء نتيجة التعرية رغم مظهرها الثابت في الصور."],["CA","Banff National Park","يحمي بانف مشاهد جبال روكي الكندية من قمم جليدية وبحيرات وموائل للحياة البرية، وهو أول متنزه وطني في كندا.","تظهر الوديان الجبلية والبحيرات الفيروزية وغابات الصنوبر والمرتفعات الثلجية.","https://parks.canada.ca/pn-np/ab/banff","تأسس بانف لحماية الينابيع الحارة والمشهد الجبلي، ثم أصبح جزءًا من شبكة حدائق روكي الكندية.","الأنهار الجليدية تطحن الصخور إلى دقائق تسهم في اللون الفيروزي لبعض البحيرات."],["CA","Lake Louise","تستمد بحيرة لويز لونها الفيروزي المميز من الجزيئات الصخرية الدقيقة المنقولة من الأنهار الجليدية.","تظهر مياه البحيرة الصافية وقمم الجبال المحيطة ونهر فيكتوريا الجليدي في نهاية الوادي.","https://parks.canada.ca/pn-np/ab/banff/activ/louise","نحتت الأنهار الجليدية في جبال روكي الكندية الوادي الذي تحتله بحيرة لويز، وتغذيها مياه ذوبان الجليد المحملة بجزيئات صخرية شديدة الدقة تُسمّى «الدقيق الصخري». تبقى هذه الجزيئات معلقة في الماء وتشتت الضوء، ما يفسر اللون الفيروزي الشهير بدل أن يكون ناتجًا عن أصباغ أو لون قاع البحيرة وحده. وترتبط البحيرة بمشهد نهر فيكتوريا الجليدي وبالتغيرات الطويلة في امتداد جليد المنطقة.","يتغير تدرج اللون بين الفصول ومع كمية الرواسب والضوء."],["CA","Historic District of Old Québec","تحتفظ كيبيك القديمة بأسوار وتخطيط عمراني يعكسان تاريخ الاستيطان الفرنسي في أمريكا الشمالية وتطور المدينة تحت الحكمين الفرنسي والبريطاني.","تظهر المباني الحجرية والشوارع المتعرجة والبوابات التاريخية وشاتو فرونتيناك أعلى نهر سان لوران.","https://whc.unesco.org/en/list/300","احتفظت كيبيك القديمة بأسوار تاريخية ومبانٍ تربط المدينة بتاريخ فرنسا الجديدة ثم التحولات اللاحقة.","تُعد المدينة المحصنة حالة مميزة بين المراكز الحضرية التاريخية في أمريكا الشمالية."],["CA","CN Tower","يمثل برج سي إن مرحلة تطور الاتصالات والهندسة العالية في كندا خلال السبعينيات، وأصبح من أبرز رموز تورونتو.","يمكن رؤية العمود الخرساني النحيل ومنصات المشاهدة وأفق تورونتو وبحيرة أونتاريو.","https://www.cntower.ca/","بُني برج سي إن في سبعينيات القرن العشرين ليخدم الاتصالات ويصبح إنجازًا هندسيًا بارزًا.","الارتفاع الكبير يتيح رؤية علاقة تورونتو ببحيرة أونتاريو وشبكة شوارعها."],["CA","Jasper National Park","يحمي جاسبر مساحة شاسعة من جبال روكي الكندية، حيث تتجاور الأنهار الجليدية والمروج والغابات والحياة البرية.","تظهر الجبال والوديان وبحيرة مالين وأجزاء من حقل كولومبيا الجليدي والمناظر الطبيعية المفتوحة.","https://parks.canada.ca/pn-np/ab/jasper","يحمي جاسبر موائل جبلية وأجزاء من النظام الجليدي لجبال روكي داخل نطاق واسع قليل الكثافة السكانية.","حقل كولومبيا الجليدي يغذي أنهارًا تتجه نحو أحواض تصريف مختلفة."],["CA","Stanley Park","يُبرز ستانلي بارك تداخل الغابات الساحلية مع الحياة الحضرية لفانكوفر، ويحمل أيضًا مواقع مهمة للتراث الثقافي للسكان الأصليين.","تظهر الأشجار العملاقة والطريق البحري المحيط بالمنتزه والشواطئ والمناظر المطلة على الجبال والمدينة.","https://vancouver.ca/parks-recreation-culture/stanley-park.aspx","تطور ستانلي بارك كحديقة عامة حول غابات ساحلية ذات تاريخ أقدم مرتبط بالشعوب الأصلية.","بعض أشجار المنطقة شاهقة وقديمة، وتجاور الممر البحري الحضري مباشرة."],["CA","Gros Morne National Park","يساعد غروس مورن على فهم حركة الصفائح الأرضية؛ إذ تكشف صخوره عن أجزاء من باطن الأرض ارتفعت إلى السطح.","تظهر جبال التابللاندز ذات الصخور الصفراء البنية والفيوردات والوديان الساحلية.","https://whc.unesco.org/en/list/419","يكشف منتزه غروس مورن في نيوفاوندلاند عن صخور من القشرة المحيطية والوشاح الأرضي دُفعت إلى السطح بفعل حركة الصفائح خلال تكوّن جبال قديمة. وبعد ذلك نحتت الأنهار الجليدية وديانًا عميقة وفيوردات، فاجتمعت في الموقع شواهد تصادم القارات والتجلد. وتُظهر منطقة تابللاندز صخورًا مكشوفة نادرة ذات لون ونباتات مختلفين عن الغابات المحيطة.","مناطق التابللاندز المكشوفة تختلف تمامًا في لونها وغطائها النباتي عن الغابات المجاورة."],["NZ","Milford Sound","يُعد ميلفورد ساوند واديًا جليديًا غمرته مياه البحر، وتحيط به تضاريس شاهقة وأمطار غزيرة وشلالات موسمية.","تظهر قمة ميتر والواجهات الصخرية العالية والشلالات التي تنحدر مباشرة إلى مياه الفيورد.","https://www.doc.govt.nz/parks-and-recreation/places-to-go/fiordland/places/fiordland-national-park/places-to-go/milford-road-milford-sound-area/","شكّلت الأنهار الجليدية عبر فترات طويلة وادي ميلفورد ذي الجوانب الشاهقة، ثم غمرته مياه البحر فأصبح فيوردًا بحريًا لا مجرد خليج نهري. يعرفه الماوري باسم «بيو بيو تاهي»، وله تاريخ من المسارات والتجارة التقليدية؛ كما ساهم شق طريق ميلفورد ونفق هومر في القرن العشرين في توسيع الوصول إلى المنطقة.","تتعدد الشلالات المؤقتة بعد الأمطار الغزيرة فوق الجروف الصخرية."],["NZ","Hobbiton Movie Set","يُظهر هوبيتون كيف تحوّل موقع تصوير سينمائي إلى معلم سياحي يعرض تصميم المشاهد والأكواخ الخيالية ضمن منظر ريفي حقيقي.","تظهر الأبواب المستديرة الملونة والتلال الخضراء والجسور الصغيرة والحدائق المصممة للتصوير.","https://www.hobbitontours.com/","أُنشئت قرية الهوبيت كموقع تصوير لسلسلة أفلام، ثم حُفظت وأُعدت لاستقبال الزوار.","الأبواب الدائرية والمنازل على التلال تفاصيل تصميم سينمائي وليست قرية تاريخية."],["NZ","Wai-O-Tapu Thermal Wonderland","تكشف واي أو تابو عن نشاط حراري أرضي في منطقة تاوبو البركانية، حيث تؤثر المعادن والحرارة في ألوان البرك والتربة.","تظهر بركة الشمبانيا والبخار والتكوينات البرتقالية والبرك الملونة؛ الالتزام بممرات المشاهدة ضروري للسلامة.","https://link.springer.com/article/10.1007/s00445-020-01414-3","تقع واي أو تابو ضمن منطقة تاوبو البركانية النشطة حراريًا، حيث تصعد مياه ساخنة وغازات عبر الشقوق وتترسب المعادن على السطح. وتشير دراسات جيولوجية إلى أن حفرة بركة الشمبانيا الشهيرة تشكلت بانفجار حراري مائي قبل نحو سبعمائة سنة، ثم أسهمت المياه الغنية بالمعادن والغازات في تكوين حوافها البرتقالية ومظاهرها الملونة.","بعض الألوان ناتج عن ترسيب المعادن أو الكائنات الدقيقة المتكيفة مع الحرارة."],["NZ","Tongariro National Park","يجمع تونغاريرو بين مناظر بركانية بارزة وأهمية روحية وثقافية لشعب الماوري، وله قيمة تراثية طبيعية وثقافية معًا.","تظهر الفوهات والحقول البركانية والبحيرات الملونة وقمم الجبال الثلاثة ضمن مشهد مرتفع.","https://whc.unesco.org/en/list/421","ترتبط قمم تونغاريرو وروابيها بروايات الماوري وممارساتهم الثقافية، وقد أُدرج المكان ضمن مواقع التراث العالمي لقيمتيه الطبيعية والثقافية.","تكتسب بعض القمم والبحيرات مكانة ثقافية؛ لذا يجب مراعاة تعليمات الحماية والاحترام."],["NZ","Aoraki / Mount Cook National Park","تُعد أوراكي أعلى قمة في نيوزيلندا، وتحمل أهمية خاصة للماوري، ويكشف متنزهها عن نشاط الأنهار الجليدية والنحت الجبلي.","تظهر القمم الثلجية والأنهار الجليدية والوديان الصخرية وبحيرات المياه الجليدية.","https://www.doc.govt.nz/parks-and-recreation/places-to-go/canterbury/places/aoraki-mount-cook-national-park/","تُظهر أوراكي آثار التجلد والنحت الصخري في أعلى جبال نيوزيلندا، ويُعد الجبل مهمًا في تراث الماوري.","يمكن مشاهدة رواسب جليدية ومياه بحيرات معكرة بدقائق الصخور الناتجة عن حركة الجليد."],["NZ","Waitomo Glowworm Caves","تشتهر كهوف وايتومو بيرقات ذباب فطري مضيئة تشكّل نقاط ضوء تشبه النجوم فوق تجاويف كلسية مظلمة.","تظهر الهوابط والتجاويف الرطبة وتجمعات الأضواء الزرقاء الصغيرة على سقف الكهف.","https://www.waitomo.com/","يرتبط ضوء كهوف وايتومو بيرقات كائنات مضيئة تستخدم الإضاءة الحيوية لجذب فرائس صغيرة.","الأضواء ليست نجومًا أو معادن مضيئة؛ إنها ظاهرة بيولوجية داخل الكهف."],["NZ","Bay of Islands","يرتبط خليج الجزر بتاريخ الملاحة والاستيطان الأوروبي وعلاقات السكان الأصليين الماوري في شمال نيوزيلندا.","تظهر الجزر الصغيرة والممرات البحرية والشواطئ الخضراء مع البلدات الساحلية التاريخية.","https://www.newzealand.com/int/bay-of-islands/","ارتبط خليج الجزر منذ زمن طويل بمجتمعات الماوري والملاحة البحرية، ثم أصبح في القرنين الثامن عشر والتاسع عشر مركزًا مبكرًا للاتصال بين الماوري والأوروبيين. وفي وايتانغي داخل الخليج جرى التوقيع الأول على معاهدة وايتانغي في 6 فبراير 1840، وهو حدث محوري في تاريخ نيوزيلندا لا تزال معانيه وتفسيراته محل نقاش.","تتجاور الجزر الصغيرة والموانئ مع مواقع تروي جوانب من تاريخ البلاد المبكر."],["NZ","Abel Tasman National Park","يمثل أبيل تاسمان منظرًا ساحليًا تتداخل فيه الشواطئ الرملية والغابات والمصبات البحرية والممرات الطبيعية.","تظهر الخلجان الذهبية والمياه الزرقاء والغابات القريبة من الشاطئ والجزر الصغيرة.","https://www.doc.govt.nz/parks-and-recreation/places-to-go/nelson-tasman/places/abel-tasman-national-park/","يحمي أبيل تاسمان شريطًا ساحليًا من الغابات والخلجان، وتتنوع المشاهد مع حركة المد والجزر.","يمكن أن تتغير المسافات المكشوفة على بعض الشواطئ والمصبات تبعًا للمد."],["JO","Petra","كانت البتراء مركزًا تجاريًا وحضريًا مهمًا للأنباط، الذين استغلوا طرق القوافل وصمموا أنظمة مائية معقدة في بيئة صحراوية.","تظهر الخزنة في نهاية السيق، والمقابر المنحوتة والمسرح والواجهات الحجرية الوردية التي تتغير ألوانها مع الضوء.","https://whc.unesco.org/en/list/326","ازدهرت البتراء عاصمةً للأنباط بفضل تجارة القوافل وتطوير أنظمة جمع المياه في بيئة قليلة المطر.","الخزنة واجهة منحوتة في الصخر؛ الاسم الشائع لا يحدد وظيفتها الأصلية بدقة."],["JO","Wadi Rum Protected Area","يحفظ وادي رم مشهدًا صحراويًا ذا قيمة طبيعية وثقافية، تشهد نقوشه وكتاباته على وجود البشر عبر آلاف السنين.","تظهر الكتل الرملية الهائلة والأقواس الطبيعية والأخاديد والرمال الحمراء والمنحوتات الصخرية.","https://whc.unesco.org/en/list/1377","احتفظت صخور وادي رم بآثار بشرية من عصور مختلفة، تشمل كتابات ونقوشًا توثق الحركة في الصحراء.","الألوان الحمراء والبرتقالية تنشأ من المعادن والتجوية في الصخور الرملية."],["JO","Jerash","كانت جرش مدينة مهمة ضمن مدن المنطقة في العصرين اليوناني والروماني، وتظهر آثارها تخطيط المدن وميادينها العامة.","تلفت الساحة البيضاوية والأعمدة والشوارع المرصوفة والمسارح والبوابات الحجرية الانتباه.","https://international.visitjordan.com/","شهدت جرش توسعًا عمرانيًا خلال العصر الروماني وظلت آثار الشوارع والساحات شاهدًا على المدينة.","الساحة البيضاوية تختلف عن التخطيط المستطيل المألوف لكثير من الميادين الرومانية."],["JO","Dead Sea","يتميز البحر الميت بملوحة عالية جدًا وبموقعه في منخفض تكتوني، كما أن انخفاض منسوبه الحديث تحدٍ بيئي كبير.","تظهر الشواطئ المالحة والتكوينات الملحية والجبال المحيطة بالمياه الزرقاء، مع اتساع السواحل المكشوفة في بعض المواضع.","https://digitallibrary.un.org/record/1292668/files/E_ESCWA_SDPD_2013_INVENTORY-EN.pdf","يقع البحر الميت في حوض انهدامي ضمن نظام صدوع البحر الميت، وهو بحيرة داخلية شديدة الملوحة لا يصب منها نهر إلى البحر. تتراكم الأملاح فيه مع التبخر عبر فترات طويلة، بينما تراجع منسوب مياهه بشدة في العصر الحديث بسبب انخفاض تدفقات نهر الأردن ومصادر المياه الأخرى نتيجة تحويل المياه، إلى جانب التبخر. وأدى انكشاف أجزاء من الشاطئ إلى ظهور حفر انهيارية في بعض المناطق.","الطفو المرتفع نتيجة كثافة المياه المالحة، لكنه لا يعني انعدام مخاطر السباحة."],["JO","Amman Citadel","تحتفظ قلعة عمّان بطبقات من التاريخ، من الآثار القديمة إلى الأبنية الأموية، وتبرز دور الموقع المرتفع في الدفاع والمراقبة.","تظهر أعمدة معبد هرقل وبقايا القصر الأموي والآثار المطلة على أحياء عمّان المتدرجة.","https://international.visitjordan.com/","تراكمت في قلعة عمّان آثار من عصور متلاحقة، منها معبد روماني ومجمع من الفترة الأموية.","الآثار الواقعة على هضبة واحدة لا تعود كلها إلى حضارة أو قرن واحد."],["JO","Mount Nebo","يرتبط جبل نيبو بالتقاليد الدينية اليهودية والمسيحية وبذكرى النبي موسى، كما يضم آثارًا كنسية وفسيفساء تاريخية.","يمكن مشاهدة فسيفساء الكنيسة القديمة والإطلالة الواسعة نحو وادي الأردن والبحر الميت عند صفاء الأجواء.","https://international.visitjordan.com/","ارتبط جبل نيبو بتقاليد دينية متعددة، وأقيمت في موقعه كنائس تعود إلى العصر البيزنطي.","فسيفساء الموقع مصدر فني لدراسة صور الحيوانات والمشاهد الدينية القديمة."],["JO","Baptism Site Bethany Beyond the Jordan","يُعد المغطس موقعًا للحج المسيحي مرتبطًا بالتقاليد المتعلقة بمعمودية السيد المسيح، وتكشف آثاره عن تاريخ الممارسات الدينية في المنطقة.","تظهر بقايا الكنائس والبرك القديمة ومسارات الوصول إلى ضفاف نهر الأردن ضمن المشهد الطبيعي.","https://whc.unesco.org/en/list/1446","تطور المغطس مكانًا للحج المسيحي قرب نهر الأردن مع بقايا منشآت دينية ومائية تاريخية.","الموقع الأثري يشمل شواهد حول النهر، وليس مجرد نقطة واحدة داخل الماء."],["JO","Umm Qais (Gadara)","كانت جدارا إحدى مدن الديكابوليس، وتبرز آثارها تبادل التأثيرات الثقافية في المنطقة خلال الفترات الهلنستية والرومانية.","تظهر الشوارع الحجرية ذات الأعمدة والمسرح والمباني البازلتية مع إطلالات على وادي اليرموك وبحيرة طبريا.","https://international.visitjordan.com/","كانت جدارا جزءًا من شبكة مدن قديمة في المنطقة، واستفادت من موقعها المطل على طرق ومناطق زراعية.","استُخدم البازلت الداكن في بعض المباني، ما يميز لونها عن الحجر الجيري بمواقع أخرى."],["OM","Sultan Qaboos Grand Mosque","يمثل جامع السلطان قابوس الأكبر إحدى أبرز تجارب العمارة الدينية الحديثة بعُمان، حيث يجمع بين الأروقة والمناظر الطبيعية والفنون الزخرفية.","تظهر القبة الرئيسية والمآذن الخمس والفناءات الرخامية والزخارف الدقيقة والسجاد الكبير في قاعة الصلاة.","https://experienceoman.om/","افتُتح جامع السلطان قابوس الأكبر في مطلع القرن الحادي والعشرين بوصفه معلمًا دينيًا وثقافيًا رئيسيًا بمسقط.","مزيج الرخام والزخارف والحدائق يعطي توازنًا بين ضخامة المبنى وهدوء ساحاته."],["OM","Nizwa Fort","يُظهر حصن نزوى أهمية التحصين والإدارة في المدن الداخلية العُمانية، ويتميز ببرج دفاعي دائري كبير من القرن السابع عشر.","تظهر جدران الحصن السميكة والممرات والفتحات الدفاعية والبرج المطل على بساتين النخيل والمدينة.","https://experienceoman.om/media/pigfokjz/oman-tourism-directory.pdf","كان حصن نزوى مركزًا دفاعيًا وإداريًا للمدينة، وأعيد بناؤه بصورته المعروفة في القرن السابع عشر.","تصميم البرج الدائري الضخم يخدم الرؤية والدفاع من اتجاهات متعددة."],["OM","Jebel Akhdar","تشتهر مرتفعات الجبل الأخضر بتنوعها المناخي النسبي ومدرجاتها الزراعية التي سمحت بزراعة محاصيل في بيئة جبلية شديدة الانحدار.","تظهر القرى الحجرية والحقول المدرجة وأشجار الفاكهة والوديان العميقة بين الجبال.","https://experienceoman.om/","ساعد الارتفاع في الجبل الأخضر على نشوء زراعة مدرجات وأفلاج في أودية ومواقع يصعب استغلالها.","تتدرج البيئات من السفوح الجافة إلى قرى أعلى ذات زراعات موسمية."],["OM","Wadi Shab","يكشف وادي شاب عن أثر جريان المياه في شق الصخور الجيرية قرب بحر العرب، ويتميز بالتباين بين البرك والممرات الصخرية.","تظهر البرك الفيروزية والمنحدرات الشاهقة والنخيل والممرات الضيقة المؤدية إلى أجزاء داخلية من الوادي.","https://experienceoman.om/","تكون وادي شاب بفعل جريان المياه ونحت الصخور ضمن جبال الحجر القريبة من الساحل.","قد تختلف كمية المياه وإمكان الوصول إلى البرك باختلاف الأمطار والسيول."],["OM","Bahla Fort","يعكس حصن بهلاء تقاليد البناء الطيني في المدن الواحية العُمانية، ويرتبط بنظام من التحصينات والأسواق والمزارع التاريخية.","تظهر الأبراج والأسوار الطينية والفناءات المتدرجة وخطوط الحصن فوق الواحة.","https://whc.unesco.org/en/list/433","ازدهرت بهلاء تحت حكم بني نبهان الذين جعلوا الواحة مركزًا لقوتهم في عُمان من القرن الثاني عشر حتى أواخر القرن الخامس عشر. وارتبط حصنها الطيني الضخم بأسوار تحمي المساكن والمزارع، وبنظام الأفلاج الذي أمد الواحة بالمياه وأسهم في استمرار الاستقرار حولها.","تحتاج الجدران الترابية إلى صيانة متكررة لأنها تتأثر بالأمطار والتعرية."],["OM","Wahiba Sands","تُعرف رمال الشرقية بكثبانها الطولية والمرتفعة وتنوع ألوانها، كما ترتبط بأنماط حياة رعوية وصحراوية عُمانية.","تظهر سلاسل الكثبان المتوازية والقمم الرملية المتغيرة بفعل الرياح والمساحات المفتوحة الممتدة.","https://experienceoman.om/","تشكلت كثبان رمال الشرقية عبر نقل الرياح للرواسب الرملية وإعادة توزيعها على مدى طويل.","تختلف أنماط التموجات والكثبان مع اتجاه الرياح وطبيعة سطح الصحراء."],["OM","Muttrah Souq","يُجسد سوق مطرح تاريخ مسقط التجاري باعتبارها ميناءً متصلًا بالمحيط الهندي وشبكات التبادل بين الجزيرة العربية وآسيا وشرق أفريقيا.","تظهر الأزقة المسقوفة والمتاجر التقليدية والممرات المتعرجة قرب الكورنيش والميناء.","https://experienceoman.om/","ارتبط سوق مطرح بالمرفأ القريب وبحركة التجارة البحرية في مسقط عبر أجيال.","الأزقة المسقوفة تساعد على توفير الظل داخل بيئة ساحلية حارة."],["OM","Ras al Jinz Turtle Reserve","يحمي رأس الجنز شاطئًا مهمًا لتعشيش السلاحف البحرية، وخاصة السلاحف الخضراء، وتحتاج عمليات المشاهدة إلى قواعد لحماية الحيوانات.","تظهر الشواطئ الرملية الواسعة وآثار زحف السلاحف وأماكن الأعشاش، دون إزعاج السلاحف أو استخدام إضاءة غير مناسبة.","https://www.rasaljinz-turtlereserve.com/","يحمي رأس الجنز ساحلًا يستخدمه بعض أنواع السلاحف البحرية للتعشيش بصورة موسمية.","تؤثر الإضاءة والضوضاء في سلوك السلاحف، ولهذا تنظم الزيارات بشروط حماية."],["PE","Machu Picchu","تمثل ماتشو بيتشو إنجازًا بارزًا في تخطيط الإنكا، حيث اندمجت العمارة الحجرية والمدرجات الزراعية مع تضاريس جبال الأنديز شديدة الانحدار.","تظهر المدرجات والبوابات الحجرية والمباني المتدرجة والقمم المغطاة بالضباب المحيطة بالموقع.","https://whc.unesco.org/en/list/274","شيد الإنكا ماتشو بيتشو في بيئة جبلية وعرة مع مدرجات وتصريف للمياه، وظل الموقع بعيدًا عن مراكز الاستيطان اللاحق.","الحجارة المتشابكة في بعض الجدران تثبت دون الحاجة إلى مونة ظاهرة."],["PE","Historic Centre of Cusco","كانت كوسكو مركزًا سياسيًا وروحيًا لحضارة الإنكا، ثم أعيد تشكيل كثير من مبانيها خلال الحقبة الاستعمارية الإسبانية.","تظهر الجدران الحجرية الدقيقة للإنكا أسفل مبانٍ استعمارية وساحات وكنائس وأزقة تاريخية.","https://whc.unesco.org/en/list/273","كانت كوسكو مركز حكم الإنكا، ثم استُخدمت قواعد حجرية قائمة في مبانٍ من الحقبة الاستعمارية.","يمكن مقارنة دقة صفوف الحجارة القديمة بواجهات المباني اللاحقة فوقها."],["PE","Nazca Lines","تُعد خطوط نازكا من أبرز الرسوم الأرضية القديمة، وقد صممت عبر إزالة الحجارة الداكنة للكشف عن التربة الأفتح لونًا.","يمكن تمييز أشكال الطائر والعنكبوت والقرد وخطوط هندسية طويلة من زوايا مشاهدة مرتفعة.","https://whc.unesco.org/en/list/700","أنشأت مجتمعات الساحل الجنوبي في بيرو الرسوم الأرضية في نازكا وبالبا خلال مراحل امتدت تقريبًا من 500 قبل الميلاد إلى 500 ميلادية؛ وذلك بكشف التربة الفاتحة تحت الحصى الداكن. وتشمل الرسوم أشكالًا حيوانية ونباتية وخطوطًا هندسية، بينما تظل أغراضها الطقسية الدقيقة موضع بحث.","كبر حجم الرسوم يجعل بعض أشكالها أوضح من نقاط مشاهدة عالية."],["PE","Lake Titicaca","تُعد تيتيكاكا من أبرز البحيرات المرتفعة في الأنديز، وترتبط بثقافات محلية ومجتمعات عاشت على ضفافها وجزرها قرونًا.","تظهر المياه الواسعة والجزر والقرى ومراكب القصب التقليدية في بعض مناطق البحيرة.","https://www.peru.travel/","تاريخ مجتمعات ضفاف تيتيكاكا مرتبط بالزراعة والطرق المائية والطقوس المحلية عبر قرون.","بعض الجزر الاصطناعية مصنوعة من نبات القصب، وتتطلب صيانة مستمرة."],["PE","Colca Canyon","يكشف وادي كولكا أثر نحت الأنهار في جبال الأنديز، كما يحتفظ بمدرجات زراعية تاريخية استغلت المنحدرات.","تظهر جدران الأخدود العميقة والحقول المدرجة وطيور كندور الأنديز المحلقة فوق بعض نقاط المشاهدة.","https://www.peru.travel/","ساعدت المدرجات الزراعية في كولكا على استغلال المنحدرات واستبقاء التربة والمياه في المرتفعات.","قد تُشاهد طيور كندور الأنديز وهي تحلّق باستغلال التيارات الهوائية الصاعدة."],["PE","Sacred Valley of the Incas","شكّل الوادي المقدس منطقة زراعية واستراتيجية مهمة للإنكا، حيث ساعدت التربة والمياه والارتفاعات على قيام المستوطنات والطرق.","تظهر مدرجات بيساك وأطلال أولانتايتامبو والقرى والحقول الممتدة على طول نهر أوروبامبا.","https://www.peru.travel/","ضم الوادي تجمعات ومواقع زراعية وإنشائية متصلة بشبكة طرق الإنكا، وبرزت فيه أولانتايتامبو بوصفها موقعًا ذا دور دفاعي وإداري.","تختلف أطلال بيساك وأولانتايتامبو في تخطيطها رغم وقوعهما ضمن الوادي نفسه."],["PE","Chan Chan Archaeological Zone","كانت تشان تشان عاصمة مملكة شيمو، ويكشف امتداد مبانيها الطينية عن مجتمع منظم قبل توسع دولة الإنكا.","تظهر الجدران الطينية المزخرفة بأشكال هندسية وبحرية والأفنية والممرات الواسعة.","https://whc.unesco.org/en/list/366","كانت تشان تشان عاصمة دولة شيمو قبل خضوعها للإنكا، وبنيت أجزاء واسعة منها بالطوب اللبن.","منحوتات الأسماك والأمواج على بعض الجدران تكشف الصلة الوثيقة بالبيئة البحرية."],["PE","Vinicunca Rainbow Mountain","تنتج ألوان فينيكونكا المتعددة من اختلاف المعادن وطبقات الرواسب التي ظهرت بفعل عمليات جيولوجية في الأنديز.","تظهر شرائط حمراء وصفراء وخضراء عبر المنحدرات العالية، مع قمم وأودية جبلية شبه خالية من الأشجار.","https://www.peru.travel/","أظهرت عمليات النحت الجبلي طبقات رسوبية تحتوي معادن مختلفة، ما منح فينيكونكا أشرطة ألوانها.","الألوان طبيعية مرتبطة بالجيولوجيا ولا تحتاج إلى تفسير أسطوري أو معالجة صناعية."],["KH","Angkor Wat","يُعد أنغكور وات تحفة للعمارة الخميرية الكلاسيكية، وارتبط بتقاليد هندوسية ثم بوذية ضمن منطقة أنغكور التاريخية.","تظهر الأبراج الخمسة والخندق المائي وممرات الأعمدة والنقوش البارزة التي تصور مشاهد أسطورية وتاريخية.","https://whc.unesco.org/en/list/668","شُيّد أنغكور وات في القرن الثاني عشر ضمن حضارة الخمير التي اتخذت منطقة أنغكور مركزًا سياسيًا ودينيًا لقرون. ارتبط المعبد في الأصل بالتقاليد الهندوسية، ثم استمر حضوره الديني مع انتشار البوذية. ويشكّل جزءًا من منطقة أثرية واسعة تضم معابد وخزانات وقنوات وطرقًا تاريخية.","النقوش البارزة الطويلة تعرض قصصًا ومشاهد شعائرية إلى جانب المخطط المحوري للمعبد."],["KH","Bayon Temple","اشتهر معبد بايون في عهد الملك جيافارمان السابع بأبراجه المزينة بوجوه حجرية كبيرة، ويقع في قلب مدينة أنغكور ثوم.","تظهر الوجوه المنحوتة من اتجاهات متعددة والممرات الضيقة والنقوش التي تعرض مشاهد من الحياة الخميرية.","https://whc.unesco.org/en/list/668","أُقيم بايون ضمن مدينة أنغكور ثوم الملكية، وأضيفت إليه عناصر ونقوش في مراحل متعاقبة؛ لذا يجمع المعبد آثارًا دينية وفنية متداخلة.","تختلف تعبيرات الوجوه بحسب زاوية النظر والضوء، بينما تصور النقوش مشاهد يومية أيضًا."],["KH","Ta Prohm","يشهد تا بروهم على العمارة الدينية الخميرية وعلى علاقة الموقع بالغابات المحيطة بعد قرون من تغيّر استعماله.","تلتف جذور الأشجار الضخمة حول البوابات والجدران الحجرية في مشهد يجمع الطبيعة والآثار.","https://whc.unesco.org/en/list/668","ارتبط تا بروهم بالمؤسسات الدينية الخميرية، وبقيت بعض الأشجار جزءًا من المشهد الأثري أثناء أعمال الحفظ.","قد تتداخل الجذور مع الأحجار فتبدو داعمة لها أحيانًا، لكنها تمثل تحديًا إنشائيًا كذلك."],["KH","Temple of Preah Vihear","يشكل معبد برياه فيهير مجمعًا دينيًا خميريًا ممتدًا على محور طولي فوق حافة جبلية، وهو من المواقع التراثية ذات الأهمية المعمارية.","تظهر السلالم والبوابات والممرات المتتابعة والأجنحة الحجرية والإطلالات المرتفعة على السهل.","https://whc.unesco.org/en/list/1224","يمتد معبد برياه فيهير فوق موقع مرتفع بمدرجات وبوابات متتابعة تعكس الهندسة الطولية للمجمع.","المحور المتدرج فوق حافة الجبل يختلف عن تركيز معابد أخرى على ساحة مركزية واحدة."],["KH","Banteay Srei","يتميز بانتيي سري بصغر بعض مبانيه وبالمنحوتات الدقيقة على الحجر الرملي ذي اللون الوردي، ويُعد مثالًا رفيعًا للفن الخميري.","تظهر الواجهات ذات النقوش الزهرية والقصص الأسطورية والبوابات المنحوتة بالتفصيل.","https://whc.unesco.org/en/list/668","برز بانتيي سري بنقوشه التفصيلية الدقيقة المحفورة في حجر رملي وردي خلال العصر الخميري.","يمكن رؤية زخارف نباتية وشخصيات أسطورية صغيرة بتفاصيل أدق من معابد أكبر."],["KH","Tonlé Sap Lake","تُعد تونلي ساب منظومة مائية حيوية يتغير حجمها كثيرًا مع المواسم نتيجة التدفق بين البحيرة ونهر ميكونغ.","تظهر القرى القائمة على أعمدة أو العائمة ومناطق الصيد والنباتات المائية عند اختلاف المنسوب.","https://www.unesco.org/en/mab/tonle-sap","تتصل بحيرة تونلي ساب بنهر ميكونغ عبر نهر يتغير اتجاه جريانه موسميًا مع الفيضانات.","يتغير اتساع المياه بدرجة كبيرة بين موسم الجفاف وموسم الأمطار."],["KH","Royal Palace of Phnom Penh","يعكس القصر الملكي في بنوم بنه استمرار تقاليد الحكم والعمارة الاحتفالية الخميرية، ويضم مباني دينية ومدنية.","تظهر الأسقف الذهبية المتدرجة والأجنحة المزخرفة والحدائق ومعبد الباغودا الفضية ضمن المجمع.","https://www.tourismcambodia.com/","انتقل مقر البلاط الملكي إلى بنوم بنه في القرن التاسع عشر، وتطورت مباني المجمع وتجدّدت لاحقًا مع تغير وظائف الحكم والاحتفال.","بعض المباني تخدم الوظائف الملكية، لذلك ليست كل أجنحة المجمع مفتوحة للزيارات."],["KH","Koh Ker Archaeological Site","كان كوه كير مركزًا ملكيًا خميريًا لفترة في القرن العاشر، وتُظهر أطلاله تخطيطًا مختلفًا عن المعالم الأشهر في أنغكور.","يبرز هرم براسات ثوم المتدرج والمباني الحجرية المنتشرة بين الأشجار والأدغال.","https://whc.unesco.org/en/list/1658","أصبحت كوه كير عاصمة للمملكة الخميرية لفترة قصيرة في القرن العاشر، وتركت هذه المرحلة معابد ومبانٍ لا تشبه جميعها المراكز اللاحقة في أنغكور.","الهرم المتدرج في الموقع يختلف بصريًا عن الأبراج المركزية المعروفة في أنغكور وات."],["NO","Geirangerfjord","نحتت الأنهار الجليدية مضيق غيرانغر العميق، وهو جزء من منظومة الفيوردات النرويجية المدرجة على قائمة التراث العالمي.","تظهر الجروف الشاهقة والشلالات المتساقطة من المرتفعات، مثل الأخوات السبع، والمزارع القديمة فوق المنحدرات.","https://whc.unesco.org/en/list/1195","نحتت الأنهار الجليدية الوادي الذي غمره البحر ليصبح غيرانغر أحد الفيوردات البارزة بغرب النرويج.","تظهر شلالات موسمية كثيرة من جوانب المضيق بحسب الأمطار وذوبان الثلوج."],["NO","Lofoten Islands","تتميز لوفوتن بالتقاء الجبال الشديدة الانحدار بالبحر، مع تراث طويل لصيد سمك القد وتجفيفه في قرى ساحلية.","يمكن مشاهدة الأكواخ الحمراء التقليدية والمرافئ الصغيرة والشواطئ البيضاء والقمم المرتفعة فوق المياه.","https://visitlofoten.com/en/the-history-of-lofoten/","حملت جزر لوفوتن مجتمعات تعتمد على الصيد منذ عصور ما قبل التاريخ، وتطورت فيها تجارة سمك القد المجفف خلال عصر الفايكنغ والقرون الوسطى. ساعد وصول أسراب سمك «سكراي» شتاءً إلى المياه المحيطة بالجزر على نشوء قرى صيد موسمية ومرافئ للتجارة، وأصبحت بلدة فوغار مركزًا مبكرًا لتجارة الأسماك. وظلت الأكواخ الخشبية التقليدية ومواقع التجفيف شاهدًا على هذا التاريخ الاقتصادي البحري.","الأكواخ الحمراء التقليدية كانت مرتبطة بأنشطة الصيد وإقامة الصيادين."],["NO","Arctic Cathedral","تُعد كاتدرائية القطب الشمالي علامة على العمارة الحديثة في ترومسو، ويستلهم تصميمها المدبب تضاريس الشمال وضوءه.","تظهر الألواح المثلثة البيضاء والواجهة الزجاجية الكبيرة والإطلالة عبر المياه إلى المدينة.","https://www.visittromso.no/","شُيّدت الكنيسة الحديثة بترومسو في ستينيات القرن العشرين ضمن اتجاه معماري يعكس بيئة الشمال.","شكلها الزاوي مختلف عن القباب والأبراج التقليدية لكثير من الكنائس التاريخية."],["NO","Preikestolen","تشكلت صخرة بريكستولين بفعل عمليات جيولوجية وتجلدية قديمة، وأصبحت إحدى أشهر نقاط مشاهدة فيورد ليسه.","تظهر المنصة الصخرية شبه المربعة وحافة الجرف العمودية فوق مياه المضيق الأزرق.","https://www.visitnorway.com/","نحت الجليد والصدوع شكل الجرف الذي تعلوه منصة بريكستولين المستوية فوق ليسهفيورد.","تتطلب الحافة الصخرية الحذَر لأن الموقع الطبيعي لا يشبه شرفة محاطة بحواجز."],["NO","Bryggen","يحفظ حي بريغن تاريخ تجارة الرابطة الهانزية في بيرغن، حيث ارتبطت المباني الخشبية بالمخازن والتجارة البحرية.","تظهر صفوف الواجهات الخشبية الملونة والأزقة الضيقة والممرات المتصلة بالميناء.","https://whc.unesco.org/en/list/59","كان بريغن جزءًا من شبكة تجارة الهانزا في شمال أوروبا وتعرضت مبانيه الخشبية للحرائق وإعادة البناء.","تنتقل الزيارة من الواجهات الملونة إلى ممرات خشبية ضيقة خلف الصف الأمامي."],["NO","Longyearbyen","تكشف لونغييربين عن طبيعة الاستيطان البشري في القطب الشمالي ودور التعدين والأبحاث في تاريخ سفالبارد الحديث.","تظهر المنازل الملونة على أرض قليلة الأشجار والجبال المحيطة والمشهد القطبي الموسمي.","https://en.visitsvalbard.com/","نشأت لونغييربين من نشاط تعدين الفحم في سفالبارد، ثم اتسع دورها للأبحاث والسياحة القطبية.","الضوء الطبيعي يتغير بشدة بين شمس منتصف الليل والليل القطبي الطويل."],["NO","Vigeland Sculpture Park","يعرض متنزه فيغلاند مجموعة مترابطة من أعمال النحات غوستاف فيغلاند تستكشف العلاقات والمشاعر ومراحل حياة الإنسان.","تظهر منحوتات الجرانيت والبرونز والجسر المزخرف والمسلة الحجرية المؤلفة من أشكال بشرية.","https://vigeland.museum.no/en","كرّس النحات غوستاف فيغلاند عشرات السنين لتكوين المجموعة النحتية داخل فروغنر.","النصب المركزي يتكون من أجساد بشرية متشابكة، لا عمود زخرفي مجرد."],["NO","Vøringsfossen","يوضح شلال فورينغسفوسن أثر الأنهار في نحت الأودية العميقة داخل مرتفعات هاردانغر النرويجية.","يظهر الماء منحدرًا من حافة صخرية عالية وسط واد أخضر، مع منصات وجسر مشاهدة حديث.","https://www.nasjonaleturistveger.no/en/routes/hardangervidda/voringsfossen/","يندفع شلال فورينغسفوسن من هضبة هاردانغيرفيدا نحو وادي موبودالن الذي نحتته المياه والجليد عبر مراحل جيولوجية طويلة. ويبلغ ارتفاع السقوط الكلي نحو 182 مترًا، وأضيفت على مر السنوات مسارات ومنصات وجسور مشاهدة تسمح برؤية الشلال والوادي من زوايا آمنة مختلفة، مع اختلاف شدة التدفق بحسب ظروف المياه.","تتبدل قوة الشلال بصريًا بحسب تدفق المياه خلال السنة."],["IS","Þingvellir National Park","يُعد ثينغفيلير ذا أهمية جيولوجية وسياسية تاريخية، إذ يقع في منطقة صدع تكتوني وارتبط بموقع اجتماع الألثينغي منذ القرن العاشر.","تظهر الجروف والشقوق الصخرية والوادي المتسع والبحيرة القريبة داخل المشهد البركاني.","https://whc.unesco.org/en/list/1152/","يقع ثينغفيلير داخل منطقة صدع جيولوجي تكشف حركة تباعد الصفائح في آيسلندا، لكن أهميته تتجاوز الطبيعة: تأسس فيه مجلس «ألثينغي» العام عام 930، وظل يجتمع في الهواء الطلق حتى عام 1798 لمناقشة القوانين وتسوية النزاعات. وما زالت آثار أماكن التجمع والمباني الترابية والحجرية شاهدة على دوره في نشأة المؤسسات السياسية الآيسلندية، وسط مشهد من الجروف والشقوق البركانية.","الحواف الصخرية تبين عملية تباعد جيولوجي لا مجرد شق محلي في الأرض."],["IS","Gullfoss","يبرز غولفوس قوة النهر الجليدي هفيتا، حيث يهبط الماء على درجتين إلى أخدود عميق.","تظهر ستارة الماء البيضاء والضباب المتصاعد والمنحدرات الصخرية، وقد تتشكل أقواس قزح في الشمس.","https://www.visiticeland.com/","نحت نهر هفيتا أخدود غولفوس بفعل جريان مياه الأنهار الجليدية عبر الصخور.","الماء يهبط على درجتين متتاليتين قبل اختفائه بين جدران الأخدود."],["IS","Geysir Geothermal Area","منحت منطقة غيسير اسمها الدولي لظاهرة الفوارات المائية، وتنتج ثوراتها عن تسخين المياه في الأعماق البركانية.","تظهر نافورات ستروكور المتقطعة والبرك الحارة والبخار المنبعث من الأرض.","https://www.visiticeland.com/","نشأت فوارات هاوكادالور نتيجة تسخين المياه تحت الأرض وارتفاع الضغط قبل اندفاعها.","الفوارة النشطة ستروكور تختلف عن غيسير الأصلي الذي يتفاوت نشاطه."],["IS","Skógafoss","يرتبط شلال سكوجافوس بالجروف التي كانت تطل على ساحل أقدم، قبل أن تتراجع مياه البحر وتتحول المنطقة البرية أمامه.","تظهر ستارة مياه عريضة تسقط من حافة مستقيمة فوق أرض خضراء، مع الضباب عند القاعدة.","https://www.visiticeland.com/","كان الجرف الذي يسقط منه الماء قريبًا من خط الساحل القديم، ثم أدى تغيّر الساحل وترسيب الرواسب إلى ابتعاد البحر عنه وبقاء الشلال على اليابسة.","قد ينتج عن رذاذ الشلال قوس قزح عندما تتوافر الشمس وزاوية الرؤية."],["IS","Reynisfjara Black Sand Beach","تتكون رمال رينيسفجارا السوداء من مواد بركانية متفتتة، وتظهر عنده أعمدة بازلتية تشكلت أثناء تبريد الحمم.","تبرز الأعمدة السداسية والمنحدرات الساحلية وأعمدة الصخور البحرية؛ أمواج الشاطئ المفاجئة خطرة جدًا.","https://safetravel.is/","تكونت الرمال السوداء من مواد بركانية، وتشكلت الأعمدة البازلتية حين بردت الحمم وتشققت.","أمواج الشاطئ المفاجئة قد تتقدم بعيدًا على اليابسة؛ الابتعاد عن الماء ضروري."],["IS","Jökulsárlón Glacier Lagoon","نشأت بحيرة يوكلسارلون من تراجع نهر بريداميركوريوكوتل الجليدي، وهي تكشف تغير موقع جبهة الجليد بمرور الزمن.","تطفو كتل الجليد الزرقاء والبيضاء في البحيرة وتتجه نحو البحر، وقد تتجمع قطع منها على الشاطئ القريب.","https://www.vatnajokulsthjodgardur.is/en","تكوّنت البحيرة في العصر الحديث بعد تراجع حافة الجليد عن موضعها القديم؛ وتوسعت مساحتها مع ابتعاد اللسان الجليدي عبر العقود.","الأشكال الجليدية متغيرة باستمرار، وقد تتقلب الكتل الجليدية أو تنكسر."],["IS","Kirkjufell","يميز كيركيوفيل شكله المدبب الناتج عن التعرية والتجلد، وأصبح من أشهر مشاهد شبه جزيرة سنفيلسنيس.","تظهر القمة منفردة قرب البحر، مع شلال كيركيوفيلسفوسن في مقدمة المشهد.","https://www.visiticeland.com/article/kirkjufell-mountain/","يتشكل جبل كيركيوفيل قرب غروندافيوردور في شبه جزيرة سنفيلسنيس من طبقات صخرية تعرّضت لعمليات تعرية وتجلد تركت له جوانب شديدة الانحدار وهيئة مستقلة بارزة. يبلغ ارتفاعه نحو 463 مترًا، واشتهر بصورته مع شلال كيركيوفيلسفوسن القريب. لا تعني قمته المنتظمة أنه مخروط بركاني نشط؛ بل يرتبط شكله بتاريخ نحت الصخور والجليد للمنطقة.","توازن منظر الجبل مع شلال كيركيوفيلسفوسن سبب شهرة زاوية تصوير معينة."],["IS","Lake Mývatn","تُظهر ميفاتن أثر النشاط البركاني في تشكيل البحيرات والفوهات الكاذبة والحقول الحممية، مع تنوع ملحوظ في الطيور المائية.","تظهر البحيرة والجزر والفوهات العشبية والحمم القديمة ومناطق البخار القريبة.","https://www.visiticeland.com/","تشكل حوض ميفاتن ضمن بيئة بركانية وتجاوره فوهات كاذبة وحقول حمم قديمة.","الفوهات الكاذبة تنتج عن تفاعل الحمم مع مياه أو رواسب رطبة، لا عن فوهات بركانية عميقة."],["NP","Sagarmatha National Park","يحمي منتزه ساغارماثا جزءًا من أعلى جبال الهيمالايا، وتعيش فيه مجتمعات الشيربا إلى جانب نظم بيئية مرتفعة وهشة.","تظهر قمة إيفرست والقمم المجاورة والأنهار الجليدية والقرى والأديرة الواقعة على المسارات الجبلية.","https://whc.unesco.org/en/list/120","يرتبط اسم ساغارماثا بجبل إيفرست ويضم المنتزه قرى ومسارات تراثية لمجتمعات الشيربا.","المناظر الجليدية الشاهقة تتعايش مع أديرة ومستوطنات بشرية في الأودية."],["NP","Kathmandu Durbar Square","تكشف ساحة دوربار في كاتماندو عن العمارة الملكية والدينية النيوارية في وادي كاتماندو، وتأثرت بعض منشآتها بالزلازل.","تظهر المعابد متعددة الأسقف والقصور الخشبية المنحوتة والأفنية والمباني التاريخية.","https://whc.unesco.org/en/list/121","كانت ساحة كاتماندو دوربار موقعًا ملكيًا وثقافيًا مهمًا، وتعرضت مبانٍ تاريخية فيها لأضرار من زلازل.","تُظهر النوافذ والأعمدة الخشبية المنحوتة دقة الحرف التقليدية النيوارية التي ما زالت أعمال الترميم تحاول المحافظة عليها."],["NP","Phewa Lake","تربط بحيرة فيوا بين طبيعة وادي بوخارا ومشهد جبال أنابورنا، وهي مركز بصري مهم للمدينة.","تظهر القوارب الملونة ومعبد تال باراهي على الجزيرة وانعكاسات القمم الجبلية في الأيام الصافية.","https://ntb.gov.np/","تكوّنت بحيرة فيوا داخل وادي بوخارا، وأصبحت جزءًا من العلاقة بين المدينة والبيئة الجبلية المحيطة.","قد تظهر قمم أنابورنا منعكسة على الماء في الصباحات الصافية."],["NP","Lumbini","ترتبط لومبيني وفق التقليد البوذي بميلاد سيدهارتا غوتاما، وأصبحت من أهم مواقع الحج والدراسة البوذية.","تظهر منطقة معبد مايا ديفي والآثار الحجرية وعمود أشوكا والحدائق الهادئة.","https://whc.unesco.org/en/list/666","ترتبط لومبيني بتقليد ميلاد بوذا وأقيمت بها منشآت دينية عبر فترات مختلفة.","تضم المنطقة أثرًا مرتبطًا بالملك أشوكا إلى جانب حدائق وأديرة حديثة."],["NP","Bhaktapur Durbar Square","تمثل ساحة بهاكتابور جزءًا من تراث وادي كاتماندو، وتشتهر بمهارة الحرفيين النيواريين في الخشب والطوب والحجر.","تظهر بوابات القصر المزخرفة والمعابد متعددة الطبقات والساحات المرصوفة والواجهات التقليدية.","https://whc.unesco.org/en/list/121","كانت بهاكتابور إحدى المدن الملكية بوادي كاتماندو واشتهرت بصناعات الخزف والنحت.","يمكن ملاحظة التدرج بين الساحات العامة والبوابات والمباني الدينية."],["NP","Boudhanath Stupa","تُعد بودهاناث مركزًا مهمًا للبوذية التبتية في نيبال، حيث تدور الطقوس والممارسات التعبدية حول الستوبا الكبيرة.","تظهر القبة البيضاء والبرج الذهبي والعيون المرسومة وأعلام الصلاة الملونة حول الموقع.","https://whc.unesco.org/en/list/121","تطورت بودهاناث محطةً للزيارة والعبادة، وازداد حضور المجتمعات البوذية التبتية المحيطة بها في العصر الحديث مع انتقال أعداد من التبتيين إلى نيبال.","تدور حركة الزوار التعبدية حول الستوبا في اتجاه محدد وفق التقليد المحلي."],["NP","Annapurna Conservation Area","تغطي محمية أنابورنا نطاقات بيئية واسعة من الغابات إلى البيئات الجبلية العالية، وتضم قرى ذات ثقافات محلية متنوعة.","تظهر القمم الثلجية والمدرجات الزراعية والممرات والوديان والغابات المتغيرة مع الارتفاع.","https://ntb.gov.np/","تخترق أنابورنا نطاقات ارتفاع شديدة الاختلاف وتضم مجتمعات زراعية وجبلية متعددة.","الانتقال عبر الارتفاعات يغيّر الغطاء النباتي من حقول وقرى إلى مناطق جليدية."],["NP","Chitwan National Park","يحافظ تشيتوان على بيئات غابية وعشبية ونهرية في تيراي، ويوفر ملاذًا مهمًا لوحيد القرن الهندي وحيوانات أخرى.","تظهر المروج والأنهار وغابات السال وآثار الحياة البرية، مع فرص لمشاهدة وحيد القرن من مسافة آمنة.","https://whc.unesco.org/en/list/284","تحولت أراضي تشيتوان إلى منطقة للحماية بعد تراجع أعداد بعض الحيوانات بسبب الصيد وفقد الموائل، وصارت برامج الحفظ جزءًا أساسيًا من إدارة المنتزه.","تغيّر الفيضانات الموسمية شكل ضفاف الأنهار والمراعي داخل المنتزه."],["LK","Sigiriya","تظهر سيجيريا تخطيطًا ملكيًا متقدمًا من القرن الخامس الميلادي يجمع الحصن والحدائق والمنشآت المائية فوق صخرة عملاقة.","تظهر البقايا المعمارية أعلى الصخرة والحدائق المتناظرة واللوحات الجدارية وآثار بوابة الأسد.","https://whc.unesco.org/en/list/202","بُني مجمع سيجيريا الملكي حول صخرة ضخمة في القرن الخامس، مع شبكة حدائق ومياه مدهشة لعصره.","بقايا أقدام الأسد عند المدخل الأعلى تفسر تسمية «صخرة الأسد»."],["LK","Temple of the Tooth","يمثل معبد السن في كاندي موقعًا ذا قدسية كبيرة للبوذيين السريلانكيين، ويرتبط بتاريخ الممالك المحلية والطقوس الدينية.","تظهر الأسقف والزخارف الخشبية والردهات والبحيرة المجاورة ومظاهر العمارة الكاندية.","https://whc.unesco.org/en/list/450","ارتبط معبد السن بعقيدة حفظ ذخيرة سن بوذا، وبموقع كاندي السياسي والديني التاريخي.","الحرم الداخلي ذو قدسية خاصة وقد يخضع الدخول لأجزاء منه لقواعد دينية."],["LK","Galle Fort","يكشف حصن غالي عن التجارة البحرية في المحيط الهندي وآثار التحصينات الأوروبية، خصوصًا الهولندية، على عمران الساحل السريلانكي.","تظهر الأسوار المطلة على البحر والمنارة والشوارع الهادئة والمنازل ذات الأفنية الداخلية.","https://whc.unesco.org/en/list/451","تحولت غالي إلى ميناء محصن وتطور عمرانها مع فترات الاستعمار البرتغالي ثم الهولندي.","الأسوار البحرية تضم مسارات للمشي تطل على مبانٍ لا تزال مأهولة."],["LK","Sacred City of Anuradhapura","كانت أنورادابورا عاصمة ومركزًا دينيًا بارزًا في سريلانكا القديمة، وتضم آثارًا بوذية ومشاريع قديمة لإدارة المياه.","تظهر الستوبات الضخمة وبقايا الأديرة والأحواض المائية والأشجار المقدسة المرتبطة بالتقاليد الدينية.","https://whc.unesco.org/en/list/200","كانت أنورادابورا عاصمة قديمة لقرون وارتبطت بأعمال الري والسدود وتاريخ البوذية السريلانكية.","الستوبات الضخمة تُقرأ ضمن شبكة آثار ومدن ومرافق مائية قديمة، لا مبنى واحد."],["LK","Dambulla Cave Temple","يضم معبد دامبولا مجموعة من الكهوف المزينة برسوم وتماثيل دينية، تعكس استمرارية الفن البوذي عبر قرون.","تظهر تماثيل بوذا المتعددة والجداريات ذات الألوان الزاهية والأسقف الصخرية المنخفضة داخل الكهوف.","https://whc.unesco.org/en/list/561","استُخدمت كهوف دامبولا مركزًا للعبادة البوذية منذ أكثر من ألفي عام، وتراكمت داخلها أعمال الرسم والنحت على مراحل تاريخية متعددة. تحوّلت التجاويف الصخرية إلى خمسة معابد كهفية مترابطة، تضم صورًا دينية وتماثيل وتشهد على استمرارية الرعاية الملكية والدينية للموقع.","بحسب اليونسكو يضم مجمع دامبولا 157 تمثالًا، وتغطي جدارياته البوذية نحو 2100 متر مربع. هذه الأرقام تخص مجموعة المعابد الكهفية التاريخية، وهي توضح كثافة الفن داخل الصخور مقارنة بالمظهر الخارجي البسيط نسبيًا للجبل."],["LK","Nuwara Eliya Tea Country","تُظهر مرتفعات نوارا إليا علاقة المناخ الأبرد نسبيًا والتضاريس المرتفعة بزراعة الشاي التي ازدهرت خلال الحقبة الاستعمارية.","تظهر صفوف شجيرات الشاي على المنحدرات والضباب والتلال الخضراء ومباني مزارع الشاي.","https://www.srilanka.travel/","أدخلت الإدارة الاستعمارية البريطانية زراعة الشاي التجاري إلى المرتفعات بعد تجارب المحاصيل السابقة، وتوسعت المزارع مع تطور النقل والسكك الحديدية.","شكل صفوف الشاي المتكررة على السفوح ناتج عن الزراعة البشرية لا غطاء طبيعي."],["LK","Nine Arch Bridge","يُعد جسر الأقواس التسعة مثالًا على هندسة السكك الحديدية التاريخية في مرتفعات سريلانكا، حيث تتبع الخطوط تضاريس شديدة الانحدار.","تظهر الأقواس الحجرية التسعة وسط النباتات الاستوائية ومزارع الشاي، مع مرور القطار عبر الوادي.","https://www.srilanka.travel/","شُيّد جسر الأقواس التسعة ضمن شبكة القطارات الجبلية بسريلانكا في الفترة الاستعمارية.","يعبر القطار مسارًا منحنيًا فوق تسع فتحات واسعة بين النباتات الكثيفة."],["LK","Yala National Park","تجمع يالا بين الغابات الجافة والسهول والمسطحات المائية الساحلية، وتشتهر بتنوعها الحيواني وخاصة الفهود.","تظهر الأراضي العشبية والبحيرات الصغيرة والفيلة والطيور، وقد تُشاهد الفهود دون ضمان أو اقتراب منها.","https://www.dwc.gov.lk/","تضم يالا مناطق جافة ومسطحات ساحلية وآثارًا تاريخية، وأصبحت محمية لحياة برية متنوعة.","رؤية الفهود تعتمد على حركتها الطبيعية ولا ينبغي التعامل معها كعرض مضمون."],["KE","Maasai Mara National Reserve","تُعد ماساي مارا امتدادًا لنظام سيرينغيتي البيئي، وتشتهر بتتبع حركة قطعان النو والأحياء البرية وتقاليد شعب الماساي في المنطقة.","تظهر سهول السافانا وقطعان الحيوانات والأسود والزرافات ونقاط عبور نهر مارا خلال مواسم الهجرة.","https://www.magicalkenya.com/","تُعد ماساي مارا جزءًا من منظومة سيرينغيتي البيئية، وتتغير حركة الحيوانات فيها وفق الأمطار والمراعي.","الهجرة الكبرى ليست حدثًا في موعد يومي ثابت، بل سلسلة تحركات موسمية طويلة."],["KE","Amboseli National Park","يمثل أمبوسيلي نموذجًا للتعايش بين السهول شبه الجافة والمستنقعات المغذاة بالمياه الجوفية، وهو موقع مهم لدراسة الأفيال.","يمكن رؤية قطعان الأفيال والسهول المفتوحة والبحيرات الموسمية مع قمة كليمنجارو في الأفق.","https://www.kws.go.ke/","تعمل المياه الجوفية على تغذية بعض مستنقعات أمبوسيلي وسط بيئة شبه جافة، ما يجذب الأفيال والحيوانات.","قد تختفي قمة كليمنجارو وراء السحب رغم وضوحها في صور المنتزه الشهيرة."],["KE","Mount Kenya National Park","يحمي جبل كينيا بيئات مرتفعة ومواقع جليدية متراجعة ويُظهر آثار النشاط البركاني والتجلد قرب خط الاستواء.","تظهر القمم الصخرية الحادة والأودية الجليدية والغابات الجبلية والنباتات المتكيفة مع الارتفاع.","https://whc.unesco.org/en/list/800","جبل كينيا بركان قديم تآكلت أجزاء من قممه وتشكلت فوقه أودية جليدية.","يمكن العثور على نباتات جبلية متكيفة مع البرد قرب خط الاستواء."],["KE","Lamu Old Town","تحفظ لامو تراث المدن السواحلية التي ازدهرت من التجارة البحرية على المحيط الهندي، مع تأثيرات أفريقية وعربية وهندية.","تظهر المنازل المبنية من الحجر المرجاني والأبواب الخشبية المنحوتة والأزقة والمرافئ التقليدية.","https://whc.unesco.org/en/list/1055","ازدهرت لامو مركزًا لتجارة المحيط الهندي، وأنتج الحرفيون فيها أبوابًا وأفنية ومنازل من الحجر المرجاني تعكس أسلوب العمران السواحلي.","تشكّل الأبواب الخشبية المحفورة جزءًا من الهوية العمرانية المحلية."],["KE","Lake Nakuru National Park","تشتهر منطقة بحيرة ناكورو بتقلبات منسوب المياه والملوحة والحياة البرية، وتختلف أعداد طيور الفلامنغو وفق الظروف البيئية.","تظهر البحيرة والطيور المائية والغابات المحيطة، ويمكن مشاهدة الزرافات ووحيد القرن في مناطق المتنزه.","https://www.kws.go.ke/","تأسست حماية المنطقة لدعم الطيور والحياة البرية، ثم اتسعت وظائف المنتزه لتشمل الحفاظ على الثدييات وإدارة تغيّرات منسوب البحيرة.","الفلامنغو ليس حاضرًا بالأعداد نفسها طوال الوقت؛ يتنقل بين بحيرات الأخدود."],["KE","Nairobi National Park","يُبرز منتزه نيروبي التنوع الحيوي عند أطراف إحدى أكبر مدن شرق أفريقيا، ويعكس تحديات حماية الحياة البرية قرب التوسع العمراني.","تظهر السهول وحيوانات السافانا مع ناطحات سحاب نيروبي في الأفق، وهو مشهد غير مألوف للمنتزهات.","https://www.kws.go.ke/","خصصت المنطقة المحمية قرب نيروبي للحياة البرية مع اتساع المدينة حولها في القرن العشرين.","قد تظهر الزرافات والأسود والحمر الوحشية أمام أفق حضري بعيد."],["KE","Karuru Falls","تقع شلالات كارورو في نطاق المرتفعات الرطبة بمنتزه أبيردار، وتوضح دور الأمطار والتضاريس في تكوين المساقط المائية.","تظهر المياه على درجات بين الجروف المشجرة والضباب فوق الوادي العميق.","https://www.kws.go.ke/","تتساقط مياه كارورو عبر تضاريس أبيردار البركانية المشجرة، في بيئة تختلف عن سهول السافانا.","تزيد الأمطار حجم المياه المتساقطة وتغير وضوح الشلال بسبب الضباب."],["KE","Watamu Marine National Park","تدعم مياه واتامو الساحلية نظمًا بيئية من الشعاب المرجانية والأسماك والأعشاب البحرية، وتحتاج الشعاب إلى حماية من الضرر البشري والحراري.","تظهر المياه الضحلة الصافية والشعاب والكائنات البحرية قرب الشواطئ الرملية.","https://www.kws.go.ke/","طُبقت الحماية البحرية على مناطق الشعاب والشواطئ لتقليل الضغط على الموائل الحساسة، بما فيها الأعشاب البحرية التي تعيش فيها كائنات متعددة.","الشعاب المرجانية كائنات حية تتضرر باللمس والرسو غير المنظم."],["TZ","Serengeti National Park","يُعد سيرينغيتي واحدًا من أهم نظم السافانا البيئية في العالم، حيث تتحرك قطعان ضخمة وفق الأمطار وتوفر المراعي.","تظهر السهول الواسعة وقطعان النو والحمر الوحشية والأسود وأشجار الأكاسيا المنعزلة.","https://whc.unesco.org/en/list/156","تحافظ سهول سيرينغيتي على نظام بيئي واسع تتعاقب فيه الأمطار والمواسم الجافة، فتتحرك قطعان النو والحمر الوحشية والغزلان بحثًا عن العشب والماء، وتتبعها الحيوانات المفترسة. ترتبط الحركة السنوية بمناطق تقع داخل تنزانيا وخارج حدود المنتزه وصولًا إلى ماساي مارا في كينيا، ولذلك لا يمكن اختزال دورة الهجرة في موقع واحد.","الهجرة ليست موكبًا يسير في موعد ثابت يومًا محددًا، بل حركة مستمرة تتبدل مع الأمطار والمراعي. ويشير وصف اليونسكو إلى أن النظام الطبيعي يتجاوز حدود المنتزه، وأن بقاء الممرات البيئية متصلة أساسي لاستمرار هذه الظاهرة."],["TZ","Mount Kilimanjaro","يمثل كليمنجارو أعلى جبل في أفريقيا، ويجمع بين أحزمة نباتية من الغابات إلى نطاقات شبه قطبية قرب القمة البركانية.","تظهر القمة المرتفعة والثلوج المتبقية والمنحدرات الواسعة، مع اختلاف الغطاء النباتي كلما ارتفع المسار.","https://whc.unesco.org/en/list/403","كليمنجارو مجموعة بركانية ضخمة، وأعلى قمتها كيبو، وتختلف البيئات الطبيعية بين سفحه وقممه.","الثلوج والجليد المرتفعان موجودان قرب خط الاستواء لكن مساحتهما تتراجع."],["TZ","Ngorongoro Crater","تُعد فوهة نغورونغورو جزءًا من منظومة بركانية قديمة، وتوفر مساحة شبه مغلقة نسبيًا لمواطن متنوعة من الحيوانات العاشبة والمفترسة.","تظهر الحافة الدائرية المرتفعة والسهول الداخلية والبحيرات الموسمية وقطعان الحياة البرية.","https://whc.unesco.org/en/list/39","تشكلت نغورونغورو بعد انهيار بنية بركانية قديمة، وأصبح داخل الفوهة موائل متنوعة.","الفوهة ليست بحيرة واحدة؛ تضم أراضي عشبية ومستنقعات ومسطحات مائية موسمية."],["TZ","Stone Town of Zanzibar","يعكس حي ستون تاون تاريخ زنجبار مركزًا للتجارة البحرية عبر المحيط الهندي، بما في ذلك تجارة التوابل والتاريخ المؤلم لتجارة الرقيق.","تظهر الأبواب الخشبية المزخرفة والشرفات والممرات الضيقة والواجهات المرجانية قرب الميناء.","https://whc.unesco.org/en/list/173","تطورت ستون تاون بفعل تجارة المحيط الهندي، وشهدت أدوارًا عربية وأفريقية وهندية وأوروبية.","الأبواب المنحوتة والشرفات تعكس مزيج تقاليد الحرف والعمارة في زنجبار."],["TZ","Lake Manyara National Park","يجمع منتزه مانيارا بين جرف الأخدود الأفريقي والبحيرة والغابات والسهول، ما يتيح تنوعًا بيئيًا في مساحة متقاربة.","تظهر الأشجار الكثيفة قرب المنحدرات والبحيرة والطيور المائية والفيلة في المناطق المفتوحة.","https://www.tanzaniaparks.go.tz/lake-manyara/about","تكوّن مشهد بحيرة مانيارا عند قاعدة الجرف الشرقي للأخدود الأفريقي العظيم، حيث تتجاور بحيرة قلوية ضحلة مع غابات تغذيها المياه الجوفية ومناطق أكثر جفافًا. أُعلنت المنطقة منتزهًا وطنيًا سنة 1960 بعد أن كانت محمية للصيد، وأصبحت ضمن شبكة محميات المحيط الحيوي سنة 1981. وساعد هذا التنوع البيئي على حماية الطيور المائية والفيلة وغيرها من الحيوانات، مع تغير ظروف البحيرة موسميًا.","حجم البحيرة يختلف حسب المواسم، ما يغير توزيع الطيور والحيوانات."],["TZ","Nyerere National Park","يحمي منتزه نيريري جزءًا كبيرًا من منظومة سيلوس البرية، ويتميز بوجود نهر روفيجي الذي يخلق بيئات مائية داخل السافانا.","تظهر الأنهار والبحيرات والسهول والأفيال وأفراس النهر والطيور المائية.","https://www.tanzaniaparks.go.tz/","أصبح نيريري متنزهًا وطنيًا في مساحة من نظام سيلوس الأوسع، حيث يشكل روفيجي عمودًا بيئيًا رئيسيًا.","تجذب المجاري المائية أفراس النهر والتماسيح وطيورًا مائية كثيرة."],["TZ","Pemba Island","تشتهر بيمبا بتضاريسها الخضراء ومزارع القرنفل وموائل الشعاب المرجانية، وهي أقل تحضرًا من جزيرة أنغوجا الرئيسية.","تظهر التلال ومزارع التوابل والخلجان الساحلية والمياه الزرقاء قرب الشعاب.","https://www.tanzaniatourism.go.tz/","ساعدت الأمطار والمناخ الاستوائي في بيمبا على زراعة القرنفل ونشوء غطاء نباتي كثيف.","بعض الخلجان الساحلية محاطة بمنحدرات خضراء بدل الشواطئ الرملية المفتوحة."],["TZ","Tarangire National Park","يتميز تارانغيري بأشجار الباوباب وأهمية نهر تارانغيري مصدرًا للمياه للحيوانات خلال مواسم الجفاف.","تظهر أشجار الباوباب ضخمة الجذوع وقطعان الأفيال والسهول النهرية.","https://www.tanzaniaparks.go.tz/","يدعم نهر تارانغيري تجمع الحيوانات خلال مواسم الجفاف في السهول المحيطة.","أشجار الباوباب تخزن المياه في جذوعها الضخمة وتتميز بأشكالها الفريدة."],["CL","Torres del Paine National Park","يعرض المنتزه تاريخ النحت الجليدي في جبال باتاغونيا، وتتجاور فيه القمم الجرانيتية والبحيرات والسهول العشبية.","تظهر أبراج باينه الثلاثة وبحيرات زرقاء وأنهار جليدية وأودية تجتاحها الرياح.","https://www.conaf.cl/","شكّلت الأنهار الجليدية الوديان والبحيرات تحت قمم باينه الجرانيتية في باتاغونيا.","تتغير ظروف المشي والرياح بسرعة حتى عندما تكون السماء صافية صباحًا."],["CL","Valle de la Luna","يرتبط وادي القمر بالبيئة شديدة الجفاف في صحراء أتاكاما، حيث شكلت التعرية والتراكمات الملحية مشاهد صخرية غير مألوفة.","تظهر الكثبان والتكوينات الصخرية الملحية والمرتفعات المتدرجة التي تتغير ألوانها مع ضوء الغروب.","https://chile.travel/","تُعد صحراء أتاكاما من أشد مناطق العالم جفافًا؛ وفي هذا الوادي تتابعت عمليات ترسيب الأملاح وتجفيفها ثم نحت الصخور، فتكونت تضاريس تشبه الكهوف والتموجات.","الأرض تبدو شبيهة بسطح كوكب آخر لكن ألوانها نتيجة معادن وتضاريس طبيعية."],["CL","Rapa Nui National Park","يحفظ رابا نوي تراث مجتمع بولينيزي نحت تماثيل مواي الضخمة، ويعكس تاريخ الجزيرة المعقد وتحديات الحفاظ على آثارها.","تظهر صفوف المواي الحجرية والمنصات الاحتفالية والمحاجر البركانية وسط المشهد المحيطي المفتوح.","https://whc.unesco.org/en/list/715","شُيدت تماثيل مواي بواسطة مجتمعات رابا نوي، وترتبط بمنصات طقسية وتاريخ الجزيرة.","التماثيل ليست رؤوسًا فقط؛ لبعضها جذوع وأجزاء جسم مدفونة أو غير ظاهرة."],["CL","Historic Quarter of Valparaíso","توضح فالبارايسو تطور مدينة ميناء على منحدرات شديدة، واستخدام مصاعد تاريخية لربط الأحياء المرتفعة بالساحل.","تظهر الواجهات الملونة والأدراج والمصاعد القديمة والمباني التجارية المطلة على الميناء.","https://whc.unesco.org/en/list/959","ازدهرت فالبارايسو ميناءً تاريخيًا مهمًا وتطورت على تلال جعلت النقل العمودي ضرورة.","المصاعد الجبلية القديمة جزء من هوية المدينة وليست مجرد وسيلة سياحية حديثة."],["CL","Chiloé Island","تعكس تشيلوي امتزاج تراث السكان الأصليين والحرف الخشبية مع التأثيرات الدينية الأوروبية، خاصة في الكنائس الخشبية التاريخية.","تظهر الكنائس الخشبية الملونة والمنازل القائمة على ركائز وبعض الموانئ الصغيرة وسط التلال الخضراء.","https://whc.unesco.org/en/list/971","تتميز تشيلوي بتقاليد صناعة الخشب وبناء الكنائس التي تجمع خبرات محلية وأوروبية.","عدد من الكنائس مبني من الخشب دون الاعتماد على الواجهات الحجرية المعتادة في مدن أخرى."],["CL","Salto del Laja","تُبرز شلالات سالتو ديل لاخا تغير انحدار نهر لاخا وتكوّن عدة مساقط مائية ضمن منطقة يسهل الوصول إليها.","تظهر تيارات الماء المتعددة المنحدرة على حواف صخرية مع نباتات وأشجار قريبة.","https://www.subturismo.gob.cl/wp-content/uploads/2021/06/ficha-de-plan-de-accion.pdf","تتكون شلالات لاخا في منطقة بيوبيو التشيلية من أربعة مساقط مائية مستقلة على امتداد مجرى النهر. نشأت بفعل اختلاف ارتفاع الحواف الصخرية ومسار المياه، وأصبحت نقطة جذب طبيعية قرب الطريق الرئيسي في المنطقة، مع تباين واضح في قوة تدفق المياه بين الفصول.","وفق وثيقة حكومية تشيلية، يبلغ ارتفاع المسقط الرئيسي نحو 35 مترًا، والثاني والثالث نحو 25 مترًا لكل منهما، والرابع نحو 20 مترًا. لذا لا يصح اختزال «سالتوس ديل لاخا» في شلال منفرد أو اعتماد رقم ارتفاع واحد لكل المساقط."],["CL","Chajnantor Plateau","اختيرت هضبة تشاخنانتور لمراصد فلكية عالمية بسبب ارتفاعها الكبير وجفاف الهواء، ما يساعد على رصد موجات قادمة من الفضاء.","تظهر صفوف هوائيات مرصد ألما فوق الهضبة القاحلة والجبال الجافة المحيطة بها.","https://www.almaobservatory.org/en/","اختيرت مرتفعات تشاخنانتور للرصد الفلكي بفضل جفاف الهواء وارتفاعها الشديد.","مصفوفة ألما ترصد أطوالًا موجية لا تراها العين البشرية في الضوء المرئي."],["CL","General Carrera Lake","تشتهر بحيرة جنرال كاريرا بلون مياهها الأزرق وكهوف رخامية حفرتها الأمواج في الصخور على مدى فترات طويلة.","تظهر تجاويف الرخام المخططة وأقواسها فوق الماء الأزرق والجبال الباتاغونية البعيدة.","https://chile.travel/","تجاور بحيرة جنرال كاريرا الحدود الأرجنتينية ويتشكل على ضفافها مشهد رخامي منحوت بالأمواج.","الأقواس الرخامية تبدو زرقاء أحيانًا نتيجة انعكاس لون الماء والضوء."],["CO","Walled City of Cartagena","كانت قرطاجنة ميناءً استعماريًا مهمًا على البحر الكاريبي، وقد أقيمت تحصينات واسعة لحمايتها في فترات الصراع البحري.","تظهر الأسوار والحصون والساحات والشرفات الخشبية والبيوت الملونة بين الأزقة.","https://whc.unesco.org/en/list/285","أدت الهجمات البحرية على ميناء قرطاجنة إلى بناء منظومة دفاعية تزايدت على مراحل، شملت أسوار المدينة وحصونًا ومواقع مراقبة.","تجاور الأسوار القديمة بيوتًا ذات شرفات خشبية ملونة وساحات عامة."],["CO","Cocora Valley","يُعد وادي كوكورا من أبرز مواطن نخيل الشمع الكولومبي، وهو شجر وطني ينمو في بيئات جبلية مرتفعة.","تظهر أشجار النخيل الطويلة الرفيعة وسط المراعي الخضراء والغابات الضبابية.","https://colombia.travel/en","تحمي جبال كوكورا بيئة نخيل الشمع الكولومبي الذي يعد من أطول أنواع النخيل.","يمنح الضباب المتكرر الأشجار الرفيعة مظهرًا مختلفًا عن واحات النخيل الصحراوية."],["CO","Ciudad Perdida","تُظهر المدينة المفقودة تراث مجتمع تايرونا قبل الاستعمار الأوروبي، حيث رُبطت المصاطب الحجرية بمسارات وسلالم في الغابة الجبلية.","تظهر المدرجات الدائرية والسلالم الحجرية داخل الغطاء النباتي الكثيف.","https://colombia.travel/en","طوّر شعب تايرونا مدرجات وممرات حجرية في سلسلة سييرا نيفادا قبل وصول الأوروبيين.","الوصول إلى الأطلال يمر عبر غابة جبلية، والموقع ليس مدينة شوارع مستقيمة."],["CO","Tayrona National Natural Park","يجمع تايرونا بين غابات سفوح سييرا نيفادا والبحر الكاريبي، وله صلة ثقافية بمجتمعات السكان الأصليين في المنطقة.","تظهر الشواطئ الرملية والخلجان الصخرية والغابات الاستوائية المطلة على البحر.","https://www.parquesnacionales.gov.co/","تصل الغابات الجبلية في تايرونا بشواطئ البحر الكاريبي، ويحتفظ المكان بمعنى ثقافي لدى مجتمعات أصلية.","بعض الشواطئ قد تكون خطرة للسباحة بسبب التيارات، رغم المياه الصافية."],["CO","Gold Museum Bogotá","يساعد متحف الذهب على فهم فنون المعادن والرموز والطقوس لدى مجتمعات كولومبيا قبل الاستعمار، بعيدًا عن النظر إلى الذهب باعتباره ثروة فقط.","تظهر الحلي والتماثيل والأوعية الذهبية المصنوعة بتقنيات معقدة داخل قاعات العرض.","https://www.banrepcultural.org/bogota/museo-del-oro","يوثق متحف الذهب تقنيات صناعة المعادن لدى ثقافات كولومبية قديمة قبل الاحتلال الأوروبي.","القطع تحمل دلالات شعائرية واجتماعية، ولا تقتصر قيمتها على وزن الذهب."],["CO","El Peñón de Guatapé","تبرز صخرة غواتابيه كتكوين جرانيت ضخم منفرد نسبيًا فوق المشهد المائي المتفرع، وقد أصبحت علامة بصرية بارزة في أنتيوكيا.","تظهر واجهة الصخرة الحادة والسلالم الصاعدة إلى القمة مع مناظر الجزر والخزانات المحيطة.","https://colombia.travel/en","تُعد صخرة غواتابيه كتلة صخرية بارزة فوق منطقة تغير منظرها بعد إنشاء خزان مائي.","تبدو الجزر الصغيرة حولها مختلفة في شكلها حسب مستوى مياه الخزان."],["CO","Chicamocha National Park","يكشف أخدود تشيكاموتشا عن تضاريس مرتفعات الأنديز التي نحتتها الأنهار، وتبرز المنطقة من نقاط المشاهدة العالية.","تظهر طبقات الجبال والوديان الجافة والمنعطفات العميقة ومشهد الأخدود الممتد.","https://colombia.travel/en","كشف نحت نهر تشيكاموتشا عبر الزمن أخدودًا كبيرًا ضمن جبال الأنديز الشرقية.","المنحدرات الجافة نسبيًا تختلف عن الغابات الرطبة المرتبطة بصور كولومبيا الشائعة."],["CO","Los Nevados National Natural Park","يحمي لوس نيفادوس بيئات بارامو الأنديزية والقمم البركانية، وهي نظم مرتفعة مهمة لمصادر المياه والتنوع البيولوجي.","تظهر القمم والبحيرات الجبلية ونباتات الفرايليخون والأراضي المرتفعة الرطبة.","https://www.parquesnacionales.gov.co/","يحمي لوس نيفادوس نظم بارامو المرتفعة التي تساهم في تنظيم المياه وتغذية الأحواض النهرية.","نباتات الفرايليخون ذات الأوراق الوبرية متكيفة مع البرد والإشعاع المرتفع."],["SG","Marina Bay Sands","يمثل المجمع أحد أبرز رموز العمارة الحضرية الحديثة في سنغافورة، ويجمع أبراجه الثلاثة بمنصة علوية طويلة.","تظهر الأبراج المتجاورة والمنصة الأفقية والواجهة البحرية وأفق المدينة من حولها.","https://www.marinabaysands.com/","أُنجز مشروع مارينا باي ساندز ضمن تطوير الواجهة البحرية الحديثة لتحويل المنطقة إلى مركز حضري وترفيهي.","المنصة العلوية الممتدة تربط الأبراج الثلاثة وتخلق هيئة تشبه السفينة من بعض الزوايا."],["SG","Gardens by the Bay","تُبرز حدائق الخليج اهتمام سنغافورة بالتخضير الحضري وتصميم الحدائق داخل مدينة شديدة الكثافة.","تظهر الأشجار العملاقة الاصطناعية والبيوت الزجاجية والنباتات المتنوعة حول الممرات.","https://www.gardensbythebay.com.sg/","نشأت حدائق الخليج كجزء من توجه سنغافورة لإدخال المساحات الخضراء إلى العمران الكثيف.","الأشجار العملاقة تجمع عناصر هندسية وإنارة وحدائق عمودية في تصميم واحد."],["SG","Sentosa Island","تُظهر سنتوسا تحول جزيرة ذات تاريخ دفاعي إلى وجهة ساحلية وترفيهية معاصرة.","تظهر الشواطئ والممرات والأجزاء المتبقية من التحصينات التاريخية والمناظر المطلة على المضيق.","https://www.sentosa.com.sg/","استُخدمت سنتوسا في أدوار دفاعية وعسكرية قبل تحول أجزاء كبيرة منها إلى وجهة ترفيهية.","يمكن مشاهدة مواقع تاريخية إلى جانب المرافق الحديثة والشواطئ."],["SG","Singapore Chinatown","يعكس الحي الصيني تاريخ الجاليات التجارية الصينية داخل سنغافورة وتجاور التقاليد الدينية والمعمارية.","تظهر البيوت التجارية الملونة والأسواق والمعابد والشوارع التراثية المحفوظة.","https://www.visitsingapore.com/","تطور الحي الصيني حول نشاط التجار والجاليات الصينية في سنغافورة خلال القرن التاسع عشر.","المعابد والمحلات التجارية القديمة تكشف تنوعًا ثقافيًا داخل شوارع متقاربة."],["SG","Singapore Botanic Gardens","تُعد الحدائق النباتية شاهدًا على تاريخ علم النبات الاستوائي وزراعة المطاط في جنوب شرق آسيا.","تظهر الأشجار الاستوائية القديمة وبحيرات الحدائق ومجموعات الأوركيد الملونة.","https://whc.unesco.org/en/list/1483","تأسست الحدائق النباتية في القرن التاسع عشر ولعبت دورًا في دراسة النباتات الاستوائية وصناعة المطاط.","حديقة الأوركيد جزء بارز من الموقع، لكن أهميته العلمية تتجاوز عروض الزهور."],["SG","Merlion Park","أصبح تمثال ميرليون رمزًا بصريًا لهوية سنغافورة، إذ يجمع رأس الأسد بجسم السمكة في إشارة رمزية لتاريخها.","تظهر نافورة التمثال على الخليج وأفق مارينا باي والمباني الحديثة في الخلفية.","https://www.visitsingapore.com/","أُقيم ميرليون رمزًا لمدينة تجمع تاريخها البحري بهوية الأسد في اسم سنغافورة.","رأس الأسد وجسم السمكة تركيبة رمزية حديثة وليست تصويرًا لحيوان حقيقي."],["SG","Sultan Mosque","يرتبط مسجد السلطان بتاريخ الجالية المسلمة في حي كامبونغ غلام وتطور العمارة الدينية بالمدينة.","تظهر القبة الذهبية الكبيرة والمآذن والممرات والمباني التراثية المحيطة.","https://www.visitsingapore.com/","بُني المسجد الحالي في القرن العشرين على موقع ارتبط بمسجد أقدم في كامبونغ غلام، وصار معلمًا بارزًا للجالية المسلمة في الحي.","القبة الذهبية الكبيرة تجعل المسجد ظاهرًا وسط البيوت التجارية المنخفضة."],["SG","Jewel Changi Airport","يُعد جويل شانغي تجربة معمارية تمزج بين النقل والترفيه والحدائق الداخلية ضمن قبة زجاجية ضخمة.","يظهر شلال رين فورتكس من السقف بين المدرجات النباتية والمسارات الزجاجية.","https://www.jewelchangiairport.com/","شُيد جويل شانغي لتجميع مساحات تجارية وترفيهية ونباتية قرب المطار في تجربة معمارية واحدة.","الشلال الداخلي ينحدر من فتحة في السقف الزجاجي ضمن غابة داخلية."],["PH","Chocolate Hills","تُعد تلال الشوكولاتة من أبرز الظواهر الجيومورفولوجية في بوهول، ويعود لونها الموسمي إلى جفاف الغطاء العشبي.","تظهر مئات القمم المخروطية المتشابهة فوق سهل أخضر تتغير ألوانه حسب الموسم.","https://philippines.travel/","تشكّلت تلال الشوكولاتة عبر عمليات جيولوجية وتعرية في صخور كلسية على جزيرة بوهول.","لون التلال البني في الصيف ناتج عن جفاف الأعشاب، وليس وجود الشوكولاتة."],["PH","Kayangan Lake","تتميز بحيرة كايانغان بمياهها الصافية ومحيطها الكارستي في أرخبيل كورون، ضمن أراضٍ ذات أهمية لمجتمعات تاغبانوا.","تظهر المنحدرات الجيرية الحادة والمياه الزرقاء والبحيرة الهادئة بين الصخور.","https://philippines.travel/","تقع كايانغان ضمن أراضٍ مهمة لمجتمعات تاغبانوا الأصلية، في منطقة كهوف وبحيرات كارستية.","نقاء الماء ومشهد الجروف الكلسية سببان رئيسيان لشهرة البحيرة."],["PH","Batad Rice Terraces","تُظهر مدرجات باتاد كيف تكيفت مجتمعات إيفوغاو مع جبال لوزون بإقامة حقول أرز مدرجة ونظم مائية تقليدية.","تظهر المصاطب الخضراء على هيئة مدرجات شبه دائرية تحيط بالقرية.","https://whc.unesco.org/en/list/722","تعتمد المدرجات على قنوات ري وأحواض متدرجة تمرر الماء من مستويات أعلى إلى أسفل، وصيانتها عمل جماعي متوارث لدى السكان المحليين.","القنوات والمياه المتدرجة تشكل جزءًا من هندسة الحقول مثلها مثل الجدران."],["PH","Intramuros","كانت إنتراموروس قلب مانيلا المسوّر خلال الحكم الإسباني، وتُظهر مبانيها تاريخ المدينة الاستعماري وتعقيداته.","تظهر الأسوار الحجرية والبوابات والكنائس التاريخية والساحات الداخلية.","https://intramuros.gov.ph/","شكلت إنتراموروس المركز المحصن لمانيلا خلال الحكم الإسباني وتعرضت لأضرار جسيمة في الحرب العالمية الثانية.","تُظهر المباني التي رُممت والأجزاء الباقية طبقات مختلفة من تاريخ المدينة."],["PH","Puerto Princesa Underground River","يحافظ المنتزه على نظام كارستي من الكهوف ونهر جوفي يتصل بالبيئة الساحلية، ويضم تنوعًا بيئيًا مهمًا.","تظهر فتحات الكهوف والمياه المتدفقة بين الصخور والغابات الكثيفة حول النهر.","https://whc.unesco.org/en/list/652","شكّلت المياه داخل التكوينات الكارستية نهرًا تحت الأرض يصب قريبًا من الساحل.","تتغير خصائص بعض أجزاء المجرى بتأثير مستوى البحر والمد والجزر."],["PH","Boracay White Beach","تُظهر بوراكاي شعبية السياحة الساحلية في الفلبين، وأهمية إدارة جودة الشواطئ والأنشطة البحرية لحماية البيئة.","تظهر الرمال البيضاء الممتدة والمياه الضحلة وأشجار النخيل والقوارب التقليدية.","https://philippines.travel/","أصبحت بوراكاي وجهة سياحية واسعة الشهرة وتعرضت لضغوط بيئية أدت إلى إجراءات لإعادة التأهيل.","جودة المياه والشاطئ مرتبطة بإدارة الصرف والنشاط السياحي، لا بالرمال وحدها."],["PH","Taal Volcano","يُعد تال نظامًا بركانيًا نشطًا ذا فوهات متعددة داخل بحيرة، وتوضح ثوراته أهمية مراقبة المخاطر الجيولوجية.","تظهر الجزيرة البركانية والبحيرة والتضاريس المتغيرة، مع مراعاة قيود السلامة الرسمية.","https://www.phivolcs.dost.gov.ph/","ينتمي تال إلى منظومة بركانية معقدة تضم فوهات وتكوينات داخل بحيرة، وله تاريخ ثورات مؤثرة.","يمكن أن تتغير مناطق السماح بالزيارة تبعًا لتحذيرات البركان الرسمية."],["PH","Mayon Volcano","يتميز مايون بمخروط بركاني شبه متناظر نتج عن تراكم طبقات الحمم والمواد البركانية، وهو بركان نشط.","تظهر القمة المدببة والمنحدرات المتماثلة والسهول الخضراء المحيطة.","https://www.phivolcs.dost.gov.ph/","نتج مخروط مايون المتناسق نسبيًا عن تراكم طبقات متتابعة من الحمم والرماد البركاني.","شكله الجميل لا ينفي نشاطه وخطر الانبعاثات أو التدفقات البركانية."],["HR","Old City of Dubrovnik","تعكس دوبروفنيك تاريخ جمهورية راغوزا البحرية وتطور التحصينات الحضرية على ساحل الأدرياتيك.","تظهر الأسوار الحجرية والميناء والأسقف الحمراء والشوارع التاريخية داخل المدينة.","https://whc.unesco.org/en/list/95","ازدهرت دوبروفنيك جمهورية بحرية مستقلة نسبيًا عُرفت تاريخيًا باسم راغوزا وحمت تجارتها بالأسوار.","ترسم الأسوار مسارًا مرتفعًا حول أسقف المدينة والبحر الأدرياتيكي."],["HR","Plitvice Lakes National Park","تتميز بحيرات بليتفيتش بتشكل حواجز الترافرتين الطبيعية التي تقسم المياه إلى بحيرات متدرجة وشلالات.","تظهر البحيرات الفيروزية والجسور الخشبية والشلالات المتتابعة وسط الغابات.","https://whc.unesco.org/en/list/98","تكوّنت بحيرات بليتفيتش عبر تراكم حواجز طبيعية من الترافرتين، تترسب من المياه الغنية بكربونات الكالسيوم بمساعدة عمليات كيميائية وبيولوجية. تنشئ هذه الحواجز المتغيرة سدودًا تفصل البحيرات وتربطها بالشلالات؛ ولذلك يتطور شكل المجاري المائية باستمرار. أُعلنت المنطقة منتزهًا وطنيًا عام 1949 وأُدرجت في التراث العالمي عام 1979 لحماية نظامها الجيولوجي والبيئي الحساس.","عدد البحيرات والممرات المائية يتغير طبيعيًا، ولا يمثل ترتيبًا حجريًا مصطنعًا."],["HR","Diocletian's Palace","يُظهر قصر دقلديانوس كيف استُخدم مجمع إمبراطوري روماني لاحقًا أساسًا لمدينة مأهولة عبر القرون.","تظهر الأفنية الرومانية والأقبية والأعمدة والمباني السكنية التي تشغل أجزاء من القصر.","https://whc.unesco.org/en/list/97","بنى الإمبراطور دقلديانوس مجمعًا كبيرًا في أواخر العصر الروماني، ثم نشأت شوارع ومساكن داخله.","القصر حيّ عمراني مأهول اليوم، وليس متحفًا رومانيًا مغلقًا فقط."],["HR","Hvar Island","تجمع هفار بين تاريخ الملاحة والتجارة في الأدرياتيك والعمارة الساحلية القديمة والمناظر المتوسطية.","تظهر المرافئ الحجرية والمباني القديمة وحقول الخزامى والخلجان الصافية.","https://croatia.hr/en-gb","ارتبطت هفار بالملاحة الأدرياتية وزراعة النباتات العطرية ضمن مناخ متوسطي.","الجزيرة تضم مدنًا وقلاعًا وخلجانًا تختلف عن المشاهد الشاطئية وحدها."],["HR","Krka National Park","تُبرز كركا عملية ترسيب الحجر الجيري التي تكوّن الحواجز الطبيعية والشلالات على امتداد النهر.","تظهر مساقط سكرادينسكي بوك والنباتات المائية والممرات بين الغابات.","https://npkrka.hr/en_us/prirodna-bastina/slapovi/skradinski-buk/","شكّلت مياه نهر كركا الغنية بالكربونات عبر الزمن حواجز من الحجر الجيري المسامي «الترافرتين» بفعل ترسّب المعادن حول الطحالب والنباتات والكائنات الدقيقة. تتكوّن شلالات ومدرجات مائية متغيرة تدريجيًا، ويعد سكرادينسكي بوك من أشهر مواضع هذه الظاهرة داخل المنتزه.","يمتد شلال سكرادينسكي بوك عبر سبع عشرة درجة مائية على طول يقارب 800 متر، وفق إدارة المنتزه. الحواجز الجيرية فيه تكوينات حية جيولوجيًا تستمر في النمو والتغير، وليست مصاطب صخرية ثابتة منذ نشأتها."],["HR","Ban Jelačić Square","تمثل الساحة قلب زغرب المدني ومكانًا ارتبط بالتجمعات والأسواق والتحولات السياسية في المدينة.","تظهر الواجهات التاريخية والترام والتمثال الفروسي وسط ميدان المشاة.","https://www.infozagreb.hr/en","أصبحت ساحة بان يلاتشيتش مركزًا مدنيًا لزغرب مع تطور الشوارع الحديثة ووسائل النقل.","الترام يخترق المكان بينما يبقى الجزء الأكبر منه مخصصًا للمشاة."],["HR","Pula Arena","يُعد مدرج بولا شاهدًا على الترفيه العام والهندسة الرومانية، ومن أكثر المدرجات القديمة احتفاظًا بواجهاته.","تظهر الأقواس الحجرية المتتابعة والساحة البيضاوية الكبيرة قرب الساحل.","https://www.ami-pula.hr/en/","شُيد مدرج بولا في العصر الروماني لإقامة فعاليات جماهيرية وشُكل كمنشأة بيضاوية كبيرة.","الأقواس الخارجية التي بقيت محفوظة تجعله من أشهر المدرجات الرومانية الباقية."],["HR","Historic City of Trogir","تحفظ تروغير تخطيطًا عمرانيًا متصلًا منذ العصور القديمة مع عمارة من العصور الوسطى والنهضة.","تظهر الكاتدرائية والشوارع الحجرية الضيقة والساحات والواجهات المطلة على الميناء.","https://whc.unesco.org/en/list/810","تطورت تروغير على جزيرة صغيرة واحتفظت بنسيج عمراني من فترات رومانية وعصور وسطى.","يمكن مشاهدة طرز معمارية متعددة داخل مساحة صغيرة ذات شوارع حجرية ضيقة."],["HU","Hungarian Parliament Building","يُجسد البرلمان المجري الطموح السياسي والمعماري لبودابست الحديثة في أواخر القرن التاسع عشر.","تظهر القبة المركزية والأبراج القوطية الجديدة والواجهة الطويلة المنعكسة على الدانوب.","https://www.parlament.hu/web/visitors","بدأ بناء البرلمان في ثمانينيات القرن التاسع عشر، واكتمل في مطلع القرن العشرين ضمن تطوير الضفة الشرقية للدانوب في العاصمة الحديثة.","القبة المركزية تنسجم مع واجهتين طويلتين متشابهتين على ضفة الدانوب."],["HU","Buda Castle","كانت قلعة بودا مقرًا ملكيًا تاريخيًا وتعرضت لتحولات وترميمات متعددة، وهي جزء من المشهد التراثي لبودابست.","تظهر ساحات المجمع الملكي والقباب والواجهات المرتفعة فوق نهر الدانوب.","https://whc.unesco.org/en/list/400","ارتبطت تلة بودا بالقصور الملكية والتحصينات عبر قرون، وتعرضت مبانيها للتغيير والترميم بعد الحروب.","الموقع المرتفع يوفر رؤية مختلفة لطرفَي المدينة على ضفاف النهر."],["HU","Fisherman's Bastion","بُني حصن الصيادين بشكله الحالي في مطلع القرن العشرين بوصفه شرفة معمارية احتفالية، لا قلعة دفاعية من القرون الوسطى.","تظهر الأبراج المخروطية البيضاء والأقواس وإطلالات البرلمان والدانوب من الهضبة.","https://www.budapestinfo.hu/","أُقيم حصن الصيادين بشكله الحالي في نهاية القرن التاسع عشر وبداية العشرين كعمل معماري احتفالي.","اسمه يوحي بحصن دفاعي قديم، لكن الأبراج البيضاء الحالية شُيدت أساسًا للمشهد التذكاري."],["HU","Széchenyi Thermal Bath","تُعد حمامات سيشيني جزءًا من تقاليد استخدام الينابيع الحرارية في بودابست، داخل مبنى تاريخي ذي طابع كلاسيكي جديد.","تظهر الأحواض الخارجية الواسعة والواجهات الصفراء والقاعات الداخلية المزخرفة.","https://www.szechenyibath.hu/","استغلت بودابست مياه الينابيع الحرارية في الحمامات العامة، وطورت سيشيني ضمن منشآت مطلع القرن العشرين.","الأحواض الخارجية شهيرة حتى في الأجواء الباردة بسبب حرارة المياه."],["HU","Széchenyi Chain Bridge","كان جسر السلسلة محطة مهمة في ربط بودا وبست وتطوير البنية التحتية للمدينة خلال القرن التاسع عشر.","تظهر الأبراج الحجرية والسلاسل المعدنية وتماثيل الأسود عند مدخلي الجسر.","https://www.budapestinfo.hu/","افتُتح الجسر سنة 1849، فصار معبرًا دائمًا بين ضفتي الدانوب وساعد على تسهيل الاتصال قبل توحيد بودا وبست رسميًا في مدينة واحدة.","تماثيل الأسود عند المداخل والسلاسل المعدنية عناصر بارزة في تصميمه."],["HU","Heroes' Square Budapest","تقدم ساحة الأبطال نصبًا تاريخيًا يعكس روايات الهوية الوطنية المجرية وشخصيات بارزة من ماضيها.","تظهر الأعمدة والنصب المركزي والتماثيل حول الساحة الواسعة عند مدخل منتزه المدينة.","https://www.budapestinfo.hu/","تحتفي ساحة الأبطال بشخصيات من التاريخ المجري عبر نصب مركزي وأعمدة وتماثيل.","الموقع جزء من محور عمراني واسع يرتبط بمنتزه المدينة والمؤسسات الثقافية."],["HU","Eger Castle","ارتبطت قلعة إيغر بالدفاع عن المدينة خلال الحروب العثمانية في القرن السادس عشر وأصبحت جزءًا من الذاكرة التاريخية المجرية.","تظهر الجدران الحجرية والأبراج وبقايا التحصينات المطلة على إيغر.","https://www.visithungary.com/","شهد حصار إيغر سنة 1552 دفاع الحامية عن القلعة في مواجهة جيش عثماني أكبر عددًا، وتحولت الواقعة لاحقًا إلى جزء بارز من الذاكرة المجرية.","يمكن ملاحظة اختلاف طبقات البناء والتحصين في الأسوار والأبراج."],["HU","Hortobágy National Park","يحفظ هورتوباج تقاليد الرعي في السهول المجرية المفتوحة، إلى جانب موائل الطيور والبرك والمراعي.","تظهر المراعي الممتدة وقطعان الحيوانات والجسر الحجري ذي الأقواس في المشهد الريفي.","https://whc.unesco.org/en/list/474","تشكلت صورة سهول هورتوباج عبر قرون من الرعي وإدارة الأراضي والمياه، وحافظ الرعاة على ممارسات محلية أصبحت جزءًا من التراث الثقافي.","جسر الأقواس التسعة رمز بصري للمنطقة، إلى جانب المراعي والطيور المهاجرة."],["BE","Grand-Place Brussels","تعكس الساحة الثراء التجاري والنقابي لبروكسل، ويتميز محيطها بوحدة معمارية لافتة. وتُظهر واجهات النقابات كيف عبّرت المهن التجارية عن مكانتها بالعمارة والرموز المنحوتة، بدل الاكتفاء بوظيفة السوق.","يمكن مشاهدة مبنى البلدية ذي البرج الرفيع وواجهات بيوت النقابات المزخرفة. لاحظ اختلاف الشعارات والتماثيل فوق بيوت النقابات، ثم قارن بينها وبين الواجهة غير المتناظرة لمبنى البلدية.","https://whc.unesco.org/en/list/857","أعيد بناء معظم المباني المحيطة بالساحة بعد قصف عام 1695، مع الحفاظ على تخطيط المكان. أُعيد تشكيل الواجهات في السنوات التالية للهجوم، ولذلك يجمع الميدان بين تخطيط أقدم ومبانٍ ترجع إلى إعادة الإعمار في أواخر القرن السابع عشر.","الواجهات تبدو متجانسة رغم اختلاف رموز النقابات والزخارف في كل مبنى. لا ينتمي كل مبنى في الساحة إلى نقابة واحدة أو إلى الحقبة نفسها؛ هذا التنوع داخل إطار بصري متناسق جزء من قيمتها التراثية."],["BE","Atomium","أصبح أتوميوم رمزًا للتفاؤل بالعلم والتقنية خلال المعرض الدولي الذي استضافته بروكسل عام 1958. يجمع التصميم بين الفنون والهندسة، ويعكس اهتمام المعرض العالمي آنذاك بالمواد والبحث العلمي والاستخدام السلمي للتقنية.","تظهر تسع كرات معدنية متصلة بأنابيب كبيرة، وبعضها يضم مساحات للعرض والمشاهدة. يمكن تتبع الأنابيب التي تصل الكرات التسع، وملاحظة انعكاسات المدينة على الكسوة المعدنية اللامعة.","https://atomium.be/","صُمم المجسم في الأصل لمعرض إكسبو 58، ثم استمر بوصفه معلمًا دائمًا للمدينة. اختير هذا الشكل لكي يلفت النظر إلى بنية المادة على مستوى ذري، ثم تحول من جناح مؤقت إلى أحد رموز بروكسل الدائمة.","يُجسد نموذجًا مكبرًا لترتيب ذرات بلورة الحديد، وليس صورة جزيء منفرد. يمثّل التكوين خلية بلورية مكبرة بنحو 165 مليار مرة؛ كراته ليست مرسومة وفق ترتيب كواكب أو نموذج للنظام الشمسي."],["BE","Historic Centre of Bruges","يبرز مركز بروج دور المدن الفلمنكية في التجارة الأوروبية خلال العصور الوسطى. تساعد شبكة القنوات والأسواق والكنائس على فهم مدينة تجارية عاشت ازدهارًا اقتصاديًا مبكرًا وما زال أثره واضحًا في نسيجها.","تظهر القنوات والجسور والبيوت القرميدية وساحة السوق والأبراج التاريخية. راقب أبراج الأجراس والساحة الكبرى والممرات المائية الضيقة، ثم تفاصيل الواجهات ذات الدرجات الحجرية المتتابعة.","https://whc.unesco.org/en/list/996","ازدهرت بروج مركزًا للتجارة والصناعات النسيجية، وظلت شوارع كثيرة تحتفظ بمقياس المدينة القديمة. تراجعت مكانة الميناء تدريجيًا حين تغيرت الممرات المائية والتجارة، وهو ما أسهم في بقاء أجزاء من المركز العمراني بعيدًا عن إعادة تشكيل صناعية واسعة.","تمنح شبكة القنوات المدينة مظهرًا مائيًا مميزًا رغم أنها ليست مدينة قائمة على جزر. المدينة لم تتوقف عند العصر الوسيط؛ بل شهدت ترميمًا وتغيرات لاحقة، لذلك فالمشهد التاريخي نتاج طبقات زمنية متعددة."],["BE","Gravensteen Castle","توضح القلعة الدور الدفاعي والرمزي لحكام فلاندرز في قلب مدينة غنت. وجود حصن لسلطة الكونت وسط مدينة تجارية يوضح العلاقة بين الحكم المحلي والطبقات الاجتماعية والطرق المائية.","تظهر الأسوار والأبراج الحجرية والفناء الداخلي ضمن بيئة حضرية قريبة من النهر. قارن بين الأسوار السميكة وأبراج المراقبة والفناء المحاط بالمباني، ولاحظ موقع القلعة داخل الشوارع المدنية وليس فوق جبل منعزل.","https://visit.gent.be/en","أعيد بناء أجزاء من القلعة وتطويرها في العصور الوسطى، ثم تغير استخدامها قبل أعمال ترميم لاحقة. ترجع الهيئة الحجرية البارزة للقلعة إلى أواخر القرن الثاني عشر؛ وقد استخدمت بعد فترتها الإقطاعية في وظائف قضائية وصناعية قبل إحيائها.","اسم غرافنستين يعني تقريبًا «قلعة الكونت»، في إشارة إلى حكام فلاندرز. مرّت القلعة بمرحلة استخدام صناعي في التاريخ الحديث، ولهذا تبدو بعض الأجزاء ثمرة ترميم لا بقايا غير ممسوسة."],["DK","Nyhavn","يحفظ نيهافن صورة من تاريخ كوبنهاغن البحري والتجاري وتحول الواجهات المينائية إلى فضاء عام. تجعل الواجهة البحرية من السهل فهم كيف ارتبط الاقتصاد الحضري بالقناة والمخازن وسكن التجار والبحارة.","تظهر صفوف المنازل الزاهية وقوارب خشبية قديمة بجوار القناة. تأمل المراكب الخشبية الراسية وتفاوت ارتفاعات وطلاءات المنازل، ثم راقب كيف ينتهي الممر المائي إلى مشهد المدينة.","https://www.visitcopenhagen.com/","شق الممر المائي في القرن السابع عشر لتسهيل وصول السفن والتجارة إلى داخل المدينة. تحولت بعض المباني تدريجيًا من مساكن ومخازن مرتبطة بالميناء إلى مقاهٍ ومرافق ثقافية، مع استمرار حضور السفن التاريخية.","سكن الكاتب هانس كريستيان أندرسن في أكثر من عنوان بشارع نيهافن خلال حياته. اسم نيهافن يعني «الميناء الجديد»، لكنه اليوم من أقدم الأجزاء المصورة في واجهة كوبنهاغن."],["DK","The Little Mermaid Statue","ارتبط التمثال بالأدب الدنماركي وبحكايات هانس كريستيان أندرسن التي انتشرت عالميًا. يربط العمل الأدب بالفن العام ويكشف كيف يمكن لشخصية خيالية بسيطة أن تتحول إلى شعار سياحي لمدينة كاملة.","يمكن رؤية تمثال برونزي صغير يجلس فوق صخرة عند الواجهة البحرية. تظهر الحورية جالسة قرب سطح الماء في وضع متأمل، مع السفن وميناء كوبنهاغن خلفها لا مع قلعة أسطورية.","https://www.visitcopenhagen.com/","وُضع التمثال في كوبنهاغن سنة 1913 تكريمًا لشخصية الحورية في الحكاية الأدبية. نحت إدوارد إريكسن التمثال بتكليف من كارل ياكوبسن، الذي تأثر بعرض مسرحي لقصة أندرسن.","التمثال أصغر بكثير مما توحي به بعض الصور المقربة؛ لذلك يفاجأ بحجمه بعض الزوار. تعرض التمثال على مر السنين لأعمال تخريب وترميم؛ النسخة المعروضة جزء من تاريخ صيانة الفن العام."],["DK","Kronborg Castle","تحكم موقع القلعة في مضيق أوريسند، ما جعلها ذات أهمية دفاعية واقتصادية في تاريخ الدنمارك. أسهم موقع كرونبورغ الضيق قرب مضيق أوريسند في مراقبة الملاحة وفرض الرسوم تاريخيًا، قبل أن تصبح رمزًا أدبيًا عالميًا.","تظهر الأسوار والحصون والقاعات الملكية بالقرب من البحر بين الدنمارك والسويد. لاحظ الحصون الترابية والمدافع والقاعات النهضوية، ثم انظر عبر الماء إلى الساحل السويدي القريب.","https://whc.unesco.org/en/list/696","بدأ تشييد القلعة النهضوية في سبعينيات القرن السادس عشر، وعُززت دفاعاتها في فترات لاحقة. شهدت القلعة حريقًا كبيرًا في القرن السابع عشر ثم أعيد بناؤها؛ وانتقلت لاحقًا بين الاستخدام الملكي والعسكري والثقافي.","اشتهرت عالميًا باسم إلسينور، مكان أحداث مسرحية هاملت لشكسبير. ترتبط بهاملت بسبب الأدب، لكن القلعة الحقيقية أقدم من معظم عروض المسرحية ولا تمثل موقع أحداث تاريخية موثقة لشخصية هاملت."],["DK","Roskilde Cathedral","توضح الكاتدرائية تطور عمارة الطوب الديني في شمال أوروبا وارتباط المكان بتاريخ الملكية الدنماركية. تُعد مقابر الأسرة الملكية داخل الكنيسة سجلًا معماريًا لتغير الذوق الدنماركي، وتظهر إضافات من طرز متعاقبة.","تظهر الأبراج الحادة والمصليات الملكية وقاعات الكنيسة الواسعة. لاحظ الطوب الأحمر والأبراج المزدوجة والقبور الملكية المنفصلة في مصليات ذات زخارف مختلفة.","https://whc.unesco.org/en/list/695","بدأ تشييدها في العصور الوسطى وشهدت إضافات معمارية تعود إلى فترات مختلفة. استبدلت المنشأة الطوبية مباني دينية أقدم، ثم توسعت بالمصليات الجنائزية على امتداد عصور حكم مختلفة.","تضم مدافن عدد كبير من ملوك وملكات الدنمارك، لا قبرًا ملكيًا واحدًا. لم تُبنَ كل المصليات دفعة واحدة؛ تنوعها يعطي فكرة عن اختلاف أساليب العمارة عبر القرون."],["SE","Gamla Stan","تحتفظ المدينة القديمة بتاريخ ستوكهولم التجاري والسياسي عبر شبكة شوارعها الموروثة. يجسد الحي العلاقة بين مركز السلطة الملكية والتجارة الحضرية في مدينة نشأت وسط جزر ومضائق مائية.","تظهر الساحات المرصوفة والمباني الصفراء والحمراء والأزقة الضيقة والقصر الملكي. تأمل ساحة ستورتوريت ذات الواجهات الملونة، ثم اتجه نحو الشوارع الحجرية المحيطة بالقصر الملكي.","https://visitsweden.com/","نشأت نواة ستوكهولم في جزر وممرات مائية تربط بحيرة مالارين ببحر البلطيق. تبلور النسيج الوسيط للمدينة حول الممرات البحرية والأسواق، ثم أضيفت واجهات وتحسينات لاحقة دون أن تختفي شبكة الأزقة.","بعض الأزقة ضيقة للغاية، لكنها ما زالت جزءًا من مدينة حية وليست متحفًا مفتوحًا. اختلاف ضيق الشوارع ليس نتيجة تصميم سياحي حديث؛ بل يعكس طبقات عمرانية قديمة وسعيًا لاستغلال الأرض في مركز مكتظ."],["SE","Vasa Museum","يحفظ المتحف نموذجًا نادرًا لسفينة حربية من القرن السابع عشر وما تكشفه عن الهندسة البحرية في تلك الفترة. تتيح السفينة للباحثين دراسة تقنيات البناء والنحت والحياة البحرية في القرن السابع عشر بقدر لا توفره غالبية حطام السفن.","تظهر السفينة الخشبية الضخمة والمنحوتات المحفوظة على جوانبها. تُظهر المنحوتات على مؤخرة السفينة صورة الملكية والقوة، بينما تكشف الطوابق الداخلية تنظيم المدافع والبحارة.","https://www.vasamuseet.se/en","غرقت السفينة فاسا في رحلتها الأولى سنة 1628، ثم رُفعت من المياه في القرن العشرين. أُعيد اكتشاف حطامها في خمسينيات القرن العشرين ورُفعت سنة 1961، ثم خضعت لعقود من أعمال حفظ الخشب.","حفظت المياه الباردة قليلة الملوحة في بحر البلطيق أجزاء كبيرة من خشب السفينة. لم يكن غرقها بسبب معركة؛ فقد فقدت توازنها في بداية إبحارها، ما جعل قصتها درسًا في تصميم السفن."],["SE","Drottningholm Palace","يُظهر المجمع الملكي فنون القصور والحدائق السويدية وتأثرها بالتقاليد الأوروبية. تحتفظ الحدائق والمسرح بملامح من حياة البلاط الأوروبي، ويمنح استمرار الدور الملكي الموقع خصوصية مقارنة بالقصور المهجورة.","تظهر واجهة القصر والحدائق المنتظمة والمسرح التاريخي ضمن المجمع. قارن المحاور المستقيمة في الحدائق الرسمية بالممرات الأكثر حرية في أجزاء أخرى، وشاهد مبنى المسرح التاريخي.","https://whc.unesco.org/en/list/559","تطور القصر بصورة رئيسية في القرن السابع عشر مع إضافات لاحقة إلى حدائقه ومرافقه. تبلورت صورتها الأساسية في عهد الملكة هيدفيغ إليونورا، وأضيفت حدائق صيغت بتأثير فرنسي وأخرى بأسلوب طبيعي لاحق.","يحتفظ الموقع بمسرح ملكي تاريخي ذي آليات خشبة مسرح قديمة. الموقع لا يقتصر على القصر؛ فالحدائق والمسرح والجناح الصيني تشكل أجزاء مكملة لقيمته."],["SE","Skansen Open-Air Museum","يقدّم سكانسن طريقة تعليمية لفهم الحياة السويدية التقليدية عبر مبانٍ نقلت من أقاليم متعددة. يساعد جمع مبانٍ من أقاليم مختلفة في مكان واحد على مقارنة الحرف والمواد وتقنيات السكن حسب البيئة المحلية.","يمكن مشاهدة منازل ريفية وورش حرف وأساليب بناء مختلفة داخل منتزه مفتوح. لاحظ الفرق بين البيوت الخشبية الريفية والورش والمزارع الصغيرة، وكيف يُشرح سياق استخدام كل مبنى.","https://www.skansen.se/en/","افتُتح سكانسن عام 1891 ليحفظ نماذج من البيوت والعادات قبل تغير الحياة الريفية سريعًا. أسسه آرثر هازيليوس في نهاية القرن التاسع عشر مع ازدياد القلق من اختفاء أنماط الحياة التقليدية بفعل التصنيع.","يُعد من أقدم المتاحف المفتوحة في العالم، ولا يعرض قرية واحدة من عصر واحد. كثير من المباني الأصلية نُقل من مواضعه الأولى وأعيد تجميعه هنا للحفظ والتعليم، لا لأنه قرية نشأت طبيعيًا في موقع واحد."],["FI","Suomenlinna","تظهر القلعة كيف أثرت الجغرافيا البحرية لبحر البلطيق في الدفاع عن هلسنكي. يوضح امتداد الأسوار عبر جزر متجاورة كيف استُخدمت الممرات البحرية كجزء من التحصين وإدارة مداخل الميناء.","تظهر التحصينات والأنفاق والأسوار ومواقع المدافع على جزر متصلة. تأمل التحصينات الحجرية والبوابات والمدافع والممرات الساحلية، ثم العلاقة بين الجزر والدفاعات التي تطل على مداخل البحر.","https://whc.unesco.org/en/list/583","بدأ تشييد الحصن خلال القرن الثامن عشر عندما كانت فنلندا جزءًا من المملكة السويدية. بُني الحصن أصلاً تحت الحكم السويدي باسم سفيابورغ، ثم انتقلت السيطرة عليه خلال تغيرات الحكم في فنلندا؛ لذلك يحمل آثار فترات سياسية متباينة.","اسم سومينلينا يعني «قلعة فنلندا»، بينما عُرف المكان تاريخيًا باسم سوابورغ. المنطقة لا تزال حيًا مأهولًا، وليست مجرد آثار عسكرية خالية من السكان."],["FI","Helsinki Cathedral","تعكس الكاتدرائية العمارة الكلاسيكية الجديدة التي شكلت المركز المدني لهلسنكي في القرن التاسع عشر. تمثل الواجهة ذات الأعمدة والقبة المرتفعة جزءًا من التخطيط الذي جعل ساحة مجلس الشيوخ محورًا رمزيًا للعاصمة الحديثة.","تظهر القبة الخضراء والدرجات العريضة والواجهة البيضاء فوق ساحة مجلس الشيوخ. لاحظ التدرج الواسع أمام المبنى والأعمدة الكلاسيكية والقباب الصغيرة المحيطة بالقبة الرئيسية، ثم مشهد الساحة عند أسفل الدرج.","https://www.myhelsinki.fi/en/","أُقيم المبنى ضمن تخطيط جديد لمركز العاصمة في القرن التاسع عشر. صمم كارل لودفيغ إنغل الكاتدرائية، واكتمل بناؤها خلال القرن التاسع عشر بعدما أصبحت هلسنكي عاصمة للدوقية الكبرى في فنلندا.","تطل الكاتدرائية على ساحة مدنية كبيرة، ولذلك تبدو واضحة من نقاط مختلفة في الميناء. الكنيسة لوثرية رغم تشابه شكل القباب والواجهة مع بعض مباني أوروبا الأرثوذكسية أو الإمبراطورية."],["FI","Santa Claus Village","تجمع القرية بين هوية لابلاند القطبية والسياحة الشتوية المستوحاة من شخصية سانتا كلوز. تُظهر القرية كيف حولت لابلاند موقعًا جغرافيًا مرتبطًا بخط العرض إلى هوية سياحية ثقافية شتوية.","يمكن مشاهدة علامة الدائرة القطبية ومبانٍ خشبية ومشاهد الغابات الثلجية في الموسم. تأمل علامة الدائرة القطبية والمباني الخشبية، وخارج القرية الغابات الشمالية التي تختلف إضاءتها وطبيعتها كثيرًا عبر الفصول.","https://www.visitrovaniemi.fi/","تطورت الوجهة السياحية قرب روفانييمي في العصر الحديث، وليست قرية تاريخية قديمة. ترتبط المنطقة قرب روفانييمي بتاريخ استقبال الزوار بعد الحرب العالمية الثانية، ثم نمت مرافق السياحة الحالية تدريجيًا.","خط الدائرة القطبية مفهوم جغرافي مرتبط بميل محور الأرض، ولا يحدد منطقة ثلجية طوال العام. ليست الشفق القطبي أو الثلوج مضمونة في كل زيارة؛ إذ يتوقف ظهورهما على الموسم والطقس والنشاط الشمسي."],["FI","Oulanka National Park","يحمي أولانكا بيئات الأنهار السريعة والغابات الشمالية والتكوينات الصخرية القريبة من الحدود الشرقية لفنلندا. يسمح تنوع الأنهار والشلالات والغابات والوديان بملاحظة العلاقة بين المياه الجارية والتضاريس والحياة النباتية الشمالية.","تظهر الجسور المعلقة والشلالات الصغيرة والغابات الصنوبرية والمسارات الطبيعية. راقب النهر من الجسور المعلقة والممرات المرتفعة، والشواطئ الصخرية التي تتشكل عند الانحناءات والمنحدرات.","https://www.nationalparks.fi/oulankanp","أُنشئت الحماية الطبيعية للحفاظ على نظام وديان وأنهار شمالية متنوع. ساهمت جهود الحماية في الحفاظ على جزء من الأودية والغابات التي تشكل موطنًا للعديد من الأنواع في الشمال الفنلندي.","نهر كيتكا معروف بمنحدراته المائية، وبعض الجسور فوقه مخصصة للمشاة فقط. يمر في نطاق المنتزه جزء من مسار كارْهونكييروس الشهير بالمشي الطويل، لكن زيارة المعالم لا تتطلب دائمًا اجتياز المسار بالكامل."],["IE","Cliffs of Moher","تُظهر المنحدرات أثر الأمواج والتعرية في تشكيل حافة اليابسة المطلة على المحيط الأطلسي. تساعد الطبقات الرسوبية المكشوفة على فهم تاريخ بيئات قديمة ترسبت فيها الرمال والطمي قبل تحولها إلى صخور صلبة.","تظهر جروف صخرية طبقية شاهقة تتبع الساحل مع تجمعات طيور بحرية. لاحظ خطوط الطبقات الأفقية والشقوق العمودية وتجمعات الطيور في مواسم التعشيش، من نقاط مشاهدة آمنة بعيدة عن الحافة.","https://www.cliffsofmoher.ie/","تراكمت الصخور الرسوبية قبل ملايين السنين، ثم كشفها النحت الساحلي لتكوين الجروف الحالية. تكونت معظم الصخور من رواسب بحرية ونهرية قديمة، ثم أدى رفع اليابسة والتعرية الساحلية إلى إبراز الجروف العالية الحالية.","منحدرات موهير ليست أعلى جروف أيرلندا، رغم أنها من أشهرها. حركة الصخور والمطر والرياح تجعل الحواف غير مستقرة في بعض المواضع؛ لا ينبغي اعتبار ممرات الزوار غير الرسمية آمنة."],["IE","Trinity College Old Library","ترتبط المكتبة بتاريخ الدراسة وحفظ المخطوطات في دبلن، وتشتهر بتراثها المكتوب. تبرز أهمية حفظ المخطوطات والكتب في نقل الثقافة والبحث العلمي، وتتجاوز شهرة المكتبة الصورة الجميلة لقاعتها الطويلة.","تظهر القاعة الطويلة ذات الرفوف الخشبية ومجموعات الكتب التاريخية. تأمل الرفوف الطويلة والتماثيل النصفية والعمارة الخشبية، مع الانتباه إلى أن إتاحة المخطوطات الأصلية تتغير وفق متطلبات الحفظ.","https://www.tcd.ie/library/","تأسست كلية ترينيتي في القرن السادس عشر، وطُورت مكتبتها على مراحل لاحقة. يعود بناء القاعة الطويلة إلى القرن الثامن عشر، وقد خضعت مجموعاتها ومرافقها لأعمال ترميم وصيانة لضمان بقاء الكتب التاريخية.","كتاب كيلز مخطوط إنجيلي مزخرف من العصور الوسطى، وليس كتابًا مطبوعًا. كتاب كيلز نُسخ وزُخرف يدويًا قبل الطباعة بقرون، وتُعرض منه صفحات محدودة حفاظًا عليه."],["IE","Rock of Cashel","يمثل الموقع مركزًا تاريخيًا للدين والسلطة في أيرلندا خلال العصور الوسطى. يجمع الموقع بين السلطة الملكية المبكرة والتاريخ الكنسي، وهو ما يفسر وجود تحصينات وأبنية دينية متجاورة على الهضبة.","تظهر بقايا الكاتدرائية والبرج الدائري والكنائس الحجرية أعلى هضبة صخرية. لاحظ البرج الدائري وكنيسة كورماك الصغيرة وزخارف المباني الحجرية، ثم نظرة الموقع المرتفع إلى السهول المحيطة.","https://heritageireland.ie/","ارتبطت صخرة كاشيل بحكام مونستر ثم تطورت عليها مبانٍ كنسية من فترات مختلفة. ارتبطت الصخرة بملوك مونستر، ثم أصبحت مركزًا كنسيًا وتطورت كاتدرائيتها وكنائسها عبر القرنين الثاني عشر والثالث عشر وما بعدهما.","المكان مجمع مبانٍ فوق قمة صخرية، وليس صخرة منفردة ذات شكل غريب. تشكل الأبراج والكنائس مجموعة من فترات مختلفة، لذلك ليس دقيقًا وصف الموقع كله بأنه قلعة عسكرية واحدة."],["IE","Killarney National Park","يحمي المنتزه بحيرات وغابات طبيعية مهمة في الجنوب الغربي الأيرلندي. تمثل الغابات المحلية والبحيرات موائل حيوية نادرة في بعض مناطق أيرلندا، حيث تتعايش النباتات الرطبة مع الجبال والسواحل القريبة.","تظهر البحيرات والجبال والغابات وقلعة روس وبعض المسارات بجوار الماء. شاهد بحيرات كيلارني وقلعة روس وغابات موكروس، وقارن بين المساحات الخضراء المفتوحة والغطاء الشجري الكثيف.","https://www.nationalparks.ie/killarney/","أُنشئ المنتزه لحماية جزء من مشهد كيلارني الطبيعي الذي تأثر أيضًا بتاريخ الإنسان في المنطقة. أُنشئت الحماية الأولى في القرن العشرين حول أراضٍ وممتلكات تاريخية، ثم تطورت إدارة المنتزه لصون الأنظمة البيئية والزوار معًا.","تحتضن بعض غابات المنتزه أشجار طقسوس وبلوط قديمة، وليست المنطقة مجرد بحيرات سياحية. تضم المنطقة جزءًا من آخر الغابات الأصلية التي بقيت من أنواع معينة في أيرلندا، ما يمنحها قيمة تتجاوز جمال البحيرات."],["PL","Historic Centre of Kraków","تكشف كراكوف القديمة عن ازدهار مدينة تجارية وملكية في أوروبا الوسطى عبر قرون. يجمع المركز بين المكانة الملكية والتجارة والتعليم، وتظهر وظائفه المتنوعة في السوق والكنائس والجامعة والمباني العامة.","تظهر ساحة السوق الكبرى وقاعة القماش والشوارع التاريخية المحيطة بها. تأمل قاعة القماش في قلب الساحة، ثم الأبراج الكنسية والشوارع التي تتفرع منها نحو حي فافل والجامعة التاريخية.","https://whc.unesco.org/en/list/29","حافظ مركز كراكوف على جزء كبير من تخطيطه التاريخي رغم التحولات السياسية التي مرت بها بولندا. تطور تخطيط ساحة السوق في القرن الثالث عشر واحتفظت المدينة بدورها التجاري والثقافي عبر تحولات ملوك بولندا وحدودها.","ساحة السوق الرئيسية من أكبر ساحات المدن التاريخية في أوروبا. ساحة السوق الكبيرة عنصر من نظام عمراني مخطط، وليست فراغًا نشأ عشوائيًا بين المباني."],["PL","Wawel Royal Castle","يظهر مجمع فافل تاريخ الملوك البولنديين وتنوع طرز العمارة داخل مركز الحكم القديم. تكشف القلعة تقاليد الحكم في بولندا عبر قاعات الدولة والفنون الملكية، وتعمل مع الكاتدرائية المجاورة كجزء من مشهد تاريخي واحد.","تظهر القصور والأفنية والكاتدرائية فوق مرتفع بجانب نهر فيستولا. لاحظ الفناء النهضوي ذي الأروقة والقاعات الملكية وإطلالة التل على نهر فيستولا والمركز العمراني.","https://wawel.krakow.pl/en","كان تل فافل مقرًا ملكيًا مهمًا، وأضيفت إليه مبانٍ وتعديلات عبر العصور. تغير المجمع بين العمارة القوطية والنهضوية بعد فترات بناء وإعادة تشكيل متعددة، كما تعرض لبعض التحولات أثناء فترات التقسيم والاحتلال.","القلعة والكاتدرائية مبنيان مرتبطان داخل المجمع، لكن لكل منهما وظيفة مختلفة. التلة تحمل آثارًا أقدم من القصر الحالي؛ لذا ينبغي التفريق بين تاريخ الموقع وتاريخ المباني الباقية."],["PL","Wieliczka Salt Mine","يبيّن المنجم دور استخراج الملح في اقتصاد المنطقة وهندسة العمل تحت الأرض. يجمع المنجم بين التاريخ الصناعي والهندسة والتقاليد الفنية للعمال، ويتجاوز أهميته مجرد استخراج مادة غذائية.","تظهر قاعات وأروقة منحوتة في الملح ومنحوتات وأشكال معمارية داخل المنجم. تظهر قاعات منحوتة في طبقات الملح ومنحوتات دينية وعناصر إنارة وجدران ذات ألوان رمادية مميزة للصخر الملحي.","https://whc.unesco.org/en/list/32","بدأ استغلال مناجم الملح في المنطقة منذ العصور الوسطى وتوسعت الأنفاق على مدى قرون. تطورت فيليتشكا عبر قرون من حفر الممرات وتأمين الأعمدة والتهوية ونقل الملح من مستويات متزايدة العمق.","بعض التماثيل والثريات داخل القاعات مصنوعة من الملح نفسه. المنجم ليس كهفًا طبيعيًا ضخمًا بالكامل؛ معظم الممرات والقاعات نتاج أعمال تعدين بشرية منظمة."],["PL","Gdańsk Main Town","تعكس المدينة القديمة مكانة غدانسك بوصفها ميناءً تجاريًا على بحر البلطيق. يروي الحي تاريخ التجارة البحرية على بحر البلطيق وتراكم الثروة في بيوت التجار ومخازن الميناء.","تظهر الواجهات الملونة والرافعات المينائية القديمة والشوارع المحيطة بالنهر. قارن الواجهات الضيقة الطويلة في شارع دووغي توغ مع الرافعة الخشبية التاريخية على ضفاف موتلافا والممرات المتفرعة من السوق.","https://visitgdansk.com/","تضررت أجزاء كبيرة من المركز التاريخي خلال الحرب العالمية الثانية ثم أعيد بناء الكثير من واجهاته. شهدت المدينة تدميرًا واسعًا خلال الحرب العالمية الثانية وأُعيد تشييد مبانٍ كثيرة وفق تصورات تاريخية للمركز الحضري؛ لذلك يتداخل الحفظ مع إعادة البناء.","قد تبدو البيوت قديمة تمامًا، لكن عددًا من الواجهات أعيد إنشاؤه بعناية بعد الحرب. المظهر التاريخي الحالي لا يعني أن كل حجر ومبنى أصلي يعود للعصور الوسطى؛ بعضه نتيجة إعادة بناء دقيقة بعد الحرب."],["RO","Bran Castle","تُظهر قلعة بران الدور الدفاعي للممرات بين ترانسيلفانيا ووالاشيا، وتربط بين تاريخ الحدود المحلية والصورة الشعبية لأسطورة دراكولا؛ أهميتها أوسع من الحكاية الخيالية.","تظهر الأبراج ذات الأسقف المدببة والسلالم الضيقة والأفنية والغرف التي تعكس حياة النبلاء وتاريخ القلعة، مع إطلالات على الجبال المحيطة.","https://bran-castle.com/","نشأت القلعة في أواخر القرن الرابع عشر لحماية الطرق والممرات التجارية، ثم تغيرت أدوارها وصارت مقرًا ملكيًا خلال القرن العشرين.","الربط التسويقي بدراكولا مستمد أساسًا من الأدب والأساطير، ولا يعني أن أحداث الرواية وقعت تاريخيًا داخل القلعة."],["RO","Peleș Castle","يعكس قصر بيليش تأسيس ملكية رومانيا الحديثة ورغبة الأسرة الحاكمة في إبراز الهوية الأوروبية من خلال العمارة والفنون والزخارف الداخلية.","تظهر الأسقف المائلة والأبراج الخشبية والحجرية والقاعة الرئيسية المزخرفة وغرف تتنوع بين تأثيرات ألمانية وإيطالية وغيرها، وسط غابات الكاربات.","https://peles.ro/","بدأ بناء القصر في عهد الملك كارول الأول خلال سبعينيات القرن التاسع عشر، وتطور ليصبح إقامة ملكية تضم تجهيزات كانت متقدمة لعصرها.","رغم أن اسمه الشائع «قلعة»، فقد صُمم في المقام الأول إقامة ملكية فاخرة، وليس حصنًا للدفاع عن حدود البلاد."],["RO","Danube Delta","تُعد دلتا الدانوب من أهم أراضي أوروبا الرطبة، وتشكل موائل واسعة للطيور والأسماك والنباتات وتؤثر حركة الترسيب والماء في رسم جزرها وقنواتها.","تظهر القنوات المتفرعة وبحيرات القصب والمسطحات الضحلة وتجمعات الطيور المائية، ويختلف المشهد باختلاف الموسم والمياه.","https://whc.unesco.org/en/list/588","تطورت الدلتا من تراكم الرواسب التي ينقلها الدانوب إلى البحر الأسود عبر آلاف السنين، وتغيّرت أذرع النهر والبحيرات مع الزمن.","ليست الدلتا أرضًا جافة عند مصب النهر؛ بل شبكة بيئية متحركة من الماء والقصب والرواسب تتغير مع الفيضانات والتدخل البشري."],["SI","Lake Bled","تجمع بحيرة بليد بين الطبيعة الألبية والتراث الديني والمحلي، ويجعل وجود جزيرة صغيرة في وسط البحيرة المشهد واحدًا من أكثر رموز سلوفينيا تميزًا.","تظهر الكنيسة على الجزيرة وقوارب بليتنا التقليدية والقلعة فوق الجرف والجبل الأخضر المحيط، وتنعكس المباني على الماء في الأجواء الهادئة.","https://www.bled.si/en/","تشكل حوض البحيرة ضمن تاريخ جليدي للمنطقة، ثم نشأت على ضفافها تقاليد زيارة دينية وترفيهية وتطورت البلدة كمنتجع.","جزيرة بليد الصغيرة من أشهر صور البلاد؛ الوصول إلى الكنيسة يتم غالبًا بقوارب لا عبر جسر بري يصل الجزيرة بالشاطئ."],["SI","Postojna Cave","تشرح كهوف بوستوينا ظاهرة الكارست التي تنتج عندما تذيب المياه الصخور الكلسية تدريجيًا، وتُعد من أشهر أنظمة الكهوف السياحية في أوروبا.","يمكن مشاهدة الصواعد والهوابط والأعمدة الكلسية والممرات الكبيرة والرحلة السياحية بقطار داخل بعض الأجزاء المجهزة.","https://www.postojnska-jama.eu/en/","تشكّل نظام الكهوف بفعل المياه الجوفية على أزمنة طويلة، وبدأت زياراته المنظمة في القرن التاسع عشر وتطورت مرافقه للحفاظ على المكان.","تعيش في المنطقة كائنات متكيفة مع الظلام مثل السمندر الكهفي المعروف محليًا باسم «سمكة الإنسان»، وهو برمائي لا سمكة."],["SI","Ljubljana Old Town","تُظهر ليوبليانا كيف يمكن لمدينة صغيرة أن تجمع التراث العمراني ونهرًا حضريًا ومساحات عامة مع عمارة حديثة صاغت هوية مركزها.","تظهر الجسور الثلاثية وجسر التنين والواجهات الملونة على ضفاف ليوبليانيتسا والساحات والمسارات الصاعدة نحو القلعة.","https://www.visitljubljana.com/en/","تطورت المدينة فوق جذور عمرانية رومانية ووسيطة، وأعاد المعماري يوجي بليتشنيك تشكيل أجزاء بارزة من مركزها في القرن العشرين.","الجسور الشهيرة ليست من عصر واحد؛ فالتكوين الحديث لبعضها يربط بين المدينة التاريخية والتصميم الحضري المعاصر."],["AL","Historic Centre of Berat","تحفظ بيرات مثالًا نادرًا لمدينة تاريخية عاشت فيها جماعات دينية وثقافية مختلفة، وتجمع منازلها العثمانية المتدرجة بين الجغرافيا والعمارة المحلية.","تظهر البيوت البيضاء ذات النوافذ المتعددة على السفوح وقلعة بيرات العالية وجسر غوريتسا فوق نهر أوسوم، مع شوارع حجرية ضيقة.","https://whc.unesco.org/en/list/569","نشأت البلدة على موقع استيطان قديم، ثم تعاقبت عليها فترات بيزنطية وعثمانية تركت آثارًا في القلعة والأحياء السكنية ودور العبادة.","وصف «مدينة الألف نافذة» لقب بصري للشكل المتكرر للنوافذ، وليس إحصاءً حقيقيًا لعدد نوافذ المدينة."],["AL","Butrint Archaeological Site","تُظهر بوترينت كيف تعاقبت حضارات عديدة على موقع واحد في جنوب ألبانيا، ما يجعلها مصدرًا لفهم التجارة والدين والتخطيط الحضري قرب البحر الأدرياتيكي.","تظهر بقايا المسرح القديم والبازيليكا والبوابات والأسوار والفسيفساء، وسط أشجار ومسطحات مائية وقنوات قريبة.","https://whc.unesco.org/en/list/570","تطورت بوترينت كمستوطنة قديمة ثم مدينة رومانية ومركز مسيحي مبكر، واستُخدمت أجزاء من منشآتها وتغيرت على مدى قرون.","بعض الآثار تقع داخل منتزه طبيعي رطب، لذلك يتغير الانطباع من موقع أثري حجري إلى مشهد يجمع الغابات والبحيرة والأنقاض."],["GE","Old Tbilisi","تُظهر تبليسي القديمة تفاعل طرق التجارة والثقافات المختلفة في القوقاز، ويضيف موقعها على منحدرات نهر كورا تنوعًا واضحًا في العمارة والأحياء.","تظهر الشرفات الخشبية المنحوتة والبيوت الملونة وحمامات الكبريت في أبانوتوباني وأزقة المنحدرات وقلعة ناريكالا فوق المدينة.","https://georgia.travel/","نشأت المدينة حول ينابيع المياه الدافئة على ضفاف النهر، وتبدل عمرانها مرارًا بفعل الفترات التاريخية المختلفة والحرائق وإعادة البناء.","تسمية تبليسي مرتبطة تقليديًا بالمياه الدافئة؛ والحمامات جزء من هوية المدينة وليس مجرد مرفق سياحي حديث."],["GE","Gergeti Trinity Church","صارت كنيسة غيرغيتي من أكثر المشاهد تعبيرًا عن العلاقة بين العمارة الدينية الجورجية وتضاريس القوقاز الجبلية، وتكتسب أهميتها من الموقع والتاريخ معًا.","تظهر الكنيسة الحجرية المنفردة فوق مرتفع أخضر وتلال كازبيغي وقمة جبل كازبيك عند صفاء الطقس، ويتغير المشهد بصورة كبيرة بين الفصول.","https://georgia.travel/","بُنيت الكنيسة في العصور الوسطى بالقرب من قرية غيرغيتي، وظلت معلمًا روحيًا مرتبطًا بمجتمعات الجبال في منطقة خيفي.","قمة كازبيك البركانية خلف الكنيسة ترتفع كثيرًا عن موضعها، لكن ظهورها الكامل يعتمد على الغيوم ولا يمكن ضمانه."],["GE","Historical Monuments of Mtskheta","تمثل متسخيتا أحد مراكز التاريخ المسيحي الجورجي، وتوضح كاتدرائياتها وأديرتها تطور العمارة الدينية في القوقاز وعلاقة المدينة بموقع التقاء الأنهار.","تظهر كاتدرائية سفيتيتسخوفيلي ذات القبة ودير جفاري على مرتفع يشرف على التقاء نهري متكفاري وأراغفي.","https://whc.unesco.org/en/list/708","كانت متسخيتا مركزًا سياسيًا ودينيًا مبكرًا، وبُنيت فيها مواقع كنسية مهمة بعد انتشار المسيحية في المملكة الجورجية القديمة.","الموقع المُدرج تراثيًا ليس كنيسة واحدة؛ بل عدة آثار منفصلة ترتبط تاريخيًا بمدينة متسخيتا ومحيطها."],["AM","Temple of Garni","يمثل معبد غارني نموذجًا نادرًا للعمارة الكلاسيكية ذات الأعمدة في أرمينيا، ويكشف جانبًا من المعتقدات والسلطة قبل التحولات المسيحية الواسعة.","تظهر الأعمدة الأيونية والواجهة المثلثة والسلالم الحجرية فوق هضبة تطل على وادي عزات، مع تضاريس بركانية قريبة.","https://armenia.travel/","يرتبط المعبد عادةً بالعصر الروماني في المنطقة، وقد تعرض للانهيار بفعل زلزال ثم أُعيد بناؤه من الأحجار المتبقية خلال القرن العشرين.","شكل المعبد الكلاسيكي يختلف عن معظم الكنائس الأرمينية، لذلك يساعد على فهم تنوع التراث المعماري قبل العصور الوسطى."],["AM","Geghard Monastery","يبرز دير غيغارد قدرة المعماريين الأرمينيين على دمج أماكن العبادة بالبيئة الصخرية، وهو شاهد على الحرف الدينية والنحت في العصور الوسطى.","تظهر القاعات المحفورة في الصخر والأعمدة والقباب الحجرية والزخارف المتقاطعة على الجدران، مع مجرى الوادي المحيط بالمجمع.","https://whc.unesco.org/en/list/960","تطور المجمع عبر مراحل، وتعود أجزاء مهمة من كنائسه وقاعاته إلى القرن الثالث عشر، مع تقاليد دينية أقدم مرتبطة بالمكان.","بعض القاعات ليست مباني أضيفت إلى الجبل؛ بل فراغات نُحتت مباشرةً داخل الصخر، ما يغير طريقة فهم بنائها."],["AM","Lake Sevan","تُعد بحيرة سيفان مصدرًا مائيًا وبيئيًا مهمًا لأرمينيا، ويمثل ارتفاعها الكبير وموقعها بين الجبال جزءًا من تميزها الطبيعي والثقافي.","تظهر المياه الزرقاء والجبال المحيطة وشبه جزيرة سيفانافانك حيث تقف كنائس حجرية أعلى التل، مع شواطئ تختلف حسب الموقع.","https://armenia.travel/","تأثر منسوب البحيرة تاريخيًا بالاستخدام البشري للمياه ومشروعات إدارتها، وأصبح التوازن بين الاستفادة الاقتصادية والحماية البيئية قضية مهمة.","تحولت منطقة سيفانافانك من جزيرة إلى شبه جزيرة بعد انخفاض منسوب المياه؛ لذا تغير المشهد الجغرافي المحيط بالدير."],["AZ","Walled City of Baku","تحفظ باكو المسوّرة مزيجًا معماريًا نتج عن تأثيرات ثقافية متعددة على ضفة بحر قزوين، وتُظهر الأسوار والقصور والأزقة تطور المدينة التجارية.","تظهر بوابات المدينة والأسوار وأزقة الحجر الفاتح وبرج العذراء وقصر الشروانشاهيين، مع تباين واضح بينها وبين الأبراج الحديثة خارج الأسوار.","https://whc.unesco.org/en/list/958","نشأت المدينة على موقع استيطان قديم، وشهدت نموًا في العصور الوسطى؛ وتحتفظ بمبانٍ من فترات مختلفة تشمل القرون الوسطى وأزمنة أحدث.","تاريخ برج العذراء ووظيفته الأصلية محل نقاش بين الباحثين؛ ليس صحيحًا الجزم بحكاية شعبية واحدة عن سبب تشييده."],["AZ","Gobustan Rock Art Cultural Landscape","تُعد غوبوستان شاهدًا مهمًا على حياة البشر القديمة في منطقة بحر قزوين، إذ تعرض النقوش الصخرية مشاهد نشاط بشري وحيواني عبر فترات طويلة.","تظهر رسوم محفورة على الصخور لأشخاص وحيوانات وقوارب، إلى جانب تضاريس صخرية وجافة ومواقع آثار قرب منطقة المحمية.","https://whc.unesco.org/en/list/1076","ترتبط النقوش بمراحل استيطان بشري قديمة تختلف في تأريخها، واستُخدمت الصخور في تسجيل مشاهد من أنشطة الصيد والحياة والطقوس.","ليست كل النقوش من العصر نفسه؛ كما أن رسومات القوارب والحيوانات قد تكشف بيئات ونشاطات اختلفت عن المشهد الحالي."],["AZ","Flame Towers","تعكس أبراج اللهب التحول العمراني المعاصر في باكو، وتستحضر صورتها فكرة النار التي تظهر في تاريخ المنطقة ورموزها الثقافية.","تظهر الأبراج الثلاثة ذات الواجهات الزجاجية المنحنية، وتتحول ليلًا إلى واجهات مضيئة تعرض أشكالًا وألوانًا مختلفة.","https://azerbaijan.travel/","شُيّدت الأبراج في بدايات القرن الحادي والعشرين لتصبح جزءًا بارزًا من أفق باكو الحديث فوق منطقة مطلة على بحر قزوين.","تشبه هيئة الأبراج ألسنة اللهب عند النظر إليها معًا، لكن الإضاءة المتغيرة ليست نيرانًا حقيقية بل عرضًا ضوئيًا على الواجهات."],["TN","Archaeological Site of Carthage","يتيح موقع قرطاج فهم حضارة بحرية قوية تحكمت في جانب من تجارة المتوسط، ثم تحولت المنطقة إلى مركز روماني مهم بعد صراعات طويلة مع روما.","تظهر بقايا حمامات أنطونيوس الهائلة والأحياء السكنية والموانئ القديمة والأعمدة والأرضيات الأثرية في نقاط متفرقة من الضاحية.","https://whc.unesco.org/en/list/37","نشأت قرطاج مستوطنة فينيقية وتوسعت عاصمةً لقوة قرطاجية كبرى؛ دمر الرومان المدينة سنة 146 قبل الميلاد وأقاموا لاحقًا مدينة رومانية على الموقع.","قرطاج ليست مبنى أثريًا واحدًا؛ آثارها موزعة في مواقع مختلفة، وقد تكون الأطلال الرومانية أوضح بصريًا من بقايا العصر القرطاجي."],["TN","Amphitheatre of El Jem","يمثل مدرج الجم مدى انتشار العمارة الرومانية العامة في شمال أفريقيا، ويُظهر مهارات البناء واستيعاب الحشود في المدن القديمة.","يمكن مشاهدة الأقواس المرتفعة والمدرجات وممرات الدخول والفراغات السفلية التي كانت مرتبطة بتنظيم العروض.","https://whc.unesco.org/en/list/38","أُقيم المدرج في القرن الثالث الميلادي في مدينة تيسدروس الرومانية، وارتبط برخاء المناطق الزراعية المحيطة وتطور النشاط الحضري.","يُشبه المدرج الكولوسيوم في روما في تصميمه البيضاوي، لكنه ليس نسخة مطابقة ولا يقع في العاصمة تونس."],["TN","Sidi Bou Said","تُظهر القرية علاقة البيئة المتوسطية بالتقاليد المعمارية المحلية، وقد جذبت فنانين وكتابًا بسبب إطلالاتها وأزقتها الهادئة.","تظهر الأبواب والمشربيات الزرقاء والواجهات البيضاء والسلالم الضيقة وإطلالة الخليج من نقاط مرتفعة بين البيوت.","https://www.discovertunisia.com/en","نشأت القرية قرب مواقع روحية ودينية قديمة وتطورت وجهةً سكنية وثقافية، ثم انتشرت قواعد حافظت على هويتها اللونية والمعمارية.","اللونان الأزرق والأبيض مشهوران جدًا في سيدي بوسعيد، لكن تاريخ المكان يتجاوز كونه موقعًا للتصوير؛ فقد ارتبط بالفنون والحياة الثقافية التونسية."],["QA","Souq Waqif","يحفظ سوق واقف جانبًا من حياة التجارة الحضرية القطرية؛ وتظهر فيه علاقة الأسواق التقليدية بالحرف والمنتجات المحلية واللقاءات الاجتماعية.","تظهر الأزقة الضيقة والأسقف المظللة ومحال التوابل والأقمشة والمصنوعات اليدوية والساحات المحاطة بمبانٍ مستوحاة من العمران المحلي.","https://visitqatar.com/intl-en/things-to-do/art-culture/souq-waqif","ارتبط السوق تاريخيًا بالتبادل التجاري في الدوحة ثم أُعيد تأهيل أجزاء واسعة منه في العصر الحديث للحفاظ على الطابع التراثي.","بعض مظهر السوق الحالي نتيجة ترميم وإعادة بناء مدروسين، لذلك لا يصح اعتبار كل مبنى فيه أثرًا أصليًا من قرون بعيدة."],["QA","Museum of Islamic Art Doha","يعرض المتحف امتداد الفنون الإسلامية جغرافيًا وزمنيًا، من الخزف والمنسوجات إلى المخطوطات والمعادن، بدل اختزالها في دولة أو فترة واحدة.","تظهر الكتل الحجرية الهندسية للمبنى المطل على الخليج وقاعات عرض للخط والزجاج والسجاد والمصنوعات الفنية.","https://mia.org.qa/en/","افتُتح المتحف سنة 2008 في مبنى صممه المعماري آي. إم. باي، واستند تصميمه الحديث إلى دراسة عناصر من العمارة الإسلامية التاريخية.","اسم «الفن الإسلامي» هنا يشمل أعمالًا صنعتها مجتمعات متنوعة عبر مناطق عديدة؛ ليست كل القطع بالضرورة أدوات دينية."],["QA","National Museum of Qatar","يقدم المتحف قصة قطر عبر الجيولوجيا والبيئة البحرية والبداوة وتجارة اللؤلؤ والتحول الاقتصادي الحديث في عرض مترابط.","تظهر الأقراص المتداخلة للواجهة المستوحاة من وردة الصحراء، والمعارض السمعية البصرية والمقتنيات المرتبطة بتاريخ البلاد.","https://nmoq.org.qa/en/","افتُتح المبنى الجديد عام 2019 بتصميم جان نوفيل، وجرى دمج القصر القديم للشيخ عبد الله بن جاسم آل ثاني ضمن المسار المتحفي.","وردة الصحراء التي ألهمت التصميم تكوين بلوري طبيعي من معادن، وليست زهرة نباتية تنمو في الرمل."],["BH","Qal'at al-Bahrain","يحفظ الموقع طبقات طويلة من الاستيطان والتجارة في الخليج العربي، ومنها آثار مرتبطة بدلمون التي لعبت دورًا في طرق التجارة القديمة.","تظهر أسوار الحصن القائم وتلال الآثار وبقايا المباني الأقدم والممرات التي تتدرج بين طبقات تاريخية مختلفة.","https://whc.unesco.org/en/list/1192","تراكمت طبقات السكن على التل الأثري عبر آلاف السنين، بينما يعود الحصن المرئي إلى فترات أحدث؛ لذا لا يمثل وحده زمن حضارة دلمون.","قلعة البحرين تجمع حصنًا فوق تل أثري واسع؛ الآثار تحت القلعة أقدم بكثير من الجدران الدفاعية الظاهرة للزائر."],["BH","Al Fateh Grand Mosque","يجسد المسجد أحد المعالم الإسلامية المعاصرة في البحرين، ويجمع المساحات الكبيرة وعناصر العمارة التقليدية بأسلوب حديث.","تظهر القبة الواسعة والأروقة والأعمدة والزخارف الداخلية والمآذن التي تحدد صورة المسجد من الخارج.","https://www.bahrain.com/en","شُيّد المسجد في ثمانينيات القرن العشرين وسُمّي تكريمًا لأحمد الفاتح، وأصبح مقصدًا للصلاة والتعريف بالثقافة الإسلامية.","حجم المسجد واتساع قبته لا يعني أنه من عصور الخلافة القديمة؛ بل إنه نموذج لعمارة دينية حديثة تستلهم عناصر تاريخية."],["BH","Tree of Life Bahrain","تُظهر شجرة الحياة قدرة بعض الأشجار على التكيف مع البيئات القاحلة، وقد أصبحت رمزًا طبيعيًا مميزًا في صحراء البحرين.","تظهر الشجرة المنفردة ذات التاج الواسع بين أرض صخرية ورملية شبه خالية من الأشجار الكبيرة.","https://www.bahrain.com/en","نمت الشجرة لعقود طويلة في موقع جاف جنوب الجزيرة؛ وقد ارتبطت بها روايات شعبية مختلفة عن مصدر المياه وقدرتها على البقاء.","لا يمكن الجزم بأن الشجرة تعيش بلا ماء؛ النباتات الصحراوية قد تصل إلى رطوبة عميقة أو تستفيد من المياه المتاحة بطرق غير مرئية."],["KW","Kuwait Towers","تمثل أبراج الكويت علامة على التطور العمراني الحديث للمدينة وعلاقة التصميم الهندسي بوظائف تخزين المياه والخدمات والمشاهدة.","تظهر الأبراج الثلاثة بأحجام مختلفة وكراتها اللامعة ذات الكسوة الهندسية، مع مشهد الخليج ومباني المدينة.","https://www.kuwaittourism.gov.kw/","اكتملت الأبراج في أواخر سبعينيات القرن العشرين، وتجمع عناصرها بين البنية التحتية اللازمة للمدينة والطابع المعماري المميز.","ليست كل الكرات مخصصة للمشاهدة؛ تشمل منظومة الأبراج وظائف مرتبطة بخزانات المياه إلى جانب المرافق العامة."],["KW","Grand Mosque of Kuwait","يوضح المسجد الكبير تطور العمارة الدينية الكويتية الحديثة وتوظيف الزخارف والخط والعناصر التقليدية في فضاء واسع.","تظهر القبة الكبيرة وقاعة الصلاة والمحراب والزخارف الجصية والخشبية والبوابات الواسعة.","https://www.awqaf.gov.kw/","افتُتح المسجد في ثمانينيات القرن العشرين وأصبح من أبرز مساجد الكويت لاستضافة الصلوات والمناسبات الدينية.","ضخامة قاعة الصلاة لا تجعل المبنى موقعًا أثريًا قديمًا؛ إنه مثال حديث على امتداد تقاليد الزخرفة الإسلامية."],["MV","Baa Atoll Biosphere Reserve","تمثل با أتول نموذجًا مهمًا للعلاقة بين الجزر المرجانية والتنوع البحري، وتتميز بعض مناطقها بتجمعات موسمية لأسماك شيطان البحر.","تظهر الجزر الرملية والمياه الفيروزية والشعاب؛ وتعد منطقة خليج هانيفارو مثالًا مشهورًا على تجمع الكائنات البحرية وفق مواسم وظروف معينة.","https://www.unesco.org/en/mab/baa-atoll","تشكّل أرخبيل المالديف من نظم شعاب مرجانية تطورت فوق بنى جيولوجية غارقة، وأُعلنت با أتول محمية محيط حيوي عام 2011.","ظهور أسماك شيطان البحر في هانيفارو موسمي ومتغير، والمنطقة تخضع لقواعد حماية؛ ليست مشاهدة الحياة البحرية فيها مضمونة دائمًا."],["MV","Malé Friday Mosque","يعكس المسجد تاريخ الحرف والعمارة الإسلامية في المالديف، حيث استخدمت مواد محلية مثل الحجر المرجاني في زخارف معقدة.","تظهر الجدران الحجرية المنحوتة والزخارف الكتابية والأعمدة الداخلية والمقابر التاريخية المحيطة بموقع المسجد.","https://www.visitmaldives.com/en","شُيّد المسجد الحالي في القرن السابع عشر ضمن تقاليد بناء محلية أقدم، ويُعرف أيضًا باسم هُكورو مِسكيي.","الحجر المرجاني المستخدم في البناء يختلف عن الرخام المستورد؛ وهو دليل على توظيف مواد الجزر محليًا، ولا يبرر أخذ المرجان من الشعاب اليوم."],["MU","Le Morne Brabant","تجمع أهمية جبل لو مورن بين الجغرافيا البركانية والذاكرة التاريخية للعبودية والمقاومة، خاصةً ارتباط المنطقة بملاجئ الفارّين من الاسترقاق.","تظهر كتلة الجبل البازلتية قرب الساحل والخلجان الفيروزية والمنحدرات التي ترتفع مباشرة من السهول الساحلية.","https://whc.unesco.org/en/list/1259","أصبحت المنطقة رمزًا لذكرى أشخاص فروا من الاسترقاق ولجأوا إلى الجبل ومحيطه؛ وتطورت هذه الذاكرة إلى جزء من التراث الوطني.","توجد روايات شعبية عن حوادث مأساوية فوق الجبل، لكن تفاصيل بعض هذه الروايات لا تُعد أحداثًا تاريخية موثقة بالدرجة نفسها."],["MU","Seven Coloured Earths","تُظهر تربة شاماريل أثر التجوية في المواد البركانية وتكوّن مركبات معدنية تمنح التلال عدة درجات لونية متجاورة.","تظهر تلال من الرمل والتربة بألوان حمراء وبنفسجية وبنية وصفراء، وتختلف درجة وضوح الألوان مع الشمس والرطوبة.","https://mauritiusnow.com/","تُعزى الألوان إلى تحلل مواد بركانية غنية بالمعادن وأكسدتها خلال فترات طويلة، ما أظهر الفروق المعدنية داخل التربة.","الألوان ليست نتيجة دهانات صناعية أو سبعة أنواع رمال أُحضرت للمكان؛ إنها ظاهرة جيولوجية طبيعية تختلف حدود ألوانها بصريًا."],["MU","Black River Gorges National Park","يحمي المنتزه أجزاء من الغابات الأصلية والوديان في موريشيوس، وهو مهم للأنواع المستوطنة التي تضررت مواطنها بفعل إدخال أنواع دخيلة.","تظهر الوديان الخضراء العميقة والشلالات ونقاط مشاهدة الغابات والمسارات التي تمر عبر نباتات استوائية.","https://www.npcs.govmu.org/","أُنشئت الحماية الحديثة لصون غابات محلية أصبحت نادرة نسبيًا بعد التغيرات الواسعة التي شهدتها الجزيرة نتيجة النشاط البشري.","القيمة البيئية للمنتزه لا تقتصر على مشاهد الأشجار؛ بعض الطيور والنباتات المحلية لا توجد طبيعيًا إلا في موريشيوس."],["CR","Arenal Volcano National Park","يوضح أرينال العلاقة بين النشاط البركاني والغابات المطيرة والتنوع البيئي في كوستاريكا، وقد شكل البركان التضاريس المحيطة وترك حقول حمم واضحة.","تظهر القمة المخروطية والامتدادات السوداء للحمم القديمة والغابات الممطرة والطيور والنباتات، ويمكن رؤية الينابيع الساخنة في المنطقة المحيطة خارج بعض مسارات المنتزه.","https://www.sinac.go.cr/","دخل أرينال مرحلة ثوران بارزة سنة 1968 واستمرت فترات نشاطه لعقود، ثم تراجع نشاطه الثوراني السطحي في السنوات اللاحقة؛ لذلك يتغير ما يمكن مشاهدته حسب الحالة البركانية.","بركان أرينال ليس مصدرًا مضمونًا لمشاهدة الحمم المتوهجة اليوم، ويجب الاعتماد على تعليمات الحماية المحلية بدل الصور التاريخية للثورانات."],["CR","Manuel Antonio National Park","يمثل مانويل أنطونيو بيئة ساحلية تجمع الغابات الاستوائية بالمياه والشواطئ، وهو موقع مناسب لفهم العلاقة بين حماية الحياة البرية وضغط السياحة.","تظهر خلجان رملية وممرات قصيرة عبر الغابات ومشاهد لقرود الكابوتشين والكسلان والطيور، مع اختلاف فرص المشاهدة حسب حركة الحيوانات.","https://www.sinac.go.cr/","أُنشئ المنتزه في القرن العشرين لحماية المنطقة الساحلية من ضغوط التنمية، وأصبحت إدارة أعداد الزوار جزءًا مهمًا من المحافظة على موائله.","لا تعني سهولة الوصول إلى الشواطئ إمكان لمس الحيوانات أو إطعامها؛ فالاقتراب المفرط يضر السلوك الطبيعي للأنواع المحمية."],["CR","Monteverde Cloud Forest Reserve","تحافظ غابة مونتيفيردي السحابية على موائل جبلية رطبة وغنية بالنباتات الهوائية والطيور؛ وتظهر أهميتها في تنوع الأحياء على مساحة محدودة.","تظهر الممرات الضبابية وأشجار مغطاة بالطحالب ونباتات البروميليا والسراخس، وقد يُشاهد طائر الكيتزال الملون في مواسم مناسبة.","https://cloudforestmonteverde.com/","نشأت مبادرات حماية الغابة في القرن العشرين مع إدراك أهمية موائل المرتفعات الحساسة، وأصبح البحث والتعليم البيئي جزءًا من رسالة المحمية.","الغابة السحابية ليست غابة تمطر طوال اليوم؛ الضباب والسحب المنخفضة مصدر مهم للرطوبة حتى عندما لا تهطل أمطار مباشرة."],["EC","Galápagos National Park","تمثل غالاباغوس نموذجًا استثنائيًا لتطور الكائنات في جزر معزولة؛ وتشتهر بسلاحفها العملاقة وإغوانا البحر وطيورها المتوطنة.","تظهر تضاريس الحمم والشواطئ الصخرية والسلاحف العملاقة وأسود البحر وطيور متنوعة، مع اختلاف الأنواع البارزة بين الجزر.","https://whc.unesco.org/en/list/1","أصبحت الجزر محورًا مهمًا في تاريخ أبحاث الطبيعة بعد زيارة تشارلز داروين عام 1835، ثم تطورت جهود حماية الكائنات والموائل البحرية والبرية.","لم يستنبط داروين نظريته كاملة أثناء الوقوف على الجزر؛ بل ساعدت ملاحظاته وعينات رحلته على تطوير أفكاره خلال سنوات لاحقة."],["EC","Historic Centre of Quito","يحفظ مركز كيتو إحدى أهم مجموعات العمارة الدينية والمدنية الاستعمارية في جبال الأنديز، وتضيف التضاريس المرتفعة خصوصية لشوارع المدينة.","تظهر ساحات مرصوفة وكنائس ذات واجهات منحوتة وأديرة وأبراج مطلة على طرق ترتفع وتنخفض عبر التلال.","https://whc.unesco.org/en/list/2","تطورت المدينة الاستعمارية بعد القرن السادس عشر على موقع كانت له أهمية في العالم الأنديزي قبل وصول الإسبان، ثم تراكمت مبانيها عبر أجيال.","كيتو مدينة مرتفعة جدًا عن سطح البحر؛ وقد يؤثر الارتفاع في التنفس لدى بعض الزوار القادمين من المناطق الساحلية."],["EC","Cotopaxi National Park","تُبرز منطقة كوتوباكسي ارتباط النشاط البركاني ببيئة البارامو الأنديزية، وتضم أحد أشهر البراكين مرتفعة القمة في الإكوادور.","تظهر القمة الثلجية المخروطية والأراضي العشبية العالية والبحيرات الصغيرة ومشاهد المرتفعات حول قاعدة البركان.","https://www.ambiente.gob.ec/","تراكم المخروط البركاني نتيجة ثورات متعاقبة خلال عصور جيولوجية، وشهد البركان نشاطًا تاريخيًا استدعى المراقبة وإجراءات السلامة.","وجود الثلج أعلى البركان لا يعني أنه خامد؛ يجب مراجعة التنبيهات الرسمية لأن النشاط والانبعاثات قد تتغير."],["BO","Salar de Uyuni","يُعد سالار دي أويوني من أكبر المسطحات الملحية في العالم، ويوضح كيف يمكن لجفاف بحيرات قديمة أن يترك طبقات واسعة من الأملاح في الهضبة الأنديزية.","تظهر مساحات الملح البيضاء والأنماط السداسية على السطح، وقد يتحول المكان إلى انعكاس واسع للسماء بعد هطول المطر.","https://bolivia.travel/","نشأ المسطح بعد تقلص بحيرات قديمة في حوض مرتفع، ثم تراكمت طبقات الملح وتغيرت مستويات الرطوبة الموسمية فوق السطح.","مشهد المرآة ليس دائمًا؛ يعتمد على وجود طبقة ماء ضحلة وهدوء الرياح، بينما يبدو السطح أبيض جافًا في فترات أخرى."],["BO","Tiwanaku Archaeological Site","يكشف تيواناكو عن حضارة أنديزية مؤثرة سبقت الإنكا، وتظهر أطلاله مهارات قطع الحجر والتخطيط والطقوس في منطقة مرتفعة قرب تيتيكاكا.","تظهر بوابة الشمس والمنصات الحجرية والجدران الكبيرة والتماثيل المنحوتة في الموقع الأثري.","https://whc.unesco.org/en/list/567","ازدهرت تيواناكو خلال الألفية الأولى الميلادية باعتبارها مركزًا دينيًا وسياسيًا لشبكات واسعة في جبال الأنديز، وتغير نفوذها قبل صعود الإنكا.","لا يصح وصف تيواناكو بأنها مدينة بناها الإنكا؛ فازدهارها الرئيسي سبق توسع دولتهم بقرون."],["BO","Isla del Sol","تحمل جزيرة الشمس مكانة أسطورية ودينية في تقاليد الإنكا، وتجمع مواقع أثرية ومدرجات زراعية مع مشاهد بحيرة تيتيكاكا المرتفعة.","تظهر الجبال والممرات الحجرية والمدرجات والمستوطنات الصغيرة والمياه الزرقاء الممتدة نحو قمم الأنديز.","https://bolivia.travel/","ارتبطت الجزيرة بمسارات وطقوس حج لدى الإنكا، واحتفظت كذلك بتقاليد ومجتمعات محلية تعيش حول موارد البحيرة.","اسم «جزيرة الشمس» يتعلق بالتقاليد الروحية للمنطقة، وليس لأنها المكان الوحيد في البحيرة الذي تشرق عليه الشمس."],["CU","Old Havana","تحفظ هافانا القديمة تاريخ ميناء تجاري محصن على الكاريبي وتأثيرات ثقافية متعددة ظهرت في الشوارع والساحات والعمارة.","تظهر ساحات الكاتدرائية والسوق والواجهات الملونة والشرفات والقلاع الساحلية والشوارع التي ما زالت مأهولة.","https://whc.unesco.org/en/list/204","توسعت المدينة مركزًا استعماريًا إسبانيًا منذ القرن السادس عشر، وأُنشئت تحصينات للدفاع عن الميناء ثم تراكمت مبانيها عبر فترات لاحقة.","المدينة القديمة ليست منطقة متحفية خالية من السكان؛ الحفاظ عليها يتداخل مع الحياة اليومية والصيانة وإعادة التأهيل."],["CU","Viñales Valley","يُبرز وادي فيناليس تضاريس كارستية ذات تلال كلسية معزولة تسمى موغوتيس، وتجاور الحقول الزراعية التقليدية منظرًا طبيعيًا غنيًا.","تظهر المرتفعات الصخرية المستديرة والجروف الحادة وحقول التبغ والبيوت الريفية والوديان الخضراء.","https://whc.unesco.org/en/list/840","نشأت أشكال الموغوتيس عبر إذابة الحجر الجيري وتعرية الصخور في مناخ رطب، واستمرت زراعة تقليدية في الوادي عبر أجيال.","التلال المميزة ليست براكين صغيرة؛ بل بقايا صخور جيرية نحتتها عمليات جيولوجية مختلفة."],["CU","Trinidad and the Valley de los Ingenios","يرتبط تراث ترينيداد ووادي مصانع السكر بتاريخ ازدهار صناعة السكر الاستعمارية، وما رافقها من عمل قسري واستعباد بشري.","تظهر الشوارع المرصوفة والقصور الملونة والأبراج التاريخية وبقايا منشآت زراعة السكر وطحنه في الوادي.","https://whc.unesco.org/en/list/460","ازدهرت المدينة خلال القرنين الثامن عشر والتاسع عشر بسبب اقتصاد السكر في المنطقة المحيطة، وكانت مزارعه تعتمد بصورة كبيرة على العمالة المستعبدة.","الجمال المعماري للمدينة مرتبط أيضًا بتاريخ اجتماعي مؤلم؛ لا ينبغي فصل القصور ومزارع السكر عن ظروف العمل القسري التي موّلتها."],["NA","Sossusvlei","تُظهر كثبان سوسوسفلي أثر الرياح الطويل الأمد في نقل الرمال داخل صحراء ناميب، ويبرز التباين بين الكثبان الحمراء والأحواض الطينية الفاتحة.","تظهر الكثبان المرتفعة والأشكال الهلالية والسهول المالحة وأشجار السنط اليابسة في منطقة ديدفلي المجاورة.","https://www.namibiatourism.com.na/","تراكمت الرمال عبر زمن طويل في حوض صحراوي، وتغيّر شكل الكثبان باستمرار بحسب حركة الرياح وتركيب الحبيبات.","ليست كثبان سوسوسفلي ثابتة تمامًا؛ بعضها يتحرك ببطء، كما أن ديدفلي حوض منفصل قريب يشتهر بالأشجار الميتة."],["NA","Etosha National Park","يُعد إيتوشا من أشهر نظم السافانا في أفريقيا الجنوبية، ويجمع الحوض الملحي الكبير مع مراعي وموارد مياه تجذب قطعان الحياة البرية.","تظهر السهول البيضاء للحوض الملحي ومناطق شرب الحيوانات والفيلة والزرافات والحمر الوحشية في مشاهد تختلف حسب الموسم.","https://www.namibiatourism.com.na/","نشأ الحوض الملحي من تغيرات جيولوجية ومائية قديمة، ثم أُعلنت المنطقة محمية ونُظمت مرافق مشاهدة الحياة البرية.","الحوض الملحي لا يمتلئ بالماء باستمرار؛ وغالبًا يكون جافًا، بينما تتركز مشاهدة الحيوانات عند بعض موارد المياه."],["NA","Skeleton Coast National Park","يكشف الساحل الهيكلي التقاء صحراء ناميب بمياه الأطلسي الباردة وتأثير الضباب والتيارات على الملاحة والحياة الساحلية.","تظهر الكثبان التي تصل إلى البحر والضباب المتكرر وحطام بعض السفن وأطراف مصبات أودية نادرة الجريان.","https://www.namibiatourism.com.na/","اشتهرت المنطقة تاريخيًا بصعوبة الملاحة والنجاة بعد الحوادث البحرية، بسبب التيارات القوية وصعوبة الوصول إلى الداخل الصحراوي.","ليس سبب الاسم هياكل السفن وحدها؛ فقد ارتبط تاريخيًا أيضًا ببقايا عظام الحيتان والفقمات المنتشرة على أجزاء من الساحل."],["BW","Okavango Delta","تمثل أوكافانغو نظامًا مائيًا نادرًا لا يصل مباشرة إلى البحر؛ إذ تنتشر مياه النهر في سهول كالاهاري وتدعم تنوعًا كبيرًا للحياة البرية.","تظهر القنوات المتعرجة والجزر العشبية والمستنقعات والطيور والفيلة، ويمكن مشاهدة بعض المناطق من قوارب موكورو التقليدية.","https://whc.unesco.org/en/list/1432","تتدفق مياه النهر من مرتفعات أنغولا نحو بوتسوانا، ويبلغ الفيضان الموسمي أجزاء من الدلتا بعد أمطار المنبع بفترة زمنية.","تبلغ بعض مناطق الدلتا ذروة الفيضان في موسم جاف محليًا، بسبب تأخر رحلة مياه الأمطار القادمة من بعيد."],["BW","Chobe National Park","يحمي منتزه تشوبي مجموعة كبيرة من الأفيال وموائل النهر والغابات والسهول، وتساعد تغيرات المواسم على تفسير توزيع الحيوانات داخله.","تظهر ضفاف نهر تشوبي والتجمعات الكبيرة للأفيال والجاموس والطيور والتماسيح في مساحات الماء والأراضي العشبية.","https://www.botswanatourism.co.bw/","أُنشئت الحماية الوطنية للمنطقة في القرن العشرين، وتطورت إدارة المنتزه لاستيعاب الحياة البرية والسياحة مع تغيرات المواسم.","قد تنتقل الحيوانات بين مناطق مختلفة تبعًا للماء والغذاء؛ لذا لا يمكن ضمان مشاهدة نوع بعينه في ساعة محددة."],["BW","Tsodilo Hills","تحمل تلال تسوديلو آلاف الرسوم والنقوش القديمة التي ترتبط بتاريخ الاستيطان والفنون والمعتقدات لدى جماعات عاشت في منطقة كالاهاري.","تظهر لوحات صخرية حمراء وبيضاء تصور حيوانات وأشكالًا بشرية على جدران وملاجئ الصخور حول التلال.","https://whc.unesco.org/en/list/1021","تراكمت الرسوم عبر فترات طويلة لدى جماعات مختلفة، وأصبحت التلال ذات مكانة روحية وثقافية بين مجتمعات محلية.","وصف الموقع أحيانًا بأنه «لوفر الصحراء» تشبيه بشهرة فنونه الصخرية، وليس دلالة على وجود متحف حديث بين التلال."]];
const byKey=new Map(rows.map(r=>[r[0]+'|'+r[1],Object.freeze({
 significanceAr:r[2],visitAr:r[3],source:r[4],storyAr:r[5]||'',factAr:r[6]||''
})]));
window.GeoVerseTourismDeepEnrichmentV597=Object.freeze({
 count:rows.length,
 get(item){return item?byKey.get(item.code+'|'+item.nameEn)||null:null}
});
})();
